INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52711, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "木の下のほうにあって、土の中にのびている、細長い部分です。", "primary_collocate": null, "pronunciation": "ね", "ipa": "ne", "syllable_count": 1, "sentences": [{"text": "木の根を見る。", "target_word": "根", "complexity_tier": "T1", "furigana": "木[き]の根[ね]を見[み]る。", "sentence_source": "generated"}, {"text": "根が土の中にある。", "target_word": "根", "complexity_tier": "T2", "furigana": "根[ね]が土[つち]の中[なか]にある。", "sentence_source": "generated"}, {"text": "木の根につまずいた。", "target_word": "根", "complexity_tier": "T2", "furigana": "木[き]の根[ね]につまずいた。", "sentence_source": "generated"}, {"text": "太い根が地面から出ている。", "target_word": "根", "complexity_tier": "T3", "furigana": "太[ふと]い根[ね]が地面[じめん]から出[で]ている。", "sentence_source": "generated"}, {"text": "花の根を傷つけないでください。", "target_word": "根", "complexity_tier": "T3", "furigana": "花[はな]の根[ね]を傷[きず]つけないでください。", "sentence_source": "generated"}, {"text": "根まで水が届くように、たっぷりやった。", "target_word": "根", "complexity_tier": "T3", "furigana": "根[ね]まで水[みず]が届[とど]くように、たっぷりやった。", "sentence_source": "generated"}, {"text": "この草は根が長いので、抜きにくい。", "target_word": "根", "complexity_tier": "T3", "furigana": "この草[くさ]は根[ね]が長[なが]いので、抜[ぬ]きにくい。", "sentence_source": "generated"}, {"text": "犬が木の根を掘っている。", "target_word": "根", "complexity_tier": "T3", "furigana": "犬[いぬ]が木[き]の根[ね]を掘[ほ]っている。", "sentence_source": "generated"}, {"text": "根を切ると、木は弱ってしまう。", "target_word": "根", "complexity_tier": "T4", "furigana": "根[ね]を切[き]ると、木[き]は弱[よわ]ってしまう。", "sentence_source": "generated"}, {"text": "大きな木の根は、石の間まで伸びている。", "target_word": "根", "complexity_tier": "T4", "furigana": "大[おお]きな木[き]の根[ね]は、石[いし]の間[あいだ]まで伸[の]びている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "根っこ", "label": "派生"}, {"form": "根元", "label": "派生"}, {"form": "根付く", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 木や草の土の中の細長い部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197d032-60fa-49db-8918-971d5b8c0885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52711, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根", "is_correct": true, "explanation": "木の土の中の部分を見る、という意味に合う。"}, {"text": "味", "is_correct": false, "explanation": "形は合うが、木の味を「見る」という意味は合わない。"}, {"text": "歌", "is_correct": false, "explanation": "形は合うが、木の歌を「見る」という意味は合わない。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、木の値段を「見る」は文脈に合わない。"}], "explanations": {"根": "木の土の中の部分を見る、という意味に合う。", "味": "形は合うが、木の味を「見る」という意味は合わない。", "歌": "形は合うが、木の歌を「見る」という意味は合わない。", "値段": "形は合うが、木の値段を「見る」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "根"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "根をペンのように使って、手紙を書いた。", "explanation": "根は筆記具ではなく、この使い方は意味が合わない。"}, {"text": "根が空に向かって太く伸びている。", "explanation": "根は土の中に伸びる器官で、空へ向かって伸びるのは幹や枝である。この文は根を誤って使っている。"}, {"text": "奥歯の根が痛くて、ものがうまく噛めなかった。", "explanation": "ここは〈歯の根元〉の意味。土の中にのびる植物の根とは別の意味で、この定義には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52711, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根", "is_correct": true, "explanation": "根が長い草は抜きにくい、という因果が通る。"}, {"text": "声", "is_correct": false, "explanation": "形は合うが、草の声が長いから抜きにくいという意味は合わない。"}, {"text": "色", "is_correct": false, "explanation": "草の色が長いことは抜きにくさの理由にならず、文意が通らない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は空にあるもので、草の一部として長いと言えず、抜きにくさの理由にならない。"}], "explanations": {"根": "根が長い草は抜きにくい、という因果が通る。", "声": "形は合うが、草の声が長いから抜きにくいという意味は合わない。", "色": "草の色が長いことは抜きにくさの理由にならず、文意が通らない。", "雲": "雲は空にあるもので、草の一部として長いと言えず、抜きにくさの理由にならない。"}, "sentence_index": 6, "correct_answer": "根"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この木の根は、秋になると赤く色づく。", "explanation": "根は土の中の器官で、秋に赤く色づくのは葉である。"}, {"text": "彼は東京に根を下ろして、もう十年になる。", "explanation": "ここは〈定住する〉の意味。「根を下ろす」は一つの場所に住み着く意味で、土の中にのびる植物の部分ではない。"}, {"text": "この木の根は、冬の間もまっすぐ立っている。", "explanation": "まっすぐ立つのは幹であり、地中にある根には当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
