"派生"}, {"form": "成人向け", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | すでに大人になった人のこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197d032-60fa-49db-8918-971d5b8c0885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52713, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "成人", "is_correct": true, "explanation": "見出し語「成人(せいじん)」そのもの。"}, {"text": "精神", "is_correct": false, "explanation": "「せいしん」は「じ」が「し」に変わった別の語。"}, {"text": "誠実", "is_correct": false, "explanation": "「せいじつ」は最後の「ん」が「つ」に変わった別の語。"}, {"text": "先人", "is_correct": false, "explanation": "「せんじん」は「い」が「ん」に変わった別の語。"}, {"text": "怪人", "is_correct": false, "explanation": "「かいじん」は最初の「せ」が「か」に変わった別の語。"}, {"text": "対人", "is_correct": false, "explanation": "「たいじん」は最初の「せ」が「た」に変わった別の語。"}], "explanations": {"成人": "見出し語「成人(せいじん)」そのもの。", "精神": "「せいしん」は「じ」が「し」に変わった別の語。", "誠実": "「せいじつ」は最後の「ん」が「つ」に変わった別の語。", "先人": "「せんじん」は「い」が「ん」に変わった別の語。", "怪人": "「かいじん」は最初の「せ」が「か」に変わった別の語。", "対人": "「たいじん」は最初の「せ」が「た」に変わった別の語。"}, "sentence_index": null, "correct_answer": "成人"}, "level_3": {"options": [{"text": "成人", "is_correct": true, "explanation": "兄が大人である、と自然に通じる。"}, {"text": "果物", "is_correct": false, "explanation": "形は合うが、兄が果物だという意味は合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、兄が天気だという意味は合わない。"}, {"text": "都市", "is_correct": false, "explanation": "形は合うが、兄が都市だという意味は合わない。"}], "explanations": {"成人": "兄が大人である、と自然に通じる。", "果物": "形は合うが、兄が果物だという意味は合わない。", "天気": "形は合うが、兄が天気だという意味は合わない。", "都市": "形は合うが、兄が都市だという意味は合わない。"}, "sentence_index": 0, "correct_answer": "成人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "成人の水は、とても冷たくておいしい。", "explanation": "成人は大人を指す語で、水の種類には使えない。"}, {"text": "成人の日は、一月の第二月曜日だ。", "explanation": "ここは祝日名〈成人の日〉の意味。〈大人になった人〉の意味ではない。"}, {"text": "生まれたばかりの成人が、泣いている。", "explanation": "成人は大人を指す語で、生まれたばかりの赤ん坊には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52713, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "成人", "is_correct": true, "explanation": "見出し語「成人(せいじん)」そのもの。"}, {"text": "名人", "is_correct": false, "explanation": "「めいじん」は最初の「せ」が「め」に変わった別の語。"}, {"text": "大臣", "is_correct": false, "explanation": "「だいじん」は最初の「せ」が「だ」に変わった別の語。"}, {"text": "内陣", "is_correct": false, "explanation": "「ないじん」は最初の「せ」が「な」に変わった別の語。"}, {"text": "成員", "is_correct": false, "explanation": "「せいいん」は「じ」が「い」に変わった別の語。"}], "explanations": {"成人": "見出し語「成人(せいじん)」そのもの。", "名人": "「めいじん」は最初の「せ」が「め」に変わった別の語。", "大臣": "「だいじん」は最初の「せ」が「だ」に変わった別の語。", "内陣": "「ないじん」は最初の「せ」が「な」に変わった別の語。", "成員": "「せいいん」は「じ」が「い」に変わった別の語。"}, "sentence_index": null, "correct_answer": "成人"}, "level_3": {"options": [{"text": "成人", "is_correct": true, "explanation": "大人の数が年々減る、と自然に通じる。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節の数が年々減るという意味は合わない。"}, {"text": "太陽", "is_correct": false, "explanation": "形は合うが、太陽の数が減るという意味は合わない。"}, {"text": "山", "is_correct": false, "explanation": "形は合うが、山の数が年々減るという意味は文脈に合わない。"}], "explanations": {"成人": "大人の数が年々減る、と自然に通じる。", "季節": "形は合うが、季節の数が年々減るという意味は合わない。", "太陽": "形は合うが、太陽の数が減るという意味は合わない。", "山": "形は合うが、山の数が年々減るという意味は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "成人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "成人を三つ買って、家に帰った。", "explanation": "成人は人を指す語で、物として買うものには使えない。"}, {"text": "このゲームは成人指定で、子どもには売れない。", "explanation": "ここは年齢制限を表す〈成人指定〉の意味。大人になった人のことではない。"}, {"text": "私は成人を食べるのが好きだ。", "explanation": "成人は人を指す語で、食べ物には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52713, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "成人にってから、母の店を手伝っている。", "corrected_sentence": "成人になってから、母の店を手伝っている。", "error_description": "「成人になる」の「なって」の「な」が抜けて「にって」となっているのが誤り。「になってから」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52713, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "成人に人口が、年々増えている地域もある。", "corrected_sentence": "成人の人口が、年々増えている地域もある。", "error_description": "「人口」を修飾するので「の」を使う。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
