INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52715, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「うっかりしていると」の「と」で、条件を表して見落とすに続く。"}, {"text": "を", "is_correct": false, "explanation": "「うっかりしていを」は助詞の続き方が成り立たず、見落とすの目的語にもならない。"}, {"text": "に", "is_correct": false, "explanation": "位置や結果を示す助詞で、条件の意味が出ない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す助詞で、見落とすとは続かない。"}], "correct_answer": "と", "explanations": {"と": "「うっかりしていると」の「と」で、条件を表して見落とすに続く。", "を": "「うっかりしていを」は助詞の続き方が成り立たず、見落とすの目的語にもならない。", "に": "位置や結果を示す助詞で、条件の意味が出ない。", "で": "手段や場所を示す助詞で、見落とすとは続かない。"}, "error_tags": {"に": "位置・結果", "で": "手段・場所", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52715, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "見ようとしているのに、気がつかないこと。", "primary_collocate": null, "pronunciation": "みおとす", "ipa": "mi.otosɯ", "syllable_count": 4, "sentences": [{"text": "急いで読んだせいで、大事な注意書きを見落としてしまった。", "target_word": "見落として", "complexity_tier": "T3", "furigana": "急[いそ]いで読[よ]んだせいで、大事[だいじ]な注意書[ちゅういが]きを見落[みお]としてしまった。", "sentence_source": "generated"}, {"text": "かぎは机の上にあったのに、見落として一時間も探した。", "target_word": "見落として", "complexity_tier": "T3", "furigana": "かぎは机[つくえ]の上[うえ]にあったのに、見落[みお]として一時間[いちじかん]も探[さが]した。", "sentence_source": "generated"}, {"text": "検査で小さな傷を見落とすと、事故につながることがある。", "target_word": "見落とす", "complexity_tier": "T3", "furigana": "検査[けんさ]で小[ちい]さな傷[きず]を見落[みお]とすと、事故[じこ]につながることがある。", "sentence_source": "generated"}, {"text": "契約書の小さな文字を見落とさないように、よく読んだ。", "target_word": "見落とさない", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]の小[ちい]さな文字[もじ]を見落[みお]とさないように、よく読[よ]んだ。", "sentence_source": "generated"}, {"text": "道路標識を見落として、道を間違えてしまった。", "target_word": "見落として", "complexity_tier": "T3", "furigana": "道路[どうろ]標識[ひょうしき]を見落[みお]として、道[みち]を間違[まちが]えてしまった。", "sentence_source": "generated"}, {"text": "レポートのまちがいを何か所も見落としていた。", "target_word": "見落としていた", "complexity_tier": "T3", "furigana": "レポートのまちがいを何[なん]か所[しょ]も見落[みお]としていた。", "sentence_source": "generated"}, {"text": "医者は、写真に写った小さな影を見落としたことを謝った。", "target_word": "見落とした", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、写真[しゃしん]に写[うつ]った小[ちい]さな影[かげ]を見落[みお]としたことを謝[あやま]った。", "sentence_source": "generated"}, {"text": "この間違い探しは、うっかりしていると見落とす。", "target_word": "見落とす", "complexity_tier": "T3", "furigana": "この間違[まちが]い探[さが]しは、うっかりしていると見落[みお]とす。", "sentence_source": "generated"}, {"text": "駅の案内を見落とさないよう、先に地図で確認した。", "target_word": "見落とさない", "complexity_tier": "T3", "furigana": "駅[えき]の案内[あんない]を見落[みお]とさないよう、先[さき]に地図[ちず]で確認[かくにん]した。", "sentence_source": "generated"}, {"text": "彼は大切なメールを見落としたため、会議に遅れた。", "target_word": "見落とした", "complexity_tier": "T3", "furigana": "彼[かれ]は大切[たいせつ]なメールを見落[みお]としたため、会議[かいぎ]に遅[おく]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "見落とす", "label": "辞書形"}, {"form": "見落として", "label": "て形"}, {"form": "見落とした", "label": "過去形"}, {"form": "見落とさない", "label": "否定形"}, {"form": "見落とし", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "目に入っていたはずのものに気づかずに、見逃してしまう", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb3c610e-ed6d-44af-8078-e5a704484799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52715, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "見落として", "is_correct": true, "explanation": "て形。見落としてしまったと、後ろの「しまった」に続けて結果を述べる。"}, {"text": "見落とせ", "is_correct": false, "explanation": "命令形なので、「しまった」に続かず文として成立しない。"}, {"text": "見落とそう", "is_correct": false, "explanation": "意向形で、「しまった」と続けても文の意味が通らない。"}, {"text": "見落とし", "is_correct": false, "explanation": "連用形で、「しまった」とつながらず不完全な文になる。"}], "explanations": {"見落として": "て形。見落としてしまったと、後ろの「しまった」に続けて結果を述べる。", "見落とせ": "命令形なので、「しまった」に続かず文として成立しない。", "見落とそう": "意向形で、「しまった」と続けても文の意味が通らない。", "見落とし": "連用形で、「しまった」とつながらず不完全な文になる。"}, "sentence_index": 0, "correct_answer": "見落として"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "似た二つの石を見落として、正しく見分けた。", "explanation": "ここは〈見分ける〉の意味。見落とすは気づかないことで、違いを判別する意味は表さない。"}, {"text": "部屋の隅を見落として、全体を見渡した。", "explanation": "ここは〈見渡す〉の意味。見落とすは気づかないことで、広く眺める意味は表さない。"}, {"text": "将来の値上がりを見落として、早めに買っておいた。", "explanation": "ここは〈見越す〉の意味。見落とすは気づかないことで、先を予測する意味は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52715, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "見落とした", "is_correct": true, "explanation": "過去形。医者が見落としたことを謝ったという過去の事実として文を完結させる。"}, {"text": "見落とされ", "is_correct": false, "explanation": "受身の連用形で、文の目的語と主語が入れ替わり、文が完結しない。"}, {"text": "見落とさせ", "is_correct": false, "explanation": "使役の語幹で、人に見落とさせた意味になり、文意に合わない。"}, {"text": "見落とせば", "is_correct": false, "explanation": "仮定形で、条件節のまま「ことを謝った」に続かない。"}], "explanations": {"見落とした": "過去形。医者が見落としたことを謝ったという過去の事実として文を完結させる。", "見落とされ": "受身の連用形で、文の目的語と主語が入れ替わり、文が完結しない。", "見落とさせ": "使役の語幹で、人に見落とさせた意味になり、文意に合わない。", "見落とせば": "仮定形で、条件節のまま「ことを謝った」に続かない。"}, "sentence_index": 6, "correct_answer": "見落とした"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は、息子の出発を最後まで見落とした。", "explanation": "ここは〈見届ける〉の意味。見落とすは気づかないことで、最後まで注意して見続ける意味は表さない。"}, {"text": "答案を一問ずつ見落として、点数を上げた。", "explanation": "ここは〈見直す〉の意味。見落とすは気づかないことで、確認し直して直す行為は表さない。"}, {"text": "解決の糸口を見落として、すぐに見いだした。", "explanation": "ここは〈見いだす〉の意味。見落とすは気づかないことで、探して見つけ出す意味は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52715, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "注意書きが見落とさないよう、一つずつ読んだ。", "corrected_sentence": "注意書きを見落とさないよう、一つずつ読んだ。", "error_description": "助詞の誤り。見落とすは「〜を見落とす」と目的語を取るので、「注意書きが」は誤り。正しくは「注意書きを見落とさない」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "見落として", "is_correct": true, "explanation": "て形。探したという結果につながり、文として成立する。"}, {"text": "見落とさない", "is_correct": false, "explanation": "否定形で、見落とさないという反対の内容になり、探した流れと合わない。"}, {"text": "見落とせ", "is_correct": false, "explanation": "命令形で、「のに、」の後に続けると文が成り立たず、探した流れとも合わない。"}, {"text": "見落とそう", "is_correct": false, "explanation": "意向形で、探した事実と合わず、文の意味が通らない。"}], "correct_form": "見落として", "base_form": "見落とす", "form_label": "て形", "sentence_index": 1, "explanations": {"見落として": "て形。探したという結果につながり、文として成立する。", "見落とさない": "否定形で、見落とさないという反対の内容になり、探した流れと合わない。", "見落とせ": "命令形で、「のに、」の後に続けると文が成り立たず、探した流れとも合わない。", "見落とそう": "意向形で、探した事実と合わず、文の意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52715, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "念のため、契約書の数字を一つずつ見落とすずに確認した。", "corrected_sentence": "念のため、契約書の数字を一つずつ見落とさずに確認した。", "error_description": "活用の誤り。見落とすは五段活用なので、否定形は「見落とさず」。「見落とすず」は誤りで、正しくは「見落とさず」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "見落とす", "is_correct": true, "explanation": "辞書形。「うっかりしていると」という条件に続き、一般的な注意を述べる。"}, {"text": "見落とすな", "is_correct": false, "explanation": "命令形で、一般論の説明と合わない。"}, {"text": "見落としたら", "is_correct": false, "explanation": "過去の仮定形で、一般論として述べる文と合わず、文が完結しない。"}, {"text": "見落とされ", "is_correct": false, "explanation": "受身の連用形で、文が完結せず、一般論の説明にならない。"}], "correct_form": "見落とす", "base_form": "見落とす", "form_label": "辞書形", "sentence_index": 7, "explanations": {"見落とす": "辞書形。「うっかりしていると」という条件に続き、一般的な注意を述べる。", "見落とすな": "命令形で、一般論の説明と合わない。", "見落としたら": "過去の仮定形で、一般論として述べる文と合わず、文が完結しない。", "見落とされ": "受身の連用形で、文が完結せず、一般論の説明にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a2bba48-ec91-4a7b-954d-832d546dc711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
