INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52717, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生きていくために必要なもの。", "primary_collocate": null, "pronunciation": "かて", "ipa": "kate", "syllable_count": 2, "sentences": [{"text": "水は命の糧だ。", "target_word": "糧", "complexity_tier": "T1", "furigana": "水[みず]は命[いのち]の糧[かて]だ。", "sentence_source": "generated"}, {"text": "糧を分け合った。", "target_word": "糧", "complexity_tier": "T1", "furigana": "糧[かて]を分[わ]け合[あ]った。", "sentence_source": "generated"}, {"text": "食べ物は生きる糧です。", "target_word": "糧", "complexity_tier": "T2", "furigana": "食[た]べ物[もの]は生[い]きる糧[かて]です。", "sentence_source": "generated"}, {"text": "畑で育てた作物が、村の人々の糧になる。", "target_word": "糧", "complexity_tier": "T3", "furigana": "畑[はたけ]で育[そだ]てた作物[さくもつ]が、村[むら]の人々[ひとびと]の糧[かて]になる。", "sentence_source": "generated"}, {"text": "彼は旅に出て、糧を探した。", "target_word": "糧", "complexity_tier": "T2", "furigana": "彼[かれ]は旅[たび]に出[で]て、糧[かて]を探[さが]した。", "sentence_source": "generated"}, {"text": "干した魚が、冬の糧になった。", "target_word": "糧", "complexity_tier": "T3", "furigana": "干[ほ]した魚[さかな]が、冬[ふゆ]の糧[かて]になった。", "sentence_source": "generated"}, {"text": "糧が足りなくなって、村を出た。", "target_word": "糧", "complexity_tier": "T3", "furigana": "糧[かて]が足[た]りなくなって、村[むら]を出[で]た。", "sentence_source": "generated"}, {"text": "少ない糧でも、家族は笑っていた。", "target_word": "糧", "complexity_tier": "T3", "furigana": "少[すく]ない糧[かて]でも、家族[かぞく]は笑[わら]っていた。", "sentence_source": "generated"}, {"text": "乏しい米を糧として、旅を続けた。", "target_word": "糧", "complexity_tier": "T3", "furigana": "乏[とぼ]しい米[こめ]を糧[かて]として、旅[たび]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "人は糧がなければ、生きていけない。", "target_word": "糧", "complexity_tier": "T4", "furigana": "人[ひと]は糧[かて]がなければ、生[い]きていけない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "糧食", "label": "派生"}, {"form": "兵糧", "label": "派生"}, {"form": "糧秣", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 生きていくために必要なもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197d032-60fa-49db-8918-971d5b8c0885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52717, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "糧", "is_correct": true, "explanation": "見出し語「かて」そのもの。"}, {"text": "角", "is_correct": false, "explanation": "「かど」で、最後の音が「て」と違う。"}, {"text": "肩", "is_correct": false, "explanation": "「かた」で、最後の音が「て」と違う。"}, {"text": "金", "is_correct": false, "explanation": "「かね」で、最後の音が「て」と違う。"}, {"text": "亀", "is_correct": false, "explanation": "「かめ」で、最後の音が「て」と違う。"}], "explanations": {"糧": "見出し語「かて」そのもの。", "角": "「かど」で、最後の音が「て」と違う。", "肩": "「かた」で、最後の音が「て」と違う。", "金": "「かね」で、最後の音が「て」と違う。", "亀": "「かめ」で、最後の音が「て」と違う。"}, "sentence_index": null, "correct_answer": "糧"}, "level_3": {"options": [{"text": "糧", "is_correct": true, "explanation": "水は命に必要なものだ、という意味に合う。"}, {"text": "傘", "is_correct": false, "explanation": "形は合うが、水が命の傘だという意味が合わない。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、水が命の机だという意味が合わない。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが、水が命の靴だという意味が合わない。"}], "explanations": {"糧": "水は命に必要なものだ、という意味に合う。", "傘": "形は合うが、水が命の傘だという意味が合わない。", "机": "形は合うが、水が命の机だという意味が合わない。", "靴": "形は合うが、水が命の靴だという意味が合わない。"}, "sentence_index": 0, "correct_answer": "糧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、糧を磨いてから学校へ行く。", "explanation": "ここは〈器物などの具体物〉の意味で使っているが、糧は生きるための食べ物や支えを指すので『磨く』と合わない。"}, {"text": "糧は十時に家を出て、駅へ向かった。", "explanation": "「糧」を人のように主語にしており、語義が合わない。"}, {"text": "彼は糧を聞いて、とても眠くなった。", "explanation": "ここは〈話・音・情報〉の意味で使っているが、糧は食べ物や支えを指すので『聞く』と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXC