INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52718, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生命を維持するために必要な食べ物や、心の支えとなるもの。", "primary_collocate": null, "pronunciation": "かて", "ipa": "kate", "syllable_count": 2, "sentences": [{"text": "水という恩恵を糧に、草木は育つ。", "target_word": "糧", "complexity_tier": "T3", "furigana": "水[みず]という恩恵[おんけい]を糧[かて]に、草木[そうもく]は育[そだ]つ。", "sentence_source": "generated"}, {"text": "麦は人の糧だ。", "target_word": "糧", "complexity_tier": "T1", "furigana": "麦[むぎ]は人[ひと]の糧[かて]だ。", "sentence_source": "generated"}, {"text": "毎日の糧を得るために働く。", "target_word": "糧", "complexity_tier": "T3", "furigana": "毎日[まいにち]の糧[かて]を得[え]るために働[はたら]く。", "sentence_source": "generated"}, {"text": "旅の糧を袋に詰めた。", "target_word": "糧", "complexity_tier": "T2", "furigana": "旅[たび]の糧[かて]を袋[ふくろ]に詰[つ]めた。", "sentence_source": "generated"}, {"text": "本は、心の糧になる。", "target_word": "糧", "complexity_tier": "T2", "furigana": "本[ほん]は、心[こころ]の糧[かて]になる。", "sentence_source": "generated"}, {"text": "失敗を糧にして、また挑戦した。", "target_word": "糧", "complexity_tier": "T3", "furigana": "失敗[しっぱい]を糧[かて]にして、また挑戦[ちょうせん]した。", "sentence_source": "generated"}, {"text": "読書は私にとって大切な心の糧だ。", "target_word": "糧", "complexity_tier": "T3", "furigana": "読書[どくしょ]は私[わたし]にとって大切[たいせつ]な心[こころ]の糧[かて]だ。", "sentence_source": "generated"}, {"text": "わずかな糧で、冬を越した。", "target_word": "糧", "complexity_tier": "T2", "furigana": "わずかな糧[かて]で、冬[ふゆ]を越[こ]した。", "sentence_source": "generated"}, {"text": "糧を求めて、人々は町へ向かった。", "target_word": "糧", "complexity_tier": "T3", "furigana": "糧[かて]を求[もと]めて、人々[ひとびと]は町[まち]へ向[む]かった。", "sentence_source": "generated"}, {"text": "経験こそが、人を育てる糧である。", "target_word": "糧", "complexity_tier": "T3", "furigana": "経験[けいけん]こそが、人[ひと]を育[そだ]てる糧[かて]である。", "sentence_source": "generated"}], "morphological_forms": [{"form": "糧食", "label": "派生"}, {"form": "兵糧", "label": "派生"}, {"form": "糧秣", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 命を保つ食べ物や心の支え", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197d032-60fa-49db-8918-971d5b8c0885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
