INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52719, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「川底を深める」で、深くする対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "他動詞「深める」の対象に「が」は使えない。"}, {"text": "の", "is_correct": false, "explanation": "「川底の深めて」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「川底と深めて」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「川底を深める」で、深くする対象を示す。", "が": "他動詞「深める」の対象に「が」は使えない。", "の": "「川底の深めて」は文として成り立たない。", "と": "「川底と深めて」は文として成り立たない。"}, "error_tags": {"が": "subject", "の": "possessive", "と": "conjunction"}, "sentence_index": 3}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浅める", "is_correct": true, "explanation": "深くするのと逆に、浅くする。"}, {"text": "掘る", "is_correct": false, "explanation": "深くする方向で、反対ではない。"}, {"text": "広げる", "is_correct": false, "explanation": "幅を増やす意味で、深さの反対ではない。"}, {"text": "磨く", "is_correct": false, "explanation": "深さとは関係がなく、反対でもない。"}], "correct_answer": "浅める", "explanations": {"浅める": "深くするのと逆に、浅くする。", "掘る": "深くする方向で、反対ではない。", "広げる": "幅を増やす意味で、深さの反対ではない。", "磨く": "深さとは関係がなく、反対でもない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52719, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「穴を深める」で、深くする対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "他動詞「深める」の対象に「が」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「穴へ深めすぎない」は文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「穴に深めすぎない」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「穴を深める」で、深くする対象を示す。", "が": "他動詞「深める」の対象に「が」は使えない。", "へ": "「穴へ深めすぎない」は文として成り立たない。", "に": "「穴に深めすぎない」は文として成り立たない。"}, "error_tags": {"が": "subject", "へ": "direction", "に": "target"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浅める", "is_correct": true, "explanation": "深くするのと逆に、浅くする。"}, {"text": "作る", "is_correct": false, "explanation": "穴を作るのは、深さの反対ではない。"}, {"text": "伸ばす", "is_correct": false, "explanation": "長さを増やす意味で、深さの反対ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "深さとは関係がなく、反対でもない。"}], "correct_answer": "浅める", "explanations": {"浅める": "深くするのと逆に、浅くする。", "作る": "穴を作るのは、深さの反対ではない。", "伸ばす": "長さを増やす意味で、深さの反対ではない。", "運ぶ": "深さとは関係がなく、反対でもない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52719, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを、もっとふかくする。", "primary_collocate": null, "pronunciation": "ふかめる", "ipa": "ɸɯkameɾɯ", "syllable_count": 4, "sentences": [{"text": "穴を深める。", "target_word": "深める", "complexity_tier": "T1", "furigana": "穴[あな]を深[ふか]める。", "sentence_source": "generated"}, {"text": "池を深めます。", "target_word": "深めます", "complexity_tier": "T1", "furigana": "池[いけ]を深[ふか]めます。", "sentence_source": "generated"}, {"text": "溝をもう少し深めた。", "target_word": "深めた", "complexity_tier": "T2", "furigana": "溝[みぞ]をもう少[すこ]し深[ふか]めた。", "sentence_source": "generated"}, {"text": "川底を深めて、船を通した。", "target_word": "深めて", "complexity_tier": "T3", "furigana": "川底[かわぞこ]を深[ふか]めて、船[ふね]を通[とお]した。", "sentence_source": "generated"}, {"text": "水をためるため、穴を深めている。", "target_word": "深めている", "complexity_tier": "T3", "furigana": "水[みず]をためるため、穴[あな]を深[ふか]めている。", "sentence_source": "generated"}, {"text": "もっと穴を深めれば、水が出るだろう。", "target_word": "深めれば", "complexity_tier": "T3", "furigana": "もっと穴[あな]を深[ふか]めれば、水[みず]が出[で]るだろう。", "sentence_source": "generated"}, {"text": "畑の溝を深めたので、水がよく流れる。", "target_word": "深めた", "complexity_tier": "T4", "furigana": "畑[はたけ]の溝[みぞ]を深[ふか]めたので、水[みず]がよく流[なが]れる。", "sentence_source": "generated"}, {"text": "穴を深めすぎないように、気をつけた。", "target_word": "深めすぎない", "complexity_tier": "T4", "furigana": "穴[あな]を深[ふか]めすぎないように、気[き]をつけた。", "sentence_source": "generated"}, {"text": "池を深められる業者を探した。", "target_word": "深められる", "complexity_tier": "T3", "furigana": "池[いけ]を深[ふか]められる業者[ぎょうしゃ]を探[さが]した。", "sentence_source": "generated"}, {"text": "父は作業員に庭の穴を深めさせた。", "target_word": "深めさせた", "complexity_tier": "T3", "furigana": "父[ちち]は作業員[さぎょういん]に庭[にわ]の穴[あな]を深[ふか]めさせた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "深めた", "label": "活用"}, {"form": "深めて", "label": "活用"}, {"form": "深められる", "label": "活用"}, {"form": "深まる", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 物をもっと深くする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197d032-60fa-49db-8918-971d5b8c0885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52719, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "深める", "is_correct": true, "explanation": "見出し語「ふかめる」そのもの。"}, {"text": "しかめる", "is_correct": false, "explanation": "「顰める」で、最初の音が「ふ」と違う。"}, {"text": "含める", "is_correct": false, "explanation": "「ふくめる」で、2音目が「か」と違う。"}, {"text": "吹かれる", "is_correct": false, "explanation": "「ふかれる」で、3音目が「め」と違う。"}, {"text": "吹かせる", "is_correct": false, "explanation": "「ふかせる」で、3音目が「め」と違う。"}], "explanations": {"深める": "見出し語「ふかめる」そのもの。", "しかめる": "「顰める」で、最初の音が「ふ」と違う。", "含める": "「ふくめる」で、2音目が「か」と違う。", "吹かれる": "「ふかれる」で、3音目が「め」と違う。", "吹かせる": "「ふかせる」で、3音目が「め」と違う。"}, "sentence_index": null, "correct_answer": "深める"}, "level_3": {"options": [{"text": "深める", "is_correct": true, "explanation": "穴をもっと深くする、という意味に合う。"}, {"text": "食べる", "is_correct": false, "explanation": "形は合うが、穴を食べるという意味が合わない。"}, {"text": "着る", "is_correct": false, "explanation": "形は合うが、穴を着るという意味が合わない。"}, {"text": "歌う", "is_correct": false, "explanation": "形は合うが、穴を歌うという意味が合わない。"}], "explanations": {"深める": "穴をもっと深くする、という意味に合う。", "食べる": "形は合うが、穴を食べるという意味が合わない。", "着る": "形は合うが、穴を着るという意味が合わない。", "歌う": "形は合うが、穴を歌うという意味が合わない。"}, "sentence_index": 0, "correct_answer": "深める"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友情を深めて、船を通した。", "explanation": "『深める』を〈友情などの程度を進める〉意味で使っているが、船を通す文脈は川底を深くする意味が必要で合わない。"}, {"text": "橋を深めて、船を通した。", "explanation": "『深める』を〈川底などの深さを増す〉意味で使っているが、橋は深さを増す対象にならない。"}, {"text": "山を深めて、船を通した。", "explanation": "『深める』を〈地面などの深さを増す〉意味で使っているが、山は深くする対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52719, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深めた", "is_correct": true, "explanation": "溝を深くしたので水が流れる、という意味に合う。"}, {"text": "履いた", "is_correct": false, "explanation": "形は合うが、溝を履いたという意味が合わない。"}, {"text": "歌った", "is_correct": false, "explanation": "形は合うが、溝を歌ったという意味が合わない。"}, {"text": "着た", "is_correct": false, "explanation": "形は合うが、溝を着たという意味が合わない。"}], "explanations": {"深めた": "溝を深くしたので水が流れる、という意味に合う。", "履いた": "形は合うが、溝を履いたという意味が合わない。", "歌った": "形は合うが、溝を歌ったという意味が合わない。", "着た": "形は合うが、溝を着たという意味が合わない。"}, "sentence_index": 6, "correct_answer": "深めた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は庭の木を深めさせた。", "explanation": "『深める』を〈地面などの深さを増す〉意味で使っているが、木は深くする対象にならない。"}, {"text": "父は庭の壁を深めさせた。", "explanation": "『深める』を〈地面などの深さを増す〉意味で使っているが、壁は深くする対象にならない。"}, {"text": "父は庭の理解を深めさせた。", "explanation": "『深める』を〈理解などの程度を進める〉意味で使っているが、ここは庭の穴を深くする話なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52719, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "井戸が深めて、水を得た。", "corrected_sentence": "井戸を深めて、水を得た。", "error_description": "「深める」は他動詞なので、対象には「を」を使う。「井戸が」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "深めます", "is_correct": true, "explanation": "丁寧な文末として自然。"}, {"text": "深めて", "is_correct": false, "explanation": "て形は文を終えられない。"}, {"text": "深めれば", "is_correct": false, "explanation": "仮定形は文を終えられない。"}, {"text": "深めさせ", "is_correct": false, "explanation": "使役の連用形で、文末にならない。"}], "correct_form": "深めます", "base_form": "深める", "form_label": "ます形", "sentence_index": 1, "explanations": {"深めます": "丁寧な文末として自然。", "深めて": "て形は文を終えられない。", "深めれば": "仮定形は文を終えられない。", "深めさせ": "使役の連用形で、文末にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52719, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "穴を深めるに、スコップを使った。", "corrected_sentence": "穴を深めるのに、スコップを使った。", "error_description": "目的を表すには「深めるのに」とする。「深めるに」は不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "深めすぎない", "is_correct": true, "explanation": "「ように」に続き、やりすぎない意味になる。"}, {"text": "深めすぎて", "is_correct": false, "explanation": "「深めすぎてように」とは続けられない。"}, {"text": "深めすぎれば", "is_correct": false, "explanation": "「深めすぎればように」とは続けられない。"}, {"text": "深めすぎ", "is_correct": false, "explanation": "連用形で、「ように」に直接続かない。"}], "correct_form": "深めすぎない", "base_form": "深める", "form_label": "ない形", "sentence_index": 7, "explanations": {"深めすぎない": "「ように」に続き、やりすぎない意味になる。", "深めすぎて": "「深めすぎてように」とは続けられない。", "深めすぎれば": "「深めすぎればように」とは続けられない。", "深めすぎ": "連用形で、「ように」に直接続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
