INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52720, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事の程度や内容を、よりいっそう進んだ状態にする。", "primary_collocate": null, "pronunciation": "ふかめる", "ipa": "ɸɯkameɾɯ", "syllable_count": 4, "sentences": [{"text": "雨を受けて、緑を深めていく。", "target_word": "深めて", "complexity_tier": "T2", "furigana": "雨[あめ]を受[う]けて、緑[みどり]を深[ふか]めていく。", "sentence_source": "generated"}, {"text": "知識を深める。", "target_word": "深める", "complexity_tier": "T1", "furigana": "知識[ちしき]を深[ふか]める。", "sentence_source": "generated"}, {"text": "理解を深めました。", "target_word": "深めました", "complexity_tier": "T2", "furigana": "理解[りかい]を深[ふか]めました。", "sentence_source": "generated"}, {"text": "友情を深めている。", "target_word": "深めている", "complexity_tier": "T2", "furigana": "友情[ゆうじょう]を深[ふか]めている。", "sentence_source": "generated"}, {"text": "読書で、知識を深めたい。", "target_word": "深めたい", "complexity_tier": "T3", "furigana": "読書[どくしょ]で、知識[ちしき]を深[ふか]めたい。", "sentence_source": "generated"}, {"text": "話し合えば、お互いの理解を深められる。", "target_word": "深められる", "complexity_tier": "T4", "furigana": "話[はな]し合[あ]えば、お互[たが]いの理解[りかい]を深[ふか]められる。", "sentence_source": "generated"}, {"text": "二人は旅を通して、絆を深めた。", "target_word": "深めた", "complexity_tier": "T3", "furigana": "二人[ふたり]は旅[たび]を通[とお]して、絆[きずな]を深[ふか]めた。", "sentence_source": "generated"}, {"text": "疑いを深めないよう、早く説明した。", "target_word": "深めない", "complexity_tier": "T4", "furigana": "疑[うたが]いを深[ふか]めないよう、早[はや]く説明[せつめい]した。", "sentence_source": "generated"}, {"text": "議論を深めるために、資料を集めた。", "target_word": "深める", "complexity_tier": "T4", "furigana": "議論[ぎろん]を深[ふか]めるために、資料[しりょう]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "交流を深めさせてもらい、感謝しています。", "target_word": "深めさせて", "complexity_tier": "T4", "furigana": "交流[こうりゅう]を深[ふか]めさせてもらい、感謝[かんしゃ]しています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "深めた", "label": "活用"}, {"form": "深めて", "label": "活用"}, {"form": "深められる", "label": "活用"}, {"form": "深まる", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 物事の程度や内容をより進める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197d032-60fa-49db-8918-971d5b8c0885') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52720, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深めて", "is_correct": true, "explanation": "緑の度合いを進める意味に合い、「いく」に続く形。"}, {"text": "閉じて", "is_correct": false, "explanation": "形は合うが、緑を閉じていくという意味が合わない。"}, {"text": "弾いて", "is_correct": false, "explanation": "形は合うが、緑を弾いていくという意味が合わない。"}, {"text": "履いて", "is_correct": false, "explanation": "形は合うが、緑を履いていくという意味が合わない。"}], "explanations": {"深めて": "緑の度合いを進める意味に合い、「いく」に続く形。", "閉じて": "形は合うが、緑を閉じていくという意味が合わない。", "弾いて": "形は合うが、緑を弾いていくという意味が合わない。", "履いて": "形は合うが、緑を履いていくという意味が合わない。"}, "sentence_index": 0, "correct_answer": "深めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机を深めて部屋を片付けた。", "explanation": "ここは〈物の深さを増す〉意味で使っているが、机は深くする対象にならない。"}, {"text": "ご飯を深めてから出かけた。", "explanation": "ここは〈物の深さを増す〉意味で使っているが、ご飯は深くする対象にならない。"}, {"text": "政府は魚を深めた。", "explanation": "「魚」は程度や内容の対象にならず、語義が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52720, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深めた", "is_correct": true, "explanation": "絆の度合いを進めた、という意味に合う。"}, {"text": "履いた", "is_correct": false, "explanation": "形は合うが、絆を履いたという意味が合わない。"}, {"text": "閉じた", "is_correct": false, "explanation": "形は合うが、絆を閉じたという意味が合わない。"}, {"text": "干した", "is_correct": false, "explanation": "形は合うが、絆を干したという意味が合わない。"}], "explanations": {"深めた": "絆の度合いを進めた、という意味に合う。", "履いた": "形は合うが、絆を履いたという意味が合わない。", "閉じた": "形は合うが、絆を閉じたという意味が合わない。", "干した": "形は合うが、絆を干したという意味が合わない。"}, "sentence_index": 6, "correct_answer": "深めた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "靴を深めさせて、玄関に置いた。", "explanation": "ここは〈物の深さを増す〉意味で使っているが、靴は深くする対象にならない。"}, {"text": "電車を深めさせて、会社に着いた。", "explanation": "ここは〈物の深さを増す〉意味で使っているが、電車は深くする対象にならない。"}, {"text": "彼は昨日の夕飯を深めた。", "explanation": "ここは〈味などを深める〉の意味で使っているが、夕飯はその対象にならず、語義が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52720, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "対話を通じて、相互理解を深まった。", "corrected_sentence": "対話を通じて、相互理解を深めた。", "error_description": "「深まる」は自動詞で「を」を取れない。他動詞の「深めた」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "深める", "is_correct": true, "explanation": "文末の終止形として自然。"}, {"text": "深めて", "is_correct": false, "explanation": "て形は文を終えられない。"}, {"text": "深めれば", "is_correct": false, "explanation": "仮定形は文を終えられない。"}, {"text": "深めさせ", "is_correct": false, "explanation": "使役の連用形で、文末にならない。"}], "correct_form": "深める", "base_form": "深める", "form_label": "辞書形", "sentence_index": 1, "explanations": {"深める": "文末の終止形として自然。", "深めて": "て形は文を終えられない。", "深めれば": "仮定形は文を終えられない。", "深めさせ": "使役の連用形で、文末にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52720, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "互いの信頼が深めて、仕事がうまくいった。", "corrected_sentence": "互いの信頼を深めて、仕事がうまくいった。", "error_description": "「深める」は他動詞なので、対象には「を」を使う。「信頼が」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "深めない", "is_correct": true, "explanation": "「よう」に続き、疑いを増やさない意味になる。"}, {"text": "深めた", "is_correct": false, "explanation": "過去形で、「よう」に続けられず、疑いを増やさない意味にならない。"}, {"text": "深めよう", "is_correct": false, "explanation": "意向形で、「よう」を重ねると文が成り立たず、疑いを増やさない意味にならない。"}, {"text": "深め", "is_correct": false, "explanation": "連用形で文を終えられず、「ないよう」の形にならない。"}], "correct_form": "深めない", "base_form": "深める", "form_label": "ない形", "sentence_index": 7, "explanations": {"深めない": "「よう」に続き、疑いを増やさない意味になる。", "深めた": "過去形で、「よう」に続けられず、疑いを増やさない意味にならない。", "深めよう": "意向形で、「よう」を重ねると文が成り立たず、疑いを増やさない意味にならない。", "深め": "連用形で文を終えられず、「ないよう」の形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec557d48-6975-4125-a84d-f46f0b2a4ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52721, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "童子が遊ぶ主体（主語）を示す。「遊んでいた」の主語として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「遊ぶ」は目的語を取らない使い方なので、童子に「を」を付けると文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や帰着点を示すが、ここで童子は遊ぶ主体なので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、遊んでいる主体の童子には付かない。"}], "correct_answer": "が", "explanations": {"が": "童子が遊ぶ主体（主語）を示す。「遊んでいた」の主語として正しい。", "を": "「遊ぶ」は目的語を取らない使い方なので、童子に「を」を付けると文が成り立たない。", "に": "「に」は相手や帰着点を示すが、ここで童子は遊ぶ主体なので合わない。", "へ": "「へ」は方向を示すので、遊んでいる主体の童子には付かない。"}, "error_tags": {"を": "対象", "に": "相手・帰着点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52721, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52721, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "子どものことです。", "primary_collocate": null, "pronunciation": "どうじ", "ipa": "doːdʑi", "syllable_count": 3, "sentences": [{"text": "昔話に出てくる童子は、いつも元気に野山を走り回っている。", "target_word": "童子", "complexity_tier": "T3", "furigana": "昔話(むかしばなし)に出(で)てくる童子(どうじ)は、いつも元気(げんき)に野山(のやま)を走(はし)り回(まわ)っている。", "sentence_source": "generated"}, {"text": "童子が川で遊んでいたので、母親は心配して迎えに行った。", "target_word": "童子", "complexity_tier": "T3", "furigana": "童子(どうじ)が川(かわ)で遊(あそ)んでいたので、母親(ははおや)は心配(しんぱい)して迎(むか)えに行(い)った。", "sentence_source": "generated"}, {"text": "絵の中の童子は、小さな手で大きな鯉をつかんでいる。", "target_word": "童子", "complexity_tier": "T3", "furigana": "絵(え)の中(なか)の童子(どうじ)は、小(ちい)さな手(て)で大(おお)きな鯉(こい)をつかんでいる。", "sentence_source": "generated"}, {"text": "祭りの夜、白い着物を着た童子が提灯を持って歩いていた。", "target_word": "童子", "complexity_tier": "T3", "furigana": "祭(まつ)りの夜(よる)、白(しろ)い着物(きもの)を着(き)た童子(どうじ)が提灯(ちょうちん)を持(も)って歩(ある)いていた。", "sentence_source": "generated"}, {"text": "童子の笑い声が聞こえて、村の人たちは思わず足を止めた。", "target_word": "童子", "complexity_tier": "T3", "furigana": "童子(どうじ)の笑(わら)い声(ごえ)が聞(き)こえて、村(むら)の人(ひと)たちは思(おも)わず足(あし)を止(と)めた。", "sentence_source": "generated"}, {"text": "おじいさんは、道ばたで泣いている童子に飴をあげた。", "target_word": "童子", "complexity_tier": "T3", "furigana": "おじいさんは、道(みち)ばたで泣(な)いている童子(どうじ)に飴(あめ)をあげた。", "sentence_source": "generated"}, {"text": "山道で出会った童子は、道に迷った旅人を村まで案内した。", "target_word": "童子", "complexity_tier": "T3", "furigana": "山道(やまみち)で出会(であ)った童子(どうじ)は、道(みち)に迷(まよ)った旅人(たびびと)を村(むら)まで案内(あんない)した。", "sentence_source": "generated"}, {"text": "昔の人は、童子は神様に守られていると信じていた。", "target_word": "童子", "complexity_tier": "T3", "furigana": "昔(むかし)の人(ひと)は、童子(どうじ)は神様(かみさま)に守(まも)られていると信(しん)じていた。", "sentence_source": "generated"}, {"text": "この掛け軸には、笛を吹く童子が優しい筆で描かれている。", "target_word": "童子", "complexity_tier": "T3", "furigana": "この掛(か)け軸(じく)には、笛(ふえ)を吹(ふ)く童子(どうじ)が優(やさ)しい筆(ふで)で描(えが)かれている。", "sentence_source": "generated"}, {"text": "童子は恥ずかしそうに、母親の後ろに隠れてしまった。", "target_word": "童子", "complexity_tier": "T3", "furigana": "童子(どうじ)は恥(は)ずかしそうに、母親(ははおや)の後(うし)ろに隠(かく)れてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "童子", "label": "基本形"}, {"form": "童子たち", "label": "複数"}], "register": "文章語", "sense_fingerprint": "童子：子ども全般を指すやや古風な語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ac7907-efd1-469f-94eb-3a83e671f0a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52721, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "童子", "is_correct": true, "explanation": "野山を元気に走り回る主体で、昔話に出る子どもを指すので文脈に合う。"}, {"text": "雲", "is_correct": false, "explanation": "雲は野山を走り回る主体になれないので、この文の主語として合わない。"}, {"text": "石", "is_correct": false, "explanation": "石は自分で走り回らないので、元気に走る主語としては合わない。"}, {"text": "波", "is_correct": false, "explanation": "波は野山を走り回らないので、この文の主語には合わない。"}], "explanations": {"童子": "野山を元気に走り回る主体で、昔話に出る子どもを指すので文脈に合う。", "雲": "雲は野山を走り回る主体になれないので、この文の主語として合わない。", "石": "石は自分で走り回らないので、元気に走る主語としては合わない。", "波": "波は野山を走り回らないので、この文の主語には合わない。"}, "sentence_index": 0, "correct_answer": "童子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村で一番の童子と呼ばれたその老職人は、今も現役で仕事をしている。", "explanation": "ここは〈子ども〉の意味。童子に〈名人〉の意味はなく、年配の職人には使えない。"}, {"text": "大人の童子たちが、会社の会議室で夜遅くまで予算の話し合いを続けた。", "explanation": "〈子ども〉の語を、〈成人〉の意味で使った誤り。童子は子どもを指すので、成人の集まりには使えない。"}, {"text": "その童子は、大学で長年研究を続けてきた教授だ。", "explanation": "〈学者〉の意味で童子を使った誤り。童子は子どもを指すので、学問の専門家には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52721, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "童子", "is_correct": true, "explanation": "山道で出会い旅人を案内する主体で、子どもを指すので文脈に合う。"}, {"text": "花", "is_correct": false, "explanation": "花は人を村まで案内しないので、この文の主語として合わない。"}, {"text": "岩", "is_correct": false, "explanation": "岩は旅人を案内する主体になれないので合わない。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は道に迷った旅人を案内できないので、この文には合わない。"}], "explanations": {"童子": "山道で出会い旅人を案内する主体で、子どもを指すので文脈に合う。", "花": "花は人を村まで案内しないので、この文の主語として合わない。", "岩": "岩は旅人を案内する主体になれないので合わない。", "椅子": "椅子は道に迷った旅人を案内できないので、この文には合わない。"}, "sentence_index": 6, "correct_answer": "童子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの童子は、毎朝駅前で新聞を売っている店の店長だ。", "explanation": "〈店主〉の意味で童子を使った誤り。童子は職業や役職を表さないので合わない。"}, {"text": "その童子は、長い白い髭を生やした老人で、村人に親しまれている。", "explanation": "〈老人〉の代わりに童子を使った誤り。童子は子どもを指すので、年配の人には使わない。"}, {"text": "部長の童子は、会議で新しい予算案を説明した。", "explanation": "〈管理職〉の意味で童子を使った誤り。童子は職務を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52721, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "童子を、いつも元気に野山を走り回っていた。", "corrected_sentence": "童子は、いつも元気に野山を走り回っていた。", "error_description": "主題を示す「は」を目的語の「を」にした誤り。「走り回る」は目的語を取らないので、童子には「は」（または「が」）が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52721, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "童子を寺の庭で掃除をしていた。", "corrected_sentence": "童子が寺の庭で掃除をしていた。", "error_description": "動作をする主語の「童子」に「を」（目的語）を付けた誤り。掃除をするのは童子なので「が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52722, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "桃から生まれた童子を話題（主題）として示す。「育った」の主題として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「育つ」は目的語を取らない自動詞なので、童子に「を」を付けると文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や帰着点を示すが、「童子に、立派な若者に育った」では童子が育つ主体にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、育つ主体の童子には付かない。"}], "correct_answer": "は", "explanations": {"は": "桃から生まれた童子を話題（主題）として示す。「育った」の主題として正しい。", "を": "「育つ」は目的語を取らない自動詞なので、童子に「を」を付けると文が成り立たない。", "に": "「に」は相手や帰着点を示すが、「童子に、立派な若者に育った」では童子が育つ主体にならず不自然。", "へ": "「へ」は方向を示すので、育つ主体の童子には付かない。"}, "error_tags": {"を": "対象", "に": "相手・帰着点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52722, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "馬に乗った童子が描かれる対象（主語）を示す。「描かれている」の主語として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「描かれている」は受身なので、童子に「を」を付けると文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示し、描かれる主体の童子には付かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、描かれる主体の童子には付かない。"}], "correct_answer": "が", "explanations": {"が": "馬に乗った童子が描かれる対象（主語）を示す。「描かれている」の主語として正しい。", "を": "「描かれている」は受身なので、童子に「を」を付けると文が成り立たない。", "で": "「で」は場所や手段を示し、描かれる主体の童子には付かない。", "へ": "「へ」は方向を示すが、描かれる主体の童子には付かない。"}, "error_tags": {"を": "対象", "で": "手段・場所", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52722, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "幼い子ども、特に男の子を指す言葉です。", "primary_collocate": null, "pronunciation": "どうじ", "ipa": "doːdʑi", "syllable_count": 3, "sentences": [{"text": "寺では、まだ十歳ぐらいの童子が、毎朝庭を掃いている。", "target_word": "童子", "complexity_tier": "T3", "furigana": "寺(てら)では、まだ十歳(じゅっさい)ぐらいの童子(どうじ)が、毎朝(まいあさ)庭(にわ)を掃(は)いている。", "sentence_source": "generated"}, {"text": "桃から生まれた童子は、立派な若者に育った。", "target_word": "童子", "complexity_tier": "T3", "furigana": "桃(もも)から生(う)まれた童子(どうじ)は、立派(りっぱ)な若者(わかもの)に育(そだ)った。", "sentence_source": "generated"}, {"text": "和尚さんは、お茶を運んできた童子に礼を言った。", "target_word": "童子", "complexity_tier": "T3", "furigana": "和尚(おしょう)さんは、お茶(ちゃ)を運(はこ)んできた童子(どうじ)に礼(れい)を言(い)った。", "sentence_source": "generated"}, {"text": "童子は師匠の言葉を聞き、まじめな顔でうなずいた。", "target_word": "童子", "complexity_tier": "T3", "furigana": "童子(どうじ)は師匠(ししょう)の言葉(ことば)を聞(き)き、まじめな顔(かお)でうなずいた。", "sentence_source": "generated"}, {"text": "髪を短く切った童子が、父親の隣で弓の稽古をしている。", "target_word": "童子", "complexity_tier": "T3", "furigana": "髪(かみ)を短(みじか)く切(き)った童子(どうじ)が、父親(ちちおや)の隣(となり)で弓(ゆみ)の稽古(けいこ)をしている。", "sentence_source": "generated"}, {"text": "山の神様のそばには、赤い服を着た童子が二人立っていた。", "target_word": "童子", "complexity_tier": "T3", "furigana": "山(やま)の神様(かみさま)のそばには、赤(あか)い服(ふく)を着(き)た童子(どうじ)が二人(ふたり)立(た)っていた。", "sentence_source": "generated"}, {"text": "あの童子は、ほかの男の子より背が低いが、足がとても速い。", "target_word": "童子", "complexity_tier": "T3", "furigana": "あの童子(どうじ)は、ほかの男(おとこ)の子(こ)より背(せ)が低(ひく)いが、足(あし)がとても速(はや)い。", "sentence_source": "generated"}, {"text": "屏風には、馬に乗った童子が堂々と描かれている。", "target_word": "童子", "complexity_tier": "T3", "furigana": "屏風(びょうぶ)には、馬(うま)に乗(の)った童子(どうじ)が堂々(どうどう)と描(えが)かれている。", "sentence_source": "generated"}, {"text": "夜になっても、童子は眠らずに師匠の帰りを待っていた。", "target_word": "童子", "complexity_tier": "T3", "furigana": "夜(よる)になっても、童子(どうじ)は眠(ねむ)らずに師匠(ししょう)の帰(かえ)りを待(ま)っていた。", "sentence_source": "generated"}, {"text": "童子の元気な声が、静かな寺の庭に響いた。", "target_word": "童子", "complexity_tier": "T3", "furigana": "童子(どうじ)の元気(げんき)な声(こえ)が、静(しず)かな寺(てら)の庭(にわ)に響(ひび)いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "童子", "label": "基本形"}, {"form": "童子たち", "label": "複数"}], "register": "文章語", "sense_fingerprint": "童子：幼い男の子。寺や昔話に出てくる少年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61ac7907-efd1-469f-94eb-3a83e671f0a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52722, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "童子", "is_correct": true, "explanation": "十歳ぐらいの子どもで、毎朝庭を掃く主体として文脈に合う。"}, {"text": "扉", "is_correct": false, "explanation": "扉は十歳ぐらいの子どもではなく、庭を掃くこともできないので合わない。"}, {"text": "鉢", "is_correct": false, "explanation": "鉢は自分で庭を掃かないので、この文の主語として合わない。"}, {"text": "石灯籠", "is_correct": false, "explanation": "石灯籠は年齢を持たず、庭を掃く動作もしないので合わない。"}], "explanations": {"童子": "十歳ぐらいの子どもで、毎朝庭を掃く主体として文脈に合う。", "扉": "扉は十歳ぐらいの子どもではなく、庭を掃くこともできないので合わない。", "鉢": "鉢は自分で庭を掃かないので、この文の主語として合わない。", "石灯籠": "石灯籠は年齢を持たず、庭を掃く動作もしないので合わない。"}, "sentence_index": 0, "correct_answer": "童子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その童子は、職人歴三十年の熟練者で、弟子を何人も持つ。", "explanation": "〈名人〉の意味で童子を使った誤り。童子は幼い男の子を指すので、腕の立つ大人には使えない。"}, {"text": "童子は、教室の前で子どもたちに算数を教えた先生だ。", "explanation": "〈教師〉の意味で童子を使った誤り。童子は子どもを指すので、大人の教職には使えない。"}, {"text": "その童子は、毎朝会社に通って、部下に仕事の指示を出している。", "explanation": "〈勤め人〉の意味で童子を使った誤り。童子は子どもを指すので、職場に勤める大人には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52722, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "童子", "is_correct": true, "explanation": "ほかの男の子と比べて背が低いが足が速い、と男の子として比べられる主体なので合う。"}, {"text": "机", "is_correct": false, "explanation": "机は足が速く走るものではなく、男の子と背丈を比べる文にも合わない。"}, {"text": "花", "is_correct": false, "explanation": "花は足が速いとは言えず、男の子と背丈を比べる対象にもならないので合わない。"}, {"text": "岩", "is_correct": false, "explanation": "岩は足を持たず速く走らないので、この文の主語として合わない。"}], "explanations": {"童子": "ほかの男の子と比べて背が低いが足が速い、と男の子として比べられる主体なので合う。", "机": "机は足が速く走るものではなく、男の子と背丈を比べる文にも合わない。", "花": "花は足が速いとは言えず、男の子と背丈を比べる対象にもならないので合わない。", "岩": "岩は足を持たず速く走らないので、この文の主語として合わない。"}, "sentence_index": 6, "correct_answer": "童子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その童子は、寺の財政を預かる会計の責任者だ。", "explanation": "〈経理係〉の意味で童子を使った誤り。童子は子どもを指すので、お金を扱う職務には合わない。"}, {"text": "その女性の童子は、寺の庭で静かに花を育てていた。", "explanation": "〈婦人〉の意味で童子を使った誤り。童子は幼い男の子を指すので、成人の婦人には使えない。"}, {"text": "その童子は、寺の庭で吠えて番をしていた。", "explanation": "〈犬〉の代わりに童子を使った誤り。童子は人の子を指すので動物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52722, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "童子を、朝早く寺の庭で鐘をついていた。", "corrected_sentence": "童子が、朝早く寺の庭で鐘をついていた。", "error_description": "鐘をつく主語の「童子」に「を」（目的語）を付けた誤り。主語には「が」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52722, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "童子に、寺の門の前で師匠の帰りを待っていた。", "corrected_sentence": "童子は、寺の門の前で師匠の帰りを待っていた。", "error_description": "「童子」に付いた「に」（方向・相手）が誤り。「待つ」の主体である童子には「は」（または「が」）が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0834fbe6-2a4d-4645-8e0a-c4a32da14127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52723, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「慈愛のある人」で、慈愛が人を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「慈愛をある」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「ある人」につながらない。"}, {"text": "から", "is_correct": false, "explanation": "起点の助詞で、「慈愛からある人」は不自然。"}], "correct_answer": "の", "explanations": {"の": "「慈愛のある人」で、慈愛が人を修飾する。", "を": "「慈愛をある」は文として成り立たない。", "へ": "方向を表す助詞で、「ある人」につながらない。", "から": "起点の助詞で、「慈愛からある人」は不自然。"}, "error_tags": {"を": "object_marker", "へ": "direction", "から": "source"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷淡", "is_correct": true, "explanation": "思いやりがなく冷たい態度で、慈愛と反対。"}, {"text": "愛情", "is_correct": false, "explanation": "慈愛に近い意味で、反対語ではない。"}, {"text": "親切", "is_correct": false, "explanation": "優しさを表し、反対語ではない。"}, {"text": "尊敬", "is_correct": false, "explanation": "好意的な気持ちで、反対語ではない。"}], "correct_answer": "冷淡", "explanations": {"冷淡": "思いやりがなく冷たい態度で、慈愛と反対。", "愛情": "慈愛に近い意味で、反対語ではない。", "親切": "優しさを表し、反対語ではない。", "尊敬": "好意的な気持ちで、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52723, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「慈愛とは」で、定義の主題を示す形になる。"}, {"text": "を", "is_correct": false, "explanation": "「慈愛をは」は文法的に成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「慈愛がは」は助詞が重なり成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「慈愛のは」は成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「慈愛とは」で、定義の主題を示す形になる。", "を": "「慈愛をは」は文法的に成り立たない。", "が": "「慈愛がは」は助詞が重なり成り立たない。", "の": "「慈愛のは」は成り立たない。"}, "error_tags": {"を": "object_marker", "が": "subject_marker", "の": "possessive"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "憎悪", "is_correct": true, "explanation": "人を大切に思う気持ちと反対の、強い憎しみ。"}, {"text": "同情", "is_correct": false, "explanation": "相手を思う気持ちで、反対語ではない。"}, {"text": "優しさ", "is_correct": false, "explanation": "慈愛に近い意味で、反対語ではない。"}, {"text": "感謝", "is_correct": false, "explanation": "好意的な気持ちで、反対語ではない。"}], "correct_answer": "憎悪", "explanations": {"憎悪": "人を大切に思う気持ちと反対の、強い憎しみ。", "同情": "相手を思う気持ちで、反対語ではない。", "優しさ": "慈愛に近い意味で、反対語ではない。", "感謝": "好意的な気持ちで、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52723, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人のことを大切に思う、あたたかい気持ちのことです。", "primary_collocate": null, "pronunciation": "じあい", "ipa": "dʑiai", "syllable_count": 3, "sentences": [{"text": "母の慈愛が好きだ。", "target_word": "慈愛", "complexity_tier": "T1", "furigana": "母[はは]の慈愛[じあい]が好[す]きだ。", "sentence_source": "generated"}, {"text": "慈愛のある人になりたい。", "target_word": "慈愛", "complexity_tier": "T2", "furigana": "慈愛[じあい]のある人[ひと]になりたい。", "sentence_source": "generated"}, {"text": "祖父は慈愛をもって話した。", "target_word": "慈愛", "complexity_tier": "T2", "furigana": "祖父[そふ]は慈愛[じあい]をもって話[はな]した。", "sentence_source": "generated"}, {"text": "彼女の慈愛に、みんなが助けられた。", "target_word": "慈愛", "complexity_tier": "T4", "furigana": "彼女[かのじょ]の慈愛[じあい]に、みんなが助[たす]けられた。", "sentence_source": "generated"}, {"text": "先生は慈愛の心で生徒を見た。", "target_word": "慈愛", "complexity_tier": "T3", "furigana": "先生[せんせい]は慈愛[じあい]の心[こころ]で生徒[せいと]を見[み]た。", "sentence_source": "generated"}, {"text": "慈愛を感じる手紙をもらった。", "target_word": "慈愛", "complexity_tier": "T3", "furigana": "慈愛[じあい]を感[かん]じる手紙[てがみ]をもらった。", "sentence_source": "generated"}, {"text": "この絵からは、慈愛が伝わってくる。", "target_word": "慈愛", "complexity_tier": "T3", "furigana": "この絵[え]からは、慈愛[じあい]が伝[つた]わってくる。", "sentence_source": "generated"}, {"text": "慈愛とは、人を大切に思う気持ちです。", "target_word": "慈愛", "complexity_tier": "T3", "furigana": "慈愛[じあい]とは、人[ひと]を大切[たいせつ]に思[おも]う気持[きも]ちです。", "sentence_source": "generated"}, {"text": "犬にも慈愛を向ける優しい人だ。", "target_word": "慈愛", "complexity_tier": "T3", "furigana": "犬[いぬ]にも慈愛[じあい]を向[む]ける優[やさ]しい人[ひと]だ。", "sentence_source": "generated"}, {"text": "彼の笑顔は慈愛そのものだった。", "target_word": "慈愛", "complexity_tier": "T3", "furigana": "彼[かれ]の笑顔[えがお]は慈愛[じあい]そのものだった。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 人を大切に思うあたたかい気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d87f72e-2602-405c-b8a8-61acb30acc84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52723, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "慈愛", "is_correct": true, "explanation": "「じあい」で見出し語と一致する。"}, {"text": "試合", "is_correct": false, "explanation": "「しあい」で、頭が「じ」ではなく「し」。"}, {"text": "気合", "is_correct": false, "explanation": "「きあい」で、頭の一音だけが違う。"}, {"text": "次回", "is_correct": false, "explanation": "「じかい」で、二音目だけが違う。"}, {"text": "事態", "is_correct": false, "explanation": "「じたい」で、二音目だけが違う。"}, {"text": "出会い", "is_correct": false, "explanation": "「であい」で、頭の一音だけが違う。"}], "explanations": {"慈愛": "「じあい」で見出し語と一致する。", "試合": "「しあい」で、頭が「じ」ではなく「し」。", "気合": "「きあい」で、頭の一音だけが違う。", "次回": "「じかい」で、二音目だけが違う。", "事態": "「じたい」で、二音目だけが違う。", "出会い": "「であい」で、頭の一音だけが違う。"}, "sentence_index": null, "correct_answer": "慈愛"}, "level_3": {"options": [{"text": "慈愛", "is_correct": true, "explanation": "母のあたたかい気持ちを表し、「好きだ」に合う。"}, {"text": "重量", "is_correct": false, "explanation": "形は合うが、「母の重量が好きだ」は意味が合わない。"}, {"text": "面積", "is_correct": false, "explanation": "形は合うが、母の面積を好きだという意味が合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "形は合うが、「母の湿度」は意味が合わない。"}], "explanations": {"慈愛": "母のあたたかい気持ちを表し、「好きだ」に合う。", "重量": "形は合うが、「母の重量が好きだ」は意味が合わない。", "面積": "形は合うが、母の面積を好きだという意味が合わない。", "湿度": "形は合うが、「母の湿度」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "慈愛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "慈愛を冷蔵庫に入れて、明日まで保存した。", "explanation": "ここは〈食品〉の意味。慈愛は気持ちなので、食品のように冷蔵庫で保存する物として扱えない。"}, {"text": "会の終わりに、彼は皆へ慈愛の書類を配った。", "explanation": "ここは〈書類〉の意味。慈愛は気持ちなので、書類のように配る物としては扱えない。"}, {"text": "慈愛を二枚買って、友だちに配った。", "explanation": "ここは〈贈り物〉の意味。慈愛は気持ちで、紙のように「二枚」と数えて買える物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52723, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "慈愛", "is_correct": true, "explanation": "「じあい」で見出し語と一致する。"}, {"text": "悲哀", "is_correct": false, "explanation": "「ひあい」で、頭の一音だけが違う。"}, {"text": "見合い", "is_correct": false, "explanation": "「みあい」で、頭の一音だけが違う。"}, {"text": "事案", "is_correct": false, "explanation": "「じあん」で、最後の一音だけが違う。"}, {"text": "自害", "is_correct": false, "explanation": "「じがい」で、二音目だけが違う。"}, {"text": "似合い", "is_correct": false, "explanation": "「にあい」で、頭の一音だけが違う。"}], "explanations": {"慈愛": "「じあい」で見出し語と一致する。", "悲哀": "「ひあい」で、頭の一音だけが違う。", "見合い": "「みあい」で、頭の一音だけが違う。", "事案": "「じあん」で、最後の一音だけが違う。", "自害": "「じがい」で、二音目だけが違う。", "似合い": "「にあい」で、頭の一音だけが違う。"}, "sentence_index": null, "correct_answer": "慈愛"}, "level_3": {"options": [{"text": "慈愛", "is_correct": true, "explanation": "絵から伝わるあたたかい気持ちを表し、文脈に合う。"}, {"text": "住所", "is_correct": false, "explanation": "形は合うが、絵から住所が伝わるという意味が合わない。"}, {"text": "税金", "is_correct": false, "explanation": "形は合うが、絵から税金が伝わるという意味が合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが、絵から辞書が伝わるという意味が合わない。"}], "explanations": {"慈愛": "絵から伝わるあたたかい気持ちを表し、文脈に合う。", "住所": "形は合うが、絵から住所が伝わるという意味が合わない。", "税金": "形は合うが、絵から税金が伝わるという意味が合わない。", "辞書": "形は合うが、絵から辞書が伝わるという意味が合わない。"}, "sentence_index": 6, "correct_answer": "慈愛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その男は、命だけは助けてほしいと慈愛を請うた。", "explanation": "ここは〈慈悲〉の意味。「慈悲を請う」は罰を免れるための情けを求める言い方だが、慈愛は相手の幸せを願う愛情で、請う対象としては使えない。"}, {"text": "慈愛が高い山に登って、頂上で休んだ。", "explanation": "ここは〈登山者〉の意味。慈愛は心の働きなので、山に登る人のように行動する主体にはならない。"}, {"text": "この道路は慈愛で、車がとても多い。", "explanation": "ここは〈混雑〉の意味。道路の状態は混雑で表すが、慈愛は人の心を表す語なので、交通量の説明には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52723, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母の慈愛を助けられた。", "corrected_sentence": "祖母の慈愛に助けられた。", "error_description": "受身文で助ける主体は「に」で表すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52723, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は子に慈愛を焼いた。", "corrected_sentence": "母は子に慈愛を注いだ。", "error_description": "「慈愛」に続く動詞は「注ぐ」で、「焼いた」は慈愛を対象にできないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52724, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「母の慈愛が子を包んだ」で、慈愛が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「子を」と目的語が重なり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、慈愛の後には入らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は後ろに名詞が要るため、「慈愛の、子を包んだ」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「母の慈愛が子を包んだ」で、慈愛が主語になる。", "を": "「子を」と目的語が重なり、文が成り立たない。", "へ": "方向を表す助詞で、慈愛の後には入らない。", "の": "「の」は後ろに名詞が要るため、「慈愛の、子を包んだ」は成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "の": "possessive"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "憎悪", "is_correct": true, "explanation": "相手の幸せを願う慈愛と反対の、強い憎しみ。"}, {"text": "愛情", "is_correct": false, "explanation": "慈愛に近い意味で、反対語ではない。"}, {"text": "親切", "is_correct": false, "explanation": "優しさを表し、反対語ではない。"}, {"text": "感謝", "is_correct": false, "explanation": "好意的な気持ちで、反対語ではない。"}], "correct_answer": "憎悪", "explanations": {"憎悪": "相手の幸せを願う慈愛と反対の、強い憎しみ。", "愛情": "慈愛に近い意味で、反対語ではない。", "親切": "優しさを表し、反対語ではない。", "感謝": "好意的な気持ちで、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52724, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「深い慈愛があった」で、存在する物を表す。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は目的語を取らず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、ここでは使えない。"}, {"text": "から", "is_correct": false, "explanation": "起点の助詞で、「あった」につながらない。"}], "correct_answer": "が", "explanations": {"が": "「深い慈愛があった」で、存在する物を表す。", "を": "「ある」は目的語を取らず、文が成り立たない。", "へ": "方向を表す助詞で、ここでは使えない。", "から": "起点の助詞で、「あった」につながらない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "から": "source"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷酷", "is_correct": true, "explanation": "思いやりがなく冷たい心で、慈愛と反対。"}, {"text": "同情", "is_correct": false, "explanation": "相手を思う気持ちで、反対語ではない。"}, {"text": "優しさ", "is_correct": false, "explanation": "慈愛に近い意味で、反対語ではない。"}, {"text": "尊敬", "is_correct": false, "explanation": "好意的な気持ちで、反対語ではない。"}], "correct_answer": "冷酷", "explanations": {"冷酷": "思いやりがなく冷たい心で、慈愛と反対。", "同情": "相手を思う気持ちで、反対語ではない。", "優しさ": "慈愛に近い意味で、反対語ではない。", "尊敬": "好意的な気持ちで、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52724, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "深い愛情をもって、相手の幸せを願い、優しく接する心。", "primary_collocate": null, "pronunciation": "じあい", "ipa": "dʑiai", "syllable_count": 3, "sentences": [{"text": "我々成人が往々にして見落とす、静謐なる成長の過程を、彼はただ純粋な慈愛をもって見守っているのだ。", "target_word": "慈愛", "complexity_tier": "T6", "furigana": "我々[われわれ]成人[せいじん]が往々[おうおう]にして見落[みお]とす、静謐[せいひつ]なる成長[せいちょう]の過程[かてい]を、彼[かれ]はただ純粋[じゅんすい]な慈愛[じあい]をもって見守[みまも]っているのだ。", "sentence_source": "mined"}, {"text": "母の慈愛が、子を包んだ。", "target_word": "慈愛", "complexity_tier": "T2", "furigana": "母[はは]の慈愛[じあい]が、子[こ]を包[つつ]んだ。", "sentence_source": "generated"}, {"text": "彼女は慈愛に満ちた目で子を見た。", "target_word": "慈愛", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は慈愛[じあい]に満[み]ちた目[め]で子[こ]を見[み]た。", "sentence_source": "generated"}, {"text": "先生の慈愛を感じて、私は泣いた。", "target_word": "慈愛", "complexity_tier": "T3", "furigana": "先生[せんせい]の慈愛[じあい]を感[かん]じて、私[わたし]は泣[な]いた。", "sentence_source": "generated"}, {"text": "慈愛とは、相手の幸せを願う心だ。", "target_word": "慈愛", "complexity_tier": "T3", "furigana": "慈愛[じあい]とは、相手[あいて]の幸[しあわ]せを願[ねが]う心[こころ]だ。", "sentence_source": "generated"}, {"text": "祖母は慈愛をもって孫を育てた。", "target_word": "慈愛", "complexity_tier": "T3", "furigana": "祖母[そぼ]は慈愛[じあい]をもって孫[まご]を育[そだ]てた。", "sentence_source": "generated"}, {"text": "神の慈愛は、すべての人に注がれる。", "target_word": "慈愛", "complexity_tier": "T4", "furigana": "神[かみ]の慈愛[じあい]は、すべての人[ひと]に注[そそ]がれる。", "sentence_source": "generated"}, {"text": "彼の厳しさの裏には、深い慈愛があった。", "target_word": "慈愛", "complexity_tier": "T3", "furigana": "彼[かれ]の厳[きび]しさの裏[うら]には、深[ふか]い慈愛[じあい]があった。", "sentence_source": "generated"}, {"text": "慈愛のある言葉に、心が軽くなった。", "target_word": "慈愛", "complexity_tier": "T3", "furigana": "慈愛[じあい]のある言葉[ことば]に、心[こころ]が軽[かる]くなった。", "sentence_source": "generated"}, {"text": "慈愛を受けて育った子は、人にも優しい。", "target_word": "慈愛", "complexity_tier": "T4", "furigana": "慈愛[じあい]を受[う]けて育[そだ]った子[こ]は、人[ひと]にも優[やさ]しい。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 深い愛情で相手の幸せを願う優しい心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d87f72e-2602-405c-b8a8-61acb30acc84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52724, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "慈愛", "is_correct": true, "explanation": "「じあい」で見出し語と一致する。"}, {"text": "試合", "is_correct": false, "explanation": "「しあい」で、頭が「じ」ではなく「し」。"}, {"text": "気合", "is_correct": false, "explanation": "「きあい」で、頭の一音だけが違う。"}, {"text": "次回", "is_correct": false, "explanation": "「じかい」で、二音目だけが違う。"}, {"text": "事態", "is_correct": false, "explanation": "「じたい」で、二音目だけが違う。"}, {"text": "出会い", "is_correct": false, "explanation": "「であい」で、頭の一音だけが違う。"}], "explanations": {"慈愛": "「じあい」で見出し語と一致する。", "試合": "「しあい」で、頭が「じ」ではなく「し」。", "気合": "「きあい」で、頭の一音だけが違う。", "次回": "「じかい」で、二音目だけが違う。", "事態": "「じたい」で、二音目だけが違う。", "出会い": "「であい」で、頭の一音だけが違う。"}, "sentence_index": null, "correct_answer": "慈愛"}, "level_3": {"options": [{"text": "慈愛", "is_correct": true, "explanation": "子の成長を優しく見守る心を表し、文脈に合う。"}, {"text": "規則", "is_correct": false, "explanation": "形は合うが、「規則をもって見守る」は意味が合わない。"}, {"text": "偶然", "is_correct": false, "explanation": "形は合うが、「純粋な偶然」で見守るという意味が合わない。"}, {"text": "価格", "is_correct": false, "explanation": "形は合うが、価格で人を見守るという意味が合わない。"}], "explanations": {"慈愛": "子の成長を優しく見守る心を表し、文脈に合う。", "規則": "形は合うが、「規則をもって見守る」は意味が合わない。", "偶然": "形は合うが、「純粋な偶然」で見守るという意味が合わない。", "価格": "形は合うが、価格で人を見守るという意味が合わない。"}, "sentence_index": 0, "correct_answer": "慈愛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は慈愛を食べて、昼ご飯にした。", "explanation": "ここは〈おにぎり〉の意味。慈愛は心の働きで、おにぎりのように口にして食べる物ではない。"}, {"text": "敵の兵士は、命だけは助けてほしいと慈愛を請うた。", "explanation": "ここは〈慈悲〉の意味。「慈悲を請う」は情けを求める言い方だが、慈愛は相手の幸せを願う愛情なので、請う対象としては使えない。"}, {"text": "慈愛で古い机を修理した。", "explanation": "ここは〈道具〉の意味。慈愛は心の働きで、工具のように机を直す手段にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52724, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "慈愛", "is_correct": true, "explanation": "「じあい」で見出し語と一致する。"}, {"text": "悲哀", "is_correct": false, "explanation": "「ひあい」で、頭の一音だけが違う。"}, {"text": "見合い", "is_correct": false, "explanation": "「みあい」で、頭の一音だけが違う。"}, {"text": "事案", "is_correct": false, "explanation": "「じあん」で、最後の一音だけが違う。"}, {"text": "自害", "is_correct": false, "explanation": "「じがい」で、二音目だけが違う。"}, {"text": "似合い", "is_correct": false, "explanation": "「にあい」で、頭の一音だけが違う。"}], "explanations": {"慈愛": "「じあい」で見出し語と一致する。", "悲哀": "「ひあい」で、頭の一音だけが違う。", "見合い": "「みあい」で、頭の一音だけが違う。", "事案": "「じあん」で、最後の一音だけが違う。", "自害": "「じがい」で、二音目だけが違う。", "似合い": "「にあい」で、頭の一音だけが違う。"}, "sentence_index": null, "correct_answer": "慈愛"}, "level_3": {"options": [{"text": "慈愛", "is_correct": true, "explanation": "神がすべての人に注ぐ深い愛を表し、文脈に合う。"}, {"text": "面積", "is_correct": false, "explanation": "形は合うが、「面積が注がれる」は意味が合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが、辞書が人に注がれるという意味が合わない。"}, {"text": "温度", "is_correct": false, "explanation": "形は合うが、「神の温度が注がれる」は意味が合わない。"}], "explanations": {"慈愛": "神がすべての人に注ぐ深い愛を表し、文脈に合う。", "面積": "形は合うが、「面積が注がれる」は意味が合わない。", "辞書": "形は合うが、辞書が人に注がれるという意味が合わない。", "温度": "形は合うが、「神の温度が注がれる」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "慈愛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "慈愛を持った新しい自転車を買った。", "explanation": "ここは〈愛着〉の意味。愛着は物にも向けられるが、慈愛は人への深い愛情なので、自転車の性質としては使えない。"}, {"text": "その映画は観客の慈愛を誘い、会場は涙に包まれた。", "explanation": "ここは〈同情〉の意味。「同情を誘う」は哀れみを呼び起こす言い方だが、慈愛は相手の幸せを願う愛情で、同情のように誘われて生じる感情ではない。"}, {"text": "慈愛は午後三時に駅に到着した。", "explanation": "ここは〈旅人〉の意味。慈愛は心の働きで、駅に到着する旅人のように移動する主体にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52724, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は慈愛を食べて子どもを育てた。", "corrected_sentence": "彼女は慈愛をもって子どもを育てた。", "error_description": "慈愛は「食べる」対象ではなく、「慈愛をもって」の形で使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52724, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は子に慈愛が注いだ。", "corrected_sentence": "彼女は子に慈愛を注いだ。", "error_description": "「注ぐ」の対象は「を」で表すので、「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52725, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「原初を振り返る」で、振り返る対象を示す。"}, {"text": "と", "is_correct": false, "explanation": "「原初と振り返る」は相手を示すが、振り返る対象にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「原初で振り返る」は場所を示すが、振り返る対象にはならない。"}, {"text": "に", "is_correct": false, "explanation": "「原初に振り返る」は振り返る対象を示さず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「原初を振り返る」で、振り返る対象を示す。", "と": "「原初と振り返る」は相手を示すが、振り返る対象にはならない。", "で": "「原初で振り返る」は場所を示すが、振り返る対象にはならない。", "に": "「原初に振り返る」は振り返る対象を示さず、不自然。"}, "error_tags": {"と": "comitative_misuse", "で": "location_misuse", "より": "comparison_misuse"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終点", "is_correct": true, "explanation": "始まりの原初に対し、物事の終わりを表す。"}, {"text": "起点", "is_correct": false, "explanation": "始まりを表し、原初に近い意味である。"}, {"text": "発端", "is_correct": false, "explanation": "物事の始まりで、反対語ではない。"}, {"text": "太古", "is_correct": false, "explanation": "非常に古い時代で、反対語ではない。"}], "correct_answer": "終点", "explanations": {"終点": "始まりの原初に対し、物事の終わりを表す。", "起点": "始まりを表し、原初に近い意味である。", "発端": "物事の始まりで、反対語ではない。", "太古": "非常に古い時代で、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52725, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最後", "is_correct": true, "explanation": "いちばん初めの原初に対し、いちばん終わりを表す。"}, {"text": "最初", "is_correct": false, "explanation": "原初と同じ意味で、反対語ではない。"}, {"text": "起源", "is_correct": false, "explanation": "始まりを表し、反対語ではない。"}, {"text": "始まり", "is_correct": false, "explanation": "原初と同じ最初を表し、反対語ではない。"}], "correct_answer": "最後", "explanations": {"最後": "いちばん初めの原初に対し、いちばん終わりを表す。", "最初": "原初と同じ意味で、反対語ではない。", "起源": "始まりを表し、反対語ではない。", "始まり": "原初と同じ最初を表し、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52725, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いちばんはじめのこと。", "primary_collocate": null, "pronunciation": "げんしょ", "ipa": "ɡenɕo", "syllable_count": 3, "sentences": [{"text": "原初の地球は熱かった。", "target_word": "原初", "complexity_tier": "T2", "furigana": "原初[げんしょ]の地球[ちきゅう]は熱[あつ]かった。", "sentence_source": "generated"}, {"text": "行き詰まったときは、物事の原初を振り返ってみよう。", "target_word": "原初", "complexity_tier": "T3", "furigana": "行[い]き詰[づ]まったときは、物事[ものごと]の原初[げんしょ]を振[ふ]り返[かえ]ってみよう。", "sentence_source": "generated"}, {"text": "これが原初の形です。", "target_word": "原初", "complexity_tier": "T2", "furigana": "これが原初[げんしょ]の形[かたち]です。", "sentence_source": "generated"}, {"text": "原初から人は火を使った。", "target_word": "原初", "complexity_tier": "T2", "furigana": "原初[げんしょ]から人[ひと]は火[ひ]を使[つか]った。", "sentence_source": "generated"}, {"text": "原初の空は、どんな色だったのだろう。", "target_word": "原初", "complexity_tier": "T3", "furigana": "原初[げんしょ]の空[そら]は、どんな色[いろ]だったのだろう。", "sentence_source": "generated"}, {"text": "物事の原初を考えてみよう。", "target_word": "原初", "complexity_tier": "T3", "furigana": "物事[ものごと]の原初[げんしょ]を考[かんが]えてみよう。", "sentence_source": "generated"}, {"text": "原初に何があったのか、誰も知らない。", "target_word": "原初", "complexity_tier": "T3", "furigana": "原初[げんしょ]に何[なに]があったのか、誰[だれ]も知[し]らない。", "sentence_source": "generated"}, {"text": "原初の記録は、もう残っていない。", "target_word": "原初", "complexity_tier": "T3", "furigana": "原初[げんしょ]の記録[きろく]は、もう残[のこ]っていない。", "sentence_source": "generated"}, {"text": "私たちは原初を知らない。", "target_word": "原初", "complexity_tier": "T2", "furigana": "私[わたし]たちは原初[げんしょ]を知[し]らない。", "sentence_source": "generated"}, {"text": "村の原初は小さな市場だった。", "target_word": "原初", "complexity_tier": "T3", "furigana": "村[むら]の原初[げんしょ]は小[ちい]さな市場[いちば]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原初的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | いちばんはじめの時や最初の状態のこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d87f72e-2602-405c-b8a8-61acb30acc84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52725, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原初", "is_correct": true, "explanation": "いちばん初めの地球を表し、文脈に合う。"}, {"text": "郵便", "is_correct": false, "explanation": "形は合うが、「郵便の地球」は意味が合わない。"}, {"text": "面積", "is_correct": false, "explanation": "形は合うが、「面積の地球は熱かった」は意味が合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが、「辞書の地球」は意味が合わない。"}], "explanations": {"原初": "いちばん初めの地球を表し、文脈に合う。", "郵便": "形は合うが、「郵便の地球」は意味が合わない。", "面積": "形は合うが、「面積の地球は熱かった」は意味が合わない。", "辞書": "形は合うが、「辞書の地球」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "原初"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の会議は原初で行う。", "explanation": "ここは〈会議室〉の意味。原初は時点や状態を表す語で、会議を行う場所にはならない。"}, {"text": "朝、原初を磨いた。", "explanation": "ここは〈窓〉の意味。窓は磨く対象になるが、原初は時点や状態を指すので、磨くことはできない。"}, {"text": "原初が三つ入った箱を送った。", "explanation": "ここは〈部品〉の意味。部品は数えて箱に入れられるが、原初は時点や状態を指すので数えたり箱に入れたりできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52725, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原初", "is_correct": true, "explanation": "いちばん初めに何があったかを問う文に合う。"}, {"text": "面積", "is_correct": false, "explanation": "形は合うが、「面積に何があったのか」は意味が合わない。"}, {"text": "速度", "is_correct": false, "explanation": "形は合うが、「速度に何があったのか」は意味が合わない。"}, {"text": "気温", "is_correct": false, "explanation": "形は合うが、「気温に何があったのか」は意味が合わない。"}], "explanations": {"原初": "いちばん初めに何があったかを問う文に合う。", "面積": "形は合うが、「面積に何があったのか」は意味が合わない。", "速度": "形は合うが、「速度に何があったのか」は意味が合わない。", "気温": "形は合うが、「気温に何があったのか」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "原初"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の午後から雨になるという原初が出ている。", "explanation": "ここは〈予報〉の意味。「予報が出る」は先の天気の見通しを伝える言い方だが、原初は最初の時点を指すので、見通しとして出るものではない。"}, {"text": "原初を着て、学校へ行った。", "explanation": "ここは〈服〉の意味。服は着る物だが、原初は時点や状態を指すので、身につけることはできない。"}, {"text": "昨日は野菜を原初で炒めた。", "explanation": "ここは〈フライパン〉の意味。原初は時点や状態を表す語で、炒める道具や手段にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52725, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "それが原初を姿です。", "corrected_sentence": "それが原初の姿です。", "error_description": "名詞「姿」を修飾するには「の」が必要で、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52725, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は言葉の原初を飲んでいる。", "corrected_sentence": "彼は言葉の原初を探している。", "error_description": "「原初」は「探す」の対象なので「探している」が正しく、「飲んでいる」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52726, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「原初の地球」で、原初が地球を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「原初を地球は」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「原初が地球は」は助詞が重なり成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「原初へ地球は」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「原初の地球」で、原初が地球を修飾する。", "を": "「原初を地球は」は成り立たない。", "が": "「原初が地球は」は助詞が重なり成り立たない。", "へ": "「原初へ地球は」は成り立たない。"}, "error_tags": {"を": "object_marker", "が": "subject_marker", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終末", "is_correct": true, "explanation": "始まりの原初に対し、物事の終わりを表す。"}, {"text": "起源", "is_correct": false, "explanation": "始まりを表し、原初の類義語である。"}, {"text": "発端", "is_correct": false, "explanation": "物事の始まりで、反対語ではない。"}, {"text": "太古", "is_correct": false, "explanation": "非常に古い時代で、反対語ではない。"}], "correct_answer": "終末", "explanations": {"終末": "始まりの原初に対し、物事の終わりを表す。", "起源": "始まりを表し、原初の類義語である。", "発端": "物事の始まりで、反対語ではない。", "太古": "非常に古い時代で、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52726, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「原初に何があった」で、時点を示す。"}, {"text": "の", "is_correct": false, "explanation": "「宇宙の原初の何があった」は、名詞が続いて動詞につながらない。"}, {"text": "と", "is_correct": false, "explanation": "「宇宙の原初と何があった」は並ぶ相手がなく、成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「宇宙の原初を何があったのか」は、「を」を受ける他動詞がなく成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「原初に何があった」で、時点を示す。", "の": "「宇宙の原初の何があった」は、名詞が続いて動詞につながらない。", "と": "「宇宙の原初と何があった」は並ぶ相手がなく、成り立たない。", "を": "「宇宙の原初を何があったのか」は、「を」を受ける他動詞がなく成り立たない。"}, "error_tags": {"の": "possessive_misuse", "と": "comitative_misuse", "を": "object_misuse"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "末期", "is_correct": true, "explanation": "始まりの原初に対し、終わりの時期を表す。"}, {"text": "起源", "is_correct": false, "explanation": "始まりを表し、原初の類義語である。"}, {"text": "始まり", "is_correct": false, "explanation": "原初と同じ最初を表し、反対語ではない。"}, {"text": "草創", "is_correct": false, "explanation": "物事の始まりで、反対語ではない。"}], "correct_answer": "末期", "explanations": {"末期": "始まりの原初に対し、終わりの時期を表す。", "起源": "始まりを表し、原初の類義語である。", "始まり": "原初と同じ最初を表し、反対語ではない。", "草創": "物事の始まりで、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52726, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が始まった最も古い時点。何かが生まれる前の、最初の状態。", "primary_collocate": null, "pronunciation": "げんしょ", "ipa": "ɡenɕo", "syllable_count": 3, "sentences": [{"text": "童子の行為は、単なる日常的な営みの模倣を超え、生命の循環に対する原初的な祈りにも似た、崇高な儀式としてそこに刻まれるのである。", "target_word": "原初的", "complexity_tier": "T6", "furigana": "童子[どうじ]の行為[こうい]は、単[たん]なる日常的[にちじょうてき]な営[いとな]みの模倣[もほう]を超[こ]え、生命[せいめい]の循環[じゅんかん]に対[たい]する原初的[げんしょてき]な祈[いの]りにも似[に]た、崇高[すうこう]な儀式[ぎしき]としてそこに刻[きざ]まれるのである。", "sentence_source": "mined"}, {"text": "原初の地球は火の海だった。", "target_word": "原初", "complexity_tier": "T3", "furigana": "原初[げんしょ]の地球[ちきゅう]は火[ひ]の海[うみ]だった。", "sentence_source": "generated"}, {"text": "物語は原初にさかのぼる。", "target_word": "原初", "complexity_tier": "T3", "furigana": "物語[ものがたり]は原初[げんしょ]にさかのぼる。", "sentence_source": "generated"}, {"text": "原初の記憶は、ぼんやりしている。", "target_word": "原初", "complexity_tier": "T3", "furigana": "原初[げんしょ]の記憶[きおく]は、ぼんやりしている。", "sentence_source": "generated"}, {"text": "人類の原初を研究する学者に会った。", "target_word": "原初", "complexity_tier": "T3", "furigana": "人類[じんるい]の原初[げんしょ]を研究[けんきゅう]する学者[がくしゃ]に会[あ]った。", "sentence_source": "generated"}, {"text": "原初からこの町には川があった。", "target_word": "原初", "complexity_tier": "T3", "furigana": "原初[げんしょ]からこの町[まち]には川[かわ]があった。", "sentence_source": "generated"}, {"text": "この祭りは原初の形を残している。", "target_word": "原初", "complexity_tier": "T3", "furigana": "この祭[まつ]りは原初[げんしょ]の形[かたち]を残[のこ]している。", "sentence_source": "generated"}, {"text": "宇宙の原初に何があったのか。", "target_word": "原初", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]の原初[げんしょ]に何[なに]があったのか。", "sentence_source": "generated"}, {"text": "原初の森は、人の手が入っていない。", "target_word": "原初", "complexity_tier": "T3", "furigana": "原初[げんしょ]の森[もり]は、人[ひと]の手[て]が入[はい]っていない。", "sentence_source": "generated"}, {"text": "彼は言葉の原初を知りたがっている。", "target_word": "原初", "complexity_tier": "T3", "furigana": "彼[かれ]は言葉[ことば]の原初[げんしょ]を知[し]りたがっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原初的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事が始まった最も古い時点や最初の状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d87f72e-2602-405c-b8a8-61acb30acc84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52726, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原初的", "is_correct": true, "explanation": "「な」が続き、根源的な祈りを表すので合う。"}, {"text": "経済的", "is_correct": false, "explanation": "形は合うが、「経済的な祈り」は意味が合わない。"}, {"text": "物理的", "is_correct": false, "explanation": "形は合うが、祈りを「物理的」とするのは意味が合わない。"}, {"text": "統計的", "is_correct": false, "explanation": "形は合うが、祈りを「統計的」とするのは意味が合わない。"}], "explanations": {"原初的": "「な」が続き、根源的な祈りを表すので合う。", "経済的": "形は合うが、「経済的な祈り」は意味が合わない。", "物理的": "形は合うが、祈りを「物理的」とするのは意味が合わない。", "統計的": "形は合うが、祈りを「統計的」とするのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "原初的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "原初の予定では、明日の会議に出席する。", "explanation": "ここは〈当初〉の意味。予定の始まりの時点は「当初」と言い、原初は物事が生まれた最も古い状態を指すので、予定には合わない。"}, {"text": "昨日、友だちと原初で歌った。", "explanation": "ここは〈カラオケ〉の意味。原初は時点や状態を表す語で、歌う場所にはならない。"}, {"text": "原初を飲みすぎて、頭が痛くなった。", "explanation": "ここは〈酒〉の意味。原初は時点や状態を表すので、酒のように飲める物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52726, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原初", "is_correct": true, "explanation": "祭りの最初の形を残すという意味で合う。"}, {"text": "料金", "is_correct": false, "explanation": "形は合うが、「料金の形を残す」は意味が合わない。"}, {"text": "偶数", "is_correct": false, "explanation": "形は合うが、祭りが偶数の形を残すという意味が合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "形は合うが、「湿度の形」は意味が合わない。"}], "explanations": {"原初": "祭りの最初の形を残すという意味で合う。", "料金": "形は合うが、「料金の形を残す」は意味が合わない。", "偶数": "形は合うが、祭りが偶数の形を残すという意味が合わない。", "湿度": "形は合うが、「湿度の形」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "原初"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "原初は来週の天気を教えてくれる。", "explanation": "ここは〈予報〉の意味。予報は未来の天気の見通しを伝えるもので、原初は物事の最も古い時点を指すので合わない。"}, {"text": "この部屋の温度を原初で測った。", "explanation": "ここは〈温度計〉の意味。原初は時点や状態を表す語で、温度を測る道具にはならない。"}, {"text": "原初を計算して、答えを出した。", "explanation": "ここは〈数値〉の意味。計算の対象は数字で、原初は時点や状態を指すので計算の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52726, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "原初を戻って考え直そう。", "corrected_sentence": "原初に戻って考え直そう。", "error_description": "戻る先は「に」で表すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52726, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私たちは原初を買いたい。", "corrected_sentence": "私たちは原初を知りたい。", "error_description": "「原初」は知る対象なので「知りたい」が正しく、「買いたい」は時点や状態を買えないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52727, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「人数は限定されています」で主題を示します。"}, {"text": "を", "is_correct": false, "explanation": "「人数を限定されています」は受身の文として不自然。"}, {"text": "の", "is_correct": false, "explanation": "「人数の限定されています」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「人数と限定されています」は意味をなさない。"}], "correct_answer": "は", "explanations": {"は": "「人数は限定されています」で主題を示します。", "を": "「人数を限定されています」は受身の文として不自然。", "の": "「人数の限定されています」は文として成り立たない。", "と": "「人数と限定されています」は意味をなさない。"}, "error_tags": {"を": "passive_object_misuse", "の": "possessive_misuse", "と": "comitative_misuse"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無制限", "is_correct": true, "explanation": "決まりがなく数や範囲に制限がないことで、限定の反対です。"}, {"text": "制限", "is_correct": false, "explanation": "限定と近い意味で、反対ではない。"}, {"text": "限界", "is_correct": false, "explanation": "これ以上進めない境目で、反対ではない。"}, {"text": "規定", "is_correct": false, "explanation": "決まりを定める意味で、反対ではない。"}], "correct_answer": "無制限", "explanations": {"無制限": "決まりがなく数や範囲に制限がないことで、限定の反対です。", "制限": "限定と近い意味で、反対ではない。", "限界": "これ以上進めない境目で、反対ではない。", "規定": "決まりを定める意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52727, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「時間を限定して」で限定する対象を示します。"}, {"text": "の", "is_correct": false, "explanation": "「時間の限定して」は動詞につながらない。"}, {"text": "と", "is_correct": false, "explanation": "「時間と限定して」は意味をなさない。"}, {"text": "へ", "is_correct": false, "explanation": "「時間へ限定して」は方向の助詞が合わない。"}], "correct_answer": "を", "explanations": {"を": "「時間を限定して」で限定する対象を示します。", "の": "「時間の限定して」は動詞につながらない。", "と": "「時間と限定して」は意味をなさない。", "へ": "「時間へ限定して」は方向の助詞が合わない。"}, "error_tags": {"の": "possessive_misuse", "と": "comitative_misuse", "へ": "direction_misuse"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拡大", "is_correct": true, "explanation": "範囲や数を広げることで、限定の反対です。"}, {"text": "制限", "is_correct": false, "explanation": "限定と近い意味で、反対ではない。"}, {"text": "設定", "is_correct": false, "explanation": "決めて置く意味で、反対ではない。"}, {"text": "決定", "is_correct": false, "explanation": "決める意味で、反対ではない。"}], "correct_answer": "拡大", "explanations": {"拡大": "範囲や数を広げることで、限定の反対です。", "制限": "限定と近い意味で、反対ではない。", "設定": "決めて置く意味で、反対ではない。", "決定": "決める意味で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52727, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある範囲や決まりの中で、何かの種類や数が少なくなること。", "primary_collocate": null, "pronunciation": "げんてい", "ipa": "ɡenteː", "syllable_count": 4, "sentences": [{"text": "数を限定する。", "target_word": "限定する", "complexity_tier": "T1", "furigana": "数[かず]を限定[げんてい]する。", "sentence_source": "generated"}, {"text": "人数は限定されています。", "target_word": "限定されています", "complexity_tier": "T2", "furigana": "人数[にんずう]は限定[げんてい]されています。", "sentence_source": "generated"}, {"text": "販売は百個に限定した。", "target_word": "限定した", "complexity_tier": "T2", "furigana": "販売[はんばい]は百個[ひゃっこ]に限定[げんてい]した。", "sentence_source": "generated"}, {"text": "範囲の限定が大切だ。", "target_word": "限定", "complexity_tier": "T2", "furigana": "範囲[はんい]の限定[げんてい]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "話を一つに限定しよう。", "target_word": "限定しよう", "complexity_tier": "T2", "furigana": "話[はなし]を一[ひと]つに限定[げんてい]しよう。", "sentence_source": "generated"}, {"text": "限定された場所でしか育たない花だ。", "target_word": "限定された", "complexity_tier": "T4", "furigana": "限定[げんてい]された場所[ばしょ]でしか育[そだ]たない花[はな]だ。", "sentence_source": "generated"}, {"text": "道具の種類が限定されている。", "target_word": "限定されている", "complexity_tier": "T3", "furigana": "道具[どうぐ]の種類[しゅるい]が限定[げんてい]されている。", "sentence_source": "generated"}, {"text": "時間を限定して勉強する。", "target_word": "限定して", "complexity_tier": "T3", "furigana": "時間[じかん]を限定[げんてい]して勉強[べんきょう]する。", "sentence_source": "generated"}, {"text": "参加できる人の限定はない。", "target_word": "限定", "complexity_tier": "T3", "furigana": "参加[さんか]できる人[ひと]の限定[げんてい]はない。", "sentence_source": "generated"}, {"text": "条件を限定しすぎると、選べなくなる。", "target_word": "限定し", "complexity_tier": "T4", "furigana": "条件[じょうけん]を限定[げんてい]しすぎると、選[えら]べなくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "限定する", "label": "活用"}, {"form": "限定された", "label": "活用"}, {"form": "限定的", "label": "派生"}, {"form": "限定品", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 決まりの中で種類や数を少なく絞ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d87f72e-2602-405c-b8a8-61acb30acc84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52727, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "限定", "is_correct": true, "explanation": "読み上げられた語そのもの（げんてい）です。"}, {"text": "検定", "is_correct": false, "explanation": "けんてい。最初の音が濁らない別語です。"}, {"text": "前提", "is_correct": false, "explanation": "ぜんてい。「げ」が「ぜ」に変わった別語です。"}, {"text": "原点", "is_correct": false, "explanation": "げんてん。最後の「い」が「ん」に変わった別語です。"}, {"text": "現在", "is_correct": false, "explanation": "げんざい。「て」が「ざ」に変わった別語です。"}], "explanations": {"限定": "読み上げられた語そのもの（げんてい）です。", "検定": "けんてい。最初の音が濁らない別語です。", "前提": "ぜんてい。「げ」が「ぜ」に変わった別語です。", "原点": "げんてん。最後の「い」が「ん」に変わった別語です。", "現在": "げんざい。「て」が「ざ」に変わった別語です。"}, "sentence_index": null, "correct_answer": "限定"}, "level_3": {"options": [{"text": "限定する", "is_correct": true, "explanation": "「数を少なく絞る」という意味に合います。"}, {"text": "洗う", "is_correct": false, "explanation": "形は合うが、数を洗うという意味が合わない。"}, {"text": "祝う", "is_correct": false, "explanation": "形は合うが、数を祝うという意味が合わない。"}, {"text": "磨く", "is_correct": false, "explanation": "形は合うが、数を磨くという意味が合わない。"}], "explanations": {"限定する": "「数を少なく絞る」という意味に合います。", "洗う": "形は合うが、数を洗うという意味が合わない。", "祝う": "形は合うが、数を祝うという意味が合わない。", "磨く": "形は合うが、数を磨くという意味が合わない。"}, "sentence_index": 0, "correct_answer": "限定する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、公園の限定を散歩している。", "explanation": "「限定」は場所を表す語ではなく、散歩する場所として使えない。"}, {"text": "駅の限定にコーヒーをこぼした。", "explanation": "「限定」に「端・床」のような場所の意味はなく、こぼす先として合わない。"}, {"text": "兄は限定が高いので、天井に手が届く。", "explanation": "「限定」は身長を表さない。身長の意味で使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
