INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52728, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「二十人に限定する」で限定の範囲を示します。"}, {"text": "を", "is_correct": false, "explanation": "「を」が二度続き、文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「二十人の限定する」では動詞につながらない。"}, {"text": "が", "is_correct": false, "explanation": "「二十人が限定する」では限定する主体が人になり、を との組み合わせで文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「二十人に限定する」で限定の範囲を示します。", "を": "「を」が二度続き、文として成り立たない。", "の": "「二十人の限定する」では動詞につながらない。", "が": "「二十人が限定する」では限定する主体が人になり、を との組み合わせで文が成り立たない。"}, "error_tags": {"を": "double_object", "の": "possessive_misuse", "と": "comitative_misuse"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無制限", "is_correct": true, "explanation": "数に決まりがないことで、限定の反対です。"}, {"text": "制限", "is_correct": false, "explanation": "限定と近い意味で、反対ではない。"}, {"text": "規制", "is_correct": false, "explanation": "決まりで抑える意味で、反対ではない。"}, {"text": "指定", "is_correct": false, "explanation": "あらかじめ決める意味で、反対ではない。"}], "correct_answer": "無制限", "explanations": {"無制限": "数に決まりがないことで、限定の反対です。", "制限": "限定と近い意味で、反対ではない。", "規制": "決まりで抑える意味で、反対ではない。", "指定": "あらかじめ決める意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52728, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「授業の内容に限定した」で限定の範囲を示します。"}, {"text": "が", "is_correct": false, "explanation": "「内容が限定した」では、限定する主体は先生なので、主語の「が」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「内容へ限定した」は方向を示すが、限定の範囲は「に」で示すので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「内容より限定した」は比べる基準を示すだけで、限定の範囲にならない。"}], "correct_answer": "に", "explanations": {"に": "「授業の内容に限定した」で限定の範囲を示します。", "が": "「内容が限定した」では、限定する主体は先生なので、主語の「が」は合わない。", "へ": "「内容へ限定した」は方向を示すが、限定の範囲は「に」で示すので合わない。", "より": "「内容より限定した」は比べる基準を示すだけで、限定の範囲にならない。"}, "error_tags": {"が": "subject_misuse", "へ": "direction_misuse", "より": "comparison_misuse"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自由", "is_correct": true, "explanation": "制限がないことで、限定の反対です。"}, {"text": "制限", "is_correct": false, "explanation": "限定と近い意味で、反対ではない。"}, {"text": "限界", "is_correct": false, "explanation": "これ以上進めない境目で、反対ではない。"}, {"text": "規定", "is_correct": false, "explanation": "決まりを定める意味で、反対ではない。"}], "correct_answer": "自由", "explanations": {"自由": "制限がないことで、限定の反対です。", "制限": "限定と近い意味で、反対ではない。", "限界": "これ以上進めない境目で、反対ではない。", "規定": "決まりを定める意味で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52728, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "範囲や数量があらかじめ決められていること。制限があること。", "primary_collocate": null, "pronunciation": "げんてい", "ipa": "ɡenteː", "syllable_count": 4, "sentences": [{"text": "鉢という限定された宇宙の中で、命は水という恩恵を糧に、時を重ねてその緑を深めていく。", "target_word": "限定された", "complexity_tier": "T6", "furigana": "鉢[はち]という限定[げんてい]された宇宙[うちゅう]の中[なか]で、命[いのち]は水[みず]という恩恵[おんけい]を糧[かて]に、時[とき]を重[かさ]ねてその緑[みどり]を深[ふか]めていく。", "sentence_source": "mined"}, {"text": "参加者を二十人に限定する。", "target_word": "限定する", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]を二十人[にじゅうにん]に限定[げんてい]する。", "sentence_source": "generated"}, {"text": "場所の限定はありません。", "target_word": "限定", "complexity_tier": "T2", "furigana": "場所[ばしょ]の限定[げんてい]はありません。", "sentence_source": "generated"}, {"text": "この商品は数が限定されている。", "target_word": "限定されている", "complexity_tier": "T3", "furigana": "この商品[しょうひん]は数[かず]が限定[げんてい]されている。", "sentence_source": "generated"}, {"text": "限定された時間で仕事を終えた。", "target_word": "限定された", "complexity_tier": "T3", "furigana": "限定[げんてい]された時間[じかん]で仕事[しごと]を終[お]えた。", "sentence_source": "generated"}, {"text": "話題を一つに限定して話そう。", "target_word": "限定して", "complexity_tier": "T3", "furigana": "話題[わだい]を一[ひと]つに限定[げんてい]して話[はな]そう。", "sentence_source": "generated"}, {"text": "範囲の限定が必要だ。", "target_word": "限定", "complexity_tier": "T2", "furigana": "範囲[はんい]の限定[げんてい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "先生は質問を授業の内容に限定した。", "target_word": "限定した", "complexity_tier": "T4", "furigana": "先生[せんせい]は質問[しつもん]を授業[じゅぎょう]の内容[ないよう]に限定[げんてい]した。", "sentence_source": "generated"}, {"text": "条件の限定が厳しすぎると、人が集まらない。", "target_word": "限定", "complexity_tier": "T4", "furigana": "条件[じょうけん]の限定[げんてい]が厳[きび]しすぎると、人[ひと]が集[あつ]まらない。", "sentence_source": "generated"}, {"text": "使える人が限定されるのは困る。", "target_word": "限定される", "complexity_tier": "T4", "furigana": "使[つか]える人[ひと]が限定[げんてい]されるのは困[こま]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "限定する", "label": "活用"}, {"form": "限定された", "label": "活用"}, {"form": "限定的", "label": "派生"}, {"form": "限定品", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 範囲や数量をあらかじめ決めて制限すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 4 words above tier T1 (max 2): 鉢 (Zipf 3.59), 恩恵 (Zipf 3.77), 糧 (Zipf 3.5), 深め (Zipf 3.73)']::text[], '0d87f72e-2602-405c-b8a8-61acb30acc84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52728, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "限定された", "is_correct": true, "explanation": "「鉢という限られた宇宙」という意味に合います。"}, {"text": "禁止された", "is_correct": false, "explanation": "形は合うが、宇宙を修飾する意味が合わない。"}, {"text": "延長された", "is_correct": false, "explanation": "形は合うが、鉢の中の宇宙という意味が合わない。"}, {"text": "輸出された", "is_correct": false, "explanation": "形は合うが、宇宙の説明として意味が合わない。"}], "explanations": {"限定された": "「鉢という限られた宇宙」という意味に合います。", "禁止された": "形は合うが、宇宙を修飾する意味が合わない。", "延長された": "形は合うが、鉢の中の宇宙という意味が合わない。", "輸出された": "形は合うが、宇宙の説明として意味が合わない。"}, "sentence_index": 0, "correct_answer": "限定された"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日は雨で、道を限定して歩けなかった。", "explanation": "ここは〈通れなくなる〉の意味。限定は範囲や数を前もって決める語で、道が通れなくなる状態は表せない。"}, {"text": "彼女は毎日楽しそうに限定している。", "explanation": "「限定する」は範囲を決める意味で、「笑う」のような様子を表さない。"}, {"text": "お酒は限定を守って飲もう。", "explanation": "ここは〈限度〉の意味。限定は範囲を前もって決めることで、守る対象にはならない。「限度を守る」が正しい言い方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52728, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "限定", "is_correct": true, "explanation": "「範囲を決めることが必要だ」という意味に合います。"}, {"text": "輸入", "is_correct": false, "explanation": "形は合うが、範囲に対する必要性として意味が合わない。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが、範囲とのつながりで意味が合わない。"}, {"text": "出産", "is_correct": false, "explanation": "形は合うが、範囲とのつながりで意味が合わない。"}], "explanations": {"限定": "「範囲を決めることが必要だ」という意味に合います。", "輸入": "形は合うが、範囲に対する必要性として意味が合わない。", "結婚": "形は合うが、範囲とのつながりで意味が合わない。", "出産": "形は合うが、範囲とのつながりで意味が合わない。"}, "sentence_index": 6, "correct_answer": "限定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "体力の限定を超えて、倒れてしまった。", "explanation": "ここは〈限界〉の意味。限定は範囲を決める語で、超えてはいけない上限の意味では使えない。「限界を超える」が正しい。"}, {"text": "窓の外に限定された鳥が飛んでいた。", "explanation": "「限定された鳥」は範囲を決めるという意味に合わない。鳥の様子は〈飛ぶ〉〈見える〉などで表す。"}, {"text": "書類の限定を過ぎてしまった。", "explanation": "ここは〈期限〉の意味。限定は範囲を決めることで、締め切りの日時を過ぎるとは言わない。「期限を過ぎる」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52728, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "定員を三十人を限定した。", "corrected_sentence": "定員を三十人に限定した。", "error_description": "限定する範囲・数量を示す助詞は「を」ではなく「に」です。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52728, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "時間が三時間を限定されている。", "corrected_sentence": "時間が三時間に限定されている。", "error_description": "受身の「限定される」では限定先を「に」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dc1648a-3cf1-4824-8fa7-eef6835fe76e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52729, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "テントを設えての形で、設えるの対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、テントが設えたという意味になり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、設える対象を示さないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、テントより設えるという意味は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "テントを設えての形で、設えるの対象を示す。", "が": "主語を示すが、テントが設えたという意味になり不自然。", "へ": "方向を示すが、設える対象を示さないので合わない。", "より": "比較を示すが、テントより設えるという意味は成り立たない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52729, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "茶席を設えたの形で、設えるの対象を示す。"}, {"text": "と", "is_correct": false, "explanation": "並列の相手を示すが、茶席と設えたという意味になり不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、茶席から設えたという意味は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、茶席が設えたという意味になり、宿の主人が主語の文と合わない。"}], "correct_answer": "を", "explanations": {"を": "茶席を設えたの形で、設えるの対象を示す。", "と": "並列の相手を示すが、茶席と設えたという意味になり不自然。", "から": "起点を示すが、茶席から設えたという意味は成り立たない。", "が": "主語を示すが、茶席が設えたという意味になり、宿の主人が主語の文と合わない。"}, "error_tags": {"と": "並列", "から": "起点", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52729, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "用意すること。", "primary_collocate": null, "pronunciation": "しつらえる", "ipa": "ɕitsɯɾaeɾɯ", "syllable_count": 5, "sentences": [{"text": "母は客のために、心のこもった膳を設えた。", "target_word": "設えた", "complexity_tier": "T3", "furigana": "母[はは]は客[きゃく]のために、心[こころ]のこもった膳[ぜん]を設[しつら]えた。", "sentence_source": "generated"}, {"text": "庭に白いテントを設えて、披露宴を行った。", "target_word": "設えて", "complexity_tier": "T3", "furigana": "庭(にわ)に白(しろ)いテントを設(しつら)えて、披露宴(ひろうえん)を行(おこな)った。", "sentence_source": "generated"}, {"text": "村人たちは、祭りの前に神輿の置き場を設えた。", "target_word": "設えた", "complexity_tier": "T3", "furigana": "村人(むらびと)たちは、祭(まつ)りの前(まえ)に神輿(みこし)の置(お)き場(ば)を設(しつら)えた。", "sentence_source": "generated"}, {"text": "旅人のために、道ばたに休める場所が設えられていた。", "target_word": "設えられて", "complexity_tier": "T3", "furigana": "旅人(たびびと)のために、道(みち)ばたに休(やす)める場所(ばしょ)が設(しつら)えられていた。", "sentence_source": "generated"}, {"text": "先生を迎えるため、教室に椅子を並べて席を設えた。", "target_word": "設えた", "complexity_tier": "T3", "furigana": "先生(せんせい)を迎(むか)えるため、教室(きょうしつ)に椅子(いす)を並(なら)べて席(せき)を設(しつら)えた。", "sentence_source": "generated"}, {"text": "寒い日だったので、客の足元に小さな火鉢を設えた。", "target_word": "設えた", "complexity_tier": "T3", "furigana": "寒(さむ)い日(ひ)だったので、客(きゃく)の足元(あしもと)に小(ちい)さな火鉢(ひばち)を設(しつら)えた。", "sentence_source": "generated"}, {"text": "展覧会では、作品が引き立つように照明を設えた。", "target_word": "設えた", "complexity_tier": "T3", "furigana": "展覧会(てんらんかい)では、作品(さくひん)が引(ひ)き立(た)つように照明(しょうめい)を設(しつら)えた。", "sentence_source": "generated"}, {"text": "宿の主人は、到着した客のために茶席を設えた。", "target_word": "設えた", "complexity_tier": "T3", "furigana": "宿(やど)の主人(しゅじん)は、到着(とうちゃく)した客(きゃく)のために茶席(ちゃせき)を設(しつら)えた。", "sentence_source": "generated"}, {"text": "十分に設えられた部屋で、彼は静かに本を読んだ。", "target_word": "設えられた", "complexity_tier": "T3", "furigana": "十分(じゅうぶん)に設(しつら)えられた部屋(へや)で、彼(かれ)は静(しず)かに本(ほん)を読(よ)んだ。", "sentence_source": "generated"}, {"text": "別荘に友人たちの寝床を設えて、到着を待った。", "target_word": "設えて", "complexity_tier": "T3", "furigana": "別荘(べっそう)に友人(ゆうじん)たちの寝床(ねどこ)を設(しつら)えて、到着(とうちゃく)を待(ま)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "設える", "label": "終止形・連体形"}, {"form": "設えない", "label": "未然形"}, {"form": "設えた", "label": "過去形"}, {"form": "設えて", "label": "連用形（て形）"}, {"form": "設えれば", "label": "仮定形"}, {"form": "設えられる", "label": "受身形"}], "register": "literary", "sense_fingerprint": "設える: to prepare or provide something ready for use (prepare, set up)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229fb64a-60c4-458a-8173-9276c7aa12bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52729, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "設えた", "is_correct": true, "explanation": "過去形で文を言い切る。膳を用意した完了の事実を示す。"}, {"text": "設えて", "is_correct": false, "explanation": "連用形で文末に置くと言い切れず、不自然になる。"}, {"text": "設えれば", "is_correct": false, "explanation": "仮定形になり、文が条件節だけで終わって主節がない。"}, {"text": "設えず", "is_correct": false, "explanation": "否定の連用形で文末では言い切れず、不自然になる。"}], "explanations": {"設えた": "過去形で文を言い切る。膳を用意した完了の事実を示す。", "設えて": "連用形で文末に置くと言い切れず、不自然になる。", "設えれば": "仮定形になり、文が条件節だけで終わって主節がない。", "設えず": "否定の連用形で文末では言い切れず、不自然になる。"}, "sentence_index": 0, "correct_answer": "設えた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は怒りを設えて、部屋を出た。", "explanation": "ここは〈抱く〉の意味。設えるは物や場を用意する動詞で、感情には使わない。"}, {"text": "ピアノの発表会で、彼女は緊張を設えた。", "explanation": "ここは〈感じる〉の意味。設えるは物や場を用意する動詞で、感情の状態には合わない。"}, {"text": "毎晩、彼は大きな夢を設えて眠った。", "explanation": "ここは〈見る〉の意味。設えるは物や場を用意する動詞で、夢を見る行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52729, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "設えた", "is_correct": true, "explanation": "過去形で文を言い切る。照明を用意した完了の事実を示す。"}, {"text": "設えられた", "is_correct": false, "explanation": "受身になり、照明を目的語にする文と合わず、「照明を設えられた」は不自然。"}, {"text": "設えられる", "is_correct": false, "explanation": "受身の辞書形で、目的語の「照明を」と合わず、文末でも成り立たない。"}, {"text": "設えられて", "is_correct": false, "explanation": "受身の連用形で文末に続かず、目的語の「照明を」とも合わない。"}], "explanations": {"設えた": "過去形で文を言い切る。照明を用意した完了の事実を示す。", "設えられた": "受身になり、照明を目的語にする文と合わず、「照明を設えられた」は不自然。", "設えられる": "受身の辞書形で、目的語の「照明を」と合わず、文末でも成り立たない。", "設えられて": "受身の連用形で文末に続かず、目的語の「照明を」とも合わない。"}, "sentence_index": 6, "correct_answer": "設えた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は友達の悩みを設えて、一晩中聞いた。", "explanation": "ここは〈聞く〉の意味。設えるは物や場を用意する動詞で、悩みを聞く行為には使わない。"}, {"text": "彼は毎日、夏の日焼けを設えた。", "explanation": "ここは〈焼く〉の意味。設えるは物や場を用意する動詞で、日焼けには使わない。"}, {"text": "会議で、彼は期限を設えた。", "explanation": "ここは〈設ける〉の意味。設えるは場や物を整えて用意する動詞で、期限や規則には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52729, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は子どもたちのために、庭に小さな池を設えられた。", "corrected_sentence": "祖父は子どもたちのために、庭に小さな池を設えた。", "error_description": "「設えられた」は受身形だが、池を用意するのは祖父なので能動の過去形「設えた」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "設えて", "is_correct": true, "explanation": "連用形。後ろの「披露宴を行った」に続き、テントを用意してから行う流れに合う。"}, {"text": "設えられて", "is_correct": false, "explanation": "受身の連用形で、「テントを」の後に受身は続かず不自然になる。"}, {"text": "設えられない", "is_correct": false, "explanation": "受身の否定形で、「テントを」の後に続かず不自然になる。"}, {"text": "設えられれば", "is_correct": false, "explanation": "受身の仮定形で、「テントを」の後に続かず不自然になる。"}], "correct_form": "設えて", "base_form": "設える", "form_label": "連用形（て形）", "sentence_index": 1, "explanations": {"設えて": "連用形。後ろの「披露宴を行った」に続き、テントを用意してから行う流れに合う。", "設えられて": "受身の連用形で、「テントを」の後に受身は続かず不自然になる。", "設えられない": "受身の否定形で、「テントを」の後に続かず不自然になる。", "設えられれば": "受身の仮定形で、「テントを」の後に続かず不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52729, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "叔父は山小屋に、客用の寝床を設えたで、朝まで待った。", "corrected_sentence": "叔父は山小屋に、客用の寝床を設えて、朝まで待った。", "error_description": "「設えたで」は接続の誤り。動作の並列には連用形「設えて」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "設えた", "is_correct": true, "explanation": "過去形。宿の主人が茶席を用意した完了の事実を示す。"}, {"text": "設えて", "is_correct": false, "explanation": "連用形で、文末では言い切れないため不自然になる。"}, {"text": "設えられた", "is_correct": false, "explanation": "「茶席を」の後に受身は続かず、「を」と噛み合わないため不自然になる。"}, {"text": "設えられない", "is_correct": false, "explanation": "受身の否定形で、ここでは意味が通らない。"}], "correct_form": "設えた", "base_form": "設える", "form_label": "過去形", "sentence_index": 7, "explanations": {"設えた": "過去形。宿の主人が茶席を用意した完了の事実を示す。", "設えて": "連用形で、文末では言い切れないため不自然になる。", "設えられた": "「茶席を」の後に受身は続かず、「を」と噛み合わないため不自然になる。", "設えられない": "受身の否定形で、ここでは意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52730, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52730, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "寝室を設えるの形で、設えるの対象を示す。"}, {"text": "と", "is_correct": false, "explanation": "並列の相手を示すが、寝室と設えるという意味になり不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、比べる文脈がないためここでは成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、寝室が設えるという意味になり不自然。"}], "correct_answer": "を", "explanations": {"を": "寝室を設えるの形で、設えるの対象を示す。", "と": "並列の相手を示すが、寝室と設えるという意味になり不自然。", "より": "比較を示すが、比べる文脈がないためここでは成り立たない。", "が": "主語を示すが、寝室が設えるという意味になり不自然。"}, "error_tags": {"と": "並列", "より": "比較", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52730, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある目的のために、必要なものを整えて置くこと。", "primary_collocate": null, "pronunciation": "しつらえる", "ipa": "ɕitsɯɾaeɾɯ", "syllable_count": 5, "sentences": [{"text": "裏庭の片隅に設えられた僅かな土塊、すなわち小さな花壇は、幼き子にとって広大な宇宙の縮図であった。", "target_word": "設えられた", "complexity_tier": "T4", "furigana": "裏庭(うらにわ)の片隅(かたすみ)に設(しつら)えられた僅(わず)かな土塊(つちくれ)、すなわち小(ちい)さな花壇(かだん)は、幼(おさな)き子(こ)にとって広大(こうだい)な宇宙(うちゅう)の縮図(しゅくず)であった。", "sentence_source": "mined"}, {"text": "客を迎えるために、玄関に季節の花を設えた。", "target_word": "設えた", "complexity_tier": "T3", "furigana": "客(きゃく)を迎(むか)えるために、玄関(げんかん)に季節(きせつ)の花(はな)を設(しつら)えた。", "sentence_source": "generated"}, {"text": "茶室には、客が座りやすいように座布団が設えてある。", "target_word": "設えて", "complexity_tier": "T3", "furigana": "茶室(ちゃしつ)には、客(きゃく)が座(すわ)りやすいように座布団(ざぶとん)が設(しつら)えてある。", "sentence_source": "generated"}, {"text": "旅館の部屋は、窓から庭が見えるように設えられている。", "target_word": "設えられて", "complexity_tier": "T3", "furigana": "旅館(りょかん)の部屋(へや)は、窓(まど)から庭(にわ)が見(み)えるように設(しつら)えられている。", "sentence_source": "generated"}, {"text": "祝いの席を設えて、親戚を招待した。", "target_word": "設えて", "complexity_tier": "T3", "furigana": "祝(いわ)いの席(せき)を設(しつら)えて、親戚(しんせき)を招待(しょうたい)した。", "sentence_source": "generated"}, {"text": "彼女は小さな書斎を二階の隅に設えた。", "target_word": "設えた", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は小(ちい)さな書斎(しょさい)を二階(にかい)の隅(すみ)に設(しつら)えた。", "sentence_source": "generated"}, {"text": "式の前日に、会場の正面へ舞台を設えておいた。", "target_word": "設えて", "complexity_tier": "T3", "furigana": "式(しき)の前日(ぜんじつ)に、会場(かいじょう)の正面(しょうめん)へ舞台(ぶたい)を設(しつら)えておいた。", "sentence_source": "generated"}, {"text": "来客用の寝室を設えるのに、丸一日かかった。", "target_word": "設える", "complexity_tier": "T3", "furigana": "来客用(らいきゃくよう)の寝室(しんしつ)を設(しつら)えるのに、丸一日(まるいちにち)かかった。", "sentence_source": "generated"}, {"text": "部屋を和風に設えたら、落ち着いた雰囲気になった。", "target_word": "設えた", "complexity_tier": "T3", "furigana": "部屋(へや)を和風(わふう)に設(しつら)えたら、落(お)ち着(つ)いた雰囲気(ふんいき)になった。", "sentence_source": "generated"}, {"text": "床の間に掛け軸と花を設えて、客の到着を待った。", "target_word": "設えて", "complexity_tier": "T3", "furigana": "床(とこ)の間(ま)に掛(か)け軸(じく)と花(はな)を設(しつら)えて、客(きゃく)の到着(とうちゃく)を待(ま)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "設える", "label": "終止形・連体形"}, {"form": "設えない", "label": "未然形"}, {"form": "設えた", "label": "過去形"}, {"form": "設えて", "label": "連用形（て形）"}, {"form": "設えれば", "label": "仮定形"}, {"form": "設えられる", "label": "受身形"}], "register": "literary", "sense_fingerprint": "設える: to arrange and set up what is needed for a purpose (fit out, furnish)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 土塊 (Zipf 1.72)']::text[], '229fb64a-60c4-458a-8173-9276c7aa12bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52730, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "設えられた", "is_correct": true, "explanation": "連体形で「僅かな土塊」を修飾する受身の過去形。片隅に整えられた、という意味で入る。"}, {"text": "設えて", "is_correct": false, "explanation": "連用形は名詞を直接修飾できないため、「僅かな土塊」の前には入らない。"}, {"text": "設えれば", "is_correct": false, "explanation": "仮定形は条件節になり、名詞句につながらないので、ここでは成り立たない。"}, {"text": "設えず", "is_correct": false, "explanation": "連用形の否定で文が途中で止まり、「僅かな土塊」を修飾できないため不自然。"}], "explanations": {"設えられた": "連体形で「僅かな土塊」を修飾する受身の過去形。片隅に整えられた、という意味で入る。", "設えて": "連用形は名詞を直接修飾できないため、「僅かな土塊」の前には入らない。", "設えれば": "仮定形は条件節になり、名詞句につながらないので、ここでは成り立たない。", "設えず": "連用形の否定で文が途中で止まり、「僅かな土塊」を修飾できないため不自然。"}, "sentence_index": 0, "correct_answer": "設えられた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は一晩で、長い小説を設えた。", "explanation": "ここは〈作る〉の意味。設えるは場や空間を整える動詞で、小説のような作品には使わない。"}, {"text": "彼女は朝、髪を設えてから出かけた。", "explanation": "ここは〈整える〉の意味。設えるは場を整えて置く動詞で、髪のような身体の一部には使わない。"}, {"text": "彼は明日の遠足のために、日記を設えた。", "explanation": "ここは〈書く〉の意味。設えるは場や物を整える動詞で、文章を書く行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52730, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "設えて", "is_correct": true, "explanation": "連用形で、後ろの「おいた」に続き、前もって準備しておいた、という流れに合う。"}, {"text": "設えた", "is_correct": false, "explanation": "過去形だと「設えたおいた」となり、後続の「おいた」とつながらない。"}, {"text": "設えない", "is_correct": false, "explanation": "未然形の否定になり、準備した事実と合わない。"}, {"text": "設えられる", "is_correct": false, "explanation": "受身形になるため、目的語の「舞台を」と合わず、文が成り立たない。"}], "explanations": {"設えて": "連用形で、後ろの「おいた」に続き、前もって準備しておいた、という流れに合う。", "設えた": "過去形だと「設えたおいた」となり、後続の「おいた」とつながらない。", "設えない": "未然形の否定になり、準備した事実と合わない。", "設えられる": "受身形になるため、目的語の「舞台を」と合わず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "設えて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は数学の難問を設えた。", "explanation": "ここは〈解く〉の意味。設えるは場や空間を整える動詞で、問題を解く行為には使わない。"}, {"text": "画家は白い紙に、美しい風景を設えた。", "explanation": "ここは〈描く〉の意味。設えるは場を整える動詞で、絵を描く行為には使わない。"}, {"text": "班長は、宿題の答えを設えた。", "explanation": "ここは〈答える〉の意味。設えるは物や場を整える動詞で、答えを示す行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52730, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夫は週末に、庭に小さな東屋を設えられた。", "corrected_sentence": "夫は週末に、庭に小さな東屋を設えた。", "error_description": "「設えられた」は受身形だが、東屋を整えるのは夫なので能動の過去形「設えた」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "設えた", "is_correct": true, "explanation": "過去形。文末の「た」で、東屋を整えた完了の事実を示す。"}, {"text": "設えられない", "is_correct": false, "explanation": "受身の否定形で、「花を」の後に続かず不自然になる。"}, {"text": "設えて", "is_correct": false, "explanation": "連用形で、文末では言い切れないためここには入らない。"}, {"text": "設えれば", "is_correct": false, "explanation": "仮定形になり、条件節となって文の意味が変わる。"}], "correct_form": "設えた", "base_form": "設える", "form_label": "過去形", "sentence_index": 1, "explanations": {"設えた": "過去形。文末の「た」で、東屋を整えた完了の事実を示す。", "設えられない": "受身の否定形で、「花を」の後に続かず不自然になる。", "設えて": "連用形で、文末では言い切れないためここには入らない。", "設えれば": "仮定形になり、条件節となって文の意味が変わる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52730, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "写真館では、撮影のために照明を設えば、雰囲気がよくなる。", "corrected_sentence": "写真館では、撮影のために照明を設えれば、雰囲気がよくなる。", "error_description": "「設えば」は活用の誤り。下一段活用の仮定形は「設えれば」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "設える", "is_correct": true, "explanation": "終止形・連体形。後ろの「のに」に続く連体形として使われる。"}, {"text": "設えず", "is_correct": false, "explanation": "連用形の否定で、「のに」の前に続かず文が成り立たない。"}, {"text": "設えられる", "is_correct": false, "explanation": "受身形になり、寝室が整えられるという意味になって動作主が合わない。"}, {"text": "設えよう", "is_correct": false, "explanation": "意志形で、「のに」の前に続かず、文が成り立たない。"}], "correct_form": "設える", "base_form": "設える", "form_label": "終止形・連体形", "sentence_index": 7, "explanations": {"設える": "終止形・連体形。後ろの「のに」に続く連体形として使われる。", "設えず": "連用形の否定で、「のに」の前に続かず文が成り立たない。", "設えられる": "受身形になり、寝室が整えられるという意味になって動作主が合わない。", "設えよう": "意志形で、「のに」の前に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52731, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "裏庭に属する池を表す「の」。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、裏庭が池でという文は成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、裏庭を池でという文は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、池の所在を表す形としては合わない。"}], "correct_answer": "の", "explanations": {"の": "裏庭に属する池を表す「の」。", "が": "主語を示すが、裏庭が池でという文は成り立たない。", "を": "目的語を示すが、裏庭を池でという文は成り立たない。", "へ": "方向を示すが、池の所在を表す形としては合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52731, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "裏庭で採れたの形で、採れた場所を示す。"}, {"text": "と", "is_correct": false, "explanation": "並列の相手を示すが、裏庭と採れたという意味になり不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、比べる文脈がないためここでは成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、裏庭が採れたという文は成り立たない。"}], "correct_answer": "で", "explanations": {"で": "裏庭で採れたの形で、採れた場所を示す。", "と": "並列の相手を示すが、裏庭と採れたという意味になり不自然。", "より": "比較を示すが、比べる文脈がないためここでは成り立たない。", "が": "主語を示すが、裏庭が採れたという文は成り立たない。"}, "error_tags": {"と": "並列", "より": "比較", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52731, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家の後ろにある庭", "primary_collocate": null, "pronunciation": "うらにわ", "ipa": "ɯɾaɲiwa", "syllable_count": 4, "sentences": [{"text": "私の家には、玄関の反対側に裏庭があって、バーベキューもできる。", "target_word": "裏庭", "complexity_tier": "T3", "furigana": "私[わたし]の家[いえ]には、玄関[げんかん]の反対側[はんたいがわ]に裏庭[うらにわ]があって、バーベキューもできる。", "sentence_source": "generated"}, {"text": "裏庭の池で、小さな金魚を飼っている。", "target_word": "裏庭", "complexity_tier": "T3", "furigana": "裏庭[うらにわ]の池[いけ]で、小[ちい]さな金魚[きんぎょ]を飼[か]っている。", "sentence_source": "generated"}, {"text": "台所の戸を開けると、すぐ裏庭に出られる。", "target_word": "裏庭", "complexity_tier": "T3", "furigana": "台所[だいどころ]の戸[と]を開[あ]けると、すぐ裏庭[うらにわ]に出[で]られる。", "sentence_source": "generated"}, {"text": "裏庭は日当たりが悪いので、花より苔がよく育つ。", "target_word": "裏庭", "complexity_tier": "T3", "furigana": "裏庭[うらにわ]は日当[ひあ]たりが悪[わる]いので、花[はな]より苔[こけ]がよく育[そだ]つ。", "sentence_source": "generated"}, {"text": "兄は裏庭にテントを張って、一晩そこで寝た。", "target_word": "裏庭", "complexity_tier": "T3", "furigana": "兄[あに]は裏庭[うらにわ]にテントを張[は]って、一晩[ひとばん]そこで寝[ね]た。", "sentence_source": "generated"}, {"text": "雪が降った朝、裏庭には小さな足跡が続いていた。", "target_word": "裏庭", "complexity_tier": "T3", "furigana": "雪[ゆき]が降[ふ]った朝[あさ]、裏庭[うらにわ]には小[ちい]さな足跡[あしあと]が続[つづ]いていた。", "sentence_source": "generated"}, {"text": "弟が裏庭でボールを蹴っていて、物置の窓を割ってしまった。", "target_word": "裏庭", "complexity_tier": "T3", "furigana": "弟[おとうと]が裏庭[うらにわ]でボールを蹴[け]っていて、物置[ものおき]の窓[まど]を割[わ]ってしまった。", "sentence_source": "generated"}, {"text": "祖母は裏庭で採れたハーブを、お茶に入れて飲む。", "target_word": "裏庭", "complexity_tier": "T3", "furigana": "祖母[そぼ]は裏庭[うらにわ]で採[と]れたハーブを、お茶[ちゃ]に入[い]れて飲[の]む。", "sentence_source": "generated"}, {"text": "隣の家との間にある裏庭には、高い塀がある。", "target_word": "裏庭", "complexity_tier": "T3", "furigana": "隣[となり]の家[いえ]との間[あいだ]にある裏庭[うらにわ]には、高[たか]い塀[へい]がある。", "sentence_source": "generated"}, {"text": "裏庭で焚き火をすると近所に迷惑なので、やめておいた。", "target_word": "裏庭", "complexity_tier": "T3", "furigana": "裏庭[うらにわ]で焚[た]き火[び]をすると近所[きんじょ]に迷惑[めいわく]なので、やめておいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "裏庭", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "家の後ろにある庭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229fb64a-60c4-458a-8173-9276c7aa12bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52731, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裏庭", "is_correct": true, "explanation": "家の後ろにある庭で、バーベキューもできる場所として玄関の反対側に合う。"}, {"text": "理由", "is_correct": false, "explanation": "抽象的な語で、玄関の反対側にあるものではない。"}, {"text": "安心", "is_correct": false, "explanation": "感情を表す語で、場所を示せないので入らない。"}, {"text": "週末", "is_correct": false, "explanation": "時間の語で、玄関の反対側にあるものにはならない。"}], "explanations": {"裏庭": "家の後ろにある庭で、バーベキューもできる場所として玄関の反対側に合う。", "理由": "抽象的な語で、玄関の反対側にあるものではない。", "安心": "感情を表す語で、場所を示せないので入らない。", "週末": "時間の語で、玄関の反対側にあるものにはならない。"}, "sentence_index": 0, "correct_answer": "裏庭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもたちは、車の多い裏庭を走って渡った。", "explanation": "ここは〈裏通り〉の意味。裏庭は家の後ろにある庭で、車が通る道は指さない。"}, {"text": "来客を裏庭の受付で待たせた。", "explanation": "ここは〈受付〉の意味。裏庭は屋外の庭で、受付のような屋内の場所は指さない。"}, {"text": "駅のホームの裏庭で、電車を待った。", "explanation": "ここは〈駅のホーム〉の意味。裏庭は家の後ろにある庭で、駅の構内は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52731, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "裏庭", "is_correct": true, "explanation": "家の裏の屋外の庭で、弟がボールを蹴る場所として自然に入る。"}, {"text": "思い出", "is_correct": false, "explanation": "記憶を表す語で、ボールを蹴る場所にはならない。"}, {"text": "手紙", "is_correct": false, "explanation": "書かれた紙で、ボールを蹴る場所にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "気象の語で、ボールを蹴る場所にはならない。"}], "explanations": {"裏庭": "家の裏の屋外の庭で、弟がボールを蹴る場所として自然に入る。", "思い出": "記憶を表す語で、ボールを蹴る場所にはならない。", "手紙": "書かれた紙で、ボールを蹴る場所にはならない。", "天気": "気象の語で、ボールを蹴る場所にはならない。"}, "sentence_index": 6, "correct_answer": "裏庭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋上の裏庭で、ビルの清掃員が休んだ。", "explanation": "ここは〈屋上〉の意味。裏庭は地上にある家の裏の庭で、屋上は指さない。"}, {"text": "地下街の裏庭に、食料品の店を並べた。", "explanation": "ここは〈地下街〉の意味。裏庭は屋外の庭で、地下の商業空間は指さない。"}, {"text": "電車の中の裏庭で、お弁当を食べた。", "explanation": "ここは〈車内〉の意味。裏庭は屋外の庭で、電車の中は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52731, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家の後ろの裏庭へ、小さな畑がある。", "corrected_sentence": "家の後ろの裏庭に、小さな畑がある。", "error_description": "「裏庭へ」は方向を示すが、畑が存在する場所を示すので「裏庭に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52731, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は毎朝、裏庭が犬を散歩させる。", "corrected_sentence": "父は毎朝、裏庭で犬を散歩させる。", "error_description": "「裏庭が」は主語を示す格助詞だが、散歩させるのは父なので、場所を示す「裏庭で」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52733, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「蹴った」の目的語で、動作の対象を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、ここは「蹴った」の対象なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や到着点を示すが、蹴る対象を示す位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、ここは蹴る対象を示すので合わない。"}], "correct_answer": "を", "explanations": {"を": "「蹴った」の目的語で、動作の対象を示す「を」。", "が": "「が」は主語を示すが、ここは「蹴った」の対象なので合わない。", "に": "「に」は相手や到着点を示すが、蹴る対象を示す位置には合わない。", "で": "「で」は手段や場所を示すが、ここは蹴る対象を示すので合わない。"}, "error_tags": {"が": "主格", "に": "相手・到着点", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
