INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52733, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "土が固まってできた小さなかたまり。", "primary_collocate": null, "pronunciation": "つちくれ", "ipa": "tsɯtɕikɯɾe", "syllable_count": 4, "sentences": [{"text": "靴の裏に土塊がはさまったまま、教室に入ってしまった。", "target_word": "土塊", "complexity_tier": "T3", "furigana": "靴[くつ]の裏[うら]に土塊[つちくれ]がはさまったまま、教室[きょうしつ]に入[はい]ってしまった。", "sentence_source": "generated"}, {"text": "彼は足元の土塊を蹴ったが、乾いていて粉々になった。", "target_word": "土塊", "complexity_tier": "T3", "furigana": "彼[かれ]は足元[あしもと]の土塊[つちくれ]を蹴[け]ったが、乾[かわ]いていて粉々[こなごな]になった。", "sentence_source": "generated"}, {"text": "掘り返した庭の土は、土塊だらけで、まだ植え付けられない。", "target_word": "土塊", "complexity_tier": "T3", "furigana": "掘[ほ]り返[かえ]した庭[にわ]の土[つち]は、土塊[つちくれ]だらけで、まだ植[う]え付[つ]けられない。", "sentence_source": "generated"}, {"text": "土塊を握りしめると、中から小さな虫が出てきた。", "target_word": "土塊", "complexity_tier": "T3", "furigana": "土塊[つちくれ]を握[にぎ]りしめると、中[なか]から小[ちい]さな虫[むし]が出[で]てきた。", "sentence_source": "generated"}, {"text": "大雨で流された土塊が、排水溝に詰まっている。", "target_word": "土塊", "complexity_tier": "T3", "furigana": "大雨[おおあめ]で流[なが]された土塊[つちくれ]が、排水溝[はいすいこう]に詰[つ]まっている。", "sentence_source": "generated"}, {"text": "雨で柔らかくなった畑の土が乾いて、硬い土塊になった。", "target_word": "土塊", "complexity_tier": "T3", "furigana": "雨[あめ]で柔[やわ]らかくなった畑[はたけ]の土[つち]が乾[かわ]いて、硬[かた]い土塊[つちくれ]になった。", "sentence_source": "generated"}, {"text": "犬が穴を掘って、その土塊を庭中にまき散らした。", "target_word": "土塊", "complexity_tier": "T3", "furigana": "犬[いぬ]が穴[あな]を掘[ほ]って、その土塊[つちくれ]を庭中[にわじゅう]にまき散[ち]らした。", "sentence_source": "generated"}, {"text": "陶芸家は粘土に混じった土塊を丁寧に取り除いた。", "target_word": "土塊", "complexity_tier": "T3", "furigana": "陶芸家[とうげいか]は粘土[ねんど]に混[ま]じった土塊[つちくれ]を丁寧[ていねい]に取[と]り除[のぞ]いた。", "sentence_source": "generated"}, {"text": "土塊が頭に当たったが、軽かったので痛くなかった。", "target_word": "土塊", "complexity_tier": "T3", "furigana": "土塊[つちくれ]が頭[あたま]に当[あ]たったが、軽[かる]かったので痛[いた]くなかった。", "sentence_source": "generated"}, {"text": "春になると、畑の土塊は雪解け水でゆるみ、柔らかくなる。", "target_word": "土塊", "complexity_tier": "T3", "furigana": "春[はる]になると、畑[はたけ]の土塊[つちくれ]は雪解[ゆきど]け水[みず]でゆるみ、柔[やわ]らかくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "土塊", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "土が固まってできた小さなかたまり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229fb64a-60c4-458a-8173-9276c7aa12bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52733, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "土塊", "is_correct": true, "explanation": "靴の裏にはさまる小さな土のかたまりを指し、文に合う。"}, {"text": "雲", "is_correct": false, "explanation": "空に浮かぶもので、靴の裏にはさまることはない。"}, {"text": "天井", "is_correct": false, "explanation": "建物の内側の上面で、靴の裏にはさまる物ではない。"}, {"text": "石炭", "is_correct": false, "explanation": "石炭は燃料の鉱物で、靴の裏にはさまる文脈としては不自然で合わない。"}], "explanations": {"土塊": "靴の裏にはさまる小さな土のかたまりを指し、文に合う。", "雲": "空に浮かぶもので、靴の裏にはさまることはない。", "天井": "建物の内側の上面で、靴の裏にはさまる物ではない。", "石炭": "石炭は燃料の鉱物で、靴の裏にはさまる文脈としては不自然で合わない。"}, "sentence_index": 0, "correct_answer": "土塊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "靴の汚れを、土塊で泡立てて落とした。", "explanation": "ここは〈石鹸〉の意味。石鹸は泡立てて汚れを落とすが、土塊は泡立たないので合わない。"}, {"text": "冷蔵庫で土塊を冷やすと、ぷるぷるに固まった。", "explanation": "ここは〈ゼリー〉の意味。ゼリーは冷やすとぷるぷる固まるが、土塊は冷やしても同じ性質を示さないので合わない。"}, {"text": "砂時計の土塊がさらさらと落ちた。", "explanation": "ここは〈砂粒〉の意味。砂粒はさらさら流れ落ちるが、土塊は固まった塊なので流れ落ちない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52733, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土塊", "is_correct": true, "explanation": "庭にまき散らされるほどの、固まった土のかたまりを指し、文に合う。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は調理器具で、庭中にまき散らす対象としては不自然で合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は布製の敷物で、庭にまき散らす対象としては合わない。"}, {"text": "水筒", "is_correct": false, "explanation": "水筒は携帯用の容器で、庭にまき散らす対象としては合わない。"}], "explanations": {"土塊": "庭にまき散らされるほどの、固まった土のかたまりを指し、文に合う。", "鍋": "鍋は調理器具で、庭中にまき散らす対象としては不自然で合わない。", "座布団": "座布団は布製の敷物で、庭にまき散らす対象としては合わない。", "水筒": "水筒は携帯用の容器で、庭にまき散らす対象としては合わない。"}, "sentence_index": 6, "correct_answer": "土塊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒い夜、暖炉に土塊を入れて火をつけた。", "explanation": "ここは〈薪〉の意味。薪は燃えて火になるが、土塊は燃えないので燃料として使えない。"}, {"text": "冬の朝、庭に土塊が積もって、一面が真っ白になった。", "explanation": "ここは〈雪〉の意味。雪は積もって景色を白く変えるが、土塊は白くならないので合わない。"}, {"text": "紅茶に土塊を入れると、すぐに溶けて甘くなった。", "explanation": "ここは〈角砂糖〉の意味。角砂糖は紅茶に溶けて甘くなるが、土塊は溶けて甘くなるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52733, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日、靴に土塊を付いたまま、友だちが教室に入ってきた。", "corrected_sentence": "雨の日、靴に土塊が付いたまま、友だちが教室に入ってきた。", "error_description": "格助詞の誤り。自動詞「付く」では、くっつくものの主語を「が」で示す。「を」は他動詞の目的語に使うので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52733, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の隅に土塊を転がっていた。", "corrected_sentence": "庭の隅に土塊が転がっていた。", "error_description": "「転がる」は自動詞なので、主語は「が」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52735, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「出る」の行き先を表すので、「屋外に出て」が自然。"}, {"text": "が", "is_correct": false, "explanation": "主語を表すので、「出る」の行き先にならない。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾する助詞で、「出る」の行き先にならない。"}, {"text": "と", "is_correct": false, "explanation": "共同の相手を表すので、「出る」の行き先にならない。"}], "correct_answer": "に", "explanations": {"に": "「出る」の行き先を表すので、「屋外に出て」が自然。", "が": "主語を表すので、「出る」の行き先にならない。", "の": "名詞を修飾する助詞で、「出る」の行き先にならない。", "と": "共同の相手を表すので、「出る」の行き先にならない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52735, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52735, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家の外のこと。", "primary_collocate": null, "pronunciation": "おくがい", "ipa": "okɯɡai", "syllable_count": 4, "sentences": [{"text": "子どもたちは屋外で元気に遊んでいる。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "子[こ]どもたちは屋外[おくがい]で元気[げんき]に遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "屋外に出て、空を見上げた。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "屋外[おくがい]に出[で]て、空[そら]を見上[みあ]げた。", "sentence_source": "generated"}, {"text": "今日は天気がいいので、昼ご飯を屋外で食べた。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "今日[きょう]は天気[てんき]がいいので、昼[ひる]ご飯[はん]を屋外[おくがい]で食[た]べた。", "sentence_source": "generated"}, {"text": "屋外の物音で、犬が目をさました。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "屋外[おくがい]の物音[ものおと]で、犬[いぬ]が目[め]をさました。", "sentence_source": "generated"}, {"text": "洗たく物は屋外にほすと、早くかわく。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "洗[せん]たく物[もの]は屋外[おくがい]にほすと、早[はや]くかわく。", "sentence_source": "generated"}, {"text": "家の中は暗いが、屋外は明るい。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "家[いえ]の中[なか]は暗[くら]いが、屋外[おくがい]は明[あか]るい。", "sentence_source": "generated"}, {"text": "屋外に置いた自転車が、雨でぬれてしまった。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "屋外[おくがい]に置[お]いた自転車[じてんしゃ]が、雨[あめ]でぬれてしまった。", "sentence_source": "generated"}, {"text": "この店は、屋外にもテーブルがある。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "この店[みせ]は、屋外[おくがい]にもテーブルがある。", "sentence_source": "generated"}, {"text": "風が強いので、屋外に出るのはやめた。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]いので、屋外[おくがい]に出[で]るのはやめた。", "sentence_source": "generated"}, {"text": "屋外の掃除は、父が毎週日曜日にします。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "屋外[おくがい]の掃除[そうじ]は、父[ちち]が毎週[まいしゅう]日曜日[にちようび]にします。", "sentence_source": "generated"}], "morphological_forms": [{"form": "屋外", "label": "基本形"}], "register": "中立", "sense_fingerprint": "家の外（家の中の対）、外で過ごす場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: 洗たく (Zipf 1.69)']::text[], 'b9355037-504a-4712-9844-167042b60a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52735, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "屋外", "is_correct": true, "explanation": "「屋外で元気に遊ぶ」で、遊ぶ場所として自然に入る。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は遊ぶ場所にならず、「宿題で元気に遊ぶ」は意味が通らない。"}, {"text": "寝不足", "is_correct": false, "explanation": "寝不足は遊ぶ場所や手段にならず、「寝不足で元気に遊ぶ」は矛盾する。"}, {"text": "病気", "is_correct": false, "explanation": "病気は遊ぶ場所や手段にならず、「病気で元気に遊ぶ」は矛盾する。"}], "explanations": {"屋外": "「屋外で元気に遊ぶ」で、遊ぶ場所として自然に入る。", "宿題": "宿題は遊ぶ場所にならず、「宿題で元気に遊ぶ」は意味が通らない。", "寝不足": "寝不足は遊ぶ場所や手段にならず、「寝不足で元気に遊ぶ」は矛盾する。", "病気": "病気は遊ぶ場所や手段にならず、「病気で元気に遊ぶ」は矛盾する。"}, "sentence_index": 0, "correct_answer": "屋外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "換気扇で屋外を取り入れて、部屋の空気を入れ替えた。", "explanation": "ここは〈外気〉の意味。取り入れるのは外の空気（外気）で、場所を表す「屋外」は取り入れられないので合わない。"}, {"text": "エアコンを止めたら、屋外の室温がすぐに上がった。", "explanation": "ここは〈室内〉の意味。「室温」は部屋の中の温度なので、場所を表す「屋外」とは合わない。"}, {"text": "屋外の先生が、宿題を見てくれた。", "explanation": "ここは〈講師〉の意味。「屋外」は場所を表すので、宿題を見る人を指す語としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52735, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "屋外", "is_correct": true, "explanation": "「屋外に置いた自転車」で、自転車を置いた場所を表す。"}, {"text": "雨", "is_correct": false, "explanation": "「雨に置いた」は場所の意味が通らず不自然。"}, {"text": "友達", "is_correct": false, "explanation": "友達は物を置く場所にならず、「友達に置いた」は意味が通らない。"}, {"text": "夕食", "is_correct": false, "explanation": "夕食は物を置く場所にならず、「夕食に置いた」は意味が通らない。"}], "explanations": {"屋外": "「屋外に置いた自転車」で、自転車を置いた場所を表す。", "雨": "「雨に置いた」は場所の意味が通らず不自然。", "友達": "友達は物を置く場所にならず、「友達に置いた」は意味が通らない。", "夕食": "夕食は物を置く場所にならず、「夕食に置いた」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "屋外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕食の時間になったので、屋外に入った。", "explanation": "ここは〈家の中〉の意味。「入る」は家の中へ向かうので、家の外を表す「屋外」とは合わない。"}, {"text": "箱のふたの屋外に、名前のシールを貼った。", "explanation": "ここは〈外側〉の意味。屋外は建物の外の場所を指すので、箱のふたの外側には使わない。"}, {"text": "来年、姉は屋外へ留学する予定だ。", "explanation": "ここは〈海外〉の意味。屋外は建物の外の場所を指すので、外国で学ぶ留学先には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52735, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもたちが屋外を遊んでいる声が聞こえる。", "corrected_sentence": "子どもたちが屋外で遊んでいる声が聞こえる。", "error_description": "「屋外で遊んでいる」の「で」が「を」になっている。「遊ぶ」は場所を「で」で示すので、「屋外を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52735, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕方、屋外で出て、ふとんを干した。", "corrected_sentence": "夕方、屋外に出て、ふとんを干した。", "error_description": "「屋外に出て」の「に」が「で」になっている。「出る」は行き先を「に」で示すので、「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
