INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52736, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "動作が行われる場所を表すので、「屋外で働く」が自然。"}, {"text": "と", "is_correct": false, "explanation": "共同の相手を表すので、働く場所にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、働く場所にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すので、働く場所にはならない。"}], "correct_answer": "で", "explanations": {"で": "動作が行われる場所を表すので、「屋外で働く」が自然。", "と": "共同の相手を表すので、働く場所にはならない。", "へ": "方向を表すので、働く場所にはならない。", "より": "比較を表すので、働く場所にはならない。"}, "error_tags": {"と": "共同", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52736, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物の中ではなく、外の場所。戸外。", "primary_collocate": null, "pronunciation": "おくがい", "ipa": "okɯɡai", "syllable_count": 4, "sentences": [{"text": "彼は泥にまみれながら、日々屋外にて植物の萌芽を見守る。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "彼[かれ]は泥[どろ]にまみれながら、日々[ひび]屋外[おくがい]にて植物[しょくぶつ]の萌芽[ほうが]を見守[みまも]る。", "sentence_source": "mined"}, {"text": "雨が降ってきたので、屋外の運動会は中止になった。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ってきたので、屋外[おくがい]の運動会[うんどうかい]は中止[ちゅうし]になった。", "sentence_source": "generated"}, {"text": "このカメラは屋外でも使える丈夫な作りです。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "このカメラは屋外[おくがい]でも使[つか]える丈夫[じょうぶ]な作[つく]りです。", "sentence_source": "generated"}, {"text": "屋外は寒いので、コートを着て出かけましょう。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "屋外[おくがい]は寒[さむ]いので、コートを着[き]て出[で]かけましょう。", "sentence_source": "generated"}, {"text": "夏祭りは屋外で行われるため、天気が心配だ。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "夏祭[なつまつ]りは屋外[おくがい]で行[おこな]われるため、天気[てんき]が心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "屋外のプールは、冬には水が抜かれる。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "屋外[おくがい]のプールは、冬[ふゆ]には水[みず]が抜[ぬ]かれる。", "sentence_source": "generated"}, {"text": "屋外のいすは、雨にぬれても平気だ。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "屋外[おくがい]のいすは、雨[あめ]にぬれても平気[へいき]だ。", "sentence_source": "generated"}, {"text": "工事の人は一日中屋外で働いている。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]は一日中[いちにちじゅう]屋外[おくがい]で働[はたら]いている。", "sentence_source": "generated"}, {"text": "屋内は暖かいが、屋外は風が強くて寒い。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "屋内[おくない]は暖[あたた]かいが、屋外[おくがい]は風[かぜ]が強[つよ]くて寒[さむ]い。", "sentence_source": "generated"}, {"text": "冬に犬を屋外につないでおくのは危ない。", "target_word": "屋外", "complexity_tier": "T3", "furigana": "冬[ふゆ]に犬[いぬ]を屋外[おくがい]につないでおくのは危[あぶ]ない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "屋外", "label": "基本形"}], "register": "中立", "sense_fingerprint": "建物の外の場所（屋内の対）、戸外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9355037-504a-4712-9844-167042b60a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52736, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "屋外", "is_correct": true, "explanation": "「にて」は場所を表すので、場所を表す「屋外」が入る。"}, {"text": "肥料", "is_correct": false, "explanation": "「にて」の前には場所の名詞が必要で、肥料は場所ではないので入らない。"}, {"text": "種子", "is_correct": false, "explanation": "種子は場所ではないので、「日々○○にて」の形に入らない。"}, {"text": "農薬", "is_correct": false, "explanation": "農薬は場所を表さず、「日々農薬にて植物の萌芽を見守る」は場所の意味が通らない。"}], "explanations": {"屋外": "「にて」は場所を表すので、場所を表す「屋外」が入る。", "肥料": "「にて」の前には場所の名詞が必要で、肥料は場所ではないので入らない。", "種子": "種子は場所ではないので、「日々○○にて」の形に入らない。", "農薬": "農薬は場所を表さず、「日々農薬にて植物の萌芽を見守る」は場所の意味が通らない。"}, "sentence_index": 0, "correct_answer": "屋外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓を開けて、屋外を深く吸い込んだ。", "explanation": "ここは〈外気〉の意味。窓から吸い込むのは外の空気（外気）で、場所を表す「屋外」は吸い込めないので合わない。"}, {"text": "この部屋は屋外なので、エアコンがなくても涼しい。", "explanation": "ここは〈屋内〉の意味。部屋は建物の中なので、「屋外」とは言わない。"}, {"text": "かばんの屋外のポケットに、財布を入れた。", "explanation": "ここは〈外側〉の意味。「屋外」は建物の外の場所を指すので、かばんの外側には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52736, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "屋外", "is_correct": true, "explanation": "「屋外のいす」で、建物の外に置いて使ういすを表すので自然。"}, {"text": "泥", "is_correct": false, "explanation": "泥は「いす」を表す語にならず、「泥のいす」は意味が通らない。"}, {"text": "萌芽", "is_correct": false, "explanation": "萌芽は「いす」を表す語にならず、「萌芽のいす」は意味が通らない。"}, {"text": "植物", "is_correct": false, "explanation": "植物は「いす」の種類や用途を表す語ではなく、「植物のいす」は意味が通らない。"}], "explanations": {"屋外": "「屋外のいす」で、建物の外に置いて使ういすを表すので自然。", "泥": "泥は「いす」を表す語にならず、「泥のいす」は意味が通らない。", "萌芽": "萌芽は「いす」を表す語にならず、「萌芽のいす」は意味が通らない。", "植物": "植物は「いす」の種類や用途を表す語ではなく、「植物のいす」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "屋外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒い日は、屋外に入ってあたたまる。", "explanation": "ここは〈屋内〉の意味。「入る」は建物の中へ向かう動詞なので、「屋外に入る」とは言わない。"}, {"text": "会議室に、会社の屋外の人を案内した。", "explanation": "ここは〈外部〉の意味。屋外は場所を指すので、会社の外から来た人は「外部の人」と言い、「屋外の人」とは言わない。"}, {"text": "大学を卒業したら、屋外へ留学するつもりだ。", "explanation": "ここは〈海外〉の意味。「屋外」は建物の外を指すので、外国を指すときには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52736, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋外を遊ぶと、日焼けしやすい。", "corrected_sentence": "屋外で遊ぶと、日焼けしやすい。", "error_description": "「屋外で遊ぶ」の「で」が「を」になっている。「遊ぶ」は場所を「で」で示すので、「屋外を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52736, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋外へ働く人は、日焼け対策が必要だ。", "corrected_sentence": "屋外で働く人は、日焼け対策が必要だ。", "error_description": "「屋外で働く」の「で」が「へ」になっている。「働く」は場所を「で」で示すので、方向の「へ」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52737, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "花が咲いている場所を表すので、「花壇に花が咲く」が自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、咲いている場所にはならない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表すので、咲いている場所にはならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すので、咲く場所を表す文として不自然。"}], "correct_answer": "に", "explanations": {"に": "花が咲いている場所を表すので、「花壇に花が咲く」が自然。", "へ": "方向を表すので、咲いている場所にはならない。", "を": "目的語を表すので、咲いている場所にはならない。", "から": "起点を表すので、咲く場所を表す文として不自然。"}, "error_tags": {"へ": "方向", "を": "目的語", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52737, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「花壇が広い」の主語を表すので、自然に入る。"}, {"text": "を", "is_correct": false, "explanation": "形容詞「広い」の主語は「が」で、「を」では文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すので、主語にならない。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾する助詞で、述語を作れない。"}], "correct_answer": "が", "explanations": {"が": "「花壇が広い」の主語を表すので、自然に入る。", "を": "形容詞「広い」の主語は「が」で、「を」では文が成り立たない。", "から": "起点を表すので、主語にならない。", "の": "名詞を修飾する助詞で、述語を作れない。"}, "error_tags": {"を": "目的語", "から": "起点", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52737, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "花をうえるための、小さな土のばしょ。", "primary_collocate": null, "pronunciation": "かだん", "ipa": "kadaɴ", "syllable_count": 3, "sentences": [{"text": "庭に小さな花壇を作りました。", "target_word": "花壇", "complexity_tier": "T2", "furigana": "庭[にわ]に小[ちい]さな花壇[かだん]を作[つく]りました。", "sentence_source": "generated"}, {"text": "花壇にきれいな花が咲いています。", "target_word": "花壇", "complexity_tier": "T2", "furigana": "花壇[かだん]にきれいな花[はな]が咲[さ]いています。", "sentence_source": "generated"}, {"text": "毎日、花壇に水をやります。", "target_word": "花壇", "complexity_tier": "T2", "furigana": "毎日[まいにち]、花壇[かだん]に水[みず]をやります。", "sentence_source": "generated"}, {"text": "学校の花壇に、あさがおの種をまきました。", "target_word": "花壇", "complexity_tier": "T2", "furigana": "学校[がっこう]の花壇[かだん]に、あさがおの種[たね]をまきました。", "sentence_source": "generated"}, {"text": "花壇の花を、ねこが踏んでしまった。", "target_word": "花壇", "complexity_tier": "T2", "furigana": "花壇[かだん]の花[はな]を、ねこが踏[ふ]んでしまった。", "sentence_source": "generated"}, {"text": "雨が降ったので、花壇の土がぬれている。", "target_word": "花壇", "complexity_tier": "T2", "furigana": "雨[あめ]が降[ふ]ったので、花壇[かだん]の土[つち]がぬれている。", "sentence_source": "generated"}, {"text": "弟は花壇の前で、チョウを見ている。", "target_word": "花壇", "complexity_tier": "T2", "furigana": "弟[おとうと]は花壇[かだん]の前[まえ]で、チョウを見[み]ている。", "sentence_source": "generated"}, {"text": "花壇が広いので、花をたくさん植えられる。", "target_word": "花壇", "complexity_tier": "T2", "furigana": "花壇[かだん]が広[ひろ]いので、花[はな]をたくさん植[う]えられる。", "sentence_source": "generated"}, {"text": "駅の近くの花壇は、いつも手入れがされている。", "target_word": "花壇", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くの花壇[かだん]は、いつも手入[ていれ]がされている。", "sentence_source": "generated"}, {"text": "母は花壇のそばにいすを置いて、本を読んでいる。", "target_word": "花壇", "complexity_tier": "T3", "furigana": "母[はは]は花壇[かだん]のそばにいすを置[お]いて、本[ほん]を読[よ]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "花壇", "label": "基本形"}], "register": "中立", "sense_fingerprint": "花をうえる小さな土の場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9355037-504a-4712-9844-167042b60a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52737, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花壇", "is_correct": true, "explanation": "「庭に小さな花壇を作る」で、作るものとして自然に入る。"}, {"text": "雨音", "is_correct": false, "explanation": "雨音は「作る」の対象として意味が通らない。"}, {"text": "体温", "is_correct": false, "explanation": "体温は「作る」の対象にならず、文が成り立たない。"}, {"text": "挨拶", "is_correct": false, "explanation": "挨拶は庭に作るものではなく、「作る」の対象として意味が通らない。"}], "explanations": {"花壇": "「庭に小さな花壇を作る」で、作るものとして自然に入る。", "雨音": "雨音は「作る」の対象として意味が通らない。", "体温": "体温は「作る」の対象にならず、文が成り立たない。", "挨拶": "挨拶は庭に作るものではなく、「作る」の対象として意味が通らない。"}, "sentence_index": 0, "correct_answer": "花壇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校の帰りに、花壇で花を買った。", "explanation": "ここは〈花屋〉の意味。花壇は買い物をする店ではないので、花を買う場所にはならない。"}, {"text": "母の誕生日に、友達が花壇を贈ってくれた。", "explanation": "ここは〈花束〉の意味。贈るのは花束で、花壇は地面の区画なので贈り物にはならない。"}, {"text": "花瓶に水を入れて、花壇を生けた。", "explanation": "ここは〈切り花〉の意味。生けるのは切り花で、土を区切った花壇は生けられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52737, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花壇", "is_correct": true, "explanation": "「弟は花壇の前で、チョウを見ている」で、場所を表す名詞として自然。"}, {"text": "夕食", "is_correct": false, "explanation": "夕食は場所ではないので、「夕食の前で」は意味が通らない。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は場所ではないので、「宿題の前で」は意味が通らない。"}, {"text": "通知", "is_correct": false, "explanation": "通知は場所ではないので、「通知の前で」は意味が通らない。"}], "explanations": {"花壇": "「弟は花壇の前で、チョウを見ている」で、場所を表す名詞として自然。", "夕食": "夕食は場所ではないので、「夕食の前で」は意味が通らない。", "宿題": "宿題は場所ではないので、「宿題の前で」は意味が通らない。", "通知": "通知は場所ではないので、「通知の前で」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "花壇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "次の花壇でバスを降りた。", "explanation": "ここは〈バス停〉の意味。降りるのはバス停で、花壇は植物を育てる場所なので合わない。"}, {"text": "寝室の花壇で、ぐっすり眠った。", "explanation": "ここは〈寝床〉の意味。眠るのは寝床だが、花壇は土を区切った屋外の場所で、寝る場所ではないので合わない。"}, {"text": "私は花壇の先生に、お礼を言った。", "explanation": "ここは〈講師〉の意味。「花壇」は場所を表すので、人を指す語としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52737, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校庭の花壇を、チューリップを植えた。", "corrected_sentence": "校庭の花壇に、チューリップを植えた。", "error_description": "「花壇に植えた」の「に」が「を」になっている。「植える」は場所を「に」で示すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
