INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52738, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "庭や公園などで、花を育てるために土を盛って区切った場所。", "primary_collocate": null, "pronunciation": "かだん", "ipa": "kadaɴ", "syllable_count": 3, "sentences": [{"text": "裏庭の片隅に設えられた僅かな土塊、すなわち小さな花壇は、幼き子にとって広大な宇宙の縮図であった。", "target_word": "花壇", "complexity_tier": "T4", "furigana": "裏庭[うらにわ]の片隅[かたすみ]に設[しつら]えられた僅[わず]かな土塊[つちくれ]、すなわち小[ちい]さな花壇[かだん]は、幼[おさな]き子[こ]にとって広大[こうだい]な宇宙[うちゅう]の縮図[しゅくず]であった。", "sentence_source": "mined"}, {"text": "春になると、公園の花壇にチューリップが咲きます。", "target_word": "花壇", "complexity_tier": "T3", "furigana": "春[はる]になると、公園[こうえん]の花壇[かだん]にチューリップが咲[さ]きます。", "sentence_source": "generated"}, {"text": "祖母は毎朝、家の前の花壇に水をやっている。", "target_word": "花壇", "complexity_tier": "T3", "furigana": "祖母[そぼ]は毎朝[まいあさ]、家[いえ]の前[まえ]の花壇[かだん]に水[みず]をやっている。", "sentence_source": "generated"}, {"text": "昨日の大雨で、花壇の土が道路まで流れ出てしまった。", "target_word": "花壇", "complexity_tier": "T3", "furigana": "昨日[きのう]の大雨[おおあめ]で、花壇[かだん]の土[つち]が道路[どうろ]まで流[なが]れ出[で]てしまった。", "sentence_source": "generated"}, {"text": "花壇をレンガで囲んだので、犬が入ってこなくなった。", "target_word": "花壇", "complexity_tier": "T3", "furigana": "花壇[かだん]をレンガで囲[かこ]んだので、犬[いぬ]が入[はい]ってこなくなった。", "sentence_source": "generated"}, {"text": "学校の花壇は、美化委員が順番に世話をしている。", "target_word": "花壇", "complexity_tier": "T3", "furigana": "学校[がっこう]の花壇[かだん]は、美化[びか]委員[いいん]が順番[じゅんばん]に世話[せわ]をしている。", "sentence_source": "generated"}, {"text": "去年の花壇にはパンジーを植えたが、今年はひまわりにするつもりだ。", "target_word": "花壇", "complexity_tier": "T3", "furigana": "去年[きょねん]の花壇[かだん]にはパンジーを植[う]えたが、今年[ことし]はひまわりにするつもりだ。", "sentence_source": "generated"}, {"text": "駅前の花壇が荒らされていて、近所の人たちが心配している。", "target_word": "花壇", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の花壇[かだん]が荒[あ]らされていて、近所[きんじょ]の人[ひと]たちが心配[しんぱい]している。", "sentence_source": "generated"}, {"text": "花壇の雑草を抜いていたら、小さなカエルが飛び出してきた。", "target_word": "花壇", "complexity_tier": "T3", "furigana": "花壇[かだん]の雑草[ざっそう]を抜[ぬ]いていたら、小[ちい]さなカエルが飛[と]び出[だ]してきた。", "sentence_source": "generated"}, {"text": "日当たりのよい花壇では、ほかの場所より早く花が開く。", "target_word": "花壇", "complexity_tier": "T3", "furigana": "日当[ひあ]たりのよい花壇[かだん]では、ほかの場所[ばしょ]より早[はや]く花[はな]が開[ひら]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "花壇", "label": "基本形"}], "register": "中立", "sense_fingerprint": "花を育てるために土を盛って区切った庭・公園の一角", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9355037-504a-4712-9844-167042b60a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52738, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花壇", "is_correct": true, "explanation": "「小さな花壇は、広大な宇宙の縮図」と、土を区切った花壇の比喩として自然に入る。"}, {"text": "郵便", "is_correct": false, "explanation": "郵便は花壇の比喩として意味が通らず、文の内容に合わない。"}, {"text": "雨音", "is_correct": false, "explanation": "雨音は土の区画を表さず、「縮図」の比喩として意味が通らない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は土を区切った場所ではないので、文の比喩が成り立たない。"}], "explanations": {"花壇": "「小さな花壇は、広大な宇宙の縮図」と、土を区切った花壇の比喩として自然に入る。", "郵便": "郵便は花壇の比喩として意味が通らず、文の内容に合わない。", "雨音": "雨音は土の区画を表さず、「縮図」の比喩として意味が通らない。", "冷蔵庫": "冷蔵庫は土を区切った場所ではないので、文の比喩が成り立たない。"}, "sentence_index": 0, "correct_answer": "花壇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花瓶に水を入れて、花壇を生けた。", "explanation": "ここは〈切り花〉の意味。生けるのは切り花で、土を区切った花壇は生けられないので合わない。"}, {"text": "駅前の花壇の店員が、丁寧に花を売ってくれた。", "explanation": "ここは〈売り場〉の意味。花壇は地面の区画で花を売る場所ではないので、「花壇の店員」とは言わない。"}, {"text": "使わなくなった道具を、花壇にしまった。", "explanation": "ここは〈物置〉の意味。しまう先は物置などの収納場所で、花壇は植物を育てる場所なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52738, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花壇", "is_correct": true, "explanation": "「去年の花壇にはパンジーを植えた」で、植えた場所を表す。"}, {"text": "肥料", "is_correct": false, "explanation": "肥料は植える場所ではないので、「去年の肥料には植えた」は意味が通らない。"}, {"text": "種子", "is_correct": false, "explanation": "種子は植える場所ではないので、「去年の種子には植えた」は意味が通らない。"}, {"text": "雨水", "is_correct": false, "explanation": "雨水は植える場所ではないので、「去年の雨水には植えた」は意味が通らない。"}], "explanations": {"花壇": "「去年の花壇にはパンジーを植えた」で、植えた場所を表す。", "肥料": "肥料は植える場所ではないので、「去年の肥料には植えた」は意味が通らない。", "種子": "種子は植える場所ではないので、「去年の種子には植えた」は意味が通らない。", "雨水": "雨水は植える場所ではないので、「去年の雨水には植えた」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "花壇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅前の花壇で、母は花を買った。", "explanation": "ここは〈花屋〉の意味。花壇は買い物をする店ではないので、花を買う場所にはならない。"}, {"text": "母の誕生日に、友達が花壇を贈ってくれた。", "explanation": "ここは〈花束〉の意味。贈るのは花束で、花壇は地面の区画なので贈り物にはならない。"}, {"text": "電車の花壇に、母は乗り込んだ。", "explanation": "ここは〈車両〉の意味。乗り込むのは電車などの車両で、花壇は地面の区画なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52738, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家の前の花壇を、春にチューリップを植えた。", "corrected_sentence": "家の前の花壇に、春にチューリップを植えた。", "error_description": "「花壇に植えた」の「に」が「を」になっている。「植える」は場所を「に」で示すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52738, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駅前の花壇が、春の花を植えた。", "corrected_sentence": "駅前の花壇に、春の花を植えた。", "error_description": "「花壇に植えた」の「に」が「が」になっている。植える人は動作の主体なので、「花壇が」は主語として不自然で、場所を表す「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
