INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52739, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "時々、何かが起こること。", "primary_collocate": null, "pronunciation": "ときおり", "ipa": "tokioɾi", "syllable_count": 4, "sentences": [{"text": "時折、雨がぱらぱらと降ってきた。", "target_word": "時折", "complexity_tier": "T2", "furigana": "時折[ときおり]、雨[あめ]がぱらぱらと降[ふ]ってきた。", "sentence_source": "generated"}, {"text": "兄は時折、私に電話をくれる。", "target_word": "時折", "complexity_tier": "T2", "furigana": "兄[あに]は時折[ときおり]、私[わたし]に電話[でんわ]をくれる。", "sentence_source": "generated"}, {"text": "この道は静かで、時折車が通るだけだ。", "target_word": "時折", "complexity_tier": "T2", "furigana": "この道[みち]は静[しず]かで、時折[ときおり]車[くるま]が通[とお]るだけだ。", "sentence_source": "generated"}, {"text": "時折、犬が庭で大きな声でほえる。", "target_word": "時折", "complexity_tier": "T2", "furigana": "時折[ときおり]、犬[いぬ]が庭[にわ]で大[おお]きな声[こえ]でほえる。", "sentence_source": "generated"}, {"text": "父は時折、夜おそくまで本を読んでいる。", "target_word": "時折", "complexity_tier": "T2", "furigana": "父[ちち]は時折[ときおり]、夜[よる]おそくまで本[ほん]を読[よ]んでいる。", "sentence_source": "generated"}, {"text": "海を見ていると、時折魚がはねた。", "target_word": "時折", "complexity_tier": "T2", "furigana": "海[うみ]を見[み]ていると、時折[ときおり]魚[さかな]がはねた。", "sentence_source": "generated"}, {"text": "母は台所で、時折なつかしい歌を口ずさんでいる。", "target_word": "時折", "complexity_tier": "T3", "furigana": "母[はは]は台所[だいどころ]で、時折[ときおり]なつかしい歌[うた]を口[くち]ずさんでいる。", "sentence_source": "generated"}, {"text": "教室の中は静かで、時折せきの音がするだけだった。", "target_word": "時折", "complexity_tier": "T3", "furigana": "教室[きょうしつ]の中[なか]は静[しず]かで、時折[ときおり]せきの音[おと]がするだけだった。", "sentence_source": "generated"}, {"text": "彼女は時折、遠くを見つめて考え込む。", "target_word": "時折", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は時折[ときおり]、遠[とお]くを見[み]つめて考[かんが]え込[こ]む。", "sentence_source": "generated"}, {"text": "風が時折、カーテンをゆらした。", "target_word": "時折", "complexity_tier": "T2", "furigana": "風[かぜ]が時折[ときおり]、カーテンをゆらした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "時折", "label": "基本形"}], "register": "やや改まった標準語", "sense_fingerprint": "何かが時々起こること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: ゆらし (Zipf 1.73)']::text[], 'b9355037-504a-4712-9844-167042b60a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52739, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "時折", "is_correct": true, "explanation": "ここは『ときどき』の意味。雨が間をおいてぱらぱら降る様子を表し、文に合う。"}, {"text": "極めて", "is_correct": false, "explanation": "形容詞や形容動詞を修飾する語で、『雨がぱらぱら降る』という動作は修飾できない。"}, {"text": "大いに", "is_correct": false, "explanation": "程度の大きさを表す語で、雨が降り出す出来事の頻度を表す文脈には合わない。"}, {"text": "決して", "is_correct": false, "explanation": "『決して〜ない』の形でしか使えない副詞なので、肯定文の空所には入らない。"}], "explanations": {"時折": "ここは『ときどき』の意味。雨が間をおいてぱらぱら降る様子を表し、文に合う。", "極めて": "形容詞や形容動詞を修飾する語で、『雨がぱらぱら降る』という動作は修飾できない。", "大いに": "程度の大きさを表す語で、雨が降り出す出来事の頻度を表す文脈には合わない。", "決して": "『決して〜ない』の形でしか使えない副詞なので、肯定文の空所には入らない。"}, "sentence_index": 0, "correct_answer": "時折"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は毎朝、時折新聞を読む。", "explanation": "ここは〈決まって毎回〉の意味。時折は不定期に起こる意味なので、決まった日課とは両立しない。"}, {"text": "その店は時折一度だけ開いた。", "explanation": "ここは〈一回限り〉の意味。時折は何度か間をおいて起こる出来事に使うので、一回きりの出来事には合わない。"}, {"text": "会議は毎回、時折延期された。", "explanation": "ここは〈規則的に決まって起こる〉の意味。時折は不定期に起こる意味なので、規則的な出来事とは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52739, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "時折", "is_correct": true, "explanation": "ここは『ときどき』の意味。母が間をおいて歌を口ずさむ様子を表し、文に合う。"}, {"text": "一向に", "is_correct": false, "explanation": "打ち消しと呼応する副詞で、肯定の『口ずさんでいる』の文脈には入らない。"}, {"text": "一切", "is_correct": false, "explanation": "『一切〜ない』と打ち消しで使う語で、肯定の文では不自然になる。"}, {"text": "二度と", "is_correct": false, "explanation": "『二度と〜ない』の形でしか使えない語なので、肯定文の空所には入らない。"}], "explanations": {"時折": "ここは『ときどき』の意味。母が間をおいて歌を口ずさむ様子を表し、文に合う。", "一向に": "打ち消しと呼応する副詞で、肯定の『口ずさんでいる』の文脈には入らない。", "一切": "『一切〜ない』と打ち消しで使う語で、肯定の文では不自然になる。", "二度と": "『二度と〜ない』の形でしか使えない語なので、肯定文の空所には入らない。"}, "sentence_index": 6, "correct_answer": "時折"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は時折、いつも同じ道を通る。", "explanation": "ここは〈決まって毎回〉の意味。時折は不定期の意味で、決まって行う習慣とは両立しない。"}, {"text": "彼女は時折、度々電話をくれる。", "explanation": "ここは〈何度も繰り返す〉の意味。時折は間をおいて起こる出来事に使うので、繰り返す様子とは合わない。"}, {"text": "この店は時折、必ず休む。", "explanation": "ここは〈確実に毎回〉の意味。時折は不定期の意味なので、確実性とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52739, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方になると、時折の雨が降り出した。", "corrected_sentence": "夕方になると、時折、雨が降り出した。", "error_description": "『時折』は副詞なので、『の』を付けて名詞を修飾できない。『時折、』と副詞として続ける形が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52739, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓辺で、時折な光が揺れた。", "corrected_sentence": "窓辺で、時折、光が揺れた。", "error_description": "『時折』は副詞なので、『な』を付けて形容動詞のように使えない。『時折、』と副詞として続ける形が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
