INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52740, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "あることが、ときどき起こるさま。たまに。", "primary_collocate": null, "pronunciation": "ときおり", "ipa": "tokioɾi", "syllable_count": 4, "sentences": [{"text": "やがて成長の過程において、植物は時折厳しい気候に晒されながらも、力強く茎を伸ばしていく。", "target_word": "時折", "complexity_tier": "T4", "furigana": "やがて成長[せいちょう]の過程[かてい]において、植物[しょくぶつ]は時折[ときおり]厳[きび]しい気候[きこう]に晒[さら]されながらも、力強[ちからづよ]く茎[くき]を伸[の]ばしていく。", "sentence_source": "mined"}, {"text": "山の天気は変わりやすく、時折強い風が吹く。", "target_word": "時折", "complexity_tier": "T3", "furigana": "山[やま]の天気[てんき]は変[か]わりやすく、時折[ときおり]強[つよ]い風[かぜ]が吹[ふ]く。", "sentence_source": "generated"}, {"text": "彼女は忙しい毎日の中でも、時折空を見上げて深呼吸をする。", "target_word": "時折", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は忙[いそが]しい毎日[まいにち]の中[なか]でも、時折[ときおり]空[そら]を見上[みあ]げて深呼吸[しんこきゅう]をする。", "sentence_source": "generated"}, {"text": "祖父は時折、若いころの旅の話を聞かせてくれる。", "target_word": "時折", "complexity_tier": "T3", "furigana": "祖父[そふ]は時折[ときおり]、若[わか]いころの旅[たび]の話[はなし]を聞[き]かせてくれる。", "sentence_source": "generated"}, {"text": "雲の切れ間から、時折日の光がさしこんできた。", "target_word": "時折", "complexity_tier": "T3", "furigana": "雲[くも]の切[き]れ間[ま]から、時折[ときおり]日[ひ]の光[ひかり]がさしこんできた。", "sentence_source": "generated"}, {"text": "窓の外から、時折子どもたちの笑い声が聞こえてくる。", "target_word": "時折", "complexity_tier": "T3", "furigana": "窓[まど]の外[そと]から、時折[ときおり]子[こ]どもたちの笑[わら]い声[ごえ]が聞[き]こえてくる。", "sentence_source": "generated"}, {"text": "普段は静かな図書館だが、時折大きな音が響いて驚かされる。", "target_word": "時折", "complexity_tier": "T3", "furigana": "普段[ふだん]は静[しず]かな図書館[としょかん]だが、時折[ときおり]大[おお]きな音[おと]が響[ひび]いて驚[おどろ]かされる。", "sentence_source": "generated"}, {"text": "昔の友人とは、時折手紙をやり取りしている。", "target_word": "時折", "complexity_tier": "T3", "furigana": "昔[むかし]の友人[ゆうじん]とは、時折[ときおり]手紙[てがみ]をやり取[と]りしている。", "sentence_source": "generated"}, {"text": "電車は順調に走っていたが、時折大きく揺れた。", "target_word": "時折", "complexity_tier": "T3", "furigana": "電車[でんしゃ]は順調[じゅんちょう]に走[はし]っていたが、時折[ときおり]大[おお]きく揺[ゆ]れた。", "sentence_source": "generated"}, {"text": "彼は無口な人だが、時折冗談を言って周りを笑わせる。", "target_word": "時折", "complexity_tier": "T3", "furigana": "彼[かれ]は無口[むくち]な人[ひと]だが、時折[ときおり]冗談[じょうだん]を言[い]って周[まわ]りを笑[わら]わせる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "時折", "label": "基本形"}], "register": "やや改まった標準語", "sense_fingerprint": "ある出来事がときどき間をおいて起こる様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: 切れ間 (Zipf 1.88)']::text[], 'b9355037-504a-4712-9844-167042b60a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52740, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "時折", "is_correct": true, "explanation": "ここは『ときどき』の意味。厳しい気候に晒される状況が間をおいて起こることを表し、文に合う。"}, {"text": "一向に", "is_correct": false, "explanation": "打ち消しと呼応する副詞で、肯定の『晒されながらも』の文脈には入らない。"}, {"text": "決して", "is_correct": false, "explanation": "『決して〜ない』の形でしか使えない副詞なので、肯定文の空所には入らない。"}, {"text": "一切", "is_correct": false, "explanation": "『一切〜ない』と打ち消しで使う語で、肯定の文では不自然になる。"}], "explanations": {"時折": "ここは『ときどき』の意味。厳しい気候に晒される状況が間をおいて起こることを表し、文に合う。", "一向に": "打ち消しと呼応する副詞で、肯定の『晒されながらも』の文脈には入らない。", "決して": "『決して〜ない』の形でしか使えない副詞なので、肯定文の空所には入らない。", "一切": "『一切〜ない』と打ち消しで使う語で、肯定の文では不自然になる。"}, "sentence_index": 0, "correct_answer": "時折"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、時折ランニングをしてから出社する。", "explanation": "ここは〈決まって毎回起こる〉の意味。時折は不定期に起こる意味なので、決まった日課とは両立しない。"}, {"text": "その展覧会は時折一度だけ開かれた。", "explanation": "ここは〈一回限りの出来事〉の意味。時折は間をおいて何度か起こる出来事に使うので、一回きりの出来事には合わない。"}, {"text": "海の波は時折、絶えず岸を打っている。", "explanation": "ここは〈途切れず続く〉の意味。時折は途切れて起こる様子を表すので、途切れずに続く様子とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52740, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "時折", "is_correct": true, "explanation": "ここは『ときどき』の意味。静かな図書館で大きな音が間をおいて響く様子を表し、文に合う。"}, {"text": "二度と", "is_correct": false, "explanation": "『二度と〜ない』の形でしか使えない語なので、肯定の『大きな音が響いて』には続かない。"}, {"text": "少しも", "is_correct": false, "explanation": "打ち消しと呼応する副詞で、肯定文の空所には入らない。"}, {"text": "断じて", "is_correct": false, "explanation": "『断じて〜ない』と否定を強める語で、肯定の文には使えない。"}], "explanations": {"時折": "ここは『ときどき』の意味。静かな図書館で大きな音が間をおいて響く様子を表し、文に合う。", "二度と": "『二度と〜ない』の形でしか使えない語なので、肯定の『大きな音が響いて』には続かない。", "少しも": "打ち消しと呼応する副詞で、肯定文の空所には入らない。", "断じて": "『断じて〜ない』と否定を強める語で、肯定の文には使えない。"}, "sentence_index": 6, "correct_answer": "時折"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は時折、常に同じ話を繰り返す。", "explanation": "ここは〈途切れず、ずっと続く〉の意味。時折は不定期の意味で、途切れずに続く様子とは両立しない。"}, {"text": "彼女は時折、度々遅刻する。", "explanation": "ここは〈何度も繰り返し起こる〉の意味。時折は間をおいて起こる出来事に使うので、繰り返し起こる様子とは合わない。"}, {"text": "この店は時折、必ず月曜日に休む。", "explanation": "ここは〈確実に毎回起こる〉の意味。時折は不定期の意味なので、確実に毎回起こるという性質とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52740, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公園の奥から時折の鳥の声が聞こえてくる。", "corrected_sentence": "公園の奥から時折、鳥の声が聞こえてくる。", "error_description": "『時折』は副詞なので、『の』を付けて名詞を修飾できない。『時折、』と副詞として続ける形が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52740, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の街で、時折な音がした。", "corrected_sentence": "夜の街で、時折、音がした。", "error_description": "『時折』は副詞なので、『な』を付けて形容動詞のように使えない。『時折、』と副詞として続ける形が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52741, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『風雨に晒される』の『に』で、晒される先を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "『風雨を晒される』となり、受身文の関係が崩れて文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "『風雨が晒される』となり、風雨が主語になって文脈に合わない。"}, {"text": "と", "is_correct": false, "explanation": "『風雨と晒される』となり、並列の意味になって文脈が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "『風雨に晒される』の『に』で、晒される先を示す格助詞。", "を": "『風雨を晒される』となり、受身文の関係が崩れて文が成り立たない。", "が": "『風雨が晒される』となり、風雨が主語になって文脈に合わない。", "と": "『風雨と晒される』となり、並列の意味になって文脈が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52741, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『潮風に晒される』の『に』で、晒される先を示す格助詞。"}, {"text": "で", "is_correct": false, "explanation": "『潮風で晒されて』は手段や場所の意味になり、受身の対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すが、『潮風へ晒される』は晒される先としては不自然。"}, {"text": "より", "is_correct": false, "explanation": "『潮風より晒される』は比較の意味になり、文が通らない。"}], "correct_answer": "に", "explanations": {"に": "『潮風に晒される』の『に』で、晒される先を示す格助詞。", "で": "『潮風で晒されて』は手段や場所の意味になり、受身の対象を示せない。", "へ": "『へ』は方向を示すが、『潮風へ晒される』は晒される先としては不自然。", "より": "『潮風より晒される』は比較の意味になり、文が通らない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52741, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "あるものを、風や雨や、人の目などに、あてること。", "primary_collocate": null, "pronunciation": "さらす", "ipa": "sarasɯ", "syllable_count": 3, "sentences": [{"text": "布を日なたに晒して、かわかします。", "target_word": "晒して", "complexity_tier": "T2", "furigana": "布[ぬの]を日[ひ]なたに晒[さら]して、かわかします。", "sentence_source": "generated"}, {"text": "畑の野菜が、強い風雨に晒されている。", "target_word": "晒されて", "complexity_tier": "T3", "furigana": "畑[はたけ]の野菜[やさい]が、強[つよ]い風雨[ふうう]に晒[さら]されている。", "sentence_source": "generated"}, {"text": "彼は顔を人の目に晒したくなくて、帽子をかぶった。", "target_word": "晒し", "complexity_tier": "T3", "furigana": "彼[かれ]は顔[かお]を人[ひと]の目[め]に晒[さら]したくなくて、帽子[ぼうし]をかぶった。", "sentence_source": "generated"}, {"text": "古い家は、雨や風に晒されてぼろぼろになった。", "target_word": "晒されて", "complexity_tier": "T3", "furigana": "古[ふる]い家[いえ]は、雨[あめ]や風[かぜ]に晒[さら]されてぼろぼろになった。", "sentence_source": "generated"}, {"text": "本を日光に晒すと、色が変わってしまう。", "target_word": "晒す", "complexity_tier": "T2", "furigana": "本[ほん]を日光[にっこう]に晒[さら]すと、色[いろ]が変[か]わってしまう。", "sentence_source": "generated"}, {"text": "寒空の下に体を晒すと、すぐに風邪をひくよ。", "target_word": "晒す", "complexity_tier": "T3", "furigana": "寒空[さむぞら]の下[した]に体[からだ]を晒[さら]すと、すぐに風邪[かぜ]をひくよ。", "sentence_source": "generated"}, {"text": "弟は友だちの前で失敗を晒してしまった。", "target_word": "晒して", "complexity_tier": "T3", "furigana": "弟[おとうと]は友[とも]だちの前[まえ]で失敗[しっぱい]を晒[さら]してしまった。", "sentence_source": "generated"}, {"text": "海のそばの船は、潮風に晒されて、さびやすい。", "target_word": "晒されて", "complexity_tier": "T3", "furigana": "海[うみ]のそばの船[ふね]は、潮風[しおかぜ]に晒[さら]されて、さびやすい。", "sentence_source": "generated"}, {"text": "犬を真夏の日差しに晒さないでください。", "target_word": "晒さ", "complexity_tier": "T3", "furigana": "犬[いぬ]を真夏[まなつ]の日差[ひざ]しに晒[さら]さないでください。", "sentence_source": "generated"}, {"text": "彼女は、みんなの目に晒されて、顔が赤くなった。", "target_word": "晒されて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は、みんなの目[め]に晒[さら]されて、顔[かお]が赤[あか]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "晒す", "label": "終止形"}, {"form": "晒さ", "label": "未然形"}, {"form": "晒し", "label": "連用形"}, {"form": "晒して", "label": "て形"}, {"form": "晒され", "label": "受身形（連用形）"}, {"form": "晒された", "label": "受身形（過去）"}], "register": "中立", "sense_fingerprint": "風・雨・人の目などにあてる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: かわかし (Zipf 1.27)']::text[], 'b9355037-504a-4712-9844-167042b60a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52741, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晒して", "is_correct": true, "explanation": "『晒す』のて形で、布を日なたに当てて乾かすという意味になり、文に合う。"}, {"text": "切って", "is_correct": false, "explanation": "『切る』のて形で、布を日なたで切るという文脈は乾かす文に合わない。"}, {"text": "縫って", "is_correct": false, "explanation": "『縫う』のて形で、日なたで布を縫うという文脈は不自然。"}, {"text": "結んで", "is_correct": false, "explanation": "『結ぶ』のて形で、布を日なたに結ぶという文脈は乾燥の文脈に合わない。"}], "explanations": {"晒して": "『晒す』のて形で、布を日なたに当てて乾かすという意味になり、文に合う。", "切って": "『切る』のて形で、布を日なたで切るという文脈は乾かす文に合わない。", "縫って": "『縫う』のて形で、日なたで布を縫うという文脈は不自然。", "結んで": "『結ぶ』のて形で、布を日なたに結ぶという文脈は乾燥の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "晒して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は寒さをしのぐため、布団の中に体を晒した。", "explanation": "ここは〈遮って守る〉の意味。晒すは風や雨などに当てる意味で、布団で遮る文脈とは逆になる。"}, {"text": "雨の日は、ビニールで野菜を晒している。", "explanation": "ここは〈覆う〉の意味。晒すは風雨や人の目に当てる意味で、覆って守る目的とは逆になる。"}, {"text": "子猫は箱に晒されていた。", "explanation": "ここは〈閉じ込める〉の意味。晒すは直接当てる意味で、箱に閉じ込める文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52741, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晒して", "is_correct": true, "explanation": "『晒す』のて形。失敗を人前にさらしたという意味になり、文に合う。"}, {"text": "叫んで", "is_correct": false, "explanation": "『叫ぶ』のて形で、失敗を叫ぶという文脈は不自然。"}, {"text": "眠って", "is_correct": false, "explanation": "『眠る』のて形で、失敗を眠らせるという文脈は成り立たない。"}, {"text": "煮て", "is_correct": false, "explanation": "『煮る』のて形で、失敗を煮るという文脈は成り立たない。"}], "explanations": {"晒して": "『晒す』のて形。失敗を人前にさらしたという意味になり、文に合う。", "叫んで": "『叫ぶ』のて形で、失敗を叫ぶという文脈は不自然。", "眠って": "『眠る』のて形で、失敗を眠らせるという文脈は成り立たない。", "煮て": "『煮る』のて形で、失敗を煮るという文脈は成り立たない。"}, "sentence_index": 6, "correct_answer": "晒して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は顔を人の目に晒すため、帽子をかぶった。", "explanation": "ここは〈隠す〉の意味。晒すは人の目に当てる意味で、人の目から隠す目的とは逆になる。"}, {"text": "強い日差しに晒すため、彼は木陰に入った。", "explanation": "ここは〈避ける〉の意味。晒すは当てる意味で、日差しを避けて木陰に入る文脈とは矛盾する。"}, {"text": "寒い日は、布で赤ちゃんを晒す。", "explanation": "ここは〈包む〉の意味。晒すは当てる意味で、布で包んで守る文脈とは逆になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52741, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家の裏で、洗った糸を日なたに晒さて、かわかす。", "corrected_sentence": "家の裏で、洗った糸を日なたに晒して、かわかす。", "error_description": "て形は『晒して』。『晒さ』は未然形なので、『て』に直接続けられない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "晒されて", "is_correct": true, "explanation": "受身のて形で、『晒されている』と状態を表す形。"}, {"text": "晒す", "is_correct": false, "explanation": "終止形の能動形で、受身の『晒されている』の形にならない。"}, {"text": "晒し", "is_correct": false, "explanation": "連用形のため、後ろの『いる』の前に『て』が要り、『晒しいる』となって成り立たない。"}, {"text": "晒さ", "is_correct": false, "explanation": "未然形で、単独では『ている』に続かない。"}], "correct_form": "晒されて", "base_form": "晒す", "form_label": "受身形（て形）", "sentence_index": 1, "explanations": {"晒されて": "受身のて形で、『晒されている』と状態を表す形。", "晒す": "終止形の能動形で、受身の『晒されている』の形にならない。", "晒し": "連用形のため、後ろの『いる』の前に『て』が要り、『晒しいる』となって成り立たない。", "晒さ": "未然形で、単独では『ている』に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52741, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓辺の鉢は、強い日差しを晒されて枯れてしまった。", "corrected_sentence": "窓辺の鉢は、強い日差しに晒されて枯れてしまった。", "error_description": "『晒される』は『～に晒される』の形で、晒される先には『に』を使う。『を』は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "晒されて", "is_correct": true, "explanation": "受身のて形で、『潮風に晒されて』と原因や経過を示す形。"}, {"text": "晒された", "is_correct": false, "explanation": "過去形で、『さびやすい』という一般的な性質の文には合わない。"}, {"text": "晒せる", "is_correct": false, "explanation": "可能形で、受身の意味にならず文が成り立たない。"}, {"text": "晒せ", "is_correct": false, "explanation": "命令形で、この文の述語として成り立たない。"}], "correct_form": "晒されて", "base_form": "晒す", "form_label": "受身形（て形）", "sentence_index": 7, "explanations": {"晒されて": "受身のて形で、『潮風に晒されて』と原因や経過を示す形。", "晒された": "過去形で、『さびやすい』という一般的な性質の文には合わない。", "晒せる": "可能形で、受身の意味にならず文が成り立たない。", "晒せ": "命令形で、この文の述語として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52742, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『日光に晒す』の『に』で、晒す先を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "『日光を晒す』となり、晒す対象が日光になってしまい文の意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "『日光が晒す』となり、日光が主語になって文脈に合わない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すが、『日光から晒す』では晒す先を示せず不自然。"}], "correct_answer": "に", "explanations": {"に": "『日光に晒す』の『に』で、晒す先を示す格助詞。", "を": "『日光を晒す』となり、晒す対象が日光になってしまい文の意味が通らない。", "が": "『日光が晒す』となり、日光が主語になって文脈に合わない。", "から": "『から』は起点を示すが、『日光から晒す』では晒す先を示せず不自然。"}, "error_tags": {"を": "目的語", "が": "主語", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52742, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52742, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事を、風雨や日光、また人の批判や危険などに、直接当てられる状態に置くこと。", "primary_collocate": null, "pronunciation": "さらす", "ipa": "sarasɯ", "syllable_count": 3, "sentences": [{"text": "やがて成長の過程において、植物は時折厳しい気候に晒されながらも、力強く茎を伸ばしていく。", "target_word": "晒され", "complexity_tier": "T4", "furigana": "やがて成長[せいちょう]の過程[かてい]において、植物[しょくぶつ]は時折[ときおり]厳[きび]しい気候[きこう]に晒[さら]されながらも、力強[ちからづよ]く茎[くき]を伸[の]ばしていく。", "sentence_source": "mined"}, {"text": "洗濯物を日光に晒すと、白い服はさらに白くなる。", "target_word": "晒す", "complexity_tier": "T3", "furigana": "洗濯物[せんたくもの]を日光[にっこう]に晒[さら]すと、白[しろ]い服[ふく]はさらに白[しろ]くなる。", "sentence_source": "generated"}, {"text": "彼は危険に身を晒してまで、子どもを助けようとした。", "target_word": "晒して", "complexity_tier": "T3", "furigana": "彼[かれ]は危険[きけん]に身[み]を晒[さら]してまで、子[こ]どもを助[たす]けようとした。", "sentence_source": "generated"}, {"text": "古い木の看板は、長年雨風に晒されて文字が消えかけている。", "target_word": "晒されて", "complexity_tier": "T3", "furigana": "古[ふる]い木[き]の看板[かんばん]は、長年[ながねん]雨風[あめかぜ]に晒[さら]されて文字[もじ]が消[き]えかけている。", "sentence_source": "generated"}, {"text": "不正が発覚し、社長は世間の批判に晒された。", "target_word": "晒された", "complexity_tier": "T3", "furigana": "不正[ふせい]が発覚[はっかく]し、社長[しゃちょう]は世間[せけん]の批判[ひはん]に晒[さら]された。", "sentence_source": "generated"}, {"text": "恥を晒すのが嫌で、彼は最後まで本当のことを言わなかった。", "target_word": "晒す", "complexity_tier": "T3", "furigana": "恥[はじ]を晒[さら]すのが嫌[いや]で、彼[かれ]は最後[さいご]まで本当[ほんとう]のことを言[い]わなかった。", "sentence_source": "generated"}, {"text": "写真を直射日光に晒さないよう、暗い場所に保管してください。", "target_word": "晒さ", "complexity_tier": "T3", "furigana": "写真[しゃしん]を直射[ちょくしゃ]日光[にっこう]に晒[さら]さないよう、暗[くら]い場所[ばしょ]に保管[ほかん]してください。", "sentence_source": "generated"}, {"text": "戦場の兵士たちは、常に命の危険に晒されている。", "target_word": "晒されて", "complexity_tier": "T3", "furigana": "戦場[せんじょう]の兵士[へいし]たちは、常[つね]に命[いのち]の危険[きけん]に晒[さら]されている。", "sentence_source": "generated"}, {"text": "彼女はネット上で個人情報を晒され、深く傷ついた。", "target_word": "晒され", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はネット上[じょう]で個人[こじん]情報[じょうほう]を晒[さら]され、深[ふか]く傷[きず]ついた。", "sentence_source": "generated"}, {"text": "海辺の岩は、波に晒されて少しずつ削られていく。", "target_word": "晒されて", "complexity_tier": "T3", "furigana": "海辺[うみべ]の岩[いわ]は、波[なみ]に晒[さら]されて少[すこ]しずつ削[けず]られていく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "晒す", "label": "終止形"}, {"form": "晒さ", "label": "未然形"}, {"form": "晒し", "label": "連用形"}, {"form": "晒して", "label": "て形"}, {"form": "晒され", "label": "受身形（連用形）"}, {"form": "晒された", "label": "受身形（過去）"}], "register": "中立", "sense_fingerprint": "風雨・日光・批判・危険などに直接当たる状態に置く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9355037-504a-4712-9844-167042b60a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52742, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晒され", "is_correct": true, "explanation": "ここは『風雨や気候に直接当てられる』の意味。厳しい気候に晒されながらも成長する文脈に合う。"}, {"text": "眠り", "is_correct": false, "explanation": "『眠る』の連用形で、厳しい気候の中で眠りながら茎を伸ばすという文脈は成り立たず、文に合わない。"}, {"text": "誘われ", "is_correct": false, "explanation": "『誘う』の受身形で、気候に誘われるという文脈は成り立たない。"}, {"text": "祈り", "is_correct": false, "explanation": "『祈る』の連用形で、植物が気候に向かって祈るという文脈は合わない。"}], "explanations": {"晒され": "ここは『風雨や気候に直接当てられる』の意味。厳しい気候に晒されながらも成長する文脈に合う。", "眠り": "『眠る』の連用形で、厳しい気候の中で眠りながら茎を伸ばすという文脈は成り立たず、文に合わない。", "誘われ": "『誘う』の受身形で、気候に誘われるという文脈は成り立たない。", "祈り": "『祈る』の連用形で、植物が気候に向かって祈るという文脈は合わない。"}, "sentence_index": 0, "correct_answer": "晒され"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暑い日差しを晒しながら、畑を耕した。", "explanation": "ここは〈浴びる・受ける〉の意味。晒すは物を風雨などに直接当てる意味で、日差しを受ける意味では使わない。"}, {"text": "彼は本心を隠すため、みんなの前に晒した。", "explanation": "ここは〈秘めて人目から遠ざける〉の意味。晒すは人目などに当てる意味で、人目から遠ざける目的とは逆になる。"}, {"text": "彼は危険を避けるため、身を危険に晒して逃げた。", "explanation": "ここは〈身を守る・安全に置く〉の意味。晒すは危険に身を置く意味なので、安全を確保する文脈とは逆になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52742, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晒さ", "is_correct": true, "explanation": "『晒す』の未然形で、『晒さないよう』と否定の形になり、写真を直射日光に当てないという意味に合う。"}, {"text": "叫び", "is_correct": false, "explanation": "『叫ぶ』の連用形で、日光に対して叫ぶという文脈は成り立たない。"}, {"text": "眠ら", "is_correct": false, "explanation": "『眠る』の未然形で、写真を日光に眠らせるという文脈は不自然。"}, {"text": "笑わ", "is_correct": false, "explanation": "『笑う』の未然形で、日光に笑わせるという文脈は合わない。"}], "explanations": {"晒さ": "『晒す』の未然形で、『晒さないよう』と否定の形になり、写真を直射日光に当てないという意味に合う。", "叫び": "『叫ぶ』の連用形で、日光に対して叫ぶという文脈は成り立たない。", "眠ら": "『眠る』の未然形で、写真を日光に眠らせるという文脈は不自然。", "笑わ": "『笑う』の未然形で、日光に笑わせるという文脈は合わない。"}, "sentence_index": 6, "correct_answer": "晒さ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜は、畑の苗を布で晒して寒さから守る。", "explanation": "ここは〈覆う〉の意味。晒すは当てる意味で、布で覆って守る文脈とは逆になる。"}, {"text": "雨の日は、屋根の下で体を雨に晒して休む。", "explanation": "ここは〈雨宿りする〉の意味。晒すは雨風に当てる意味で、屋根の下で雨を避ける文脈とは逆になる。"}, {"text": "猫は部屋に晒されていた。", "explanation": "ここは〈閉じ込める〉の意味。晒すは直接当てる意味で、閉じ込める文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52742, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓辺の鉢は、直射日光に晒されすと枯れやすい。", "corrected_sentence": "窓辺の鉢は、直射日光に晒されると枯れやすい。", "error_description": "受身形の終止形は『晒される』で、『と』に続けるには『る』が必要。『晒されす』は活用が誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "晒す", "is_correct": true, "explanation": "終止形で、『晒すと』と『と』に続けて条件を表す形。"}, {"text": "晒さ", "is_correct": false, "explanation": "未然形で、『と』には続かないため『晒さと』は成り立たない。"}, {"text": "晒し", "is_correct": false, "explanation": "連用形で、『と』に続けることができない。"}, {"text": "晒して", "is_correct": false, "explanation": "て形で、『と』には続かないため条件の文にならない。"}], "correct_form": "晒す", "base_form": "晒す", "form_label": "終止形（「と」に続く）", "sentence_index": 1, "explanations": {"晒す": "終止形で、『晒すと』と『と』に続けて条件を表す形。", "晒さ": "未然形で、『と』には続かないため『晒さと』は成り立たない。", "晒し": "連用形で、『と』に続けることができない。", "晒して": "て形で、『と』には続かないため条件の文にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52742, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "堤防は高波を晒されて、毎年少しずつ傷んでいく。", "corrected_sentence": "堤防は高波に晒されて、毎年少しずつ傷んでいく。", "error_description": "『晒す』は『～に晒す』の形で、晒される先には『に』を使う。『を』は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "晒されて", "is_correct": true, "explanation": "受身のて形で、『晒されている』と状態を表す形。"}, {"text": "晒された", "is_correct": false, "explanation": "過去の受身形で、現在の状態を表す文には合わない。"}, {"text": "晒され", "is_correct": false, "explanation": "連用形のため、後ろの『いる』の前に『て』が要り、『晒されいる』となって成り立たない。"}, {"text": "晒せる", "is_correct": false, "explanation": "可能形で、受身の意味にならず文が成り立たない。"}], "correct_form": "晒されて", "base_form": "晒す", "form_label": "受身形（て形）", "sentence_index": 7, "explanations": {"晒されて": "受身のて形で、『晒されている』と状態を表す形。", "晒された": "過去の受身形で、現在の状態を表す文には合わない。", "晒され": "連用形のため、後ろの『いる』の前に『て』が要り、『晒されいる』となって成り立たない。", "晒せる": "可能形で、受身の意味にならず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df3970cd-a79e-421f-bc7f-eec2cb8b2e61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52743, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「茎が長い」で、長いという状態の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「茎を長くて」は形容詞の主語を「を」で示すことになり、文法に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「茎に長くて」は位置を表し、長いという状態の主語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「茎で長くて」は手段の意味になり、状態の説明として通じない。"}], "correct_answer": "が", "explanations": {"が": "「茎が長い」で、長いという状態の主語を示す。", "を": "「茎を長くて」は形容詞の主語を「を」で示すことになり、文法に合わない。", "に": "「茎に長くて」は位置を表し、長いという状態の主語にならない。", "で": "「茎で長くて」は手段の意味になり、状態の説明として通じない。"}, "error_tags": {"を": "形容詞の主語の誤り", "に": "位置の誤り", "で": "手段の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52743, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「茎の太い草」で、茎の性質を名詞に結びつける用法として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「茎を太い草」は名詞の間に「を」を置けず、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「茎へ太い草」は方向を表し、性質の説明にならない。"}, {"text": "から", "is_correct": false, "explanation": "「茎から太い草」は起点を表し、茎の太さを説明しない。"}], "correct_answer": "の", "explanations": {"の": "「茎の太い草」で、茎の性質を名詞に結びつける用法として正しい。", "を": "「茎を太い草」は名詞の間に「を」を置けず、文として成り立たない。", "へ": "「茎へ太い草」は方向を表し、性質の説明にならない。", "から": "「茎から太い草」は起点を表し、茎の太さを説明しない。"}, "error_tags": {"を": "名詞の間の誤り", "へ": "方向の誤り", "から": "起点の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52743, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "くきのこと。花や葉っぱがついている、まっすぐなところ。", "primary_collocate": null, "pronunciation": "くき", "ipa": "kɯki", "syllable_count": 2, "sentences": [{"text": "花の茎をはさみで切って、水に入れました。", "target_word": "茎", "complexity_tier": "T3", "furigana": "花[はな]の茎[くき]をはさみで切[き]って、水[みず]に入[い]れました。", "sentence_source": "generated"}, {"text": "この草は茎が長くて、まっすぐ立っています。", "target_word": "茎", "complexity_tier": "T3", "furigana": "この草[くさ]は茎[くき]が長[なが]くて、まっすぐ立[た]っています。", "sentence_source": "generated"}, {"text": "茎に小さな葉がたくさんついています。", "target_word": "茎", "complexity_tier": "T3", "furigana": "茎[くき]に小[ちい]さな葉[は]がたくさんついています。", "sentence_source": "generated"}, {"text": "茎を持つと、少し冷たくて、しっとりしていました。", "target_word": "茎", "complexity_tier": "T3", "furigana": "茎[くき]を持[も]つと、少[すこ]し冷[つめ]たくて、しっとりしていました。", "sentence_source": "generated"}, {"text": "弟は花の茎を折ってしまって、母にしかられた。", "target_word": "茎", "complexity_tier": "T3", "furigana": "弟[おとうと]は花[はな]の茎[くき]を折[お]ってしまって、母[はは]にしかられた。", "sentence_source": "generated"}, {"text": "朝顔の茎が棒にくるくる巻きついています。", "target_word": "茎", "complexity_tier": "T3", "furigana": "朝顔[あさがお]の茎[くき]が棒[ぼう]にくるくる巻[ま]きついています。", "sentence_source": "generated"}, {"text": "茎が細い花は、風にゆらゆら揺れます。", "target_word": "茎", "complexity_tier": "T3", "furigana": "茎[くき]が細[ほそ]い花[はな]は、風[かぜ]にゆらゆら揺[ゆ]れます。", "sentence_source": "generated"}, {"text": "茎の太い草は、なかなか折れません。", "target_word": "茎", "complexity_tier": "T3", "furigana": "茎[くき]の太[ふと]い草[くさ]は、なかなか折[お]れません。", "sentence_source": "generated"}, {"text": "先生は、茎と葉と花を黒板に分けて描きました。", "target_word": "茎", "complexity_tier": "T3", "furigana": "先生[せんせい]は、茎[くき]と葉[は]と花[はな]を黒板[こくばん]に分[わ]けて描[えが]きました。", "sentence_source": "generated"}, {"text": "茎の上のほうに、つぼみが二つ出てきました。", "target_word": "茎", "complexity_tier": "T3", "furigana": "茎[くき]の上[うえ]のほうに、つぼみが二[ふた]つ出[で]てきました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "茎", "label": "基本形"}], "register": "標準", "sense_fingerprint": "花や葉がついているまっすぐな部分(茎)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f522c88-2b37-4463-ae1e-fd98b63d1180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52743, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "茎", "is_correct": true, "explanation": "花についている茎は、はさみで切って水に入れる対象として自然。"}, {"text": "花粉", "is_correct": false, "explanation": "花粉ははさみで切るものではなく、「花粉をはさみで切る」は成り立たない。"}, {"text": "蜜", "is_correct": false, "explanation": "蜜は液体なので、はさみで切ることはできない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは形がなく、はさみで切る対象にならない。"}], "explanations": {"茎": "花についている茎は、はさみで切って水に入れる対象として自然。", "花粉": "花粉ははさみで切るものではなく、「花粉をはさみで切る」は成り立たない。", "蜜": "蜜は液体なので、はさみで切ることはできない。", "香り": "香りは形がなく、はさみで切る対象にならない。"}, "sentence_index": 0, "correct_answer": "茎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この木は茎が太くて、台風でもびくともしない。", "explanation": "ここは〈幹〉の意味。木の太い中心部分は幹と言い、茎とは言わない。"}, {"text": "このフライパンは茎が長いので、手で持つと疲れにくい。", "explanation": "ここは〈柄〉の意味。道具を握る部分は柄と言い、茎とは言わない。"}, {"text": "ペンの茎をはずすと、中のインクが見えます。", "explanation": "ここは〈軸〉の意味。ペンの胴の部分は軸と言い、茎とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52743, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "茎", "is_correct": true, "explanation": "茎は細さを持つ部分なので、「茎が細い花」は自然に続く。"}, {"text": "色", "is_correct": false, "explanation": "「色が細い花」は意味が通らず、細さを表せない。"}, {"text": "音", "is_correct": false, "explanation": "「音が細い花」は意味が通らず、花の形を説明できない。"}, {"text": "影", "is_correct": false, "explanation": "「影が細い花」は花の形状を表せず、文として不自然。"}], "explanations": {"茎": "茎は細さを持つ部分なので、「茎が細い花」は自然に続く。", "色": "「色が細い花」は意味が通らず、細さを表せない。", "音": "「音が細い花」は意味が通らず、花の形を説明できない。", "影": "「影が細い花」は花の形状を表せず、文として不自然。"}, "sentence_index": 6, "correct_answer": "茎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この木は茎が広く張り出して、夏に木陰を作る。", "explanation": "ここは〈枝〉の意味。木から横に広がる部分は枝と言い、茎とは言わない。"}, {"text": "ひょうたんの茎が土の中へまっすぐ伸びて、水を吸い取っている。", "explanation": "ここは〈根〉の意味。土の中に伸びて水を吸う部分は根と言い、茎とは言わない。"}, {"text": "麦畑の茎がたくさんの種をつけ、もうすぐ刈り取りの時期です。", "explanation": "ここは〈穂〉の意味。麦や稲の実をつける先の部分は穂と言い、茎とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52743, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "花の茎を長くまっすぐ伸びて、先に花がつきます。", "corrected_sentence": "花の茎が長くまっすぐ伸びて、先に花がつきます。", "error_description": "助詞の誤り。「伸びる」は自動詞なので主語は「茎が」。「茎を」は誤りで、「茎が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52743, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "花の茎を折ないように、やさしく摘みました。", "corrected_sentence": "花の茎を折らないように、やさしく摘みました。", "error_description": "活用の誤り。「折る」の否定形は「折らない」で、「折ない」は誤った形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52744, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「切る」の対象を示す「茎を」で、直後の斜めに切る動作と合う。"}, {"text": "に", "is_correct": false, "explanation": "「茎に斜めに切る」では切る対象が示せず、場所や相手の意味になってしまう。"}, {"text": "が", "is_correct": false, "explanation": "「茎が斜めに切る」では茎が切る主体になり、意味が逆になる。"}, {"text": "と", "is_correct": false, "explanation": "「茎と斜めに切る」は相手や並列を表し、切る対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「切る」の対象を示す「茎を」で、直後の斜めに切る動作と合う。", "に": "「茎に斜めに切る」では切る対象が示せず、場所や相手の意味になってしまう。", "が": "「茎が斜めに切る」では茎が切る主体になり、意味が逆になる。", "と": "「茎と斜めに切る」は相手や並列を表し、切る対象を示せない。"}, "error_tags": {"に": "対象の誤り", "が": "主語の誤り", "と": "並列の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52744, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「茎が折れた」で、折れる主体を示し、バラの状態を正しく説明する。"}, {"text": "を", "is_correct": false, "explanation": "折れるは自動詞なので「茎を折れた」とは言わない。"}, {"text": "へ", "is_correct": false, "explanation": "「茎へ折れた」は方向を表し、折れた状態の説明にならない。"}, {"text": "と", "is_correct": false, "explanation": "「茎と折れたバラ」は並列を表し、折れる起点を示せず、文として不自然。"}], "correct_answer": "が", "explanations": {"が": "「茎が折れた」で、折れる主体を示し、バラの状態を正しく説明する。", "を": "折れるは自動詞なので「茎を折れた」とは言わない。", "へ": "「茎へ折れた」は方向を表し、折れた状態の説明にならない。", "と": "「茎と折れたバラ」は並列を表し、折れる起点を示せず、文として不自然。"}, "error_tags": {"を": "自動詞との誤り", "へ": "方向の誤り", "と": "並列の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52744, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物の、根と葉や花をつなぐ部分。地上に伸び、葉や花を支える。", "primary_collocate": null, "pronunciation": "くき", "ipa": "kɯki", "syllable_count": 2, "sentences": [{"text": "やがて成長の過程において、植物は時折厳しい気候に晒されながらも、力強く茎を伸ばしていく。", "target_word": "茎", "complexity_tier": "T4", "furigana": "やがて成長[せいちょう]の過程[かてい]において、植物[しょくぶつ]は時折[ときおり]厳[きび]しい気候[きこう]に晒[さら]されながらも、力強[ちからづよ]く茎[くき]を伸[の]ばしていく。", "sentence_source": "mined"}, {"text": "花瓶に入れる前に、チューリップの茎を斜めに切りました。", "target_word": "茎", "complexity_tier": "T3", "furigana": "花瓶[かびん]に入[い]れる前[まえ]に、チューリップの茎[くき]を斜[なな]めに切[き]りました。", "sentence_source": "generated"}, {"text": "この花は茎が細いので、強い風が吹くと折れてしまいます。", "target_word": "茎", "complexity_tier": "T3", "furigana": "この花[はな]は茎[くき]が細[ほそ]いので、強[つよ]い風[かぜ]が吹[ふ]くと折[お]れてしまいます。", "sentence_source": "generated"}, {"text": "茎の先にきれいな黄色い花が一輪咲いています。", "target_word": "茎", "complexity_tier": "T3", "furigana": "茎[くき]の先[さき]にきれいな黄色[きいろ]い花[はな]が一輪[いちりん]咲[さ]いています。", "sentence_source": "generated"}, {"text": "ひまわりの茎は太くて、子供の背丈より高く伸びました。", "target_word": "茎", "complexity_tier": "T3", "furigana": "ひまわりの茎[くき]は太[ふと]くて、子供[こども]の背丈[せたけ]より高[たか]く伸[の]びました。", "sentence_source": "generated"}, {"text": "雨でアサガオの茎が倒れたので、支柱を立てて結びました。", "target_word": "茎", "complexity_tier": "T3", "furigana": "雨[あめ]でアサガオの茎[くき]が倒[たお]れたので、支柱[しちゅう]を立[た]てて結[むす]びました。", "sentence_source": "generated"}, {"text": "茎の中を水が通って、葉の先まで届きます。", "target_word": "茎", "complexity_tier": "T3", "furigana": "茎[くき]の中[なか]を水[みず]が通[とお]って、葉[は]の先[さき]まで届[とど]きます。", "sentence_source": "generated"}, {"text": "茎が折れたバラは、花瓶に挿しても長くはもちません。", "target_word": "茎", "complexity_tier": "T3", "furigana": "茎[くき]が折[お]れたバラは、花瓶[かびん]に挿[さ]しても長[なが]くはもちません。", "sentence_source": "generated"}, {"text": "虫が茎にとまっていたので、そっと葉のほうへ移しました。", "target_word": "茎", "complexity_tier": "T3", "furigana": "虫[むし]が茎[くき]にとまっていたので、そっと葉[は]のほうへ移[うつ]しました。", "sentence_source": "generated"}, {"text": "緑色の茎は、葉と同じように光合成をしています。", "target_word": "茎", "complexity_tier": "T3", "furigana": "緑色[みどりいろ]の茎[くき]は、葉[は]と同[おな]じように光合成[こうごうせい]をしています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "茎", "label": "基本形"}], "register": "標準", "sense_fingerprint": "植物の根と葉や花をつなぎ、地上で全体を支える部分(茎)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f522c88-2b37-4463-ae1e-fd98b63d1180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52744, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "茎", "is_correct": true, "explanation": "植物が地上に伸ばして葉や花を支える部分なので、力強く伸ばしていく対象として自然。"}, {"text": "花", "is_correct": false, "explanation": "花は咲くものであり、力強く伸ばしていく対象としては合わない。"}, {"text": "種", "is_correct": false, "explanation": "種は芽を出させるものであり、伸ばしていく対象にはならない。"}, {"text": "実", "is_correct": false, "explanation": "実は実って熟すもので、伸ばして長くするものではない。"}], "explanations": {"茎": "植物が地上に伸ばして葉や花を支える部分なので、力強く伸ばしていく対象として自然。", "花": "花は咲くものであり、力強く伸ばしていく対象としては合わない。", "種": "種は芽を出させるものであり、伸ばしていく対象にはならない。", "実": "実は実って熟すもので、伸ばして長くするものではない。"}, "sentence_index": 0, "correct_answer": "茎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この松の茎は太くて、雪の重さにも耐えている。", "explanation": "ここは〈幹〉の意味。樹木の太い中心部分は幹と言い、茎とは言わない。"}, {"text": "このフライパンは茎が長いので、手で持つと疲れにくい。", "explanation": "ここは〈柄〉の意味。道具を握る部分は柄と言い、茎とは言わない。"}, {"text": "ペンの茎を回すと、芯が出てくる仕組みです。", "explanation": "ここは〈軸〉の意味。ペンの胴の部分は軸と言い、茎とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52744, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "茎", "is_correct": true, "explanation": "茎は根から吸い上げた水が通る管の部分なので、中を水が通るという文に合う。"}, {"text": "花粉", "is_correct": false, "explanation": "花粉は粒子であり、水が中を通って届く管にはならない。"}, {"text": "蜜", "is_correct": false, "explanation": "蜜は花が出す甘い液で、水が通って葉の先まで届く経路を表せない。"}, {"text": "色", "is_correct": false, "explanation": "色は通り道になるものではなく、「色の中を水が通る」は意味が通らない。"}], "explanations": {"茎": "茎は根から吸い上げた水が通る管の部分なので、中を水が通るという文に合う。", "花粉": "花粉は粒子であり、水が中を通って届く管にはならない。", "蜜": "蜜は花が出す甘い液で、水が通って葉の先まで届く経路を表せない。", "色": "色は通り道になるものではなく、「色の中を水が通る」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "茎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この木の茎は横へ広がって、夏に涼しい影を作る。", "explanation": "ここは〈枝〉の意味。木から横へ分かれて伸びる部分は枝と言い、茎とは言わない。"}, {"text": "ぶどうの茎が土の中へまっすぐ伸びて、水を吸い取っている。", "explanation": "ここは〈根〉の意味。土の中に伸びて水を吸う部分は根と言い、茎とは言わない。"}, {"text": "稲の茎が黄金色に実って、もうすぐ刈り取りの時期です。", "explanation": "ここは〈穂〉の意味。稲の実をつける先の部分は穂と言い、茎とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52744, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "花の茎に斜めに切ってから、水の入った花瓶に入れましょう。", "corrected_sentence": "花の茎を斜めに切ってから、水の入った花瓶に入れましょう。", "error_description": "助詞の誤り。「切る」は切る対象を「を」で示す他動詞なので、「茎に」ではなく「茎を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52744, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水は茎で葉の先まで上っていきます。", "corrected_sentence": "水は茎から葉の先まで上っていきます。", "error_description": "助詞の誤り。水が通る起点は「から」で示す。「茎で」は手段の意味になり、起点を表せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52745, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「手で伸ばす」で、動作の手段を示し、手で引き延ばす様子と合う。"}, {"text": "が", "is_correct": false, "explanation": "「手が伸ばして」は手が主語になり、粘土を伸ばす動作を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「手と伸ばして」は並列の意味になり、動作の手段を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「手から伸ばして」は起点を表し、手段の説明にならない。"}], "correct_answer": "で", "explanations": {"で": "「手で伸ばす」で、動作の手段を示し、手で引き延ばす様子と合う。", "が": "「手が伸ばして」は手が主語になり、粘土を伸ばす動作を表せない。", "と": "「手と伸ばして」は並列の意味になり、動作の手段を示せない。", "から": "「手から伸ばして」は起点を表し、手段の説明にならない。"}, "error_tags": {"が": "対象の誤り", "と": "並列の誤り", "から": "起点の誤り"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "縮める", "is_correct": true, "explanation": "「伸ばす」の対義語として、長さを短くする意味を表す。"}, {"text": "広げる", "is_correct": false, "explanation": "「広げる」は面積や範囲を広くする意味で、長さの対義語ではない。"}, {"text": "押す", "is_correct": false, "explanation": "「押す」は力を加える動作で、伸ばすの反対の意味ではない。"}, {"text": "まとめる", "is_correct": false, "explanation": "「まとめる」は集めて一つにする意味で、長さの対義語ではない。"}], "correct_answer": "縮める", "explanations": {"縮める": "「伸ばす」の対義語として、長さを短くする意味を表す。", "広げる": "「広げる」は面積や範囲を広くする意味で、長さの対義語ではない。", "押す": "「押す」は力を加える動作で、伸ばすの反対の意味ではない。", "まとめる": "「まとめる」は集めて一つにする意味で、長さの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52745, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「前に伸ばす」で、腕を伸ばす向きを示し、動作の状況に合う。"}, {"text": "を", "is_correct": false, "explanation": "「前を伸ばして」は前という場所を対象にしてしまい、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「前の伸ばして」は名詞修飾にならず、動詞の働きを示せない。"}, {"text": "より", "is_correct": false, "explanation": "「前より伸ばして」は比較の意味になり、腕を伸ばす動作の説明にならない。"}], "correct_answer": "に", "explanations": {"に": "「前に伸ばす」で、腕を伸ばす向きを示し、動作の状況に合う。", "を": "「前を伸ばして」は前という場所を対象にしてしまい、意味が通らない。", "の": "「前の伸ばして」は名詞修飾にならず、動詞の働きを示せない。", "より": "「前より伸ばして」は比較の意味になり、腕を伸ばす動作の説明にならない。"}, "error_tags": {"を": "対象の誤り", "の": "修飾の誤り", "より": "比較の誤り"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "縮める", "is_correct": true, "explanation": "「伸ばす」の対義語として、前足を縮める意味を表す。"}, {"text": "掴む", "is_correct": false, "explanation": "「掴む」は握る動作で、伸ばすの反対の意味ではない。"}, {"text": "叩く", "is_correct": false, "explanation": "「叩く」は打つ動作で、伸ばすの対義語とはされない。"}, {"text": "投げる", "is_correct": false, "explanation": "「投げる」は放る動作で、伸ばすの対義語とはされない。"}], "correct_answer": "縮める", "explanations": {"縮める": "「伸ばす」の対義語として、前足を縮める意味を表す。", "掴む": "「掴む」は握る動作で、伸ばすの反対の意味ではない。", "叩く": "「叩く」は打つ動作で、伸ばすの対義語とはされない。", "投げる": "「投げる」は放る動作で、伸ばすの対義語とはされない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52745, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "引っ張ったり広げたりして、物や体を長くまっすぐにすること。", "primary_collocate": null, "pronunciation": "のばす", "ipa": "nobasɯ", "syllable_count": 3, "sentences": [{"text": "ゴムを引っ張って伸ばすと、細く長くなります。", "target_word": "伸ばす", "complexity_tier": "T3", "furigana": "ゴムを引[ひ]っ張[ぱ]って伸[の]ばすと、細[ほそ]く長[なが]くなります。", "sentence_source": "generated"}, {"text": "粘土を手で伸ばして、細いひものような形にしました。", "target_word": "伸ばして", "complexity_tier": "T3", "furigana": "粘土[ねんど]を手[て]で伸[の]ばして、細[ほそ]いひものような形[かたち]にしました。", "sentence_source": "generated"}, {"text": "折れ曲がった針金をまっすぐに伸ばしてください。", "target_word": "伸ばして", "complexity_tier": "T3", "furigana": "折[お]れ曲[ま]がった針金[はりがね]をまっすぐに伸[の]ばしてください。", "sentence_source": "generated"}, {"text": "母はパン生地を麺棒で薄く伸ばしています。", "target_word": "伸ばして", "complexity_tier": "T3", "furigana": "母[はは]はパン生地[きじ]を麺棒[めんぼう]で薄[うす]く伸[の]ばしています。", "sentence_source": "generated"}, {"text": "長いすで足を伸ばして、のんびり休みました。", "target_word": "伸ばして", "complexity_tier": "T3", "furigana": "長[なが]いすで足[あし]を伸[の]ばして、のんびり休[やす]みました。", "sentence_source": "generated"}, {"text": "寝る前に、背中を伸ばす体操をしています。", "target_word": "伸ばす", "complexity_tier": "T3", "furigana": "寝[ね]る前[まえ]に、背中[せなか]を伸[の]ばす体操[たいそう]をしています。", "sentence_source": "generated"}, {"text": "先生はひもを伸ばして、端から端までの長さを測った。", "target_word": "伸ばして", "complexity_tier": "T3", "furigana": "先生[せんせい]はひもを伸[の]ばして、端[はし]から端[はし]までの長[なが]さを測[はか]った。", "sentence_source": "generated"}, {"text": "腕を前に伸ばして、棚の上の箱を取りました。", "target_word": "伸ばして", "complexity_tier": "T3", "furigana": "腕[うで]を前[まえ]に伸[の]ばして、棚[たな]の上[うえ]の箱[はこ]を取[と]りました。", "sentence_source": "generated"}, {"text": "折りたたみ式の棒を伸ばすと、二メートルになります。", "target_word": "伸ばす", "complexity_tier": "T3", "furigana": "折[お]りたたみ式[しき]の棒[ぼう]を伸[の]ばすと、二[に]メートルになります。", "sentence_source": "generated"}, {"text": "犬が前足を伸ばして、大きくあくびをした。", "target_word": "伸ばして", "complexity_tier": "T3", "furigana": "犬[いぬ]が前足[まえあし]を伸[の]ばして、大[おお]きくあくびをした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "伸ばす", "label": "終止形"}, {"form": "伸ばし", "label": "連用形"}, {"form": "伸ばして", "label": "て形"}, {"form": "伸ばした", "label": "た形"}, {"form": "伸ばさない", "label": "ない形"}, {"form": "伸ばせば", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "引っ張ったり広げたりして、物や体を長くまっすぐにする(他動詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T3: contains vocabulary far above tier T3: 麺棒 (Zipf 1.91)']::text[], '1f522c88-2b37-4463-ae1e-fd98b63d1180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52745, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伸ばす", "is_correct": true, "explanation": "終止形で「伸ばすと、細く長くなる」と条件の文になり、ゴムの性質を正しく述べる。"}, {"text": "伸ばさ", "is_correct": false, "explanation": "未然形は「伸ばさと」と続かず、条件の文が成り立たない。"}, {"text": "伸ばそう", "is_correct": false, "explanation": "意志形の「伸ばそうと」は意図の意味になり、ゴムの性質を述べる文に合わない。"}, {"text": "伸ばせ", "is_correct": false, "explanation": "命令形は文中で条件を表せず、「伸ばせと」は文法に合わない。"}], "explanations": {"伸ばす": "終止形で「伸ばすと、細く長くなる」と条件の文になり、ゴムの性質を正しく述べる。", "伸ばさ": "未然形は「伸ばさと」と続かず、条件の文が成り立たない。", "伸ばそう": "意志形の「伸ばそうと」は意図の意味になり、ゴムの性質を述べる文に合わない。", "伸ばせ": "命令形は文中で条件を表せず、「伸ばせと」は文法に合わない。"}, "sentence_index": 0, "correct_answer": "伸ばす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ボタンを強く伸ばすと、ランプがつきます。", "explanation": "ここは〈押す〉の意味。ボタンに力を加えて押す動作は押すと言い、伸ばすとは言わない。"}, {"text": "眼鏡を伸ばして、本を読んだ。", "explanation": "ここは〈かける〉の意味。眼鏡を顔に乗せる動作はかけると言い、伸ばすとは言わない。"}, {"text": "蓋を伸ばして、中身を隠した。", "explanation": "ここは〈かぶせる〉の意味。蓋を物の上に置く動作はかぶせると言い、伸ばすとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52745, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伸ばして", "is_correct": true, "explanation": "て形で「ひもを伸ばして、長さを測った」と動作が続き、文として成り立つ。"}, {"text": "伸ばせる", "is_correct": false, "explanation": "可能形は能力を表し、「ひもを伸ばせる」は動作の続きとして成り立たない。"}, {"text": "伸ばされる", "is_correct": false, "explanation": "受身形にするとひもが主語になり、先生が行った動作と合わない。"}, {"text": "伸ばさせる", "is_correct": false, "explanation": "使役形は他者に行わせる意味になり、先生が測る文脈と合わない。"}], "explanations": {"伸ばして": "て形で「ひもを伸ばして、長さを測った」と動作が続き、文として成り立つ。", "伸ばせる": "可能形は能力を表し、「ひもを伸ばせる」は動作の続きとして成り立たない。", "伸ばされる": "受身形にするとひもが主語になり、先生が行った動作と合わない。", "伸ばさせる": "使役形は他者に行わせる意味になり、先生が測る文脈と合わない。"}, "sentence_index": 6, "correct_answer": "伸ばして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷蔵庫の扉を伸ばして、中の牛乳を取り出した。", "explanation": "ここは〈開ける〉の意味。扉を開く動作は開けると言い、伸ばすとは言わない。"}, {"text": "雑誌を伸ばして、目次を読んだ。", "explanation": "ここは〈広げる〉の意味。紙面を広く開いて見る動作は広げると言い、伸ばすとは言わない。"}, {"text": "風船を伸ばして、子どもたちに配った。", "explanation": "ここは〈膨らませる〉の意味。風船に空気を入れて大きくする動作は膨らませると言い、伸ばすとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52745, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ひもが両手で伸ばして、長さを測りました。", "corrected_sentence": "ひもを両手で伸ばして、長さを測りました。", "error_description": "助詞の誤り。「伸ばす」は対象を「を」で示す他動詞なので、「ひもが」ではなく「ひもを」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "伸ばして", "is_correct": true, "explanation": "て形で、後ろに「細いひものような形にしました」と続き、手順として自然。"}, {"text": "伸ばした", "is_correct": false, "explanation": "た形で言い切ると後ろの文が続かず、「、」で結べない。"}, {"text": "伸ばさない", "is_correct": false, "explanation": "否定形は「伸ばさない」となり、形にしたという結果と逆になる。"}, {"text": "伸ばせば", "is_correct": false, "explanation": "仮定形は条件節になり、「形にしました」という事実を述べる文と合わない。"}], "correct_form": "伸ばして", "base_form": "伸ばす", "form_label": "て形", "sentence_index": 1, "explanations": {"伸ばして": "て形で、後ろに「細いひものような形にしました」と続き、手順として自然。", "伸ばした": "た形で言い切ると後ろの文が続かず、「、」で結べない。", "伸ばさない": "否定形は「伸ばさない」となり、形にしたという結果と逆になる。", "伸ばせば": "仮定形は条件節になり、「形にしました」という事実を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52745, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は折れた針金を手で伸ばしで、まっすぐにした。", "corrected_sentence": "弟は折れた針金を手で伸ばして、まっすぐにした。", "error_description": "活用の誤り。て形は「伸ばして」で、「伸ばしで」は誤った形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "伸ばして", "is_correct": true, "explanation": "て形で、後ろに「棚の上の箱を取りました」と続き、動作の順序を示す。"}, {"text": "伸ばさ", "is_correct": false, "explanation": "未然形は「、」で続けられず、文として成り立たない。"}, {"text": "伸ばされ", "is_correct": false, "explanation": "受身の連用形では腕が伸ばされる意味になり、腕を伸ばす動作と合わない。"}, {"text": "伸ばせる", "is_correct": false, "explanation": "可能形は能力の意味になり、「取りました」と続く動作の流れと合わない。"}], "correct_form": "伸ばして", "base_form": "伸ばす", "form_label": "て形", "sentence_index": 7, "explanations": {"伸ばして": "て形で、後ろに「棚の上の箱を取りました」と続き、動作の順序を示す。", "伸ばさ": "未然形は「、」で続けられず、文として成り立たない。", "伸ばされ": "受身の連用形では腕が伸ばされる意味になり、腕を伸ばす動作と合わない。", "伸ばせる": "可能形は能力の意味になり、「取りました」と続く動作の流れと合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52746, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「髪を伸ばす」で、伸ばす対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「髪が伸ばして」は伸ばす対象を示せず、主語にもならない。"}, {"text": "に", "is_correct": false, "explanation": "「髪に伸ばして」は位置や相手を表し、対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "「髪で伸ばして」は手段の意味になり、伸ばす対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「髪を伸ばす」で、伸ばす対象を示す。", "が": "「髪が伸ばして」は伸ばす対象を示せず、主語にもならない。", "に": "「髪に伸ばして」は位置や相手を表し、対象にならない。", "で": "「髪で伸ばして」は手段の意味になり、伸ばす対象を示せない。"}, "error_tags": {"が": "対象の誤り", "に": "位置の誤り", "で": "手段の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52746, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「横に伸ばす」で、伸ばす向きを示す副詞的な用法として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「横を伸ばして」は、横という場所を伸ばす対象にしてしまい、意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「横の伸ばして」は名詞修飾にならず、動詞の働きを示せない。"}, {"text": "より", "is_correct": false, "explanation": "「横より伸ばして」は比較の意味になり、ここでは通じない。"}], "correct_answer": "に", "explanations": {"に": "「横に伸ばす」で、伸ばす向きを示す副詞的な用法として正しい。", "を": "「横を伸ばして」は、横という場所を伸ばす対象にしてしまい、意味が通らない。", "の": "「横の伸ばして」は名詞修飾にならず、動詞の働きを示せない。", "より": "「横より伸ばして」は比較の意味になり、ここでは通じない。"}, "error_tags": {"を": "対象の誤り", "の": "修飾の誤り", "より": "比較の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52746, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "長さや大きさを大きくするようにすること。", "primary_collocate": null, "pronunciation": "のばす", "ipa": "nobasɯ", "syllable_count": 3, "sentences": [{"text": "やがて成長の過程において、植物は時折厳しい気候に晒されながらも、力強く茎を伸ばしていく。", "target_word": "伸ばし", "complexity_tier": "T4", "furigana": "やがて成長[せいちょう]の過程[かてい]において、植物[しょくぶつ]は時折[ときおり]厳[きび]しい気候[きこう]に晒[さら]されながらも、力強[ちからづよ]く茎[くき]を伸[の]ばしていく。", "sentence_source": "mined"}, {"text": "妹は髪を伸ばして、腰まで届くほど長くしたいそうです。", "target_word": "伸ばして", "complexity_tier": "T3", "furigana": "妹[いもうと]は髪[かみ]を伸[の]ばして、腰[こし]まで届[とど]くほど長[なが]くしたいそうです。", "sentence_source": "generated"}, {"text": "朝顔はつるを伸ばして、竹の棒に巻きついていきます。", "target_word": "伸ばして", "complexity_tier": "T3", "furigana": "朝顔[あさがお]はつるを伸[の]ばして、竹[たけ]の棒[ぼう]に巻[ま]きついていきます。", "sentence_source": "generated"}, {"text": "木は光を求めて、枝を空へ伸ばします。", "target_word": "伸ばします", "complexity_tier": "T3", "furigana": "木[き]は光[ひかり]を求[もと]めて、枝[えだ]を空[そら]へ伸[の]ばします。", "sentence_source": "generated"}, {"text": "祖父は去年からひげを伸ばしていて、顔の印象が変わった。", "target_word": "伸ばして", "complexity_tier": "T3", "furigana": "祖父[そふ]は去年[きょねん]からひげを伸[の]ばしていて、顔[かお]の印象[いんしょう]が変[か]わった。", "sentence_source": "generated"}, {"text": "植物は土の中で根を四方に伸ばし、水を探します。", "target_word": "伸ばし", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は土[つち]の中[なか]で根[ね]を四方[しほう]に伸[の]ばし、水[みず]を探[さが]します。", "sentence_source": "generated"}, {"text": "彼女は爪を伸ばして、毎週きれいに塗っています。", "target_word": "伸ばして", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は爪[つめ]を伸[の]ばして、毎週[まいしゅう]きれいに塗[ぬ]っています。", "sentence_source": "generated"}, {"text": "トマトは茎を横に伸ばして、実をたくさんつけます。", "target_word": "伸ばして", "complexity_tier": "T3", "furigana": "トマトは茎[くき]を横[よこ]に伸[の]ばして、実[み]をたくさんつけます。", "sentence_source": "generated"}, {"text": "雨が続いたせいで、雑草が一気に葉を伸ばした。", "target_word": "伸ばした", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]いたせいで、雑草[ざっそう]が一気[いっき]に葉[は]を伸[の]ばした。", "sentence_source": "generated"}, {"text": "長く伸ばした髪を、母が三つ編みにしてくれた。", "target_word": "伸ばした", "complexity_tier": "T3", "furigana": "長[なが]く伸[の]ばした髪[かみ]を、母[はは]が三[み]つ編[あ]みにしてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "伸ばす", "label": "終止形"}, {"form": "伸ばし", "label": "連用形"}, {"form": "伸ばして", "label": "て形"}, {"form": "伸ばした", "label": "た形"}, {"form": "伸ばさない", "label": "ない形"}, {"form": "伸ばせば", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "髪・枝・根などを成長させて長く大きくする(他動詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f522c88-2b37-4463-ae1e-fd98b63d1180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52746, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伸ばし", "is_correct": true, "explanation": "連用形で「伸ばしていく」となり、茎を長くしていく過程として自然に続く。"}, {"text": "伸ばさ", "is_correct": false, "explanation": "未然形は「伸ばさていく」と続かず、文が成り立たない。"}, {"text": "伸ばせ", "is_correct": false, "explanation": "命令形は文の途中に置けず、「伸ばせていく」は文法に合わない。"}, {"text": "伸ばす", "is_correct": false, "explanation": "終止形は「伸ばすていく」と続かず、「ていく」の前に置けない。"}], "explanations": {"伸ばし": "連用形で「伸ばしていく」となり、茎を長くしていく過程として自然に続く。", "伸ばさ": "未然形は「伸ばさていく」と続かず、文が成り立たない。", "伸ばせ": "命令形は文の途中に置けず、「伸ばせていく」は文法に合わない。", "伸ばす": "終止形は「伸ばすていく」と続かず、「ていく」の前に置けない。"}, "sentence_index": 0, "correct_answer": "伸ばし"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社の名前を伸ばして、人気を集めた。", "explanation": "ここは〈上げる〉の意味。評判を高める場合は名を上げると言い、伸ばすとは言わない。"}, {"text": "寒くなって食欲を伸ばした。", "explanation": "ここは〈増す〉の意味。食欲が強まることは増すと言い、伸ばすとは言わない。"}, {"text": "父は玄関のドアを伸ばして、外の風を入れた。", "explanation": "ここは〈開ける〉の意味。扉を開いて通す動作は開けると言い、伸ばすとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52746, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伸ばして", "is_correct": true, "explanation": "て形で「爪を伸ばして、毎週きれいに塗っている」と続き、文が成り立つ。"}, {"text": "伸ばそう", "is_correct": false, "explanation": "意志形は「伸ばそう」と言い切る形で、事実を述べる文に続かない。"}, {"text": "伸ばせる", "is_correct": false, "explanation": "可能形は能力や可能性を表し、爪が伸びている状態の説明にならない。"}, {"text": "伸ばされる", "is_correct": false, "explanation": "受身形にすると主語が爪ではなくなり、「爪を」という文の構造と合わない。"}], "explanations": {"伸ばして": "て形で「爪を伸ばして、毎週きれいに塗っている」と続き、文が成り立つ。", "伸ばそう": "意志形は「伸ばそう」と言い切る形で、事実を述べる文に続かない。", "伸ばせる": "可能形は能力や可能性を表し、爪が伸びている状態の説明にならない。", "伸ばされる": "受身形にすると主語が爪ではなくなり、「爪を」という文の構造と合わない。"}, "sentence_index": 6, "correct_answer": "伸ばして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議で意見を伸ばして、提案を通した。", "explanation": "ここは〈述べる〉の意味。考えを言葉にする動作は述べると言い、伸ばすとは言わない。"}, {"text": "来客に笑顔を伸ばして迎えた。", "explanation": "ここは〈浮かべる〉の意味。顔に笑みを表す場合は浮かべると言い、伸ばすとは言わない。"}, {"text": "友だちの悩みを伸ばして、夜遅くまで話した。", "explanation": "ここは〈聞く〉の意味。相手の悩みを受け止める場合は聞くと言い、伸ばすとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52746, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭の木は枝を伸びて、夏に日陰を作る。", "corrected_sentence": "庭の木は枝を伸ばして、夏に日陰を作る。", "error_description": "語の誤り。「伸びる」は自動詞で「枝を」と合わない。対象を「を」で示す他動詞「伸ばす」の「伸ばして」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "伸ばして", "is_correct": true, "explanation": "て形で、後ろに「腰まで届くほど長くしたい」と続けられる。"}, {"text": "伸ばした", "is_correct": false, "explanation": "た形で文を言い切ると、後ろの文が続かず、「、」で結べない。"}, {"text": "伸ばさない", "is_correct": false, "explanation": "否定形にすると「髪を伸ばさない」となり、伸ばしたいという文意と逆になる。"}, {"text": "伸ばせば", "is_correct": false, "explanation": "仮定形は条件節になり、「届くほど長くしたい」と続く文の流れに合わない。"}], "correct_form": "伸ばして", "base_form": "伸ばす", "form_label": "て形", "sentence_index": 1, "explanations": {"伸ばして": "て形で、後ろに「腰まで届くほど長くしたい」と続けられる。", "伸ばした": "た形で文を言い切ると、後ろの文が続かず、「、」で結べない。", "伸ばさない": "否定形にすると「髪を伸ばさない」となり、伸ばしたいという文意と逆になる。", "伸ばせば": "仮定形は条件節になり、「届くほど長くしたい」と続く文の流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52746, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は髪が伸ばして、毎朝まとめています。", "corrected_sentence": "祖母は髪を伸ばして、毎朝まとめています。", "error_description": "助詞の誤り。「伸ばす」は対象を「を」で示す他動詞なので、「髪が」ではなく「髪を」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "伸ばして", "is_correct": true, "explanation": "て形で、後ろに「実をたくさんつけます」と続き、茎を伸ばした結果を表す。"}, {"text": "伸ばさ", "is_correct": false, "explanation": "未然形は「、」で続けられず、文として成り立たない。"}, {"text": "伸ばそう", "is_correct": false, "explanation": "意志形は意図を表すので、事実として伸ばしたという文と合わない。"}, {"text": "伸ばせる", "is_correct": false, "explanation": "可能形は「伸ばすことができる」という能力の意味になり、結果を述べる文と合わない。"}], "correct_form": "伸ばして", "base_form": "伸ばす", "form_label": "て形", "sentence_index": 7, "explanations": {"伸ばして": "て形で、後ろに「実をたくさんつけます」と続き、茎を伸ばした結果を表す。", "伸ばさ": "未然形は「、」で続けられず、文として成り立たない。", "伸ばそう": "意志形は意図を表すので、事実として伸ばしたという文と合わない。", "伸ばせる": "可能形は「伸ばすことができる」という能力の意味になり、結果を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
