INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52747, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "じっと見ること。", "primary_collocate": null, "pronunciation": "ぎょうし", "ipa": "ɡʲoːɕi", "syllable_count": 3, "sentences": [{"text": "弟は私の顔を凝視して、何も言いませんでした。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "弟[おとうと]は私[わたし]の顔[かお]を凝視[ぎょうし]して、何[なに]も言[い]いませんでした。", "sentence_source": "generated"}, {"text": "猫がおもちゃを凝視して、飛びかかる準備をしている。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "猫[ねこ]がおもちゃを凝視[ぎょうし]して、飛[と]びかかる準備[じゅんび]をしている。", "sentence_source": "generated"}, {"text": "知らない人に凝視されて、とても恥ずかしかった。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "知[し]らない人[ひと]に凝視[ぎょうし]されて、とても恥[は]ずかしかった。", "sentence_source": "generated"}, {"text": "彼は地図を凝視したまま、長い間考えていた。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "彼[かれ]は地図[ちず]を凝視[ぎょうし]したまま、長[なが]い間[あいだ]考[かんが]えていた。", "sentence_source": "generated"}, {"text": "赤ちゃんが母親の顔を凝視して、にっこり笑った。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんが母親[ははおや]の顔[かお]を凝視[ぎょうし]して、にっこり笑[わら]った。", "sentence_source": "generated"}, {"text": "長い凝視のあと、彼はやっと口を開いた。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "長[なが]い凝視[ぎょうし]のあと、彼[かれ]はやっと口[くち]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "窓の外を凝視していた母が、急に立ち上がった。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "窓[まど]の外[そと]を凝視[ぎょうし]していた母[はは]が、急[きゅう]に立[た]ち上[あ]がった。", "sentence_source": "generated"}, {"text": "絵を凝視すると、細かい線がたくさん見えてくる。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "絵[え]を凝視[ぎょうし]すると、細[こま]かい線[せん]がたくさん見[み]えてくる。", "sentence_source": "generated"}, {"text": "彼女は私の手元を凝視して、動きをまねしようとした。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は私[わたし]の手元[てもと]を凝視[ぎょうし]して、動[うご]きをまねしようとした。", "sentence_source": "generated"}, {"text": "彼の凝視に気づいて、私は思わず顔をそらした。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "彼[かれ]の凝視[ぎょうし]に気[き]づいて、私[わたし]は思[おも]わず顔[かお]をそらした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "凝視", "label": "基本形"}, {"form": "凝視する", "label": "する動詞 終止形"}, {"form": "凝視した", "label": "た形"}, {"form": "凝視して", "label": "て形"}, {"form": "凝視しない", "label": "ない形"}], "register": "やや硬い書き言葉", "sense_fingerprint": "目をそらさずにじっと見る(凝視する)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f522c88-2b37-4463-ae1e-fd98b63d1180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52747, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凝視", "is_correct": true, "explanation": "「顔を凝視して」は、じっと見つめたまま黙っていた状況に合う。"}, {"text": "解凍", "is_correct": false, "explanation": "解凍は凍った食品を溶かす意味で、人の顔は対象にならない。"}, {"text": "購入", "is_correct": false, "explanation": "購入は品物を買う意味で、人の顔を対象にできない。"}, {"text": "換気", "is_correct": false, "explanation": "換気は空気を入れ替える意味で、人の顔には使わない。"}], "explanations": {"凝視": "「顔を凝視して」は、じっと見つめたまま黙っていた状況に合う。", "解凍": "解凍は凍った食品を溶かす意味で、人の顔は対象にならない。", "購入": "購入は品物を買う意味で、人の顔を対象にできない。", "換気": "換気は空気を入れ替える意味で、人の顔には使わない。"}, "sentence_index": 0, "correct_answer": "凝視"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は書類をちらりと凝視して、すぐに次の作業に移った。", "explanation": "ここは〈一瞥〉の意味。「じっと見る」凝視に「ちらりと」「すぐ」を添えると矛盾するので合わない。"}, {"text": "遠くの鈴の音を凝視して、耳を澄ませた。", "explanation": "ここは〈聞き耳を立てる〉の意味。凝視は目でじっと見ることなので、音には使わない。"}, {"text": "彼は趣味のパン作りの味を凝視して、毎週新しい配合を試している。", "explanation": "ここは〈凝る（熱中してこだわる）〉の意味。凝視は物を見つめることなので、味にこだわって工夫する意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52747, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凝視", "is_correct": true, "explanation": "「窓の外を凝視していた母」は、窓の外をじっと見ていた様子を表し、文脈に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は文章を別の言語に置き換える意味で、窓の外は対象にならない。"}, {"text": "採点", "is_correct": false, "explanation": "採点は答案に点数をつける意味で、窓の外には合わない。"}, {"text": "凝固", "is_correct": false, "explanation": "凝固は液体が固まる意味で、人の行動を表す文には合わない。"}], "explanations": {"凝視": "「窓の外を凝視していた母」は、窓の外をじっと見ていた様子を表し、文脈に合う。", "翻訳": "翻訳は文章を別の言語に置き換える意味で、窓の外は対象にならない。", "採点": "採点は答案に点数をつける意味で、窓の外には合わない。", "凝固": "凝固は液体が固まる意味で、人の行動を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "凝視"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "溶かしたチョコレートを凝視して、型の中で固めた。", "explanation": "ここは〈固める（凝固させる）〉の意味。凝視は目で一点を見つめる行為なので、物を固める意味では使わない。"}, {"text": "煮物を口にして、味を凝視した。", "explanation": "ここは〈味見〉の意味。凝視は視線を一点に据える行為なので、味を確かめる動作には使わない。"}, {"text": "花束の香りを凝視して、深く吸い込んだ。", "explanation": "ここは〈嗅ぐ〉の意味。凝視は目で一点を見つめる行為なので、香りのような嗅覚の対象には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52747, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は生徒の答案に凝視して、点数をつけた。", "corrected_sentence": "先生は生徒の答案を凝視して、点数をつけた。", "error_description": "「凝視する」の対象は「を」で示す。「答案に凝視して」の「に」は誤りで、正しくは「答案を凝視して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52747, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は窓の外を凝視て、涙を拭った。", "corrected_sentence": "母は窓の外を凝視して、涙を拭った。", "error_description": "「凝視」の後に「し」が抜けている。「凝視て」は誤りで、正しくは「凝視して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
