INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52748, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "一つの物や人に、注意を集中してじっと見つめること。", "primary_collocate": null, "pronunciation": "ぎょうし", "ipa": "ɡʲoːɕi", "syllable_count": 3, "sentences": [{"text": "その姿を凝視する子供の瞳には、生命が持つ根源的な逞しさへの畏敬の念が宿っている。", "target_word": "凝視", "complexity_tier": "T4", "furigana": "その姿[すがた]を凝視[ぎょうし]する子供[こども]の瞳[ひとみ]には、生命[せいめい]が持[も]つ根源的[こんげんてき]な逞[たくま]しさへの畏敬[いけい]の念[ねん]が宿[やど]っている。", "sentence_source": "mined"}, {"text": "医者はレントゲン写真を凝視して、小さな影を見つけました。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "医者[いしゃ]はレントゲン写真[しゃしん]を凝視[ぎょうし]して、小[ちい]さな影[かげ]を見[み]つけました。", "sentence_source": "generated"}, {"text": "彼は暗闇の中の一点を凝視したまま、動かなくなった。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "彼[かれ]は暗闇[くらやみ]の中[なか]の一点[いってん]を凝視[ぎょうし]したまま、動[うご]かなくなった。", "sentence_source": "generated"}, {"text": "子供は水槽の魚を凝視して、少しも目をそらしません。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "子供[こども]は水槽[すいそう]の魚[さかな]を凝視[ぎょうし]して、少[すこ]しも目[め]をそらしません。", "sentence_source": "generated"}, {"text": "画面を凝視しすぎて、目が痛くなってしまった。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "画面[がめん]を凝視[ぎょうし]しすぎて、目[め]が痛[いた]くなってしまった。", "sentence_source": "generated"}, {"text": "彼女の鋭い凝視に耐えられず、私は目を伏せた。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の鋭[するど]い凝視[ぎょうし]に耐[た]えられず、私[わたし]は目[め]を伏[ふ]せた。", "sentence_source": "generated"}, {"text": "鳥の巣を凝視していると、小さなひなが顔を出した。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "鳥[とり]の巣[す]を凝視[ぎょうし]していると、小[ちい]さなひなが顔[かお]を出[だ]した。", "sentence_source": "generated"}, {"text": "被告は裁判官の顔を凝視し、ゆっくりと口を開いた。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "被告[ひこく]は裁判官[さいばんかん]の顔[かお]を凝視[ぎょうし]し、ゆっくりと口[くち]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "星空を凝視していたら、流れ星が横切った。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "星空[ほしぞら]を凝視[ぎょうし]していたら、流[なが]れ星[ぼし]が横切[よこぎ]った。", "sentence_source": "generated"}, {"text": "運転手は前方の信号を凝視して、青に変わるのを待った。", "target_word": "凝視", "complexity_tier": "T3", "furigana": "運転手[うんてんしゅ]は前方[ぜんぽう]の信号[しんごう]を凝視[ぎょうし]して、青[あお]に変[か]わるのを待[ま]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "凝視", "label": "基本形"}, {"form": "凝視する", "label": "する動詞 終止形"}, {"form": "凝視した", "label": "た形"}, {"form": "凝視して", "label": "て形"}, {"form": "凝視しない", "label": "ない形"}], "register": "やや硬い書き言葉", "sense_fingerprint": "一点に注意を集中して目をそらさずに見つめる(凝視する)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f522c88-2b37-4463-ae1e-fd98b63d1180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52748, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "凝視", "is_correct": true, "explanation": "「姿を凝視する子供」は、姿に注意を集中して見つめるという意味で文脈に合う。"}, {"text": "承諾", "is_correct": false, "explanation": "承諾は申し出に同意する意味で、「姿を」を目的語に取れないので文が成り立たない。"}, {"text": "吐露", "is_correct": false, "explanation": "吐露は心の内を打ち明ける意味で、目に見える姿を対象にできない。"}, {"text": "解雇", "is_correct": false, "explanation": "解雇は雇用を打ち切る意味で、子供が姿を見つめるという内容と無関係。"}], "explanations": {"凝視": "「姿を凝視する子供」は、姿に注意を集中して見つめるという意味で文脈に合う。", "承諾": "承諾は申し出に同意する意味で、「姿を」を目的語に取れないので文が成り立たない。", "吐露": "吐露は心の内を打ち明ける意味で、目に見える姿を対象にできない。", "解雇": "解雇は雇用を打ち切る意味で、子供が姿を見つめるという内容と無関係。"}, "sentence_index": 0, "correct_answer": "凝視"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女はちらりと凝視して、すぐに目をそらした。", "explanation": "ここは〈一瞥〉の意味。凝視は一つの対象に注意を集中してじっと見続けることなので、「ちらりと」「すぐに目をそらした」とは矛盾して合わない。"}, {"text": "遠くの足音を凝視して、誰が来たのかを考えた。", "explanation": "ここは〈聞き耳を立てる〉の意味。凝視は目で物や人を見つめる行為なので、音を対象にはできない。"}, {"text": "彼は料理の味を凝視して、味付けにこだわった。", "explanation": "ここは〈凝る（熱中してこだわる）〉の意味。凝視は物を見つめることなので、味付けに熱中する意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52748, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凝視", "is_correct": true, "explanation": "「鳥の巣を凝視していると」は、巣に注意を集中して見つめ続けた様子を表し、文脈に合う。"}, {"text": "採点", "is_correct": false, "explanation": "採点は答案などに点数をつける意味で、鳥の巣は対象にならない。"}, {"text": "解約", "is_correct": false, "explanation": "解約は契約を終わらせる意味で、巣には使わない。"}, {"text": "承認", "is_correct": false, "explanation": "承認は認めて許可する意味で、巣を見つめるという文の内容と合わない。"}], "explanations": {"凝視": "「鳥の巣を凝視していると」は、巣に注意を集中して見つめ続けた様子を表し、文脈に合う。", "採点": "採点は答案などに点数をつける意味で、鳥の巣は対象にならない。", "解約": "解約は契約を終わらせる意味で、巣には使わない。", "承認": "承認は認めて許可する意味で、巣を見つめるという文の内容と合わない。"}, "sentence_index": 6, "correct_answer": "凝視"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は冷めかけた鍋の温度を凝視して、火加減を調整した。", "explanation": "ここは〈温度を測る〉の意味。凝視は目で一点を見つめる行為なので、温度を確かめる動作には使わない。"}, {"text": "スープを一口飲んで、味を凝視した。", "explanation": "ここは〈味見〉の意味。凝視は視線を一点に据える行為なので、味を確かめる動作には使わない。"}, {"text": "花の香りを凝視して、深く吸い込んだ。", "explanation": "ここは〈嗅ぐ〉の意味。凝視は目で一点を見つめる行為なので、香りのような嗅覚の対象には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
