INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52749, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人やものを育てること。", "primary_collocate": null, "pronunciation": "いくせい", "ipa": "ikɯseː", "syllable_count": 4, "sentences": [{"text": "この農園では、新しい品種のバラの育成に取り組んでいる。", "target_word": "育成", "complexity_tier": "T3", "furigana": "この農園[のうえん]では、新[あたら]しい品種[ひんしゅ]のバラの育成[いくせい]に取[と]り組[く]んでいる。", "sentence_source": "generated"}, {"text": "犬の育成には、毎日の散歩としつけが大切だ。", "target_word": "育成", "complexity_tier": "T3", "furigana": "犬[いぬ]の育成[いくせい]には、毎日[まいにち]の散歩[さんぽ]としつけが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "稚魚の育成に成功し、川に放流することができた。", "target_word": "育成", "complexity_tier": "T3", "furigana": "稚魚[ちぎょ]の育成[いくせい]に成功[せいこう]し、川[かわ]に放流[ほうりゅう]することができた。", "sentence_source": "generated"}, {"text": "市は若手芸術家の育成を支援している。", "target_word": "育成", "complexity_tier": "T3", "furigana": "市[し]は若手[わかて]芸術家[げいじゅつか]の育成[いくせい]を支援[しえん]している。", "sentence_source": "generated"}, {"text": "苗の育成は難しいので、温度管理を毎日確認する。", "target_word": "育成", "complexity_tier": "T3", "furigana": "苗[なえ]の育成[いくせい]は難[むずか]しいので、温度管理[おんどかんり]を毎日[まいにち]確認[かくにん]する。", "sentence_source": "generated"}, {"text": "野菜の育成が順調で、来月には収穫できそうだ。", "target_word": "育成", "complexity_tier": "T3", "furigana": "野菜[やさい]の育成[いくせい]が順調[じゅんちょう]で、来月[らいげつ]には収穫[しゅうかく]できそうだ。", "sentence_source": "generated"}, {"text": "このゲームでは、キャラクターの育成が楽しみの一つだ。", "target_word": "育成", "complexity_tier": "T3", "furigana": "このゲームでは、キャラクターの育成[いくせい]が楽[たの]しみの一[ひと]つだ。", "sentence_source": "generated"}, {"text": "子どもの育成について、親たちが集まって話し合った。", "target_word": "育成", "complexity_tier": "T3", "furigana": "子[こ]どもの育成[いくせい]について、親[おや]たちが集[あつ]まって話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "花の育成を趣味にしている祖父は、庭に温室を作った。", "target_word": "育成", "complexity_tier": "T3", "furigana": "花[はな]の育成[いくせい]を趣味[しゅみ]にしている祖父[そふ]は、庭[にわ]に温室[おんしつ]を作[つく]った。", "sentence_source": "generated"}, {"text": "工場では、優秀な技術者の育成を続けている。", "target_word": "育成", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、優秀[ゆうしゅう]な技術者[ぎじゅつしゃ]の育成[いくせい]を続[つづ]けている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "育成", "label": "基本形"}, {"form": "育成する", "label": "動詞形"}, {"form": "育成した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "動植物・人・キャラクターなどを世話して育てること(品種・稚魚・苗の育成)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f522c88-2b37-4463-ae1e-fd98b63d1180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52749, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "育成", "is_correct": true, "explanation": "「育成に取り組んでいる」は、育てる作業に力を注いでいる意味で文脈に合う。"}, {"text": "撤回", "is_correct": false, "explanation": "撤回は発言や決定を取り消す意味で、バラを対象にはできない。"}, {"text": "解体", "is_correct": false, "explanation": "解体は組み立てたものをばらす意味で、品種の栽培には合わない。"}, {"text": "清算", "is_correct": false, "explanation": "清算は金銭や関係を終わらせる意味で、バラの話には合わない。"}], "explanations": {"育成": "「育成に取り組んでいる」は、育てる作業に力を注いでいる意味で文脈に合う。", "撤回": "撤回は発言や決定を取り消す意味で、バラを対象にはできない。", "解体": "解体は組み立てたものをばらす意味で、品種の栽培には合わない。", "清算": "清算は金銭や関係を終わらせる意味で、バラの話には合わない。"}, "sentence_index": 0, "correct_answer": "育成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店は毎日、新商品を育成している。", "explanation": "ここは〈販売〉の意味。育成は生き物や人を育てることなので、商品を売る場面には合わない。"}, {"text": "船は港まで大量の荷物を育成した。", "explanation": "ここは〈運搬〉の意味。育成は生き物や人を育てることなので、荷物を運ぶ場面には合わない。"}, {"text": "彼は木製の家具を育成した。", "explanation": "ここは〈製作〉の意味。育成は生き物やキャラクターを育てることなので、家具を組み立てる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52749, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "育成", "is_correct": true, "explanation": "「キャラクターの育成」は、キャラクターを育てる遊びの要素を指し、文脈に合う。"}, {"text": "撤去", "is_correct": false, "explanation": "撤去は設置したものを取り除く意味で、キャラクターには使わない。"}, {"text": "収穫", "is_correct": false, "explanation": "収穫は作物を取り入れる意味で、キャラクターには使わない。"}, {"text": "返却", "is_correct": false, "explanation": "返却は借りたものを戻す意味で、キャラクターには使わない。"}], "explanations": {"育成": "「キャラクターの育成」は、キャラクターを育てる遊びの要素を指し、文脈に合う。", "撤去": "撤去は設置したものを取り除く意味で、キャラクターには使わない。", "収穫": "収穫は作物を取り入れる意味で、キャラクターには使わない。", "返却": "返却は借りたものを戻す意味で、キャラクターには使わない。"}, "sentence_index": 6, "correct_answer": "育成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "町の職人は古い橋を育成している。", "explanation": "ここは〈修理〉の意味。育成は人や生き物などを育てることなので、橋を直す場面には使わない。"}, {"text": "整備士は毎朝、機械の状態を育成している。", "explanation": "ここは〈点検〉の意味。育成は人や生き物を育てることなので、機械の状態を調べる場面には合わない。"}, {"text": "係員は毎朝、駅の床を育成している。", "explanation": "ここは〈清掃〉の意味。育成は時間をかけて伸ばすことなので、床をきれいにする場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52749, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この研究所では、耐病性の高い稲の育成を取り組んでいる。", "corrected_sentence": "この研究所では、耐病性の高い稲の育成に取り組んでいる。", "error_description": "「取り組む」の対象は「に」で示す。「育成を取り組んでいる」の「を」は誤りで、正しくは「育成に取り組んでいる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52749, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その花屋は新しい品種の花を育成ている。", "corrected_sentence": "その花屋は新しい品種の花を育成している。", "error_description": "「育成している」の「し」が抜けている。「育成ている」は誤りで、正しくは「育成している」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52750, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「育成に力を入れる」の「に」は、力を向ける対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「力を入れる」は「に」で対象を示すので誤り。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、力を向ける対象の説明にならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「力を入れる」の対象には合わない。"}], "correct_answer": "に", "explanations": {"に": "「育成に力を入れる」の「に」は、力を向ける対象を示す。", "を": "「を」は目的語を示すが、「力を入れる」は「に」で対象を示すので誤り。", "から": "「から」は起点を示すので、力を向ける対象の説明にならない。", "と": "「と」は並列や相手を示すので、「力を入れる」の対象には合わない。"}, "error_tags": {"を": "目的語の格", "から": "起点", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52750, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52750, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人や動物、植物などを育てて成長させること。特に、能力や精神を発達させること。", "primary_collocate": null, "pronunciation": "いくせい", "ipa": "ikɯseː", "syllable_count": 4, "sentences": [{"text": "まさに、大地と対話するその姿勢こそが、未来を担う魂の育成に他ならないのだろう。", "target_word": "育成", "complexity_tier": "T3", "furigana": "まさに、大地[だいち]と対話[たいわ]するその姿勢[しせい]こそが、未来[みらい]を担[にな]う魂[たましい]の育成[いくせい]に他[ほか]ならないのだろう。", "sentence_source": "mined"}, {"text": "この学校は、将来の指導者の育成に力を入れている。", "target_word": "育成", "complexity_tier": "T3", "furigana": "この学校[がっこう]は、将来[しょうらい]の指導者[しどうしゃ]の育成[いくせい]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "若い選手の育成には、時間と根気が必要だ。", "target_word": "育成", "complexity_tier": "T3", "furigana": "若[わか]い選手[せんしゅ]の育成[いくせい]には、時間[じかん]と根気[こんき]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "会社は新入社員の育成のため、半年間の研修を行う。", "target_word": "育成", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は新入社員[しんにゅうしゃいん]の育成[いくせい]のため、半年間[はんとしかん]の研修[けんしゅう]を行[おこな]う。", "sentence_source": "generated"}, {"text": "子どもの心の育成には、家族との会話が欠かせない。", "target_word": "育成", "complexity_tier": "T3", "furigana": "子[こ]どもの心[こころ]の育成[いくせい]には、家族[かぞく]との会話[かいわ]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "優れた研究者の育成を目標に、大学は奨学金制度を設けた。", "target_word": "育成", "complexity_tier": "T4", "furigana": "優[すぐ]れた研究者[けんきゅうしゃ]の育成[いくせい]を目標[もくひょう]に、大学[だいがく]は奨学金制度[しょうがくきんせいど]を設[もう]けた。", "sentence_source": "generated"}, {"text": "人材の育成が遅れたせいで、現場では人手が足りなくなった。", "target_word": "育成", "complexity_tier": "T3", "furigana": "人材[じんざい]の育成[いくせい]が遅[おく]れたせいで、現場[げんば]では人手[ひとで]が足[た]りなくなった。", "sentence_source": "generated"}, {"text": "教師は知識を教えるだけでなく、生徒の自主性の育成も目指すべきだ。", "target_word": "育成", "complexity_tier": "T4", "furigana": "教師[きょうし]は知識[ちしき]を教[おし]えるだけでなく、生徒[せいと]の自主性[じしゅせい]の育成[いくせい]も目指[めざ]すべきだ。", "sentence_source": "generated"}, {"text": "音楽家の育成で知られるこの町には、世界中から学生が集まる。", "target_word": "育成", "complexity_tier": "T4", "furigana": "音楽家[おんがくか]の育成[いくせい]で知[し]られるこの町[まち]には、世界中[せかいじゅう]から学生[がくせい]が集[あつ]まる。", "sentence_source": "generated"}, {"text": "後輩の育成を任された彼は、毎週勉強会を開いている。", "target_word": "育成", "complexity_tier": "T3", "furigana": "後輩[こうはい]の育成[いくせい]を任[まか]された彼[かれ]は、毎週[まいしゅう]勉強会[べんきょうかい]を開[ひら]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "育成", "label": "基本形"}, {"form": "育成する", "label": "動詞形"}, {"form": "育成した", "label": "過去形"}], "register": "formal", "sense_fingerprint": "人の能力や精神を時間をかけて伸ばし育てること(人材・後進・心の育成)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f522c88-2b37-4463-ae1e-fd98b63d1180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52750, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "育成", "is_correct": true, "explanation": "「魂の育成に他ならない」は、魂を育てることだという意味で文脈に合う。"}, {"text": "違反", "is_correct": false, "explanation": "違反は決まりを破る意味で、魂の育成という内容と結びつかない。"}, {"text": "解約", "is_correct": false, "explanation": "解約は契約を終わらせる意味で、魂には使わない。"}, {"text": "乗車", "is_correct": false, "explanation": "乗車は乗り物に乗る意味で、「魂の」に続けると文が成り立たない。"}], "explanations": {"育成": "「魂の育成に他ならない」は、魂を育てることだという意味で文脈に合う。", "違反": "違反は決まりを破る意味で、魂の育成という内容と結びつかない。", "解約": "解約は契約を終わらせる意味で、魂には使わない。", "乗車": "乗車は乗り物に乗る意味で、「魂の」に続けると文が成り立たない。"}, "sentence_index": 0, "correct_answer": "育成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町は新しい校舎を育成するため、寄付を集めている。", "explanation": "ここは〈建設〉の意味。育成は人や能力を育てることに使うので、校舎のような建物には使わない。"}, {"text": "市は来月、国際会議を育成する予定だ。", "explanation": "ここは〈開催〉の意味。育成は人や能力を時間をかけて伸ばすことなので、会議の実施には合わない。"}, {"text": "彼はアニメ映画を育成している。", "explanation": "ここは〈制作〉の意味。育成は人や能力を伸ばすことなので、作品を作り上げる意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52750, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "育成", "is_correct": true, "explanation": "「人材の育成が遅れた」は、人材を育てる作業が遅れたという意味で合う。"}, {"text": "配線", "is_correct": false, "explanation": "配線は電気の線を通す作業の意味で、人材には使わない。"}, {"text": "清掃", "is_correct": false, "explanation": "清掃は汚れを取り除く意味で、人材の話には合わない。"}, {"text": "解凍", "is_correct": false, "explanation": "解凍は凍ったものを溶かす意味で、人材には使わない。"}], "explanations": {"育成": "「人材の育成が遅れた」は、人材を育てる作業が遅れたという意味で合う。", "配線": "配線は電気の線を通す作業の意味で、人材には使わない。", "清掃": "清掃は汚れを取り除く意味で、人材の話には合わない。", "解凍": "解凍は凍ったものを溶かす意味で、人材には使わない。"}, "sentence_index": 6, "correct_answer": "育成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場は毎日、新型の部品を育成している。", "explanation": "ここは〈製造〉の意味。育成は人や生き物などを育てることなので、工場で部品を作る場面には合わない。"}, {"text": "国会は新しい法律を育成した。", "explanation": "ここは〈制定〉の意味。育成は人や能力を伸ばすことなので、法律を定める場面には使わない。"}, {"text": "渋滞のため、駅前の交通を育成した。", "explanation": "ここは〈規制〉の意味。育成は人や能力を育てることなので、交通を制限する場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52750, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町は子どもの体力の育成を力を入れている。", "corrected_sentence": "町は子どもの体力の育成に力を入れている。", "error_description": "「力を入れる」の対象は「に」で示す。「育成を力を入れている」の「を」は誤りで、正しくは「育成に力を入れている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52750, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地域の子どもの育成するを支えるため、町は補助金を出した。", "corrected_sentence": "地域の子どもの育成を支えるため、町は補助金を出した。", "error_description": "「育成」の後に「する」を入れて「育成するを」としたのは誤り。正しくは「育成を支える」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c190d335-8ef3-45bf-92fb-7411b14c7a2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52751, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「魂がある」で、魂が主語として存在を表す。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は目的語を取らないので、「を」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同や引用を表すので、「魂とある」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すため、存在を表す「ある」とは組み合わない。"}], "correct_answer": "が", "explanations": {"が": "「魂がある」で、魂が主語として存在を表す。", "を": "「ある」は目的語を取らないので、「を」は合わない。", "と": "「と」は共同や引用を表すので、「魂とある」は文として成り立たない。", "へ": "「へ」は方向を表すため、存在を表す「ある」とは組み合わない。"}, "error_tags": {"を": "目的語", "と": "共同・引用", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
