INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52751, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人の心や、生きる力のこと。", "primary_collocate": null, "pronunciation": "たましい", "ipa": "tamaɕii", "syllable_count": 4, "sentences": [{"text": "祖父は、この仕事に魂を込めて四十年間働いた。", "target_word": "魂", "complexity_tier": "T3", "furigana": "祖父[そふ]は、この仕事[しごと]に魂[たましい]を込[こ]めて四十年間[よんじゅうねんかん]働[はたら]いた。", "sentence_source": "generated"}, {"text": "彼の歌には、聴く人の心を動かす魂がある。", "target_word": "魂", "complexity_tier": "T3", "furigana": "彼[かれ]の歌[うた]には、聴[き]く人[ひと]の心[こころ]を動[うご]かす魂[たましい]がある。", "sentence_source": "generated"}, {"text": "選手たちの闘う魂は最後まで消えなかった。", "target_word": "魂", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちの闘[たたか]う魂[たましい]は最後[さいご]まで消[き]えなかった。", "sentence_source": "generated"}, {"text": "職人は、一つ一つの器に魂を吹き込むように土をこねる。", "target_word": "魂", "complexity_tier": "T3", "furigana": "職人[しょくにん]は、一[ひと]つ一[ひと]つの器[うつわ]に魂[たましい]を吹[ふ]き込[こ]むように土[つち]をこねる。", "sentence_source": "generated"}, {"text": "病気で体は弱ったが、彼女の魂は最後まで強かった。", "target_word": "魂", "complexity_tier": "T3", "furigana": "病気[びょうき]で体[からだ]は弱[よわ]ったが、彼女[かのじょ]の魂[たましい]は最後[さいご]まで強[つよ]かった。", "sentence_source": "generated"}, {"text": "彼女の絵は技術だけでなく、描いた人の魂が感じられる。", "target_word": "魂", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の絵[え]は技術[ぎじゅつ]だけでなく、描[えが]いた人[ひと]の魂[たましい]が感[かん]じられる。", "sentence_source": "generated"}, {"text": "魂のこもった演奏に、会場は大きな拍手に包まれた。", "target_word": "魂", "complexity_tier": "T3", "furigana": "魂[たましい]のこもった演奏[えんそう]に、会場[かいじょう]は大[おお]きな拍手[はくしゅ]に包[つつ]まれた。", "sentence_source": "generated"}, {"text": "魂を揺さぶる言葉に出会って、私は進む道を決めた。", "target_word": "魂", "complexity_tier": "T3", "furigana": "魂[たましい]を揺[ゆ]さぶる言葉[ことば]に出会[であ]って、私[わたし]は進[すす]む道[みち]を決[き]めた。", "sentence_source": "generated"}, {"text": "貧しい村でも、人々は生きようとする魂を失わなかった。", "target_word": "魂", "complexity_tier": "T3", "furigana": "貧[まず]しい村[むら]でも、人々[ひとびと]は生[い]きようとする魂[たましい]を失[うしな]わなかった。", "sentence_source": "generated"}, {"text": "仕事は忙しいが、魂まで売るつもりはない。", "target_word": "魂", "complexity_tier": "T3", "furigana": "仕事[しごと]は忙[いそが]しいが、魂[たましい]まで売[う]るつもりはない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "魂", "label": "基本形"}], "register": "標準", "sense_fingerprint": "人の心の奥にある、生きる力や精神", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6fe5c65-9a1d-44c6-9f19-15b31205c511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52751, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "魂", "is_correct": true, "explanation": "「魂を込める」は、仕事に精神を注ぐという意味で、文の意味に合う。"}, {"text": "汗", "is_correct": false, "explanation": "汗は体から出る液体で、「込める」とは組み合わない。"}, {"text": "足", "is_correct": false, "explanation": "足は体の部位で、「込める」の対象にならない。"}, {"text": "目", "is_correct": false, "explanation": "目は器官で、「仕事に目を込める」とは言わない。"}], "explanations": {"魂": "「魂を込める」は、仕事に精神を注ぐという意味で、文の意味に合う。", "汗": "汗は体から出る液体で、「込める」とは組み合わない。", "足": "足は体の部位で、「込める」の対象にならない。", "目": "目は器官で、「仕事に目を込める」とは言わない。"}, "sentence_index": 0, "correct_answer": "魂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お盆には、先祖の魂を家に迎える。", "explanation": "ここは〈霊魂〉の意味。死者の霊を指す別の意味で、心や生きる力とは違う。"}, {"text": "この島には、千の魂が暮らしている。", "explanation": "ここは〈人数〉の意味。人を数える用法で、心や志を表す語ではない。"}, {"text": "彼は大きな手術を受ける魂を決めた。", "explanation": "ここは〈覚悟〉の意味。「覚悟を決める」とは言うが、〈魂〉は「決める」の目的語にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52751, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "魂", "is_correct": true, "explanation": "「魂のこもった演奏」は、精神が込められた演奏という意味で文に合う。"}, {"text": "歯", "is_correct": false, "explanation": "歯は体の部位で、「歯のこもった」は意味をなさない。"}, {"text": "膝", "is_correct": false, "explanation": "膝は体の部位で、「膝のこもった演奏」とは言わない。"}, {"text": "爪", "is_correct": false, "explanation": "爪は体の部位で、「爪のこもった」は不自然で文脈に合わない。"}], "explanations": {"魂": "「魂のこもった演奏」は、精神が込められた演奏という意味で文に合う。", "歯": "歯は体の部位で、「歯のこもった」は意味をなさない。", "膝": "膝は体の部位で、「膝のこもった演奏」とは言わない。", "爪": "爪は体の部位で、「爪のこもった」は不自然で文脈に合わない。"}, "sentence_index": 6, "correct_answer": "魂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は魂が確かで、どんな難しい手術も任される。", "explanation": "ここは〈技術〉の意味。〈魂〉は腕前を指さないので、「確か」と言う対象は〈技術〉になる。"}, {"text": "彼女は几帳面な魂で、机の上はいつも整っている。", "explanation": "ここは〈性格〉の意味。「几帳面な性格」とは言うが、〈魂〉は性格を表す言葉としては使わない。"}, {"text": "彼は魂が悪いので、早退した。", "explanation": "ここは〈顔色〉の意味。「顔色が悪い」とは言うが、〈魂〉を主語にして「悪い」と言っても、体調を表すことにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52751, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は仕事に魂で注いで、毎日夜遅くまで働いた。", "corrected_sentence": "彼は仕事に魂を注いで、毎日夜遅くまで働いた。", "error_description": "正しくは「魂を注いで」。〈注ぐ〉は〈魂〉を目的語に取るので「を」が必要で、「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52751, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は魂に込めて、この絵を描いた。", "corrected_sentence": "彼女は魂を込めて、この絵を描いた。", "error_description": "正しくは「魂を込めて」。〈込める〉は〈魂〉を目的語に取るので「を」が必要で、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
