INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52753, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "順調だった関係・計画・話などが崩れて、成り立たなくなること。", "primary_collocate": null, "pronunciation": "はたん", "ipa": "hatan", "syllable_count": 3, "sentences": [{"text": "順調だった計画が、一つの失敗で破綻してしまった。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "順調[じゅんちょう]だった計画[けいかく]が、一[ひと]つの失敗[しっぱい]で破綻[はたん]してしまった。", "sentence_source": "generated"}, {"text": "長く続いた二人の結婚生活は、ついに破綻した。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "長[なが]く続[つづ]いた二人[ふたり]の結婚生活[けっこんせいかつ]は、ついに破綻[はたん]した。", "sentence_source": "generated"}, {"text": "約束が守られなかったため、両社の協力関係は破綻した。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "約束[やくそく]が守[まも]られなかったため、両社[りょうしゃ]の協力関係[きょうりょくかんけい]は破綻[はたん]した。", "sentence_source": "generated"}, {"text": "彼の説明は途中で矛盾が出て、話が破綻した。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "彼[かれ]の説明[せつめい]は途中[とちゅう]で矛盾[むじゅん]が出[で]て、話[はなし]が破綻[はたん]した。", "sentence_source": "generated"}, {"text": "景気が悪くなり、順調だった会社の経営も破綻した。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "景気[けいき]が悪[わる]くなり、順調[じゅんちょう]だった会社[かいしゃ]の経営[けいえい]も破綻[はたん]した。", "sentence_source": "generated"}, {"text": "信頼がなくなれば、友人との関係はすぐに破綻する。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "信頼[しんらい]がなくなれば、友人[ゆうじん]との関係[かんけい]はすぐに破綻[はたん]する。", "sentence_source": "generated"}, {"text": "計算を間違えたせいで、うまく組んだ予定が破綻した。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "計算[けいさん]を間違[まちが]えたせいで、うまく組[く]んだ予定[よてい]が破綻[はたん]した。", "sentence_source": "generated"}, {"text": "夫婦の会話がなくなり、家庭は静かに破綻していった。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "夫婦[ふうふ]の会話[かいわ]がなくなり、家庭[かてい]は静[しず]かに破綻[はたん]していった。", "sentence_source": "generated"}, {"text": "一度の大きな失敗でチームの連携が破綻してしまった。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "一度[いちど]の大[おお]きな失敗[しっぱい]でチームの連携[れんけい]が破綻[はたん]してしまった。", "sentence_source": "generated"}, {"text": "長年うまくいっていた取引が、突然破綻して驚いた。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "長年[ながねん]うまくいっていた取引[とりひき]が、突然[とつぜん]破綻[はたん]して驚[おどろ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "破綻", "label": "基本形"}, {"form": "破綻する", "label": "辞書形"}, {"form": "破綻した", "label": "過去形"}, {"form": "破綻してしまう", "label": "完了形"}, {"form": "破綻しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "順調だった関係・計画・話などが崩れてだめになること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0888c172-05ca-47fc-b033-bf6b11e5f019') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52753, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "破綻", "is_correct": true, "explanation": "正解。順調だった計画が崩れてだめになる意味で、「破綻してしまった」が入る。"}, {"text": "応援", "is_correct": false, "explanation": "「計画が応援してしまった」は意味が通らず、失敗で計画が崩れた文脈に合わない。"}, {"text": "感謝", "is_correct": false, "explanation": "「感謝してしまった」は意味が通らず、計画が崩れた話に合わない。"}, {"text": "挨拶", "is_correct": false, "explanation": "「挨拶してしまった」は失敗と結びつかず、計画の結末を表せない。"}], "explanations": {"破綻": "正解。順調だった計画が崩れてだめになる意味で、「破綻してしまった」が入る。", "応援": "「計画が応援してしまった」は意味が通らず、失敗で計画が崩れた文脈に合わない。", "感謝": "「感謝してしまった」は意味が通らず、計画が崩れた話に合わない。", "挨拶": "「挨拶してしまった」は失敗と結びつかず、計画の結末を表せない。"}, "sentence_index": 0, "correct_answer": "破綻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "強風で窓ガラスが破綻した。", "explanation": "ここは〈破損〉の意味。窓ガラスのような物が壊れる場合は「破損」を使い、「破綻」は計画や関係などが崩れて成り立たなくなることに使う。"}, {"text": "古いパソコンが急に破綻した。", "explanation": "ここは〈故障〉の意味。機械が動かなくなることは「故障」と言い、「破綻」は計画や関係など抽象的なものに使う。"}, {"text": "台風の影響で、テレビの放送が破綻した。", "explanation": "ここは〈中断〉の意味。途中で止まることは「中断」で、「破綻」は計画や関係が崩れてだめになる場合に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52753, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "破綻", "is_correct": true, "explanation": "正解。うまく組んだ予定が崩れてだめになる意味で、「破綻した」が入る。"}, {"text": "納得", "is_correct": false, "explanation": "「予定が納得した」は意味が成り立たず、予定が崩れる話に合わない。"}, {"text": "感動", "is_correct": false, "explanation": "「予定が感動した」は意味が通らず、予定が崩れる話に合わない。"}, {"text": "翻訳", "is_correct": false, "explanation": "「予定が翻訳した」は主語と動詞が合わず、文脈にも合わない。"}], "explanations": {"破綻": "正解。うまく組んだ予定が崩れてだめになる意味で、「破綻した」が入る。", "納得": "「予定が納得した」は意味が成り立たず、予定が崩れる話に合わない。", "感動": "「予定が感動した」は意味が通らず、予定が崩れる話に合わない。", "翻訳": "「予定が翻訳した」は主語と動詞が合わず、文脈にも合わない。"}, "sentence_index": 6, "correct_answer": "破綻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三年かけて工事したダムが、ついに破綻した。", "explanation": "ここは〈決壊〉の意味。ダムなどの構造物が崩れて壊れることは「決壊」で、「破綻」は計画や関係がうまくいかなくなることに使う。"}, {"text": "面倒な問題が、話し合いできれいに破綻した。", "explanation": "ここは〈解決〉の意味。問題が片づくことは「解決」で、「破綻」は計画や関係がうまくいかなくなることを指す。"}, {"text": "よくかき混ぜたホイップクリームが、ついに破綻した。", "explanation": "ここは〈分離〉の意味。液体や生地が分かれてしまうことは「分離」で、「破綻」は計画や関係などが崩れてだめになることに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52753, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二人の関係は、ささいな誤解で破綻を起きた。", "corrected_sentence": "二人の関係は、ささいな誤解で破綻した。", "error_description": "正しくは「破綻した」。「破綻」は「破綻する」の形で使う名詞で、「起きる」は「破綻が起きた」のように主語に付く。「破綻を起きた」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52753, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "どんなに大変でも、計画は最後まで破綻なかった。", "corrected_sentence": "どんなに大変でも、計画は最後まで破綻しなかった。", "error_description": "正しくは「破綻しなかった」。「破綻」は「破綻する」の形で動詞として使うので、否定には「しなかった」が必要。「破綻なかった」は文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52754, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52754, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「破綻に終わる」の「に」で、結果を示す。"}, {"text": "を", "is_correct": false, "explanation": "「終わる」は自動詞なので、目的語の「を」は取れない。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾する「の」で、「破綻の終わった」とは続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「終わる」は結果を「に」で示し、「へ」では不自然。"}], "correct_answer": "に", "explanations": {"に": "「破綻に終わる」の「に」で、結果を示す。", "を": "「終わる」は自動詞なので、目的語の「を」は取れない。", "の": "名詞を修飾する「の」で、「破綻の終わった」とは続かない。", "へ": "「終わる」は結果を「に」で示し、「へ」では不自然。"}, "error_tags": {"を": "自動詞", "の": "連体修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52754, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事がうまく進まなくなり、続けられなくなること。", "primary_collocate": null, "pronunciation": "はたん", "ipa": "hatan", "syllable_count": 3, "sentences": [{"text": "しかし、産業革命以降の急激な人間活動、とりわけ化石燃料の大量消費と森林破壊は、この循環に深刻な破綻をもたらした。", "target_word": "破綻", "complexity_tier": "T5", "furigana": "しかし、産業革命[さんぎょうかくめい]以降[いこう]の急激[きゅうげき]な人間[にんげん]活動[かつどう]、とりわけ化石燃料[かせきねんりょう]の大量[たいりょう]消費[しょうひ]と森林[しんりん]破壊[はかい]は、この循環[じゅんかん]に深刻[しんこく]な破綻[はたん]をもたらした。", "sentence_source": "mined"}, {"text": "計画に無理があったため、事業はついに破綻した。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "計画[けいかく]に無理[むり]があったため、事業[じぎょう]はついに破綻[はたん]した。", "sentence_source": "generated"}, {"text": "借金が増えすぎて、家計が破綻する前に生活を見直した。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "借金[しゃっきん]が増[ふ]えすぎて、家計[かけい]が破綻[はたん]する前[まえ]に生活[せいかつ]を見直[みなお]した。", "sentence_source": "generated"}, {"text": "二人の関係は、小さな嘘から破綻していった。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "二人[ふたり]の関係[かんけい]は、小[ちい]さな嘘[うそ]から破綻[はたん]していった。", "sentence_source": "generated"}, {"text": "会社の経営が破綻し、社員は仕事を失った。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の経営[けいえい]が破綻[はたん]し、社員[しゃいん]は仕事[しごと]を失[うしな]った。", "sentence_source": "generated"}, {"text": "費用が足りず、工事の計画は途中で破綻した。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "費用[ひよう]が足[た]りず、工事[こうじ]の計画[けいかく]は途中[とちゅう]で破綻[はたん]した。", "sentence_source": "generated"}, {"text": "国の財政が破綻すれば、国民の生活にも大きな影響が出る。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "国[くに]の財政[ざいせい]が破綻[はたん]すれば、国民[こくみん]の生活[せいかつ]にも大[おお]きな影響[えいきょう]が出[で]る。", "sentence_source": "generated"}, {"text": "無理な約束を重ねた結果、交渉は破綻に終わった。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "無理[むり]な約束[やくそく]を重[かさ]ねた結果[けっか]、交渉[こうしょう]は破綻[はたん]に終[お]わった。", "sentence_source": "generated"}, {"text": "収入より支出が多い生活は、いつか破綻する。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "収入[しゅうにゅう]より支出[ししゅつ]が多[おお]い生活[せいかつ]は、いつか破綻[はたん]する。", "sentence_source": "generated"}, {"text": "資金が尽きて、その店の経営は破綻寸前だった。", "target_word": "破綻", "complexity_tier": "T3", "furigana": "資金[しきん]が尽[つ]きて、その店[みせ]の経営[けいえい]は破綻[はたん]寸前[すんぜん]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "破綻", "label": "基本形"}, {"form": "破綻する", "label": "辞書形"}, {"form": "破綻した", "label": "過去形"}, {"form": "破綻している", "label": "継続形"}, {"form": "破綻しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "経営・財政・計画などが行き詰まり、続けられなくなること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0888c172-05ca-47fc-b033-bf6b11e5f019') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52754, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "破綻", "is_correct": true, "explanation": "「深刻な破綻をもたらす」の形で、行き詰まりを表す語として自然に入る。"}, {"text": "深刻", "is_correct": false, "explanation": "状態を表す語で、「深刻な深刻」とは続かない。"}, {"text": "散歩", "is_correct": false, "explanation": "行為を表す名詞で、「深刻な散歩をもたらす」は意味が通らない。"}, {"text": "相談", "is_correct": false, "explanation": "話し合いを表す名詞で、「もたらす」の目的語として不自然。"}], "explanations": {"破綻": "「深刻な破綻をもたらす」の形で、行き詰まりを表す語として自然に入る。", "深刻": "状態を表す語で、「深刻な深刻」とは続かない。", "散歩": "行為を表す名詞で、「深刻な散歩をもたらす」は意味が通らない。", "相談": "話し合いを表す名詞で、「もたらす」の目的語として不自然。"}, "sentence_index": 0, "correct_answer": "破綻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大雨で試合は破綻になった。", "explanation": "ここは〈中止〉の場面。雨で試合を取りやめることは、計画や経営が行き詰まる破綻とは言わない。"}, {"text": "届いた荷物の箱が破綻していた。", "explanation": "ここは〈破損〉の場面。箱などの物の壊れには使わず、破綻は計画や財政などに使う。"}, {"text": "古いエアコンが破綻して、暑さに耐えられなかった。", "explanation": "ここは〈故障〉の場面。機械の不具合には使わず、破綻は計画や経営が続けられなくなる時に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52754, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "破綻", "is_correct": true, "explanation": "「財政が破綻すれば」の形で、財政が行き詰まることを表す。"}, {"text": "水曜日", "is_correct": false, "explanation": "曜日を表す名詞で、「財政が水曜日すれば」とは続かない。"}, {"text": "大量", "is_correct": false, "explanation": "数量を表す語で、「財政が大量すれば」とは続かない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "家電を表す名詞で、財政の状態を表す語として続かない。"}], "explanations": {"破綻": "「財政が破綻すれば」の形で、財政が行き詰まることを表す。", "水曜日": "曜日を表す名詞で、「財政が水曜日すれば」とは続かない。", "大量": "数量を表す語で、「財政が大量すれば」とは続かない。", "冷蔵庫": "家電を表す名詞で、財政の状態を表す語として続かない。"}, "sentence_index": 6, "correct_answer": "破綻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "強く握ったら、風船がとうとう破綻した。", "explanation": "ここは〈破裂〉の場面。風船のような物の割れには使わず、破綻は計画や経営が行き詰まる時に使う。"}, {"text": "長い沈黙が、ついに破綻した。", "explanation": "ここは〈破れる〉の場面。沈黙は破られるもので、計画や経営のように行き詰まるものではない。"}, {"text": "転んで骨が破綻した。", "explanation": "ここは〈折れる〉の場面。骨など体の部位の損傷には使わず、破綻は計画や財政などに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52754, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家計の破綻に防ぐため、支出を減らした。", "corrected_sentence": "家計の破綻を防ぐため、支出を減らした。", "error_description": "「防ぐ」の目的語は「を」で示す。「破綻に防ぐ」は誤りで、「に」を「を」に直す必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52754, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の提案で交渉は破綻されなかった。", "corrected_sentence": "彼の提案で交渉は破綻しなかった。", "error_description": "「破綻する」は自動詞的に使うので、受け身の「される」は誤り。「破綻しなかった」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52755, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吸収", "is_correct": true, "explanation": "正解。放出が中にあったものを外へ出すのに対し、吸収は外のものを取り込むため、対義語になる。"}, {"text": "混合", "is_correct": false, "explanation": "異なるものを混ぜることで、外へ出す放出と対になる関係にはない。"}, {"text": "整理", "is_correct": false, "explanation": "物を片づけることで、外へ出す放出の対義語とは言えない。"}, {"text": "点火", "is_correct": false, "explanation": "火をつけることで、中のものを外へ出す放出とは対になる関係ではない。"}], "correct_answer": "吸収", "explanations": {"吸収": "正解。放出が中にあったものを外へ出すのに対し、吸収は外のものを取り込むため、対義語になる。", "混合": "異なるものを混ぜることで、外へ出す放出と対になる関係にはない。", "整理": "物を片づけることで、外へ出す放出の対義語とは言えない。", "点火": "火をつけることで、中のものを外へ出す放出とは対になる関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52755, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吸収", "is_correct": true, "explanation": "正解。放出が中のものを外へ出すのに対し、吸収は外のものを中に取り入れるため、対義語になる。"}, {"text": "包装", "is_correct": false, "explanation": "商品を包むことで、外へ出す放出とは対になる関係にない。"}, {"text": "濃縮", "is_correct": false, "explanation": "成分を集めて密度を高めることで、放出の対義語とは言えない。"}, {"text": "製造", "is_correct": false, "explanation": "ものをつくり出すことで、外へ出す放出と対になる関係ではない。"}], "correct_answer": "吸収", "explanations": {"吸収": "正解。放出が中のものを外へ出すのに対し、吸収は外のものを中に取り入れるため、対義語になる。", "包装": "商品を包むことで、外へ出す放出とは対になる関係にない。", "濃縮": "成分を集めて密度を高めることで、放出の対義語とは言えない。", "製造": "ものをつくり出すことで、外へ出す放出と対になる関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52755, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "中にあったものを外に出すこと。", "primary_collocate": null, "pronunciation": "ほうしゅつ", "ipa": "hoːɕɯtsɯ", "syllable_count": 4, "sentences": [{"text": "この機械は、使うたびに少し熱を放出する。", "target_word": "放出", "complexity_tier": "T3", "furigana": "この機械[きかい]は、使[つか]うたびに少[すこ]し熱[ねつ]を放出[ほうしゅつ]する。", "sentence_source": "generated"}, {"text": "木は葉から水蒸気を放出して、まわりを涼しくする。", "target_word": "放出", "complexity_tier": "T3", "furigana": "木[き]は葉[は]から水蒸気[すいじょうき]を放出[ほうしゅつ]して、まわりを涼[すず]しくする。", "sentence_source": "generated"}, {"text": "古い冷蔵庫から、ガスが放出されていて危なかった。", "target_word": "放出", "complexity_tier": "T3", "furigana": "古[ふる]い冷蔵庫[れいぞうこ]から、ガスが放出[ほうしゅつ]されていて危[あぶ]なかった。", "sentence_source": "generated"}, {"text": "風船の口を開けると、中の空気が放出されて小さくなった。", "target_word": "放出", "complexity_tier": "T3", "furigana": "風船[ふうせん]の口[くち]を開[あ]けると、中[なか]の空気[くうき]が放出[ほうしゅつ]されて小[ちい]さくなった。", "sentence_source": "generated"}, {"text": "花火は火薬のエネルギーを一気に放出して光る。", "target_word": "放出", "complexity_tier": "T3", "furigana": "花火[はなび]は火薬[かやく]のエネルギーを一気[いっき]に放出[ほうしゅつ]して光[ひか]る。", "sentence_source": "generated"}, {"text": "温泉地では、地面から熱い蒸気が放出されている。", "target_word": "放出", "complexity_tier": "T3", "furigana": "温泉地[おんせんち]では、地面[じめん]から熱[あつ]い蒸気[じょうき]が放出[ほうしゅつ]されている。", "sentence_source": "generated"}, {"text": "缶スプレーを押すと、中のガスが外に放出される。", "target_word": "放出", "complexity_tier": "T3", "furigana": "缶[かん]スプレーを押[お]すと、中[なか]のガスが外[そと]に放出[ほうしゅつ]される。", "sentence_source": "generated"}, {"text": "雨が降ったあと、土は吸った水をゆっくり放出する。", "target_word": "放出", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ったあと、土[つち]は吸[す]った水[みず]をゆっくり放出[ほうしゅつ]する。", "sentence_source": "generated"}, {"text": "電球は電気を使って、光と熱を放出している。", "target_word": "放出", "complexity_tier": "T3", "furigana": "電球[でんきゅう]は電気[でんき]を使[つか]って、光[ひかり]と熱[ねつ]を放出[ほうしゅつ]している。", "sentence_source": "generated"}, {"text": "換気扇は部屋にこもった煙を外に放出する。", "target_word": "放出", "complexity_tier": "T3", "furigana": "換気扇[かんきせん]は部屋[へや]にこもった煙[けむり]を外[そと]に放出[ほうしゅつ]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "放出", "label": "基本形"}, {"form": "放出する", "label": "辞書形"}, {"form": "放出される", "label": "受身形"}, {"form": "放出している", "label": "継続形"}, {"form": "放出して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "熱・空気・水など中にあったものを外へ出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0888c172-05ca-47fc-b033-bf6b11e5f019') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52755, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放出", "is_correct": true, "explanation": "正解。使うたびに少しずつ熱を外へ出す意味で、「放出する」が入る。"}, {"text": "応募", "is_correct": false, "explanation": "「熱を応募する」は文として通らず、機械の熱の話に合わない。"}, {"text": "寄付", "is_correct": false, "explanation": "「熱を寄付する」は対象が合わず、文脈にも合わない。"}, {"text": "採点", "is_correct": false, "explanation": "「熱を採点する」は意味が成り立たず、機械の動作の説明にならない。"}], "explanations": {"放出": "正解。使うたびに少しずつ熱を外へ出す意味で、「放出する」が入る。", "応募": "「熱を応募する」は文として通らず、機械の熱の話に合わない。", "寄付": "「熱を寄付する」は対象が合わず、文脈にも合わない。", "採点": "「熱を採点する」は意味が成り立たず、機械の動作の説明にならない。"}, "sentence_index": 0, "correct_answer": "放出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は相続の権利を放出した。", "explanation": "ここは〈放棄〉の意味。権利を手放すことは「放棄」で、「放出」は中にあったものを外に出す意味で使う。"}, {"text": "コップに牛乳を放出した。", "explanation": "ここは〈注ぐ〉の意味。容器に液体を入れることは「注ぐ」で、「放出」は内部のものが外へ出る場合に使う。"}, {"text": "雑草を放出した。", "explanation": "ここは〈排除〉の意味。取り除くことは「排除」で、「放出」は中にあったものを外へ出すことに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52755, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放出", "is_correct": true, "explanation": "正解。中のガスが外へ出る意味で、「外に放出される」が入る。"}, {"text": "掲載", "is_correct": false, "explanation": "「外に掲載される」は文として成り立たず、ガスの動きに合わない。"}, {"text": "乾燥", "is_correct": false, "explanation": "「外に乾燥される」は意味が通らず、ガスが外へ出る文脈に合わない。"}, {"text": "解体", "is_correct": false, "explanation": "「外に解体される」は対象も動作も合わず、文脈に反する。"}], "explanations": {"放出": "正解。中のガスが外へ出る意味で、「外に放出される」が入る。", "掲載": "「外に掲載される」は文として成り立たず、ガスの動きに合わない。", "乾燥": "「外に乾燥される」は意味が通らず、ガスが外へ出る文脈に合わない。", "解体": "「外に解体される」は対象も動作も合わず、文脈に反する。"}, "sentence_index": 6, "correct_answer": "放出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スープに塩を放出した。", "explanation": "ここは〈追加〉の意味。料理に加えることは「追加」で、「放出」は内部にあったものを外へ出す場合に使う。"}, {"text": "注文した荷物を玄関まで放出した。", "explanation": "ここは〈配達〉の意味。品物を届けることは「配達」で、「放出」は閉じ込められたものを外に出す場合に使う。"}, {"text": "本を棚に放出して片づけた。", "explanation": "ここは〈収納〉の意味。物をしまうことは「収納」で、「放出」は中にあるものを外に出すことに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52755, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ボトルを強く振ると、中の炭酸ガスが放出を吹き出す。", "corrected_sentence": "ボトルを強く振ると、中の炭酸ガスが放出される。", "error_description": "正しくは「放出される」。「放出」は「放出する」「放出される」の形で動詞として使うため、名詞のまま「放出を吹き出す」と続けるのは不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52755, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ストーブは部屋に熱を放出ながら、暖かさを保つ。", "corrected_sentence": "ストーブは部屋に熱を放出しながら、暖かさを保つ。", "error_description": "正しくは「放出しながら」。「放出」は「放出する」の形で動詞として使うため、「ながら」の前に「し」が必要。「放出ながら」は文法的に成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52756, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吸収", "is_correct": true, "explanation": "正解。放出が中のものを外へ出すのに対し、吸収は外のものを中に取り入れるため、対義語になる。"}, {"text": "点検", "is_correct": false, "explanation": "物の状態を調べることで、放出の反対語にはならない。"}, {"text": "散布", "is_correct": false, "explanation": "まき散らす動作で、外へ出す点は似るが、対義語ではなく同類の動作。"}, {"text": "変換", "is_correct": false, "explanation": "形や性質を変えることで、外に出すこととは対になる関係にない。"}], "correct_answer": "吸収", "explanations": {"吸収": "正解。放出が中のものを外へ出すのに対し、吸収は外のものを中に取り入れるため、対義語になる。", "点検": "物の状態を調べることで、放出の反対語にはならない。", "散布": "まき散らす動作で、外へ出す点は似るが、対義語ではなく同類の動作。", "変換": "形や性質を変えることで、外に出すこととは対になる関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52756, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吸収", "is_correct": true, "explanation": "正解。放出が中のものを外へ出すのに対し、吸収は外のものを中に取り入れるため、対義語になる。"}, {"text": "配置", "is_correct": false, "explanation": "ものを決まった場所に置くことで、外へ出す放出とは対義関係にない。"}, {"text": "採掘", "is_correct": false, "explanation": "地中から取り出す作業で、放出とは対になる関係にない。"}, {"text": "制御", "is_correct": false, "explanation": "抑えて管理することで、外へ出す放出の対義語にはならない。"}], "correct_answer": "吸収", "explanations": {"吸収": "正解。放出が中のものを外へ出すのに対し、吸収は外のものを中に取り入れるため、対義語になる。", "配置": "ものを決まった場所に置くことで、外へ出す放出とは対義関係にない。", "採掘": "地中から取り出す作業で、放出とは対になる関係にない。", "制御": "抑えて管理することで、外へ出す放出の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52756, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "内部に閉じ込められていたものを、外部に出すこと。", "primary_collocate": null, "pronunciation": "ほうしゅつ", "ipa": "hoːɕɯtsɯ", "syllable_count": 4, "sentences": [{"text": "人為的な要因によって大気中に放出された過剰な温室効果ガスは、放射強制力を変化させ、全球規模での気候変動を加速させている。", "target_word": "放出", "complexity_tier": "T5", "furigana": "人為的[じんいてき]な要因[よういん]によって大気中[たいきちゅう]に放出[ほうしゅつ]された過剰[かじょう]な温室効果[おんしつこうか]ガスは、放射強制力[ほうしゃきょうせいりょく]を変化[へんか]させ、全球規模[ぜんきゅうきぼ]での気候変動[きこうへんどう]を加速[かそく]させている。", "sentence_source": "mined"}, {"text": "火山が噴火すると、地下の熱とガスが一気に放出される。", "target_word": "放出", "complexity_tier": "T3", "furigana": "火山[かざん]が噴火[ふんか]すると、地下[ちか]の熱[ねつ]とガスが一気[いっき]に放出[ほうしゅつ]される。", "sentence_source": "generated"}, {"text": "植物は光合成によって、酸素を空気中に放出する。", "target_word": "放出", "complexity_tier": "T3", "furigana": "植物[しょくぶつ]は光合成[こうごうせい]によって、酸素[さんそ]を空気中[くうきちゅう]に放出[ほうしゅつ]する。", "sentence_source": "generated"}, {"text": "原子炉の事故で、放射性物質が外部に放出された。", "target_word": "放出", "complexity_tier": "T3", "furigana": "原子炉[げんしろ]の事故[じこ]で、放射性物質[ほうしゃせいぶっしつ]が外部[がいぶ]に放出[ほうしゅつ]された。", "sentence_source": "generated"}, {"text": "太陽は莫大なエネルギーを宇宙へ放出し続けている。", "target_word": "放出", "complexity_tier": "T3", "furigana": "太陽[たいよう]は莫大[ばくだい]なエネルギーを宇宙[うちゅう]へ放出[ほうしゅつ]し続[つづ]けている。", "sentence_source": "generated"}, {"text": "缶の中に閉じ込めた圧縮空気を放出すると、大きな音が出る。", "target_word": "放出", "complexity_tier": "T3", "furigana": "缶[かん]の中[なか]に閉[と]じ込[こ]めた圧縮空気[あっしゅくくうき]を放出[ほうしゅつ]すると、大[おお]きな音[おと]が出[で]る。", "sentence_source": "generated"}, {"text": "体は暑くなると、汗とともに熱を放出して温度を下げる。", "target_word": "放出", "complexity_tier": "T3", "furigana": "体[からだ]は暑[あつ]くなると、汗[あせ]とともに熱[ねつ]を放出[ほうしゅつ]して温度[おんど]を下[さ]げる。", "sentence_source": "generated"}, {"text": "地震の前に、岩の割れ目から地下のガスが放出されることがある。", "target_word": "放出", "complexity_tier": "T3", "furigana": "地震[じしん]の前[まえ]に、岩[いわ]の割[わ]れ目[め]から地下[ちか]のガスが放出[ほうしゅつ]されることがある。", "sentence_source": "generated"}, {"text": "湖の底にたまっていた二酸化炭素が、急に放出された。", "target_word": "放出", "complexity_tier": "T3", "furigana": "湖[みずうみ]の底[そこ]にたまっていた二酸化炭素[にさんかたんそ]が、急[きゅう]に放出[ほうしゅつ]された。", "sentence_source": "generated"}, {"text": "装置のバルブを開けて、中の蒸気を安全に放出した。", "target_word": "放出", "complexity_tier": "T3", "furigana": "装置[そうち]のバルブを開[あ]けて、中[なか]の蒸気[じょうき]を安全[あんぜん]に放出[ほうしゅつ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "放出", "label": "基本形"}, {"form": "放出する", "label": "辞書形"}, {"form": "放出される", "label": "受身形"}, {"form": "放出した", "label": "過去形"}, {"form": "放出して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "ガス・熱・エネルギーなど内部にたまっていたものを外へ出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0888c172-05ca-47fc-b033-bf6b11e5f019') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52756, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放出", "is_correct": true, "explanation": "正解。閉じ込められていたガスを外へ出す意味で、「放出された」が入る。"}, {"text": "粉砕", "is_correct": false, "explanation": "「大気中に粉砕された」は意味が通らず、ガスが外へ出る文脈に合わない。"}, {"text": "凝固", "is_correct": false, "explanation": "「大気中に凝固された」は主語の状態と合わず、文が成り立たない。"}, {"text": "研磨", "is_correct": false, "explanation": "「大気中に研磨された」は対象も動作も合わず、文脈に反する。"}], "explanations": {"放出": "正解。閉じ込められていたガスを外へ出す意味で、「放出された」が入る。", "粉砕": "「大気中に粉砕された」は意味が通らず、ガスが外へ出る文脈に合わない。", "凝固": "「大気中に凝固された」は主語の状態と合わず、文が成り立たない。", "研磨": "「大気中に研磨された」は対象も動作も合わず、文脈に反する。"}, "sentence_index": 0, "correct_answer": "放出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "テレビ局が新しいドラマを放出した。", "explanation": "ここは〈放送〉の意味。番組を電波で流すことは「放送」で、「放出」は閉じ込められていたものを外へ出すことに使う。"}, {"text": "捕らえられていた人を放出した。", "explanation": "ここは〈解放〉の意味。人を自由にすることは「解放」で、「放出」は気体・熱・エネルギーなどに使う。"}, {"text": "ごみを海に放出した。", "explanation": "ここは〈投棄〉の意味。ごみを捨てることは「投棄」で、「放出」は内部にあったものを外へ出す場合に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52756, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放出", "is_correct": true, "explanation": "正解。汗とともに熱を外へ出す意味で、「放出して」が入る。"}, {"text": "採用", "is_correct": false, "explanation": "「熱を採用して温度を下げる」は意味が通らず、熱の処理の文脈に合わない。"}, {"text": "延期", "is_correct": false, "explanation": "「熱を延期して」は対象と動作が合わず、文が成り立たない。"}, {"text": "解約", "is_correct": false, "explanation": "「熱を解約して」は契約の語で、体温調節の文脈に合わない。"}], "explanations": {"放出": "正解。汗とともに熱を外へ出す意味で、「放出して」が入る。", "採用": "「熱を採用して温度を下げる」は意味が通らず、熱の処理の文脈に合わない。", "延期": "「熱を延期して」は対象と動作が合わず、文が成り立たない。", "解約": "「熱を解約して」は契約の語で、体温調節の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "放出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は大切にしてきた絵画を、展覧会に放出した。", "explanation": "ここは〈出品〉の意味。展覧会に作品を出すことは「出品」で、「放出」は閉じ込められていたものを外へ出す場合に使う。"}, {"text": "厳しい規制を放出して、市場は活気づいた。", "explanation": "ここは〈解除〉の意味。規制を取り払うことは「解除」で、「放出」は閉じ込められたものを外に出す場合に使う。"}, {"text": "国連は昨日、停戦を放出した。", "explanation": "ここは〈宣言〉の意味。停戦などを公に告げることは「宣言」で、「放出」は内部にあったものを外へ出す場合に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52756, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地下にたまったメタンが、一気に放出を開けた。", "corrected_sentence": "地下にたまったメタンが、一気に放出された。", "error_description": "正しくは「放出された」。「放出」は「放出する」「放出される」の形で動詞として使うため、名詞のまま「放出を開けた」と続けるのは不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52756, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ボイラーは余分な蒸気を外に放出されて、圧力を下げる。", "corrected_sentence": "ボイラーは余分な蒸気を外に放出して、圧力を下げる。", "error_description": "正しくは「放出して」。ボイラーが蒸気を出す主体なので能動態の「放出して」が必要で、「放出されて」は受身となり主語と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52757, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "任意", "is_correct": true, "explanation": "強制の対義語。本人が選べることを表し、「強制だ」の反対にあたる。"}, {"text": "協調", "is_correct": false, "explanation": "互いに調子を合わせる意味で、強制の対義語ではない。"}, {"text": "祝福", "is_correct": false, "explanation": "幸いを祈る意味で、強制の対義語ではない。"}, {"text": "談笑", "is_correct": false, "explanation": "楽しく話す意味で、強制の対義語ではない。"}], "correct_answer": "任意", "explanations": {"任意": "強制の対義語。本人が選べることを表し、「強制だ」の反対にあたる。", "協調": "互いに調子を合わせる意味で、強制の対義語ではない。", "祝福": "幸いを祈る意味で、強制の対義語ではない。", "談笑": "楽しく話す意味で、強制の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52757, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "任意", "is_correct": true, "explanation": "強制の対義語。本人が自由に選べることを表し、「本人に選ばせる」という文脈の反対にあたる。"}, {"text": "歓迎", "is_correct": false, "explanation": "喜んで迎える意味で、強制の対義語ではない。"}, {"text": "応援", "is_correct": false, "explanation": "力を添える意味で、強制の対義語ではない。"}, {"text": "謝罪", "is_correct": false, "explanation": "詫びる意味で、強制の対義語ではない。"}], "correct_answer": "任意", "explanations": {"任意": "強制の対義語。本人が自由に選べることを表し、「本人に選ばせる」という文脈の反対にあたる。", "歓迎": "喜んで迎える意味で、強制の対義語ではない。", "応援": "力を添える意味で、強制の対義語ではない。", "謝罪": "詫びる意味で、強制の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52757, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "「強制」は、むりやり何かをさせることです。", "primary_collocate": null, "pronunciation": "きょうせい", "ipa": "kʲoːseː", "syllable_count": 4, "sentences": [{"text": "寒いのに、先生は私たちに窓を開けるよう強制した。", "target_word": "強制", "complexity_tier": "T3", "furigana": "寒[さむ]いのに、先生[せんせい]は私[わたし]たちに窓[まど]を開[あ]けるよう強制[きょうせい]した。", "sentence_source": "generated"}, {"text": "弟に野菜を食べることを強制しても、嫌いなままだ。", "target_word": "強制", "complexity_tier": "T3", "furigana": "弟[おとうと]に野菜[やさい]を食[た]べることを強制[きょうせい]しても、嫌[きら]いなままだ。", "sentence_source": "generated"}, {"text": "この旅行は自由参加で、強制ではありません。", "target_word": "強制", "complexity_tier": "T3", "furigana": "この旅行[りょこう]は自由参加[じゆうさんか]で、強制[きょうせい]ではありません。", "sentence_source": "generated"}, {"text": "嫌がる友達に歌を歌わせるのは強制だ。", "target_word": "強制", "complexity_tier": "T3", "furigana": "嫌[いや]がる友達[ともだち]に歌[うた]を歌[うた]わせるのは強制[きょうせい]だ。", "sentence_source": "generated"}, {"text": "兄に強制されて、私は早起きして走ることになった。", "target_word": "強制", "complexity_tier": "T3", "furigana": "兄[あに]に強制[きょうせい]されて、私[わたし]は早起[はやお]きして走[はし]ることになった。", "sentence_source": "generated"}, {"text": "人に何かを強制してはいけないと、母はいつも言っている。", "target_word": "強制", "complexity_tier": "T3", "furigana": "人[ひと]に何[なに]かを強制[きょうせい]してはいけないと、母[はは]はいつも言[い]っている。", "sentence_source": "generated"}, {"text": "参加を強制されたので、行きたくなかったが会議に出た。", "target_word": "強制", "complexity_tier": "T3", "furigana": "参加[さんか]を強制[きょうせい]されたので、行[い]きたくなかったが会議[かいぎ]に出[で]た。", "sentence_source": "generated"}, {"text": "強制されてする勉強は、あまり身につかない。", "target_word": "強制", "complexity_tier": "T3", "furigana": "強制[きょうせい]されてする勉強[べんきょう]は、あまり身[み]につかない。", "sentence_source": "generated"}, {"text": "店員に高額な商品を買うよう強制されたら、はっきり断ろう。", "target_word": "強制", "complexity_tier": "T3", "furigana": "店員[てんいん]に高額[こうがく]な商品[しょうひん]を買[か]うよう強制[きょうせい]されたら、はっきり断[ことわ]ろう。", "sentence_source": "generated"}, {"text": "子どもに習い事を強制しないで、本人に選ばせることにした。", "target_word": "強制", "complexity_tier": "T3", "furigana": "子[こ]どもに習[なら]い事[ごと]を強制[きょうせい]しないで、本人[ほんにん]に選[えら]ばせることにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "強制", "label": "基本形"}, {"form": "強制する", "label": "サ変動詞"}, {"form": "強制された", "label": "受身過去"}], "register": "neutral", "sense_fingerprint": "forcing someone to do something against their will", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: 断ろ (Zipf 2.42)']::text[], '668c9d2b-8db0-417b-ae24-4fd397db1504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52757, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "強制", "is_correct": true, "explanation": "正解。窓を開けるよう命じた、という文脈に合う。"}, {"text": "禁止", "is_correct": false, "explanation": "やめさせる意味で、「窓を開けるよう禁止した」は命じる文脈に合わない。"}, {"text": "放置", "is_correct": false, "explanation": "そのままにしておく意味で、窓を開けさせる文脈とは合わない。"}, {"text": "中止", "is_correct": false, "explanation": "取りやめる意味で、窓を開けるよう命じる文脈に合わない。"}], "explanations": {"強制": "正解。窓を開けるよう命じた、という文脈に合う。", "禁止": "やめさせる意味で、「窓を開けるよう禁止した」は命じる文脈に合わない。", "放置": "そのままにしておく意味で、窓を開けさせる文脈とは合わない。", "中止": "取りやめる意味で、窓を開けるよう命じる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "強制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議では、この数字を強制して説明した。", "explanation": "ここは〈強調〉（特に際立たせること）の意味。強制は無理に押し付けることで、数字を際立たせる意味では使わないので合わない。"}, {"text": "みんなが快く強制してくれたので、準備が早く終わった。", "explanation": "ここは〈協力〉の意味。「快く」と矛盾し、無理に押し付けることは協力の意味にならない。"}, {"text": "母の強制をして、皿を洗った。", "explanation": "ここは〈手伝い〉の意味。強制は相手の意志に関係なく何かをさせることで、手を貸す行為とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52757, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "強制", "is_correct": true, "explanation": "正解。「強制された」の形で、参加を押し付けられたことを表す。"}, {"text": "採点", "is_correct": false, "explanation": "点数をつける意味で、参加の文脈には合わない。"}, {"text": "配信", "is_correct": false, "explanation": "情報を送る意味で、参加を受ける文脈には合わない。"}, {"text": "翻訳", "is_correct": false, "explanation": "言語を移し替える意味で、参加には使わない。"}], "explanations": {"強制": "正解。「強制された」の形で、参加を押し付けられたことを表す。", "採点": "点数をつける意味で、参加の文脈には合わない。", "配信": "情報を送る意味で、参加を受ける文脈には合わない。", "翻訳": "言語を移し替える意味で、参加には使わない。"}, "sentence_index": 6, "correct_answer": "強制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友人の悲しみを強制した。", "explanation": "ここは〈分かち合う〉（同じ気持ちになる）の意味。強制は相手に無理に押し付けることで、悲しみを共有する意味にはならない。"}, {"text": "彼の無事を強制した。", "explanation": "ここは〈祈る〉（無事を願う）の意味。強制は無理にさせることで、無事を願う意味にはならない。"}, {"text": "相手の意見を強制して、発言を控えた。", "explanation": "ここは〈尊重する〉の意味。強制は相手の意向を無視して押し付けることで、意見を尊重する意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52757, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は生徒に掃除で強制しなかった。", "corrected_sentence": "先生は生徒に掃除を強制しなかった。", "error_description": "「掃除で」の「で」が誤り。強制する対象には「を」が必要で、「掃除を強制しなかった」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52757, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は昨夜、弟に宿題を強制する。", "corrected_sentence": "母は昨夜、弟に宿題を強制した。", "error_description": "「強制する」は非過去形で、過去を表す「昨夜」と合わない。過去形の「強制した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52758, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "任意", "is_correct": true, "explanation": "強制の対義語。本人の意思で選べることを表し、「強制参加」に対する「任意参加」にあたる。"}, {"text": "協力", "is_correct": false, "explanation": "力を合わせる意味で、強制の対義語ではない。"}, {"text": "歓迎", "is_correct": false, "explanation": "喜んで迎える意味で、強制の対義語ではない。"}, {"text": "参加", "is_correct": false, "explanation": "加わる意味で、強制の対義語ではない。"}], "correct_answer": "任意", "explanations": {"任意": "強制の対義語。本人の意思で選べることを表し、「強制参加」に対する「任意参加」にあたる。", "協力": "力を合わせる意味で、強制の対義語ではない。", "歓迎": "喜んで迎える意味で、強制の対義語ではない。", "参加": "加わる意味で、強制の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52758, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "任意", "is_correct": true, "explanation": "強制の対義語。本人が自由に選べることを表し、「習い事を強制される」の反対にあたる。"}, {"text": "応援", "is_correct": false, "explanation": "力を添える意味で、強制の対義語ではない。"}, {"text": "歓喜", "is_correct": false, "explanation": "大きく喜ぶ意味で、強制の対義語ではない。"}, {"text": "謝罪", "is_correct": false, "explanation": "詫びる意味で、強制の対義語ではない。"}], "correct_answer": "任意", "explanations": {"任意": "強制の対義語。本人が自由に選べることを表し、「習い事を強制される」の反対にあたる。", "応援": "力を添える意味で、強制の対義語ではない。", "歓喜": "大きく喜ぶ意味で、強制の対義語ではない。", "謝罪": "詫びる意味で、強制の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52758, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "「強制」とは、相手の意志に関係なく、ある行動や状態を無理に押し付けること。", "primary_collocate": null, "pronunciation": "きょうせい", "ipa": "kʲoːseː", "syllable_count": 4, "sentences": [{"text": "雨の日でも、監督は選手に外での練習を強制した。", "target_word": "強制", "complexity_tier": "T5", "furigana": "雨[あめ]の日[ひ]でも、監督[かんとく]は選手[せんしゅ]に外[そと]での練習[れんしゅう]を強制[きょうせい]した。", "sentence_source": "generated"}, {"text": "部活への参加を強制されて、私はやる気をなくした。", "target_word": "強制", "complexity_tier": "T3", "furigana": "部活[ぶかつ]への参加[さんか]を強制[きょうせい]されて、私[わたし]はやる気[き]をなくした。", "sentence_source": "generated"}, {"text": "親が子どもの進路を強制するのは、よくないと思う。", "target_word": "強制", "complexity_tier": "T3", "furigana": "親[おや]が子[こ]どもの進路[しんろ]を強制[きょうせい]するのは、よくないと思[おも]う。", "sentence_source": "generated"}, {"text": "強制ではありませんので、都合の悪い方は欠席しても構いません。", "target_word": "強制", "complexity_tier": "T3", "furigana": "強制[きょうせい]ではありませんので、都合[つごう]の悪[わる]い方[かた]は欠席[けっせき]しても構[かま]いません。", "sentence_source": "generated"}, {"text": "無理な残業を強制する会社は、社員から信頼されない。", "target_word": "強制", "complexity_tier": "T4", "furigana": "無理[むり]な残業[ざんぎょう]を強制[きょうせい]する会社[かいしゃ]は、社員[しゃいん]から信頼[しんらい]されない。", "sentence_source": "generated"}, {"text": "彼は強制されたわけではなく、自分で手伝うと決めたのだ。", "target_word": "強制", "complexity_tier": "T3", "furigana": "彼[かれ]は強制[きょうせい]されたわけではなく、自分[じぶん]で手伝[てつだ]うと決[き]めたのだ。", "sentence_source": "generated"}, {"text": "本人の意思に反して署名を強制された場合、その契約は取り消すことができる。", "target_word": "強制", "complexity_tier": "T3", "furigana": "本人[ほんにん]の意思[いし]に反[はん]して署名[しょめい]を強制[きょうせい]された場合[ばあい]、その契約[けいやく]は取[と]り消[け]すことができる。", "sentence_source": "generated"}, {"text": "学校側は、生徒に意見表明を強制しないと明言した。", "target_word": "強制", "complexity_tier": "T3", "furigana": "学校[がっこう]側[がわ]は、生徒[せいと]に意見[いけん]表明[ひょうめい]を強制[きょうせい]しないと明言[めいげん]した。", "sentence_source": "generated"}, {"text": "警察は市民に協力を強制することはできない。", "target_word": "強制", "complexity_tier": "T4", "furigana": "警察[けいさつ]は市民[しみん]に協力[きょうりょく]を強制[きょうせい]することはできない。", "sentence_source": "generated"}, {"text": "好きでもない習い事を強制されると、続ける気が起きない。", "target_word": "強制", "complexity_tier": "T3", "furigana": "好[す]きでもない習[なら]い事[ごと]を強制[きょうせい]されると、続[つづ]ける気[き]が起[お]きない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "強制", "label": "基本形"}, {"form": "強制する", "label": "サ変動詞"}, {"form": "強制された", "label": "受身過去"}], "register": "formal", "sense_fingerprint": "compulsion: forcing an action or state on someone regardless of their will", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '668c9d2b-8db0-417b-ae24-4fd397db1504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52758, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "強制", "is_correct": true, "explanation": "正解。選手に外での練習を押し付けたことを表し、ここでは「強制した」が入る。"}, {"text": "翻訳", "is_correct": false, "explanation": "言語を移し替える意味で、「練習を翻訳した」とは言えない。"}, {"text": "作曲", "is_correct": false, "explanation": "曲を作る意味で、練習には使えず空所に入らない。"}, {"text": "装飾", "is_correct": false, "explanation": "飾り付ける意味で、「練習を装飾した」とは言えない。"}], "explanations": {"強制": "正解。選手に外での練習を押し付けたことを表し、ここでは「強制した」が入る。", "翻訳": "言語を移し替える意味で、「練習を翻訳した」とは言えない。", "作曲": "曲を作る意味で、練習には使えず空所に入らない。", "装飾": "飾り付ける意味で、「練習を装飾した」とは言えない。"}, "sentence_index": 0, "correct_answer": "強制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その点を強制して説明した。", "explanation": "ここは〈強調〉（特に際立たせること）の意味。強制は相手に無理に押し付けることで、点を際立たせる意味では使わないので合わない。"}, {"text": "値段を強制して、少し安くしてもらった。", "explanation": "ここは〈交渉〉の意味。値段は話し合いで決めるもので、相手の意志を無視して押し付ける強制とは合わない。"}, {"text": "先生の強制を得て、早退した。", "explanation": "ここは〈許可〉の意味。強制は相手の意志に関係なく押し付けるもので、得て喜ぶものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52758, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "強制", "is_correct": true, "explanation": "正解。「強制された」の形で、本人の意思に反して押し付けられた状態を表す。"}, {"text": "出品", "is_correct": false, "explanation": "商品を市場に出す意味で、署名には使わない。"}, {"text": "翻訳", "is_correct": false, "explanation": "言語を移し替える意味で、署名には使わない。"}, {"text": "採点", "is_correct": false, "explanation": "点数をつける意味で、署名には使わない。"}], "explanations": {"強制": "正解。「強制された」の形で、本人の意思に反して押し付けられた状態を表す。", "出品": "商品を市場に出す意味で、署名には使わない。", "翻訳": "言語を移し替える意味で、署名には使わない。", "採点": "点数をつける意味で、署名には使わない。"}, "sentence_index": 6, "correct_answer": "強制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友人の心遣いを強制した。", "explanation": "ここは〈喜ぶ〉の意味。強制は相手の意志に関係なく無理に押し付けることで、心遣いを喜ぶ意味にはならない。"}, {"text": "友達を強制すると、笑顔になる。", "explanation": "ここは〈褒める〉の意味。強制は無理に押し付けることで、喜ばせる行為とは合わない。"}, {"text": "祖母の形見の皿を強制して大切にしている。", "explanation": "ここは〈大切にする〉の意味。強制は相手の意志を無視して無理にさせることで、物を大切に扱う意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52758, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は生徒に宿題で強制して、ひどく嫌われた。", "corrected_sentence": "先生は生徒に宿題を強制して、ひどく嫌われた。", "error_description": "「宿題で」の「で」が誤り。強制する対象には「を」が必要で、「宿題を強制する」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52758, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日、警察は市民に協力を強制する。", "corrected_sentence": "昨日、警察は市民に協力を強制した。", "error_description": "「強制する」は非過去形で、過去を表す「昨日」と合わない。過去形の「強制した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52759, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「森林の中」で名詞をつなぎ、場所を示す。「森林の中にあり」が自然"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語。「中にある」には目的語が付かない"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語。場所を表す句に付けると文が成立しない"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所。存在を表す「にある」には合わない"}], "correct_answer": "の", "explanations": {"の": "「森林の中」で名詞をつなぎ、場所を示す。「森林の中にあり」が自然", "を": "「を」は目的語。「中にある」には目的語が付かない", "が": "「が」は主語。場所を表す句に付けると文が成立しない", "で": "「で」は動作の場所。存在を表す「にある」には合わない"}, "error_tags": {"を": "目的語", "が": "主語", "で": "動作の場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52759, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「森林の中」で名詞をつなぎ、場所を示す。「森林の中では」が自然"}, {"text": "に", "is_correct": false, "explanation": "存在の場所を示す「に」だが、「森林に中では」と名詞に続けられない"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、場所を表す句にならない"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「中では」という場所の言い方に合わない"}], "correct_answer": "の", "explanations": {"の": "「森林の中」で名詞をつなぎ、場所を示す。「森林の中では」が自然", "に": "存在の場所を示す「に」だが、「森林に中では」と名詞に続けられない", "と": "「と」は並列や相手を示すので、場所を表す句にならない", "へ": "「へ」は方向を示すので、「中では」という場所の言い方に合わない"}, "error_tags": {"に": "場所（存在）", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52759, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たくさんの木が生えている広い場所", "primary_collocate": null, "pronunciation": "しんりん", "ipa": "ɕinɾin", "syllable_count": 4, "sentences": [{"text": "森林の奥に入ると、昼でも暗くて涼しい。", "target_word": "森林", "complexity_tier": "T3", "furigana": "森林[しんりん]の奥[おく]に入[はい]ると、昼[ひる]でも暗[くら]くて涼[すず]しい。", "sentence_source": "generated"}, {"text": "キャンプ場は広い森林の中にあり、夜は星がよく見える。", "target_word": "森林", "complexity_tier": "T3", "furigana": "キャンプ場[じょう]は広[ひろ]い森林[しんりん]の中[なか]にあり、夜[よる]は星[ほし]がよく見[み]える。", "sentence_source": "generated"}, {"text": "森林には、鹿やリスなど、いろいろな動物が住んでいる。", "target_word": "森林", "complexity_tier": "T3", "furigana": "森林[しんりん]には、鹿[しか]やリスなど、いろいろな動物[どうぶつ]が住[す]んでいる。", "sentence_source": "generated"}, {"text": "私たちは森林で道に迷わないように、地図を持って歩いた。", "target_word": "森林", "complexity_tier": "T3", "furigana": "私[わたし]たちは森林[しんりん]で道[みち]に迷[まよ]わないように、地図[ちず]を持[も]って歩[ある]いた。", "sentence_source": "generated"}, {"text": "森林の木々が紅葉して、山全体が赤と黄色になった。", "target_word": "森林", "complexity_tier": "T3", "furigana": "森林[しんりん]の木々[きぎ]が紅葉[こうよう]して、山全体[やまぜんたい]が赤[あか]と黄色[きいろ]になった。", "sentence_source": "generated"}, {"text": "祖母の村は、森林に囲まれた静かな場所にある。", "target_word": "森林", "complexity_tier": "T3", "furigana": "祖母[そぼ]の村[むら]は、森林[しんりん]に囲[かこ]まれた静[しず]かな場所[ばしょ]にある。", "sentence_source": "generated"}, {"text": "森林を抜けると、急に広い湖が見えてきた。", "target_word": "森林", "complexity_tier": "T3", "furigana": "森林[しんりん]を抜[ぬ]けると、急[きゅう]に広[ひろ]い湖[みずうみ]が見[み]えてきた。", "sentence_source": "generated"}, {"text": "雨が降っても、森林の中では傘がいらないほど葉が茂っている。", "target_word": "森林", "complexity_tier": "T4", "furigana": "雨[あめ]が降[ふ]っても、森林[しんりん]の中[なか]では傘[かさ]がいらないほど葉[は]が茂[しげ]っている。", "sentence_source": "generated"}, {"text": "森林の空気はおいしくて、深呼吸すると気持ちがいい。", "target_word": "森林", "complexity_tier": "T3", "furigana": "森林[しんりん]の空気[くうき]はおいしくて、深呼吸[しんこきゅう]すると気持[きも]ちがいい。", "sentence_source": "generated"}, {"text": "この森林は広すぎて、一日では歩いて回れない。", "target_word": "森林", "complexity_tier": "T3", "furigana": "この森林[しんりん]は広[ひろ]すぎて、一日[いちにち]では歩[ある]いて回[まわ]れない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "森林", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "forest as a wide place with many trees, experienced as a place to walk in or live near", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '668c9d2b-8db0-417b-ae24-4fd397db1504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52759, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "森林", "is_correct": true, "explanation": "「森林の奥」の森林。広い場所の奥に入ると暗くて涼しいという文脈に合う"}, {"text": "会議", "is_correct": false, "explanation": "話し合いの場を指し、「会議の奥に入る」とは言わない"}, {"text": "天気", "is_correct": false, "explanation": "空模様を指し、「天気の奥」という場所の言い方にならない"}, {"text": "交通", "is_correct": false, "explanation": "移動の手段や流れを指し、「交通の奥に入る」とは言えない"}], "explanations": {"森林": "「森林の奥」の森林。広い場所の奥に入ると暗くて涼しいという文脈に合う", "会議": "話し合いの場を指し、「会議の奥に入る」とは言わない", "天気": "空模様を指し、「天気の奥」という場所の言い方にならない", "交通": "移動の手段や流れを指し、「交通の奥に入る」とは言えない"}, "sentence_index": 0, "correct_answer": "森林"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私たちは森林で、新鮮な野菜を買った。", "explanation": "ここは〈八百屋〉の意味。森林は買い物をする店ではないので合わない"}, {"text": "森林の本棚に、古い辞書を並べた。", "explanation": "ここは〈本棚〉の意味。本棚は家具で、森林は本を並べる場所ではないので合わない"}, {"text": "森林が一軒あって、そこで休んだ。", "explanation": "ここは〈山小屋〉の意味。森林は地域を指す語で、『一軒』と数えるものではないので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52759, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "森林", "is_correct": true, "explanation": "「森林を抜ける」の森林。通り抜けた先に湖が見えるという文脈に合う"}, {"text": "値段", "is_correct": false, "explanation": "金額を指し、「値段を抜ける」とは言わない"}, {"text": "時計", "is_correct": false, "explanation": "時刻を示す道具で、「時計を抜ける」という使い方にならない"}, {"text": "切符", "is_correct": false, "explanation": "乗車券を指し、「切符を抜けると」は場所の話にならない"}], "explanations": {"森林": "「森林を抜ける」の森林。通り抜けた先に湖が見えるという文脈に合う", "値段": "金額を指し、「値段を抜ける」とは言わない", "時計": "時刻を示す道具で、「時計を抜ける」という使い方にならない", "切符": "乗車券を指し、「切符を抜けると」は場所の話にならない"}, "sentence_index": 6, "correct_answer": "森林"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この森林は地下にあり、改札まで長い階段を下りる。", "explanation": "ここは〈駅〉の意味。森林は地上に広がる地域で、地下の改札や階段の話には合わないので不適"}, {"text": "この森林は、髪を切るのに一時間かかる。", "explanation": "ここは〈美容院〉の意味。森林は髪を切る場所ではないので合わない"}, {"text": "森林のスイッチを押すと、電気がつく。", "explanation": "ここは〈照明〉の意味。森林は電気器具ではないので、スイッチで点くものとは言わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52759, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は森林で抜けて、川まで歩いた。", "corrected_sentence": "私は森林を抜けて、川まで歩いた。", "error_description": "『抜ける』は通り過ぎる場所に『を』を付ける。『で』は場所や手段を表すので誤り。正しくは『森林を抜けて』", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52759, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "森林を歩くて、涼しい風を感じた。", "corrected_sentence": "森林を歩いて、涼しい風を感じた。", "error_description": "『歩く』の て形は『歩いて』。『歩くて』は活用の誤りで、正しくは『歩いて』", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52760, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「おおわれる」の相手を示す「に」。「森林におおわれている」が自然"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語。「おおわれる」は受け身なので「を」は取れない"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示す。覆われた状態を表す文には合わない"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ。述語「おおわれている」の前には置けない"}], "correct_answer": "に", "explanations": {"に": "「おおわれる」の相手を示す「に」。「森林におおわれている」が自然", "を": "「を」は他動詞の目的語。「おおわれる」は受け身なので「を」は取れない", "へ": "「へ」は移動の方向を示す。覆われた状態を表す文には合わない", "の": "「の」は名詞どうしをつなぐ。述語「おおわれている」の前には置けない"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "名詞接続"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52760, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「広がっている」の主語を示す「が」。「森林が広がっている」が自然"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示す。広がる主語にはならない"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」は、広がるの主語にならない"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」は、述語の主語を作れない"}], "correct_answer": "が", "explanations": {"が": "「広がっている」の主語を示す「が」。「森林が広がっている」が自然", "と": "「と」は並列や相手を示す。広がる主語にはならない", "で": "場所や手段を示す「で」は、広がるの主語にならない", "より": "比較を示す「より」は、述語の主語を作れない"}, "error_tags": {"と": "並列・相手", "で": "場所・手段", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52760, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "樹木が密集して生えている地域。", "primary_collocate": null, "pronunciation": "しんりん", "ipa": "ɕinɾin", "syllable_count": 4, "sentences": [{"text": "産業革命以降、人間は燃料や木材を求めて、広い森林を次々と切り開いてきた。", "target_word": "森林", "complexity_tier": "T4", "furigana": "産業革命[さんぎょうかくめい]以降[いこう]、人間[にんげん]は燃料[ねんりょう]や木材[もくざい]を求[もと]めて、広[ひろ]い森林[しんりん]を次々[つぎつぎ]と切[き]り開[ひら]いてきた。", "sentence_source": "generated"}, {"text": "この国は国土の約七割が森林におおわれている。", "target_word": "森林", "complexity_tier": "T3", "furigana": "この国[くに]は国土[こくど]の約[やく]七割[ななわり]が森林[しんりん]におおわれている。", "sentence_source": "generated"}, {"text": "森林は二酸化炭素を吸収して、地球の気候を安定させる。", "target_word": "森林", "complexity_tier": "T4", "furigana": "森林[しんりん]は二酸化炭素[にさんかたんそ]を吸収[きゅうしゅう]して、地球[ちきゅう]の気候[きこう]を安定[あんてい]させる。", "sentence_source": "generated"}, {"text": "森林の中を歩くと、鳥の声と木の香りに包まれた。", "target_word": "森林", "complexity_tier": "T3", "furigana": "森林[しんりん]の中[なか]を歩[ある]くと、鳥[とり]の声[こえ]と木[き]の香[かお]りに包[つつ]まれた。", "sentence_source": "generated"}, {"text": "森林を守るために、ボランティアが毎年木を植えている。", "target_word": "森林", "complexity_tier": "T3", "furigana": "森林[しんりん]を守[まも]るために、ボランティアが毎年[まいとし]木[き]を植[う]えている。", "sentence_source": "generated"}, {"text": "山火事で広い森林が焼け、多くの動物が住む場所を失った。", "target_word": "森林", "complexity_tier": "T4", "furigana": "山火事[やまかじ]で広[ひろ]い森林[しんりん]が焼[や]け、多[おお]くの動物[どうぶつ]が住[す]む場所[ばしょ]を失[うしな]った。", "sentence_source": "generated"}, {"text": "森林の面積が減ると、大雨のとき土砂崩れが起きやすくなる。", "target_word": "森林", "complexity_tier": "T4", "furigana": "森林[しんりん]の面積[めんせき]が減[へ]ると、大雨[おおあめ]のとき土砂崩[どしゃくず]れが起[お]きやすくなる。", "sentence_source": "generated"}, {"text": "地図で見ると、この町の北側には深い森林が広がっている。", "target_word": "森林", "complexity_tier": "T3", "furigana": "地図[ちず]で見[み]ると、この町[まち]の北側[きたがわ]には深[ふか]い森林[しんりん]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "森林から切り出した木材は、家や家具の材料になる。", "target_word": "森林", "complexity_tier": "T4", "furigana": "森林[しんりん]から切[き]り出[だ]した木材[もくざい]は、家[いえ]や家具[かぐ]の材料[ざいりょう]になる。", "sentence_source": "generated"}, {"text": "叔父は森林を見回る仕事をしていて、毎日山に入る。", "target_word": "森林", "complexity_tier": "T3", "furigana": "叔父[おじ]は森林[しんりん]を見回[みまわ]る仕事[しごと]をしていて、毎日[まいにち]山[やま]に入[はい]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "森林", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "forest: an area where trees grow densely, as a land or ecological region", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: 見回る (Zipf 1.74)']::text[], '668c9d2b-8db0-417b-ae24-4fd397db1504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52760, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "森林", "is_correct": true, "explanation": "「森林を切り開く」の森林。燃料や木材を求めて広い土地を切り開くという文脈に合う"}, {"text": "地下水", "is_correct": false, "explanation": "地中の水を指し、「地下水を切り開く」とは言わないので空所に入らない"}, {"text": "機械", "is_correct": false, "explanation": "「機械を切り開く」とは言わず、この位置に入らない"}, {"text": "人口", "is_correct": false, "explanation": "人の数を指し、「人口を切り開く」とは言わないので空所に入らない"}], "explanations": {"森林": "「森林を切り開く」の森林。燃料や木材を求めて広い土地を切り開くという文脈に合う", "地下水": "地中の水を指し、「地下水を切り開く」とは言わないので空所に入らない", "機械": "「機械を切り開く」とは言わず、この位置に入らない", "人口": "人の数を指し、「人口を切り開く」とは言わないので空所に入らない"}, "sentence_index": 0, "correct_answer": "森林"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の森林を剪定すると、枝が元気に伸びてくる。", "explanation": "ここは〈樹木〉の意味。剪定は一本ずつの木に行う作業で、地域を指す森林には合わない"}, {"text": "製材所では、丸太を板に挽いて森林として出荷する。", "explanation": "ここは〈木材〉の意味。森林は地域を指す語で、板に挽いて出荷するものではないので合わない"}, {"text": "ベランダの鉢に、森林を一本植えて育てている。", "explanation": "ここは〈鉢植えの木〉の意味。森林は広い地域を指すので、鉢に一本植える対象にはならない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52760, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "森林", "is_correct": true, "explanation": "「森林の面積」の森林。減ると土砂崩れが起きやすくなるという文脈に合う"}, {"text": "大気", "is_correct": false, "explanation": "空気の層を指し、「大気の面積」とは言わないので空所に入らない"}, {"text": "化石燃料", "is_correct": false, "explanation": "燃料の種類で、面積を持つ対象ではないため「面積が減る」に合わない"}, {"text": "所得", "is_correct": false, "explanation": "収入を指し、「所得の面積」とは言えないので文脈に合わない"}], "explanations": {"森林": "「森林の面積」の森林。減ると土砂崩れが起きやすくなるという文脈に合う", "大気": "空気の層を指し、「大気の面積」とは言わないので空所に入らない", "化石燃料": "燃料の種類で、面積を持つ対象ではないため「面積が減る」に合わない", "所得": "収入を指し、「所得の面積」とは言えないので文脈に合わない"}, "sentence_index": 6, "correct_answer": "森林"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "熱が出て森林に行き、注射を打ってもらった。", "explanation": "ここは〈病院〉の意味。注射を打ってもらう場所は病院で、地域を指す森林には合わないので誤り"}, {"text": "この森林では、ネジを一本ずつ締めている。", "explanation": "ここは〈工場〉の意味。ネジを締める作業場は森林ではないので合わない"}, {"text": "森林を、一本ずつ丁寧にリボンで結んだ。", "explanation": "ここは〈花束〉の意味。花束は束ねて結ぶものだが、森林は束にできないので合わない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52760, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "荒れた森林に元に戻すため、植林が行われた。", "corrected_sentence": "荒れた森林を元に戻すため、植林が行われた。", "error_description": "『元に戻す』の対象は『を』で示す。『に』では対象が立たず不自然。正しくは『森林を元に戻す』", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52760, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地方には、今も深い森林を残っている。", "corrected_sentence": "この地方には、今も深い森林が残っている。", "error_description": "『残る』は主語の『森林が』で示す。『を』は目的語を取らない自動詞には付かないので誤り。正しくは『森林が残っている』", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
