INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52761, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「放射で手が温かくなった」の「で」。放射による手段を示す。"}, {"text": "に", "is_correct": false, "explanation": "「放射に手が」は相手や着点を示すが、放射は手を温める相手にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「放射へ手が」は方向を示す「へ」で、温まった手の主語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「放射の手が」は手と放射を直接つなぐ形になり、温まる理由が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「放射で手が温かくなった」の「で」。放射による手段を示す。", "に": "「放射に手が」は相手や着点を示すが、放射は手を温める相手にはならない。", "へ": "「放射へ手が」は方向を示す「へ」で、温まった手の主語にはならない。", "の": "「放射の手が」は手と放射を直接つなぐ形になり、温まる理由が成り立たない。"}, "error_tags": {"に": "相手", "へ": "方向", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52761, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "光や熱が遠くへ伝わること。", "primary_collocate": null, "pronunciation": "ほうしゃ", "ipa": "hoːɕa", "syllable_count": 3, "sentences": [{"text": "ストーブから放射される熱で、部屋が暖まった。", "target_word": "放射", "complexity_tier": "T2", "furigana": "ストーブからほうしゃされるねつで、へやがあたたまった。", "sentence_source": "generated"}, {"text": "焚き火のそばに座ると、放射の熱が顔に伝わってくる。", "target_word": "放射", "complexity_tier": "T3", "furigana": "たきびのそばにすわると、ほうしゃのねつがかおにつたわってくる。", "sentence_source": "generated"}, {"text": "太陽の光は、放射によって宇宙を通って地球に届く。", "target_word": "放射", "complexity_tier": "T3", "furigana": "たいようのひかりは、ほうしゃによってうちゅうをとおってちきゅうにとどく。", "sentence_source": "generated"}, {"text": "電気ヒーターは、放射で体を直接温めるので、足もとがすぐ暖かくなる。", "target_word": "放射", "complexity_tier": "T3", "furigana": "でんきヒーターは、ほうしゃでからだをちょくせつあたためるので、あしもとがすぐあたたかくなる。", "sentence_source": "generated"}, {"text": "夏の日、アスファルトは強い放射を出して、歩く人を暑くさせる。", "target_word": "放射", "complexity_tier": "T3", "furigana": "なつのひ、アスファルトはつよいほうしゃをだして、あるくひとをあつくさせる。", "sentence_source": "generated"}, {"text": "夜になると地面の熱が空へ放射され、朝は冷え込む。", "target_word": "放射", "complexity_tier": "T3", "furigana": "よるになるとじめんのねつがそらへほうしゃされ、あさはひえこむ。", "sentence_source": "generated"}, {"text": "空気を温めるのではなく、放射で人を温める暖房が人気だ。", "target_word": "放射", "complexity_tier": "T3", "furigana": "くうきをあたためるのではなく、ほうしゃでひとをあたためるだんぼうがにんきだ。", "sentence_source": "generated"}, {"text": "風がなくても、ランプの放射で手が温かくなった。", "target_word": "放射", "complexity_tier": "T3", "furigana": "かぜがなくても、ランプのほうしゃでてがあたたかくなった。", "sentence_source": "generated"}, {"text": "放射の熱は、間に壁があると遮られてしまう。", "target_word": "放射", "complexity_tier": "T3", "furigana": "ほうしゃのねつは、あいだにかべがあるとさえぎられてしまう。", "sentence_source": "generated"}, {"text": "冬の晴れた夜は雲がなく、放射で熱が逃げて霜ができやすい。", "target_word": "放射", "complexity_tier": "T3", "furigana": "ふゆのはれたよるはくもがなく、ほうしゃでねつがにげて、しもができやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "放射", "label": "基本形"}, {"form": "放射する", "label": "サ変動詞形"}], "register": "標準・中立", "sense_fingerprint": "光や熱が空間を伝わって遠くへ届くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '668c9d2b-8db0-417b-ae24-4fd397db1504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52761, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放射", "is_correct": true, "explanation": "ストーブが熱を遠くへ伝えるという意味で、「放射される熱」と自然につながる。"}, {"text": "注入", "is_correct": false, "explanation": "注入は液体などを中へ入れること。熱が遠くへ伝わる意味には合わない。"}, {"text": "点火", "is_correct": false, "explanation": "点火は火をつけること。熱が伝わる様子を表すのには使わない。"}, {"text": "転写", "is_correct": false, "explanation": "転写は写し取ること。熱の伝わり方には使わない。"}], "explanations": {"放射": "ストーブが熱を遠くへ伝えるという意味で、「放射される熱」と自然につながる。", "注入": "注入は液体などを中へ入れること。熱が遠くへ伝わる意味には合わない。", "点火": "点火は火をつけること。熱が伝わる様子を表すのには使わない。", "転写": "転写は写し取ること。熱の伝わり方には使わない。"}, "sentence_index": 0, "correct_answer": "放射"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "選手が強いシュートを放射して、ゴールを決めた。", "explanation": "ここは〈放つ〉の意味。シュートや矢などを勢いよく打つ場合は放つを使い、放射は光や熱が遠くへ伝わる現象に使うので合わない。"}, {"text": "熱が金属の棒の中を放射で伝わって、先端が熱くなる。", "explanation": "ここは〈伝導〉の意味。固体の中を熱が伝わる場合は伝導を使い、放射は遠くへ届く熱の伝わり方に限るので合わない。"}, {"text": "弓を引いた選手が、矢を放射して的に当てた。", "explanation": "ここは〈放つ〉の意味。矢を飛ばす場合は放つを使い、放射は光や熱が遠くへ伝わる現象に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52761, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放射", "is_correct": true, "explanation": "電磁波で熱が空気を介さず届く意味で、熱で人を温める文脈に合う。"}, {"text": "放水", "is_correct": false, "explanation": "放水は水を勢いよく出すこと。人を温める手段としては成り立たない。"}, {"text": "照明", "is_correct": false, "explanation": "照明は光で照らすこと。熱で人を温める手段としては合わない。"}, {"text": "看板", "is_correct": false, "explanation": "看板は広告などの掲示物。人を温める手段には使えない。"}], "explanations": {"放射": "電磁波で熱が空気を介さず届く意味で、熱で人を温める文脈に合う。", "放水": "放水は水を勢いよく出すこと。人を温める手段としては成り立たない。", "照明": "照明は光で照らすこと。熱で人を温める手段としては合わない。", "看板": "看板は広告などの掲示物。人を温める手段には使えない。"}, "sentence_index": 6, "correct_answer": "放射"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "換気扇が部屋の空気を放射して外へ出す。", "explanation": "ここは〈排気〉の意味。室内の空気を外へ出す場合は排気を使い、放射は電磁波などでエネルギーを出す現象に使うので合わない。"}, {"text": "局は新しいドラマを毎週放射している。", "explanation": "ここは〈放映〉の意味。番組を映像で流す場合は放映や放送を使い、放射は使わない。"}, {"text": "ヤカンが水蒸気を放射して、部屋が湿った。", "explanation": "ここは〈放出〉の意味。気体を外へ出す場合は放出を使い、放射はエネルギーを電磁波で出す現象に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52761, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "薪ストーブは、放射を部屋の隅々まで熱を届ける。", "corrected_sentence": "薪ストーブは、放射で部屋の隅々まで熱を届ける。", "error_description": "「放射で」は放射による手段の意味。「放射を」と目的語にすると、熱を届けるという文の構造が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52761, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ランプの光は、放射せれて遠くまで届く。", "corrected_sentence": "ランプの光は、放射されて遠くまで届く。", "error_description": "「放射される」の受身の活用を誤っている。「せれて」は「されて」が正しい形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52762, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「強い放射を宇宙へ出す」の「を」。出すという動詞の目的語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「強い放射と宇宙へ出す」は並列の意味になり、出す対象が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「強い放射の宇宙へ出す」は名詞をつなぐだけで、出すという動詞の形が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は出す先を示すが、放射を目的語にする形にはならない。"}], "correct_answer": "を", "explanations": {"を": "「強い放射を宇宙へ出す」の「を」。出すという動詞の目的語を示す。", "と": "「強い放射と宇宙へ出す」は並列の意味になり、出す対象が成り立たない。", "の": "「強い放射の宇宙へ出す」は名詞をつなぐだけで、出すという動詞の形が成り立たない。", "に": "「に」は出す先を示すが、放射を目的語にする形にはならない。"}, "error_tags": {"と": "並列", "の": "名詞接続", "に": "着点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52762, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「放射の一部」の「の」。放射と一部をつなぎ、一部を修飾する役割を持つ。"}, {"text": "が", "is_correct": false, "explanation": "「放射が一部を」では放射が主語になるが、ここは一部を修飾する位置なので合わない。"}, {"text": "を", "is_correct": false, "explanation": "「放射を一部を」は目的語が二つになり、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、放射は着く先になれないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「放射の一部」の「の」。放射と一部をつなぎ、一部を修飾する役割を持つ。", "が": "「放射が一部を」では放射が主語になるが、ここは一部を修飾する位置なので合わない。", "を": "「放射を一部を」は目的語が二つになり、文として成り立たない。", "へ": "「へ」は方向を示すが、放射は着く先になれないので合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52762, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物体からエネルギーが電磁波や粒子の形で放出される現象。", "primary_collocate": null, "pronunciation": "ほうしゃ", "ipa": "hoːɕa", "syllable_count": 3, "sentences": [{"text": "温室効果ガスは、地表から宇宙へ出ていく放射を大気中で吸収し、地球の気温を上げている。", "target_word": "放射", "complexity_tier": "T3", "furigana": "温室効果[おんしつこうか]ガスは、地表[ちひょう]から宇宙[うちゅう]へ出[で]ていく放射[ほうしゃ]を大気中[たいきちゅう]で吸収[きゅうしゅう]し、地球[ちきゅう]の気温[きおん]を上[あ]げている。", "sentence_source": "generated"}, {"text": "太陽の表面は高温なので、強い放射を宇宙へ出している。", "target_word": "放射", "complexity_tier": "T3", "furigana": "たいようのひょうめんはこうおんなので、つよいほうしゃをうちゅうへだしている。", "sentence_source": "generated"}, {"text": "物体の温度が高くなるほど、放射のエネルギーは大きくなる。", "target_word": "放射", "complexity_tier": "T3", "furigana": "ぶったいのおんどがたかくなるほど、ほうしゃのエネルギーはおおきくなる。", "sentence_source": "generated"}, {"text": "地表から出る放射が雲に吸収されるため、曇りの夜は冷え込みにくい。", "target_word": "放射", "complexity_tier": "T3", "furigana": "ちひょうからでるほうしゃがくもにきゅうしゅうされるため、くもりのよるはひえこみにくい。", "sentence_source": "generated"}, {"text": "黒い物体は、白い物体よりも放射をよく吸収し、よく出す。", "target_word": "放射", "complexity_tier": "T3", "furigana": "くろいぶったいは、しろいぶったいよりもほうしゃをよくきゅうしゅうし、よくだす。", "sentence_source": "generated"}, {"text": "実験では、金属の板が出す放射の強さを測定した。", "target_word": "放射", "complexity_tier": "T3", "furigana": "じっけんでは、きんぞくのいたがだすほうしゃのつよさをそくていした。", "sentence_source": "generated"}, {"text": "放射によって失われる熱は、周囲との温度差が大きいほど多い。", "target_word": "放射", "complexity_tier": "T3", "furigana": "ほうしゃによってうしなわれるねつは、しゅういとのおんどさがおおきいほどおおい。", "sentence_source": "generated"}, {"text": "地球は太陽から受けた放射の一部を、再び宇宙へ返している。", "target_word": "放射", "complexity_tier": "T3", "furigana": "ちきゅうはたいようからうけたほうしゃのいちぶを、ふたたびうちゅうへかえしている。", "sentence_source": "generated"}, {"text": "星が出す放射を分析すると、その星の温度が分かる。", "target_word": "放射", "complexity_tier": "T3", "furigana": "ほしがだすほうしゃをぶんせきすると、そのほしのおんどがわかる。", "sentence_source": "generated"}, {"text": "原子が高いエネルギーの状態から戻るとき、光が放射される。", "target_word": "放射", "complexity_tier": "T3", "furigana": "げんしがたかいエネルギーのじょうたいからもどるとき、ひかりがほうしゃされる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "放射", "label": "基本形"}, {"form": "放射する", "label": "サ変動詞形"}], "register": "書き言葉・科学用語", "sense_fingerprint": "物体が電磁波や粒子の形でエネルギーを放出する物理現象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '668c9d2b-8db0-417b-ae24-4fd397db1504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52762, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放射", "is_correct": true, "explanation": "地表から宇宙へ出ていく放射の意味。温室効果ガスが吸収する熱の話に合う。"}, {"text": "放電", "is_correct": false, "explanation": "電気が流れ出す現象で、宇宙へ出ていく熱や光の話にはならない。"}, {"text": "放流", "is_correct": false, "explanation": "水や魚を流し出す意味で、宇宙へ出ていくエネルギーの話にはならない。"}, {"text": "注射", "is_correct": false, "explanation": "薬液などを体に入れること。大気が吸収する対象にはならない。"}], "explanations": {"放射": "地表から宇宙へ出ていく放射の意味。温室効果ガスが吸収する熱の話に合う。", "放電": "電気が流れ出す現象で、宇宙へ出ていく熱や光の話にはならない。", "放流": "水や魚を流し出す意味で、宇宙へ出ていくエネルギーの話にはならない。", "注射": "薬液などを体に入れること。大気が吸収する対象にはならない。"}, "sentence_index": 0, "correct_answer": "放射"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鏡は太陽の光を放射して、部屋を明るくしている。", "explanation": "ここは〈反射〉の意味。鏡が光を跳ね返す場合は反射を使い、放射は物体が自らエネルギーを出す現象に使うので合わない。"}, {"text": "ダムが水を一気に放射して、下流の川が増水した。", "explanation": "ここは〈放出〉の意味。水のような物質を勢いよく出す場合は放出を使い、放射は電磁波や粒子のエネルギーに限るので合わない。"}, {"text": "スプレーから殺虫剤を放射して、部屋中に広がった。", "explanation": "ここは〈噴射〉の意味。液体や気体を吹き出す場合は噴射を使い、放射はエネルギーの放出に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52762, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放射", "is_correct": true, "explanation": "電磁波としてエネルギーが出ていく意味で、熱が失われる理由に合う。"}, {"text": "放棄", "is_correct": false, "explanation": "権利や物を捨てる意味で、熱が失われる物理的な現象には合わない。"}, {"text": "放送", "is_correct": false, "explanation": "放送は番組を電波で送ること。熱が失われるという内容には合わない。"}, {"text": "放牧", "is_correct": false, "explanation": "家畜を野外で放し飼いにすること。熱が失われる理由としては成り立たない。"}], "explanations": {"放射": "電磁波としてエネルギーが出ていく意味で、熱が失われる理由に合う。", "放棄": "権利や物を捨てる意味で、熱が失われる物理的な現象には合わない。", "放送": "放送は番組を電波で送ること。熱が失われるという内容には合わない。", "放牧": "家畜を野外で放し飼いにすること。熱が失われる理由としては成り立たない。"}, "sentence_index": 6, "correct_answer": "放射"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場の煙突が、有害な煙を放射し続けている。", "explanation": "ここは〈排出〉の意味。煙などの気体を外へ出す場合は排出を使い、放射は電磁波などでエネルギーを出す現象に限るので合わない。"}, {"text": "熱は金属の棒の中を放射して、先端まで届く。", "explanation": "ここは〈伝導〉の意味。固体の中を熱が伝わることには伝導を使い、放射は物質を介さず電磁波で届く現象なので合わない。"}, {"text": "テレビ局が、夜のニュース番組を放射している。", "explanation": "ここは〈放映〉の意味。番組を映像や音声で流す場合は放映や放送を使い、放射は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52762, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "温かい物体は放射に熱を外へ出す。", "corrected_sentence": "温かい物体は放射で熱を外へ出す。", "error_description": "「放射で」は放射によって、という手段を表す。「放射に」では手段を示せず不自然。正しくは「で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52762, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ストーブは熱を放射しで、部屋を暖める。", "corrected_sentence": "ストーブは熱を放射して、部屋を暖める。", "error_description": "「放射する」のて形は「放射して」。「放射しで」は濁音の誤りで、続く動詞の形が正しくない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52764, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「全球の平均気温」と名詞をつなぎ、文が成り立つ。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「全球へ平均気温は」は成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「全球を平均気温は」では成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「全球から平均気温は上昇」は文脈に合わない。"}], "correct_answer": "の", "explanations": {"の": "「全球の平均気温」と名詞をつなぎ、文が成り立つ。", "へ": "方向を示すが、「全球へ平均気温は」は成り立たない。", "を": "目的語を示すが、「全球を平均気温は」では成り立たない。", "から": "起点を示すが、「全球から平均気温は上昇」は文脈に合わない。"}, "error_tags": {"へ": "方向マーカー", "を": "目的語マーカー", "から": "起点マーカー"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52764, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52764, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "地球全体。全世界。", "primary_collocate": null, "pronunciation": "ぜんきゅう", "ipa": "zeŋkʲɯː", "syllable_count": 4, "sentences": [{"text": "人為的な要因によって大気中に放出された過剰な温室効果ガスは、放射強制力を変化させ、全球規模での気候変動を加速させている。", "target_word": "全球", "complexity_tier": "T5", "furigana": "人為的[じんいてき]な要因[よういん]によって大気中[たいきちゅう]に放出[ほうしゅつ]された過剰[かじょう]な温室効果[おんしつこうか]ガスは、放射強制力[ほうしゃきょうせいりょく]を変化[へんか]させ、全球規模[ぜんきゅうきぼ]での気候変動[きこうへんどう]を加速[かそく]させている。", "sentence_source": "mined"}, {"text": "全球の平均気温は、この百年で上昇した。", "target_word": "全球", "complexity_tier": "T3", "furigana": "全球[ぜんきゅう]の平均気温[へいきんきおん]は、この百年[ひゃくねん]で上昇[じょうしょう]した。", "sentence_source": "generated"}, {"text": "衛星は、全球の雲の動きを毎日観測している。", "target_word": "全球", "complexity_tier": "T3", "furigana": "衛星[えいせい]は、全球[ぜんきゅう]の雲[くも]の動[うご]きを毎日[まいにち]観測[かんそく]している。", "sentence_source": "generated"}, {"text": "この気候モデルは、一つの地域ではなく全球を対象にしている。", "target_word": "全球", "complexity_tier": "T4", "furigana": "この気候[きこう]モデルは、一[ひと]つの地域[ちいき]ではなく全球[ぜんきゅう]を対象[たいしょう]にしている。", "sentence_source": "generated"}, {"text": "火山の噴火で灰が広がり、全球の気温が一時的に下がった。", "target_word": "全球", "complexity_tier": "T4", "furigana": "火山[かざん]の噴火[ふんか]で灰[はい]が広[ひろ]がり、全球[ぜんきゅう]の気温[きおん]が一時的[いちじてき]に下[さ]がった。", "sentence_source": "generated"}, {"text": "海面の上昇は全球で進んでおり、沿岸の都市を脅かしている。", "target_word": "全球", "complexity_tier": "T4", "furigana": "海面[かいめん]の上昇[じょうしょう]は全球[ぜんきゅう]で進[すす]んでおり、沿岸[えんがん]の都市[とし]を脅[おびやか]している。", "sentence_source": "generated"}, {"text": "研究者たちは、全球の降水量のデータを集めて比較した。", "target_word": "全球", "complexity_tier": "T4", "furigana": "研究者[けんきゅうしゃ]たちは、全球[ぜんきゅう]の降水量[こうすいりょう]のデータを集[あつ]めて比較[ひかく]した。", "sentence_source": "generated"}, {"text": "二酸化炭素の濃度は、全球でほぼ同じ値を示す。", "target_word": "全球", "complexity_tier": "T4", "furigana": "二酸化炭素[にさんかたんそ]の濃度[のうど]は、全球[ぜんきゅう]でほぼ同[おな]じ値[あたい]を示[しめ]す。", "sentence_source": "generated"}, {"text": "全球の海洋を調べるため、各国が共同で観測船を出した。", "target_word": "全球", "complexity_tier": "T4", "furigana": "全球[ぜんきゅう]の海洋[かいよう]を調[しら]べるため、各国[かっこく]が共同[きょうどう]で観測船[かんそくせん]を出[だ]した。", "sentence_source": "generated"}, {"text": "地域の天気予報とは違い、この図は全球の大気の流れを表す。", "target_word": "全球", "complexity_tier": "T4", "furigana": "地域[ちいき]の天気予報[てんきよほう]とは違[ちが]い、この図[ず]は全球[ぜんきゅう]の大気[たいき]の流[なが]れを表[あらわ]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "全球", "label": "基本形"}], "register": "専門的・文章語", "sense_fingerprint": "気象・気候などの科学で、地域ではなく地球全体を指す語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04359626-3ca1-4f32-9bac-ab26ac416c0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52764, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全球", "is_correct": true, "explanation": "「全球規模での気候変動」は地球全体を指し、全球が入る。"}, {"text": "全身", "is_correct": false, "explanation": "身体全体を指すので、気候変動の規模には合わない。"}, {"text": "血流", "is_correct": false, "explanation": "血液の流れを指すので、気候変動の規模には合わない。"}, {"text": "電子", "is_correct": false, "explanation": "物質を構成する粒子を指すので、気候変動の規模には合わない。"}], "explanations": {"全球": "「全球規模での気候変動」は地球全体を指し、全球が入る。", "全身": "身体全体を指すので、気候変動の規模には合わない。", "血流": "血液の流れを指すので、気候変動の規模には合わない。", "電子": "物質を構成する粒子を指すので、気候変動の規模には合わない。"}, "sentence_index": 0, "correct_answer": "全球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この望遠鏡は、全球の遠い星を観測する。", "explanation": "ここは〈宇宙〉の意味。全球は地球全体を指すので、宇宙の天体には使わない。"}, {"text": "薬が、全球の細胞に行き渡る。", "explanation": "ここは〈全身〉の意味。全球は地球全体を指すので、体の全体には使わない。"}, {"text": "夜になり、全球の照明を消した。", "explanation": "ここは〈全館〉の意味。全球は地球全体を指すので、建物全体の設備には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52764, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全球", "is_correct": true, "explanation": "「全球の降水量のデータ」で、地球全体の降水量を指し全球が入る。"}, {"text": "脳波", "is_correct": false, "explanation": "脳の電気活動を指すので、降水量のデータとは合わない。"}, {"text": "通貨", "is_correct": false, "explanation": "お金の単位や流通を指すので、降水量のデータとは合わない。"}, {"text": "皮膚", "is_correct": false, "explanation": "体の表面を指すので、降水量のデータとは合わない。"}], "explanations": {"全球": "「全球の降水量のデータ」で、地球全体の降水量を指し全球が入る。", "脳波": "脳の電気活動を指すので、降水量のデータとは合わない。", "通貨": "お金の単位や流通を指すので、降水量のデータとは合わない。", "皮膚": "体の表面を指すので、降水量のデータとは合わない。"}, "sentence_index": 6, "correct_answer": "全球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全球の生徒が、体育館に集まった。", "explanation": "ここは〈全校〉の意味。全球は地球全体を指すので、学校全体の人々には使わない。"}, {"text": "全球が、しんと静まり返った。", "explanation": "ここは〈教室〉の意味。全球は地球全体を指すので、部屋の中の場所には使わない。"}, {"text": "夕食の準備ができて、全球に料理が並んだ。", "explanation": "ここは〈食卓〉の意味。全球は地球全体を指すので、料理を置く台には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52764, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "気象台は、全球を気圧を毎朝記録している。", "corrected_sentence": "気象台は、全球の気圧を毎朝記録している。", "error_description": "誤り: 全球を（正しくは全球の）。「を」が二つ重なっており、全球は気圧を修飾するので連体の「の」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
