INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52765, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「局面に入る」は到達する段階を表す「に」。"}, {"text": "を", "is_correct": false, "explanation": "「入る」は「を」を目的語にとれないため、「新しい局面を入った」は誤り。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を表し、「局面と入った」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すが、「局面で入った」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「局面に入る」は到達する段階を表す「に」。", "を": "「入る」は「を」を目的語にとれないため、「新しい局面を入った」は誤り。", "と": "「と」は並列や引用を表し、「局面と入った」は文として成り立たない。", "で": "「で」は手段や場所を表すが、「局面で入った」は意味が通らない。"}, "error_tags": {"を": "目的語（入るは取らない）", "と": "引用・並列", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52765, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「局面を見る」の目的語を示す「を」。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾する助詞で、「局面の見て」では動詞に続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、「局面へ見て」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は引用や並列を表し、「局面と見て」は目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「局面を見る」の目的語を示す「を」。", "の": "「の」は名詞を修飾する助詞で、「局面の見て」では動詞に続かない。", "へ": "「へ」は方向を表すが、「局面へ見て」は意味が通らない。", "と": "「と」は引用や並列を表し、「局面と見て」は目的語にならない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "と": "引用・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52765, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ことがらの、あるときのようすのこと。", "primary_collocate": null, "pronunciation": "きょくめん", "ipa": "kʲokɯmeɴ", "syllable_count": 4, "sentences": [{"text": "試合は、苦しい局面になった。", "target_word": "局面", "complexity_tier": "T2", "furigana": "試合[しあい]は、苦[くる]しい局面[きょくめん]になった。", "sentence_source": "generated"}, {"text": "話し合いは、新しい局面に入った。", "target_word": "局面", "complexity_tier": "T2", "furigana": "話[はな]し合[あ]いは、新[あたら]しい局面[きょくめん]に入[はい]った。", "sentence_source": "generated"}, {"text": "碁では、一つの石で局面が変わる。", "target_word": "局面", "complexity_tier": "T3", "furigana": "碁[ご]では、一[ひと]つの石[いし]で局面[きょくめん]が変[か]わる。", "sentence_source": "generated"}, {"text": "勝てるかどうかが決まる大事な局面だ。", "target_word": "局面", "complexity_tier": "T3", "furigana": "勝[か]てるかどうかが決[き]まる大事[だいじ]な局面[きょくめん]だ。", "sentence_source": "generated"}, {"text": "仕事が忙しくなり、難しい局面が続いた。", "target_word": "局面", "complexity_tier": "T3", "furigana": "仕事[しごと]が忙[いそが]しくなり、難[むずか]しい局面[きょくめん]が続[つづ]いた。", "sentence_source": "generated"}, {"text": "試合の最後に、逆転できる局面が来た。", "target_word": "局面", "complexity_tier": "T3", "furigana": "試合[しあい]の最後[さいご]に、逆転[ぎゃくてん]できる局面[きょくめん]が来[き]た。", "sentence_source": "generated"}, {"text": "事件は、思いがけない局面を迎えた。", "target_word": "局面", "complexity_tier": "T3", "furigana": "事件[じけん]は、思[おも]いがけない局面[きょくめん]を迎[むか]えた。", "sentence_source": "generated"}, {"text": "将棋の局面を見て、先生は次の一手を考えた。", "target_word": "局面", "complexity_tier": "T3", "furigana": "将棋[しょうぎ]の局面[きょくめん]を見[み]て、先生[せんせい]は次[つぎ]の一手[いって]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "天気が悪くなり、登山は危ない局面に入った。", "target_word": "局面", "complexity_tier": "T3", "furigana": "天気[てんき]が悪[わる]くなり、登山[とざん]は危[あぶ]ない局面[きょくめん]に入[はい]った。", "sentence_source": "generated"}, {"text": "二人の話し合いは、最後の局面に近づいている。", "target_word": "局面", "complexity_tier": "T3", "furigana": "二人[ふたり]の話[はな]し合[あ]いは、最後[さいご]の局面[きょくめん]に近[ちか]づいている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "局面", "label": "基本形"}], "register": "中立（やや硬い）", "sense_fingerprint": "ことがらが進む中の、ある時点のようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04359626-3ca1-4f32-9bac-ab26ac416c0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52765, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "局面", "is_correct": true, "explanation": "「苦しい局面になった」は状況の段階を表し、文の意味に合う。"}, {"text": "年齢", "is_correct": false, "explanation": "「年齢」は人の歳を指すため、「苦しい年齢になった」は不自然。"}, {"text": "配線", "is_correct": false, "explanation": "「配線」は電気の線を指すので、「苦しい配線になった」は成り立たない。"}, {"text": "包装", "is_correct": false, "explanation": "「包装」は包むことを指すため、「苦しい包装になった」は意味が通らない。"}], "explanations": {"局面": "「苦しい局面になった」は状況の段階を表し、文の意味に合う。", "年齢": "「年齢」は人の歳を指すため、「苦しい年齢になった」は不自然。", "配線": "「配線」は電気の線を指すので、「苦しい配線になった」は成り立たない。", "包装": "「包装」は包むことを指すため、「苦しい包装になった」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "局面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この壁紙は、明るい局面の色で部屋を広く見せる。", "explanation": "ここは〈色合い〉の意味。局面は物事のようすを指すので、色そのものには使わない。"}, {"text": "このかばんの局面は、三万円だ。", "explanation": "ここは〈値段〉の意味。局面は状況を表すため、金額は表せない。"}, {"text": "彼は、おおらかな局面の持ち主だ。", "explanation": "ここは〈性格〉の意味。局面はことがらの状態を指すので、人の性質には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52765, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "局面", "is_correct": true, "explanation": "「思いがけない局面を迎える」は予想外の状況に至ることを表し、文に合う。"}, {"text": "解答", "is_correct": false, "explanation": "「解答」は問題への答えを指すため、「思いがけない解答を迎えた」は不自然。"}, {"text": "利息", "is_correct": false, "explanation": "「利息」は金銭の利子なので、「思いがけない利息を迎えた」は意味が通らない。"}, {"text": "寝具", "is_correct": false, "explanation": "「寝具」は寝るための道具を指すため、「思いがけない寝具を迎えた」は成り立たない。"}], "explanations": {"局面": "「思いがけない局面を迎える」は予想外の状況に至ることを表し、文に合う。", "解答": "「解答」は問題への答えを指すため、「思いがけない解答を迎えた」は不自然。", "利息": "「利息」は金銭の利子なので、「思いがけない利息を迎えた」は意味が通らない。", "寝具": "「寝具」は寝るための道具を指すため、「思いがけない寝具を迎えた」は成り立たない。"}, "sentence_index": 6, "correct_answer": "局面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープは、ほどよい塩味の局面がある。", "explanation": "ここは〈味〉の意味。局面は物事の状況を指すので、味の強さには使えない。"}, {"text": "この箱は、重さが五キロという局面だ。", "explanation": "ここは〈重さ〉の意味。局面は状況の段階を表し、重量は表さない。"}, {"text": "駅までは、歩いて十分という局面だ。", "explanation": "ここは〈所要時間〉の意味。局面は進行上の状態を指すので、時間の長さは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52765, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "両国の交渉は、最終の局面を入った。", "corrected_sentence": "両国の交渉は、最終の局面に入った。", "error_description": "「入る」は「に」で到達する段階を表す。「局面を入った」は助詞の誤りで、正しくは「局面に入った」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52765, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "選手たちは、難しい局面が迎えた。", "corrected_sentence": "選手たちは、難しい局面を迎えた。", "error_description": "「迎える」は他動詞で目的語に「を」をとる。「局面が迎えた」は局面を主語にしてしまい目的語が欠けるため誤り。正しくは「局面を迎えた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52766, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「局面を迎える」の目的語を示す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「局面が迎えた」では局面が迎える主体になり意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「迎える」は「に」と結びつかず、「局面に迎えた」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すが、「局面で迎えた」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「局面を迎える」の目的語を示す格助詞。", "が": "「が」は主語を示すが、「局面が迎えた」では局面が迎える主体になり意味が通らない。", "に": "「迎える」は「に」と結びつかず、「局面に迎えた」は文として成り立たない。", "で": "「で」は場所や手段を表すが、「局面で迎えた」は意味が通らない。"}, "error_tags": {"が": "主語", "に": "位置・帰着", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52766, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「局面に入る」は到達する先を表す「に」。"}, {"text": "を", "is_correct": false, "explanation": "「入る」は「に」をとるので、「局面を入った」は誤り。"}, {"text": "と", "is_correct": false, "explanation": "「と」は引用や並列を表し、「局面と入った」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞につく修飾の助詞で、「局面の入った」は文が続かない。"}], "correct_answer": "に", "explanations": {"に": "「局面に入る」は到達する先を表す「に」。", "を": "「入る」は「に」をとるので、「局面を入った」は誤り。", "と": "「と」は引用や並列を表し、「局面と入った」は成り立たない。", "の": "「の」は名詞につく修飾の助詞で、「局面の入った」は文が続かない。"}, "error_tags": {"を": "目的語（入るは取らない）", "と": "引用・並列", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52766, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の進行上、ある時点での状態や様子。特に、重要な場面や状況。", "primary_collocate": null, "pronunciation": "きょくめん", "ipa": "kʲokɯmeɴ", "syllable_count": 4, "sentences": [{"text": "かつては安定していた生態系のサイクルが、現代文明の経済活動によって歪められ、その修復は極めて困難な局面を迎えている。", "target_word": "局面", "complexity_tier": "T5", "furigana": "かつては安定[あんてい]していた生態系[せいたいけい]のサイクルが、現代文明[げんだいぶんめい]の経済活動[けいざいかつどう]によって歪[ゆが]められ、その修復[しゅうふく]は極[きわ]めて困難[こんなん]な局面[きょくめん]を迎[むか]えている。", "sentence_source": "mined"}, {"text": "試合は、終盤の厳しい局面を迎えた。", "target_word": "局面", "complexity_tier": "T3", "furigana": "試合[しあい]は、終盤[しゅうばん]の厳[きび]しい局面[きょくめん]を迎[むか]えた。", "sentence_source": "generated"}, {"text": "交渉は新しい局面に入り、両社が譲歩を始めた。", "target_word": "局面", "complexity_tier": "T4", "furigana": "交渉[こうしょう]は新[あたら]しい局面[きょくめん]に入[はい]り、両社[りょうしゃ]が譲歩[じょうほ]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "将棋では、一手で局面が大きく変わる。", "target_word": "局面", "complexity_tier": "T3", "furigana": "将棋[しょうぎ]では、一手[いって]で局面[きょくめん]が大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "会社は経営の苦しい局面でも、社員を減らさなかった。", "target_word": "局面", "complexity_tier": "T4", "furigana": "会社[かいしゃ]は経営[けいえい]の苦[くる]しい局面[きょくめん]でも、社員[しゃいん]を減[へ]らさなかった。", "sentence_source": "generated"}, {"text": "首相の発言で、問題は新たな局面を迎えた。", "target_word": "局面", "complexity_tier": "T4", "furigana": "首相[しゅしょう]の発言[はつげん]で、問題[もんだい]は新[あら]たな局面[きょくめん]を迎[むか]えた。", "sentence_source": "generated"}, {"text": "病気は回復に向かい、治療は次の局面に進んだ。", "target_word": "局面", "complexity_tier": "T4", "furigana": "病気[びょうき]は回復[かいふく]に向[む]かい、治療[ちりょう]は次[つぎ]の局面[きょくめん]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "戦争は、和平交渉という局面に入った。", "target_word": "局面", "complexity_tier": "T4", "furigana": "戦争[せんそう]は、和平交渉[わへいこうしょう]という局面[きょくめん]に入[はい]った。", "sentence_source": "generated"}, {"text": "難しい局面でこそ、冷静な判断が求められる。", "target_word": "局面", "complexity_tier": "T4", "furigana": "難[むずか]しい局面[きょくめん]でこそ、冷静[れいせい]な判断[はんだん]が求[もと]められる。", "sentence_source": "generated"}, {"text": "選挙戦は終盤になり、勝負を分ける局面が近づいている。", "target_word": "局面", "complexity_tier": "T4", "furigana": "選挙戦[せんきょせん]は終盤[しゅうばん]になり、勝負[しょうぶ]を分[わ]ける局面[きょくめん]が近[ちか]づいている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "局面", "label": "基本形"}], "register": "中立（やや硬い）", "sense_fingerprint": "物事が進む中の、ある時点の状況。特に重要な場面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04359626-3ca1-4f32-9bac-ab26ac416c0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52766, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "局面", "is_correct": true, "explanation": "「困難な局面を迎える」は状況の段階を表し、文の意味に合う。"}, {"text": "解釈", "is_correct": false, "explanation": "「解釈」は意味の読み取りを指すので、「困難な解釈を迎える」とは言えない。"}, {"text": "手順", "is_correct": false, "explanation": "「手順」は作業の順序を指すため、「困難な手順を迎える」は意味が通らない。"}, {"text": "利益", "is_correct": false, "explanation": "「利益」は得られるものを指すため、「困難な利益を迎える」は成り立たない。"}], "explanations": {"局面": "「困難な局面を迎える」は状況の段階を表し、文の意味に合う。", "解釈": "「解釈」は意味の読み取りを指すので、「困難な解釈を迎える」とは言えない。", "手順": "「手順」は作業の順序を指すため、「困難な手順を迎える」は意味が通らない。", "利益": "「利益」は得られるものを指すため、「困難な利益を迎える」は成り立たない。"}, "sentence_index": 0, "correct_answer": "局面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓の外には、雪をかぶった山々の局面が広がっている。", "explanation": "ここは〈景色〉の意味。局面は物事の進行上の状態を表すので、山の眺めには使えない。"}, {"text": "事務所は、駅前の商店街を抜けた局面にある。", "explanation": "ここは〈場所〉の意味。局面は進行の様子を指すので、位置を示す語としては使わない。"}, {"text": "ケーキの局面に生クリームを塗った。", "explanation": "ここは〈表面〉の意味。局面は物事の状況を指すので、物の表面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52766, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "局面", "is_correct": true, "explanation": "「次の局面に進む」は段階が進むことを表し、文の意味に合う。"}, {"text": "寝具", "is_correct": false, "explanation": "「寝具」は寝るための道具を指すため、「次の寝具に進んだ」は意味が通らない。"}, {"text": "信条", "is_correct": false, "explanation": "「信条」は信念を指すので、「次の信条に進んだ」は意味が通らない。"}, {"text": "気温", "is_correct": false, "explanation": "「気温」は温度を指すため、「次の気温に進んだ」は成り立たない。"}], "explanations": {"局面": "「次の局面に進む」は段階が進むことを表し、文の意味に合う。", "寝具": "「寝具」は寝るための道具を指すため、「次の寝具に進んだ」は意味が通らない。", "信条": "「信条」は信念を指すので、「次の信条に進んだ」は意味が通らない。", "気温": "「気温」は温度を指すため、「次の気温に進んだ」は成り立たない。"}, "sentence_index": 6, "correct_answer": "局面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この窓は、高さが二メートルという局面だ。", "explanation": "ここは〈高さ〉の意味。局面は進行上の状態を指すので、寸法は表せない。"}, {"text": "このシャツは、千円という局面で売られている。", "explanation": "ここは〈価格〉の意味。局面は状況を表すので、金額は表せない。"}, {"text": "このバイオリンは、柔らかい局面を持っている。", "explanation": "ここは〈音色〉の意味。局面は状況の段階を指し、音の質には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52766, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "両チームは、一進一退の局面に迎えている。", "corrected_sentence": "両チームは、一進一退の局面を迎えている。", "error_description": "「迎える」は目的語に「を」をとる。「局面に迎えている」は助詞の誤りで、正しくは「局面を迎えている」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52766, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "両社は新しい局面を入り、協議を再開した。", "corrected_sentence": "両社は新しい局面に入り、協議を再開した。", "error_description": "「入る」は「に」で到達先を表す。「局面を入り」は助詞の誤りで、正しくは「局面に入り」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52767, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「針金を歪めた」の目的語を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「針金が歪めた」では針金が主語になり、目的語が欠ける。"}, {"text": "に", "is_correct": false, "explanation": "「針金に歪めた」では歪める対象を示せず、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「針金へ歪めた」は方向の意味になり、対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「針金を歪めた」の目的語を示す「を」。", "が": "「針金が歪めた」では針金が主語になり、目的語が欠ける。", "に": "「針金に歪めた」では歪める対象を示せず、意味が通らない。", "へ": "「針金へ歪めた」は方向の意味になり、対象を表せない。"}, "error_tags": {"が": "主語", "に": "位置・帰着", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
