INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52767, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "まっすぐなものを、まがったかたちにすること。", "primary_collocate": null, "pronunciation": "ゆがめる", "ipa": "jɯɡameɾɯ", "syllable_count": 4, "sentences": [{"text": "強い力で金属の棒を歪めてしまった。", "target_word": "歪めて", "complexity_tier": "T2", "furigana": "強[つよ]い力[ちから]で金属[きんぞく]の棒[ぼう]を歪[ゆが]めてしまった。", "sentence_source": "generated"}, {"text": "子どもがいたずらで針金を歪めた。", "target_word": "歪めた", "complexity_tier": "T2", "furigana": "子[こ]どもがいたずらで針金[はりがね]を歪[ゆが]めた。", "sentence_source": "generated"}, {"text": "熱は、プラスチックの板を歪めることがある。", "target_word": "歪める", "complexity_tier": "T3", "furigana": "熱[ねつ]は、プラスチックの板[いた]を歪[ゆが]めることがある。", "sentence_source": "generated"}, {"text": "定規を歪めないように、そっと持ってください。", "target_word": "歪め", "complexity_tier": "T3", "furigana": "定規[じょうぎ]を歪[ゆが]めないように、そっと持[も]ってください。", "sentence_source": "generated"}, {"text": "まっすぐな釘を力まかせに歪めてしまった。", "target_word": "歪めて", "complexity_tier": "T3", "furigana": "まっすぐな釘[くぎ]を力[ちから]まかせに歪[ゆが]めてしまった。", "sentence_source": "generated"}, {"text": "重い荷物が、棚の板を歪めている。", "target_word": "歪め", "complexity_tier": "T2", "furigana": "重[おも]い荷物[にもつ]が、棚[たな]の板[いた]を歪[ゆが]めている。", "sentence_source": "generated"}, {"text": "鉄の枠を歪めて、すき間を作った。", "target_word": "歪めて", "complexity_tier": "T3", "furigana": "鉄[てつ]の枠[わく]を歪[ゆが]めて、すき間[ま]を作[つく]った。", "sentence_source": "generated"}, {"text": "力を入れすぎると、傘の骨を歪めるおそれがある。", "target_word": "歪める", "complexity_tier": "T3", "furigana": "力[ちから]を入[い]れすぎると、傘[かさ]の骨[ほね]を歪[ゆが]めるおそれがある。", "sentence_source": "generated"}, {"text": "湿気は木の戸を歪めるので、注意が必要だ。", "target_word": "歪める", "complexity_tier": "T3", "furigana": "湿気[しっけ]は木[き]の戸[と]を歪[ゆが]めるので、注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "職人は、まっすぐな金属線を少しだけ歪めて形を作った。", "target_word": "歪めて", "complexity_tier": "T4", "furigana": "職人[しょくにん]は、まっすぐな金属線[きんぞくせん]を少[すこ]しだけ歪[ゆが]めて形[かたち]を作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "歪めない", "label": "否定形"}, {"form": "歪めます", "label": "丁寧形"}, {"form": "歪めて", "label": "て形"}, {"form": "歪めた", "label": "た形"}, {"form": "歪められる", "label": "受身形"}, {"form": "歪めれば", "label": "仮定形"}, {"form": "歪めよう", "label": "意志形"}], "register": "標準", "sense_fingerprint": "まっすぐな物を力や熱で曲がった形にする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04359626-3ca1-4f32-9bac-ab26ac416c0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52767, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歪めて", "is_correct": true, "explanation": "「歪めてしまった」で、他動詞「歪める」の意味に合う。"}, {"text": "曲がって", "is_correct": false, "explanation": "「曲がる」は自動詞なので、「棒を曲がってしまった」は目的語の「を」と合わない。"}, {"text": "縮んで", "is_correct": false, "explanation": "「縮む」は自動詞で、「棒を縮んでしまった」は文が成り立たない。"}, {"text": "消えて", "is_correct": false, "explanation": "「消える」は自動詞で、「棒を消えてしまった」は意味が通らない。"}], "explanations": {"歪めて": "「歪めてしまった」で、他動詞「歪める」の意味に合う。", "曲がって": "「曲がる」は自動詞なので、「棒を曲がってしまった」は目的語の「を」と合わない。", "縮んで": "「縮む」は自動詞で、「棒を縮んでしまった」は文が成り立たない。", "消えて": "「消える」は自動詞で、「棒を消えてしまった」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "歪めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "やかんを歪めて、お湯を沸かした。", "explanation": "ここは〈沸かす〉の意味。歪めるは形を曲げる意味で、加熱する意味はない。"}, {"text": "ガラスの表面を歪めて、磨いた。", "explanation": "ここは〈磨く〉の意味。歪めるは形を曲げることで、表面をなめらかにする意味はない。"}, {"text": "洗った服を歪めて、乾かした。", "explanation": "ここは〈乾かす〉の意味。歪めるは曲げる意味で、水分を飛ばす意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52767, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歪めて", "is_correct": true, "explanation": "「鉄の枠を歪めて」は他動詞の動作を表し、すき間を作る文に合う。"}, {"text": "飲んで", "is_correct": false, "explanation": "「鉄の枠を飲んで」は意味が通らず、文の内容に合わない。"}, {"text": "聞いて", "is_correct": false, "explanation": "「鉄の枠を聞いて」は成り立たず、文の意味が通らない。"}, {"text": "笑って", "is_correct": false, "explanation": "「鉄の枠を笑って」は意味が通らず、文の内容に合わない。"}], "explanations": {"歪めて": "「鉄の枠を歪めて」は他動詞の動作を表し、すき間を作る文に合う。", "飲んで": "「鉄の枠を飲んで」は意味が通らず、文の内容に合わない。", "聞いて": "「鉄の枠を聞いて」は成り立たず、文の意味が通らない。", "笑って": "「鉄の枠を笑って」は意味が通らず、文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "歪めて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "熱いスープを歪めて、冷やした。", "explanation": "ここは〈冷やす〉の意味。歪めるは形を曲げる意味で、温度を下げる意味はない。"}, {"text": "白い布を歪めて、縫った。", "explanation": "ここは〈縫う〉の意味。歪めるは曲げる意味で、糸で綴じる意味はない。"}, {"text": "大根を歪めて、煮た。", "explanation": "ここは〈煮る〉の意味。歪めるは形を曲げることで、火を通す意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52767, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友人は、薄い鉄板に歪めないように、そっと運んだ。", "corrected_sentence": "友人は、薄い鉄板を歪めないように、そっと運んだ。", "error_description": "「歪める」は「を」で目的語をとる。「鉄板に歪めない」は助詞の誤りで、正しくは「鉄板を歪めない」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "歪めた", "is_correct": true, "explanation": "た形で、「いたずらで針金を歪めた」と過去の出来事を述べる。"}, {"text": "歪めて", "is_correct": false, "explanation": "て形では文が終わらず、「歪めて。」は不完全な文になる。"}, {"text": "歪められ", "is_correct": false, "explanation": "受身の連用形では文を終えられず、「歪められ。」は成り立たない。"}, {"text": "歪めれば", "is_correct": false, "explanation": "仮定形は文を終えられず、「歪めれば。」は成り立たない。"}], "correct_form": "歪めた", "base_form": "歪める", "form_label": "た形", "sentence_index": 1, "explanations": {"歪めた": "た形で、「いたずらで針金を歪めた」と過去の出来事を述べる。", "歪めて": "て形では文が終わらず、「歪めて。」は不完全な文になる。", "歪められ": "受身の連用形では文を終えられず、「歪められ。」は成り立たない。", "歪めれば": "仮定形は文を終えられず、「歪めれば。」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52767, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "職人は、細い針金を歪めれて形を作った。", "corrected_sentence": "職人は、細い針金を歪めて形を作った。", "error_description": "「歪めれて」は活用の誤り。て形の接続は「歪めて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "歪めた", "is_correct": false, "explanation": "「〜たおそれがある」とは言えず、「おそれ」には辞書形を使う。"}, {"text": "歪めれば", "is_correct": false, "explanation": "仮定形は「おそれがある」に続かず、文が成り立たない。"}, {"text": "歪めよう", "is_correct": false, "explanation": "意志形は「おそれがある」の前に置けず、文の意味が通らない。"}, {"text": "歪める", "is_correct": true, "explanation": "辞書形で「おそれがある」に続き、歪めてしまう危険を表す。"}], "correct_form": "歪める", "base_form": "歪める", "form_label": "辞書形", "sentence_index": 7, "explanations": {"歪めた": "「〜たおそれがある」とは言えず、「おそれ」には辞書形を使う。", "歪めれば": "仮定形は「おそれがある」に続かず、文が成り立たない。", "歪めよう": "意志形は「おそれがある」の前に置けず、文の意味が通らない。", "歪める": "辞書形で「おそれがある」に続き、歪めてしまう危険を表す。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52768, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「事実を歪める」の目的語を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「事実が歪めて」では事実が主語になり、「歪める」の目的語が欠ける。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、「事実へ歪めて」は歪める対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を表し、「事実と歪めて」は歪める対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「事実を歪める」の目的語を示す「を」。", "が": "「事実が歪めて」では事実が主語になり、「歪める」の目的語が欠ける。", "へ": "「へ」は方向を表すが、「事実へ歪めて」は歪める対象を示せない。", "と": "「と」は並列や引用を表し、「事実と歪めて」は歪める対象を示せない。"}, "error_tags": {"が": "主語", "へ": "方向", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52768, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「市場を歪める」の目的語を示す「を」。"}, {"text": "と", "is_correct": false, "explanation": "「と」は引用や並列を表し、「市場と歪める」は目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "「市場に歪める」は歪める対象を表せず、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すが、「市場より歪める」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「市場を歪める」の目的語を示す「を」。", "と": "「と」は引用や並列を表し、「市場と歪める」は目的語にならない。", "に": "「市場に歪める」は歪める対象を表せず、意味が通らない。", "より": "「より」は比較を表すが、「市場より歪める」は文として成り立たない。"}, "error_tags": {"と": "引用・並列", "に": "位置・帰着", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52768, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "形や状態を、正常でない方向に変えること。また、本来の意味や内容を、都合の良いように変えること。", "primary_collocate": null, "pronunciation": "ゆがめる", "ipa": "jɯɡameɾɯ", "syllable_count": 4, "sentences": [{"text": "かつては安定していた生態系のサイクルが、現代文明の経済活動によって歪められ、その修復は極めて困難な局面を迎えている。", "target_word": "歪め", "complexity_tier": "T5", "furigana": "かつては安定[あんてい]していた生態系[せいたいけい]のサイクルが、現代[げんだい]文明[ぶんめい]の経済[けいざい]活動[かつどう]によって歪[ゆが]められ、その修復[しゅうふく]は極[きわ]めて困難[こんなん]な局面[きょくめん]を迎[むか]えている。", "sentence_source": "mined"}, {"text": "政治家が事実を歪めて伝えたため、国民の不信が広がった。", "target_word": "歪めて", "complexity_tier": "T3", "furigana": "政治家[せいじか]が事実[じじつ]を歪[ゆが]めて伝[つた]えたため、国民[こくみん]の不信[ふしん]が広[ひろ]がった。", "sentence_source": "generated"}, {"text": "過度な競争は、子どもの成長を歪めてしまうことがある。", "target_word": "歪めて", "complexity_tier": "T3", "furigana": "過度[かど]な競争[きょうそう]は、子[こ]どもの成長[せいちょう]を歪[ゆが]めてしまうことがある。", "sentence_source": "generated"}, {"text": "彼は自分に都合よく話を歪めるので、信用できない。", "target_word": "歪める", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]に都合[つごう]よく話[はなし]を歪[ゆが]めるので、信用[しんよう]できない。", "sentence_source": "generated"}, {"text": "記者は発言の意図を歪めずに、そのまま記事にした。", "target_word": "歪め", "complexity_tier": "T3", "furigana": "記者[きしゃ]は発言[はつげん]の意図[いと]を歪[ゆが]めずに、そのまま記事[きじ]にした。", "sentence_source": "generated"}, {"text": "数字を歪めた報告書が、後で問題になった。", "target_word": "歪めた", "complexity_tier": "T3", "furigana": "数字[すうじ]を歪[ゆが]めた報告書[ほうこくしょ]が、後[あと]で問題[もんだい]になった。", "sentence_source": "generated"}, {"text": "偏った情報は、物事の見方を歪めかねない。", "target_word": "歪め", "complexity_tier": "T4", "furigana": "偏[かたよ]った情報[じょうほう]は、物事[ものごと]の見方[みかた]を歪[ゆが]めかねない。", "sentence_source": "generated"}, {"text": "市場を歪める補助金は、見直すべきだという意見がある。", "target_word": "歪める", "complexity_tier": "T4", "furigana": "市場[しじょう]を歪[ゆが]める補助金[ほじょきん]は、見直[みなお]すべきだという意見[いけん]がある。", "sentence_source": "generated"}, {"text": "歴史を歪めて教えてはいけない。", "target_word": "歪めて", "complexity_tier": "T2", "furigana": "歴史[れきし]を歪[ゆが]めて教[おし]えてはいけない。", "sentence_source": "generated"}, {"text": "強い先入観が、私たちの判断を歪めることもある。", "target_word": "歪める", "complexity_tier": "T3", "furigana": "強[つよ]い先入観[せんにゅうかん]が、私[わたし]たちの判断[はんだん]を歪[ゆが]めることもある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "歪めない", "label": "否定形"}, {"form": "歪めます", "label": "丁寧形"}, {"form": "歪めて", "label": "て形"}, {"form": "歪めた", "label": "た形"}, {"form": "歪められる", "label": "受身形"}, {"form": "歪めれば", "label": "仮定形"}, {"form": "歪めよう", "label": "意志形"}], "register": "標準（書き言葉寄り）", "sense_fingerprint": "事実・意味・状態を本来と違う都合のよい方向へ変える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04359626-3ca1-4f32-9bac-ab26ac416c0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52768, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歪め", "is_correct": true, "explanation": "「歪め」は「歪める」の語幹で、「られ」と続けて受身になり、文の意味に合う。"}, {"text": "汚れ", "is_correct": false, "explanation": "「汚れる」は自動詞で受身にならないため、「汚れられ」は成り立たない。"}, {"text": "崩れ", "is_correct": false, "explanation": "「崩れる」は自動詞なので、「崩れられ」という受身の形は存在しない。"}, {"text": "途切れ", "is_correct": false, "explanation": "「途切れる」は自動詞で、「られ」の受身にはならないため文が成り立たない。"}], "explanations": {"歪め": "「歪め」は「歪める」の語幹で、「られ」と続けて受身になり、文の意味に合う。", "汚れ": "「汚れる」は自動詞で受身にならないため、「汚れられ」は成り立たない。", "崩れ": "「崩れる」は自動詞なので、「崩れられ」という受身の形は存在しない。", "途切れ": "「途切れる」は自動詞で、「られ」の受身にはならないため文が成り立たない。"}, "sentence_index": 0, "correct_answer": "歪め"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窓ガラスを歪めて、拭いた。", "explanation": "ここは〈拭く〉の意味。歪めるは形や内容を変える意味で、汚れを拭き取る意味はない。"}, {"text": "ジュースを歪めて、水で割った。", "explanation": "ここは〈薄める〉の意味。歪めるは形や内容を曲げる意味で、濃さを変える意味はない。"}, {"text": "鉛筆を歪めて、短くした。", "explanation": "ここは〈削る〉の意味。歪めるは曲げる意味で、長さを縮める意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52768, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歪め", "is_correct": true, "explanation": "「歪めかねない」で、物事の見方を歪めるおそれを表し、文に合う。"}, {"text": "噛み", "is_correct": false, "explanation": "「見方を噛みかねない」は意味が通らず、文の内容に合わない。"}, {"text": "洗い", "is_correct": false, "explanation": "「見方を洗いかねない」は意味が通らず、成り立たない。"}, {"text": "飲み", "is_correct": false, "explanation": "「見方を飲みかねない」は意味が通らず、文の内容に合わない。"}], "explanations": {"歪め": "「歪めかねない」で、物事の見方を歪めるおそれを表し、文に合う。", "噛み": "「見方を噛みかねない」は意味が通らず、文の内容に合わない。", "洗い": "「見方を洗いかねない」は意味が通らず、成り立たない。", "飲み": "「見方を飲みかねない」は意味が通らず、文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "歪め"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "牛乳を歪めて、温めた。", "explanation": "ここは〈温める〉の意味。歪めるは形や内容を曲げることで、温度を上げる意味はない。"}, {"text": "服を歪めて、洗った。", "explanation": "ここは〈洗う〉の意味。歪めるは曲げる・ねじる意味で、汚れを落とす意味はない。"}, {"text": "道路の凸凹を歪めて、平らにした。", "explanation": "ここは〈平らにする〉の意味。歪めるは形を正常でない方向へ変えることで、正しい形に戻す意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52768, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その記者は事実に歪めて報じた。", "corrected_sentence": "その記者は事実を歪めて報じた。", "error_description": "「歪める」は他動詞で、対象に「を」をつける。「事実に歪めて」は助詞の誤りで、正しくは「事実を歪めて」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "歪めて", "is_correct": true, "explanation": "て形で、後ろの「伝えた」へ続けて一文を作る。"}, {"text": "歪めない", "is_correct": false, "explanation": "否定形では「伝えた」へ続かず、文の形が崩れる。"}, {"text": "歪めた", "is_correct": false, "explanation": "た形では「伝えた」へ続けられず、文が成り立たない。"}, {"text": "歪めれば", "is_correct": false, "explanation": "仮定形は「伝えた」へ続かず、意味が通らない。"}], "correct_form": "歪めて", "base_form": "歪める", "form_label": "て形", "sentence_index": 1, "explanations": {"歪めて": "て形で、後ろの「伝えた」へ続けて一文を作る。", "歪めない": "否定形では「伝えた」へ続かず、文の形が崩れる。", "歪めた": "た形では「伝えた」へ続けられず、文が成り立たない。", "歪めれば": "仮定形は「伝えた」へ続かず、意味が通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52768, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は証言を歪めせず、正確に伝えた。", "corrected_sentence": "彼は証言を歪めず、正確に伝えた。", "error_description": "「歪める」の否定形は「歪めず」。「歪めせず」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "歪める", "is_correct": true, "explanation": "辞書形で「補助金」を修飾し、「市場を歪める補助金」の意味に合う。"}, {"text": "歪めて", "is_correct": false, "explanation": "て形では「補助金」を修飾できず、文が途中で止まる。"}, {"text": "歪めよう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、「補助金」の説明にならない。"}, {"text": "歪められ", "is_correct": false, "explanation": "受身の連用形は文を続けられず、「補助金」を修飾できない。"}], "correct_form": "歪める", "base_form": "歪める", "form_label": "辞書形", "sentence_index": 7, "explanations": {"歪める": "辞書形で「補助金」を修飾し、「市場を歪める補助金」の意味に合う。", "歪めて": "て形では「補助金」を修飾できず、文が途中で止まる。", "歪めよう": "意志形は名詞を修飾できず、「補助金」の説明にならない。", "歪められ": "受身の連用形は文を続けられず、「補助金」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52769, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「海岸に迫る」の到達点を示す。正しい。"}, {"text": "を", "is_correct": false, "explanation": "「海岸を迫る」と目的語にすると不自然。"}, {"text": "と", "is_correct": false, "explanation": "「海岸と迫る」となり、相手を取る形は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の格で、「海岸より迫る」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「海岸に迫る」の到達点を示す。正しい。", "を": "「海岸を迫る」と目的語にすると不自然。", "と": "「海岸と迫る」となり、相手を取る形は成り立たない。", "より": "比較の格で、「海岸より迫る」は意味が通らない。"}, "error_tags": {"を": "目的語", "と": "相手・引用", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52769, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52769, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かが近くに来る。", "primary_collocate": null, "pronunciation": "せまる", "ipa": "semaɾɯ", "syllable_count": 3, "sentences": [{"text": "後ろから大きな犬が迫ってきて、思わず走り出した。", "target_word": "迫って", "complexity_tier": "T3", "furigana": "後[うし]ろから大[おお]きな犬[いぬ]が迫[せま]ってきて、思[おも]わず走[はし]り出[だ]した。", "sentence_source": "generated"}, {"text": "津波が海岸に迫っているという知らせが入った。", "target_word": "迫って", "complexity_tier": "T4", "furigana": "津波[つなみ]が海岸[かいがん]に迫[せま]っているという知[し]らせが入[はい]った。", "sentence_source": "generated"}, {"text": "敵の軍が、城の近くまで迫ってきた。", "target_word": "迫って", "complexity_tier": "T3", "furigana": "敵[てき]の軍[ぐん]が、城[しろ]の近[ちか]くまで迫[せま]ってきた。", "sentence_source": "generated"}, {"text": "山が川のすぐそばまで迫っている場所を歩いた。", "target_word": "迫って", "complexity_tier": "T3", "furigana": "山[やま]が川[かわ]のすぐそばまで迫[せま]っている場所[ばしょ]を歩[ある]いた。", "sentence_source": "generated"}, {"text": "暗い雲が空いっぱいに迫り、雨が降り出した。", "target_word": "迫り", "complexity_tier": "T3", "furigana": "暗[くら]い雲[くも]が空[そら]いっぱいに迫[せま]り、雨[あめ]が降[ふ]り出[だ]した。", "sentence_source": "generated"}, {"text": "足音が背後に迫るのを感じて、振り返った。", "target_word": "迫る", "complexity_tier": "T4", "furigana": "足音[あしおと]が背後[はいご]に迫[せま]るのを感[かん]じて、振[ふ]り返[かえ]った。", "sentence_source": "generated"}, {"text": "崖が道の両側に迫る細い道を、慎重に進んだ。", "target_word": "迫る", "complexity_tier": "T4", "furigana": "崖[がけ]が道[みち]の両側[りょうがわ]に迫[せま]る細[ほそ]い道[みち]を、慎重[しんちょう]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "火が家のそばまで迫ったので、住民は避難した。", "target_word": "迫った", "complexity_tier": "T3", "furigana": "火[ひ]が家[いえ]のそばまで迫[せま]ったので、住民[じゅうみん]は避難[ひなん]した。", "sentence_source": "generated"}, {"text": "大きな波が岸に迫るのを、私たちは見ていた。", "target_word": "迫る", "complexity_tier": "T3", "furigana": "大[おお]きな波[なみ]が岸[きし]に迫[せま]るのを、私[わたし]たちは見[み]ていた。", "sentence_source": "generated"}, {"text": "車がすぐ後ろに迫ってきたので、道をゆずった。", "target_word": "迫って", "complexity_tier": "T2", "furigana": "車[くるま]がすぐ後[うし]ろに迫[せま]ってきたので、道[みち]をゆずった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "迫らない", "label": "否定形"}, {"form": "迫ります", "label": "丁寧形"}, {"form": "迫って", "label": "て形"}, {"form": "迫った", "label": "た形"}, {"form": "迫られる", "label": "受身形"}, {"form": "迫れば", "label": "仮定形"}, {"form": "迫ろう", "label": "意志形"}], "register": "標準", "sense_fingerprint": "人・物・自然が空間的にすぐ近くへ寄ってくる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04359626-3ca1-4f32-9bac-ab26ac416c0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52769, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迫って", "is_correct": true, "explanation": "て形。「大きな犬が迫ってきて」の空所に入り、近づく意味で正しい。"}, {"text": "迫る", "is_correct": false, "explanation": "終止形。「犬が迫るきて」となり不可。"}, {"text": "迫ら", "is_correct": false, "explanation": "未然形。「犬が迫らきて」となり不可。"}, {"text": "迫れ", "is_correct": false, "explanation": "命令・已然形。「犬が迫れきて」となり不可。"}], "explanations": {"迫って": "て形。「大きな犬が迫ってきて」の空所に入り、近づく意味で正しい。", "迫る": "終止形。「犬が迫るきて」となり不可。", "迫ら": "未然形。「犬が迫らきて」となり不可。", "迫れ": "命令・已然形。「犬が迫れきて」となり不可。"}, "sentence_index": 0, "correct_answer": "迫って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友人との約束から、もう一年が迫った。", "explanation": "ここは〈時間が経つ〉の意味。迫るは近くに来る語なので、過去から経った年月には使えない。〈経つ〉が正しい。"}, {"text": "その言葉が、胸に迫った。", "explanation": "ここは〈強く心を動かす〉の意味。近くに来る意味ではないので、〈心を打つ〉が正しい。"}, {"text": "夕飯のにおいが、家じゅうに迫った。", "explanation": "ここは〈広がる〉の意味。においが広がる場面では〈広がる〉を使い、迫るは近くに来る語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52769, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迫る", "is_correct": true, "explanation": "連体形。「崖が道の両側に迫る細い道」と名詞を修飾し、近づく意味で正しい。"}, {"text": "迫って", "is_correct": false, "explanation": "て形。「迫って細い道」と名詞を修飾できない。"}, {"text": "迫れば", "is_correct": false, "explanation": "仮定形。「迫れば細い道」と続かない。"}, {"text": "迫ろう", "is_correct": false, "explanation": "意志形。「迫ろう細い道」と続かない。"}], "explanations": {"迫る": "連体形。「崖が道の両側に迫る細い道」と名詞を修飾し、近づく意味で正しい。", "迫って": "て形。「迫って細い道」と名詞を修飾できない。", "迫れば": "仮定形。「迫れば細い道」と続かない。", "迫ろう": "意志形。「迫ろう細い道」と続かない。"}, "sentence_index": 6, "correct_answer": "迫る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ふと、名案が頭に迫った。", "explanation": "ここは〈思い浮かぶ〉の意味。迫るは近くに来る語で、考えが頭に現れる場面には合わない。〈浮かぶ〉が正しい。"}, {"text": "会長が、役員に辞任を迫った。", "explanation": "ここは〈強く要求する〉の意味。近くに来る意味ではないので、〈要求する〉が正しい。"}, {"text": "締め切りは昨日迫った。", "explanation": "ここは〈過去の時点に来た〉の意味で使われている。迫るは近くに来る語なので、過去の日付には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52769, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "足音をだんだん迫ってきて、怖くなった。", "corrected_sentence": "足音がだんだん迫ってきて、怖くなった。", "error_description": "迫ってくるのは「足音が」。「足音を」と目的語にすると誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "迫って", "is_correct": true, "explanation": "「迫っている」の形で、文中の形と一致する。"}, {"text": "迫り", "is_correct": false, "explanation": "連用形。「迫りいる」となり不可。"}, {"text": "迫る", "is_correct": false, "explanation": "終止・連体形。「迫るいる」となり不可。"}, {"text": "迫ら", "is_correct": false, "explanation": "未然形。「迫らいる」となり不可。"}], "correct_form": "迫って", "base_form": "迫る", "form_label": "て形・た形", "sentence_index": 1, "explanations": {"迫って": "「迫っている」の形で、文中の形と一致する。", "迫り": "連用形。「迫りいる」となり不可。", "迫る": "終止・連体形。「迫るいる」となり不可。", "迫ら": "未然形。「迫らいる」となり不可。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52769, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "車が両側の崖に迫り狭い峠道を、慎重に走った。", "corrected_sentence": "車が両側の崖に迫る狭い峠道を、慎重に走った。", "error_description": "名詞を修飾する連体形「迫る」が、連用形「迫り」になっている。「迫り狭い」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "迫った", "is_correct": true, "explanation": "た形。「火が家のそばまで迫った」の形で、文中の形と一致する。"}, {"text": "迫らない", "is_correct": false, "explanation": "否定形。「火が家のそばまで迫らないので」だと、火が近づかず避難もしないことになり、文の内容と矛盾する。"}, {"text": "迫れば", "is_correct": false, "explanation": "仮定形。「迫れば、ので」と続かず、実際に起きた出来事として「迫ったので」の理由を述べられない。"}, {"text": "迫ろう", "is_correct": false, "explanation": "意志形。「迫ろうので」と「ので」に続かず、火には意志がないので文として成り立たない。"}], "correct_form": "迫った", "base_form": "迫る", "form_label": "た形", "sentence_index": 7, "explanations": {"迫った": "た形。「火が家のそばまで迫った」の形で、文中の形と一致する。", "迫らない": "否定形。「火が家のそばまで迫らないので」だと、火が近づかず避難もしないことになり、文の内容と矛盾する。", "迫れば": "仮定形。「迫れば、ので」と続かず、実際に起きた出来事として「迫ったので」の理由を述べられない。", "迫ろう": "意志形。「迫ろうので」と「ので」に続かず、火には意志がないので文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52770, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「試験の日が迫る」の主語を示す。正しい。"}, {"text": "を", "is_correct": false, "explanation": "「日を迫る」と目的語にすると不自然。迫るは自動詞。"}, {"text": "で", "is_correct": false, "explanation": "「日で迫る」と手段・場所の格では意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「日と迫る」となり、相手を取る形は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「試験の日が迫る」の主語を示す。正しい。", "を": "「日を迫る」と目的語にすると不自然。迫るは自動詞。", "で": "「日で迫る」と手段・場所の格では意味が通らない。", "と": "「日と迫る」となり、相手を取る形は成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "相手・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52770, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「年末が迫る」の主語を示す。正しい。"}, {"text": "から", "is_correct": false, "explanation": "「年末から迫る」は起点の格で、主語の関係が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の格で、「年末より迫る」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の格で、「年末へ迫る」は主語関係を示せず不自然。"}], "correct_answer": "が", "explanations": {"が": "「年末が迫る」の主語を示す。正しい。", "から": "「年末から迫る」は起点の格で、主語の関係が成り立たない。", "より": "比較の格で、「年末より迫る」は意味が通らない。", "へ": "方向の格で、「年末へ迫る」は主語関係を示せず不自然。"}, "error_tags": {"から": "起点", "より": "比較", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52770, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある物事や状態が、すぐそこまで近づくこと。", "primary_collocate": null, "pronunciation": "せまる", "ipa": "semaɾɯ", "syllable_count": 3, "sentences": [{"text": "期限が迫らないうちに、申請書を出した。", "target_word": "迫ら", "complexity_tier": "T3", "furigana": "期限[きげん]が迫[せま]らないうちに、申請書[しんせいしょ]を出[だ]した。", "sentence_source": "generated"}, {"text": "試験の日が迫っているので、毎日勉強している。", "target_word": "迫っ", "complexity_tier": "T2", "furigana": "試験[しけん]の日[ひ]が迫[せま]っているので、毎日[まいにち]勉強[べんきょう]している。", "sentence_source": "generated"}, {"text": "締め切りが迫ると、いつも焦ってしまう。", "target_word": "迫る", "complexity_tier": "T3", "furigana": "締[し]め切[き]りが迫[せま]ると、いつも焦[あせ]ってしまう。", "sentence_source": "generated"}, {"text": "出発の時間が迫り、みんな急いで準備を始めた。", "target_word": "迫り", "complexity_tier": "T3", "furigana": "出発[しゅっぱつ]の時間[じかん]が迫[せま]り、みんな急[いそ]いで準備[じゅんび]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "選挙が迫る中、各党は政策を訴えている。", "target_word": "迫る", "complexity_tier": "T4", "furigana": "選挙[せんきょ]が迫[せま]る中[なか]、各党[かくとう]は政策[せいさく]を訴[うった]えている。", "sentence_source": "generated"}, {"text": "別れの時が迫っていると思うと、寂しくなった。", "target_word": "迫っ", "complexity_tier": "T3", "furigana": "別[わか]れの時[とき]が迫[せま]っていると思[おも]うと、寂[さび]しくなった。", "sentence_source": "generated"}, {"text": "期限が迫ってから、やっと宿題に取りかかった。", "target_word": "迫って", "complexity_tier": "T3", "furigana": "期限[きげん]が迫[せま]ってから、やっと宿題[しゅくだい]に取[と]りかかった。", "sentence_source": "generated"}, {"text": "年末が迫り、街はにぎやかになってきた。", "target_word": "迫り", "complexity_tier": "T3", "furigana": "年末[ねんまつ]が迫[せま]り、街[まち]はにぎやかになってきた。", "sentence_source": "generated"}, {"text": "危機が迫っていることに、誰も気づいていなかった。", "target_word": "迫っ", "complexity_tier": "T4", "furigana": "危機[きき]が迫[せま]っていることに、誰[だれ]も気[き]づいていなかった。", "sentence_source": "generated"}, {"text": "締め切りが迫らないと、やる気が出ない。", "target_word": "迫ら", "complexity_tier": "T3", "furigana": "締[し]め切[き]りが迫[せま]らないと、やる気[き]が出[で]ない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "迫らない", "label": "否定形"}, {"form": "迫ります", "label": "丁寧形"}, {"form": "迫って", "label": "て形"}, {"form": "迫った", "label": "た形"}, {"form": "迫られる", "label": "受身形"}, {"form": "迫れば", "label": "仮定形"}, {"form": "迫ろう", "label": "意志形"}], "register": "標準", "sense_fingerprint": "期限・時期・危機などがすぐ目前に近づく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04359626-3ca1-4f32-9bac-ab26ac416c0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52770, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迫ら", "is_correct": true, "explanation": "未然形。「期限が迫らないうちに」の空所に入り、否定の形として正しい。"}, {"text": "迫り", "is_correct": false, "explanation": "連用形。「迫りないうちに」となり不可。"}, {"text": "迫る", "is_correct": false, "explanation": "終止・連体形。「迫るないうちに」となり否定の形が作れないので不可。"}, {"text": "迫っ", "is_correct": false, "explanation": "て形の語幹。「迫っないうちに」となり不可。"}], "explanations": {"迫ら": "未然形。「期限が迫らないうちに」の空所に入り、否定の形として正しい。", "迫り": "連用形。「迫りないうちに」となり不可。", "迫る": "終止・連体形。「迫るないうちに」となり否定の形が作れないので不可。", "迫っ": "て形の語幹。「迫っないうちに」となり不可。"}, "sentence_index": 0, "correct_answer": "迫ら"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父が亡くなってから、もう十年が迫った。", "explanation": "ここは〈時間が経つ〉の意味。迫るは近づく語なので、過去から経った年月には使えない。〈経つ〉が正しい。"}, {"text": "締め切りは昨日迫った。", "explanation": "ここは〈過ぎ去る〉の意味。迫るは未来の時点へ近づく語なので、済んだ日付の締め切りには使えない。〈過ぎる〉が正しい。"}, {"text": "悔しさが、胸に迫ってきた。", "explanation": "ここは〈強く心を動かす〉の意味。時期が近づく意味ではないので、〈込み上げる〉が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52770, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迫って", "is_correct": true, "explanation": "て形。「期限が迫ってから」の空所に入り、〈〜してから〉の文脈で正しい。"}, {"text": "迫り", "is_correct": false, "explanation": "連用形。「迫りから」となり文が成立しない。"}, {"text": "迫ら", "is_correct": false, "explanation": "未然形。「迫らから」となり不可。"}, {"text": "迫れ", "is_correct": false, "explanation": "命令・已然形。「迫れから」となり不可。"}], "explanations": {"迫って": "て形。「期限が迫ってから」の空所に入り、〈〜してから〉の文脈で正しい。", "迫り": "連用形。「迫りから」となり文が成立しない。", "迫ら": "未然形。「迫らから」となり不可。", "迫れ": "命令・已然形。「迫れから」となり不可。"}, "sentence_index": 6, "correct_answer": "迫って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故から三年が迫った。", "explanation": "ここは〈時間が過ぎる〉の意味。迫るは近づくことなので、過去の三年には使えない。〈経つ〉が正しい。"}, {"text": "ふと、妙案が頭に迫った。", "explanation": "ここは〈思い浮かぶ〉の意味。迫るは近づいてくる意味で、考えが頭に現れる場面には合わない。〈浮かぶ〉が正しい。"}, {"text": "悲しみが、彼女の胸に迫った。", "explanation": "ここは〈強く心を動かす〉の意味。時期が近づく意味ではないので、〈込み上げる〉が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52770, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "連休を迫ったので、早めに切符を予約した。", "corrected_sentence": "連休が迫ったので、早めに切符を予約した。", "error_description": "「迫る」は自動詞で、主語「連休が」をとる。「連休を」と目的語にすると誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "迫っ", "is_correct": true, "explanation": "「迫っている」の語幹。文中の形と一致する。"}, {"text": "迫ら", "is_correct": false, "explanation": "未然形。「迫らっている」となり不可。"}, {"text": "迫り", "is_correct": false, "explanation": "連用形。「迫りっている」となり不可。"}, {"text": "迫れ", "is_correct": false, "explanation": "命令・已然形。「迫れっている」となり不可。"}], "correct_form": "迫っ", "base_form": "迫る", "form_label": "て形・た形の語幹（促音便）", "sentence_index": 1, "explanations": {"迫っ": "「迫っている」の語幹。文中の形と一致する。", "迫ら": "未然形。「迫らっている」となり不可。", "迫り": "連用形。「迫りっている」となり不可。", "迫れ": "命令・已然形。「迫れっている」となり不可。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52770, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "期限が迫りてきたので、急いで準備した。", "corrected_sentence": "期限が迫ってきたので、急いで準備した。", "error_description": "「迫る」のて形は「迫って」。「迫りて」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "迫り", "is_correct": true, "explanation": "連用形。「年末が迫り、」と中止の用法で文中の形と一致する。"}, {"text": "迫る", "is_correct": false, "explanation": "終止・連体形。「迫る、街は」と続けると文が不自然になる。"}, {"text": "迫っ", "is_correct": false, "explanation": "て形の語幹。「迫っ、街は」と続かない。"}, {"text": "迫ら", "is_correct": false, "explanation": "未然形。「迫ら、街は」と続かない。"}], "correct_form": "迫り", "base_form": "迫る", "form_label": "連用形", "sentence_index": 7, "explanations": {"迫り": "連用形。「年末が迫り、」と中止の用法で文中の形と一致する。", "迫る": "終止・連体形。「迫る、街は」と続けると文が不自然になる。", "迫っ": "て形の語幹。「迫っ、街は」と続かない。", "迫ら": "未然形。「迫ら、街は」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52771, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「告白を受け止める」の目的語を示す。正しい。"}, {"text": "が", "is_correct": false, "explanation": "「告白が受け止めて」は主語として成立しない。"}, {"text": "に", "is_correct": false, "explanation": "対象の「に」で、「告白に受け止めて」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の格で、「告白へ受け止めて」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「告白を受け止める」の目的語を示す。正しい。", "が": "「告白が受け止めて」は主語として成立しない。", "に": "対象の「に」で、「告白に受け止めて」は不自然。", "へ": "方向の格で、「告白へ受け止めて」は意味が通らない。"}, "error_tags": {"が": "主語", "に": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52771, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「メッセージを受け止める」の目的語を示す。正しい。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」で、「メッセージで受け止める」は目的語関係が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "相手・引用の「と」で、「メッセージと受け止める」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の格で、「メッセージより受け止める」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「メッセージを受け止める」の目的語を示す。正しい。", "で": "手段の「で」で、「メッセージで受け止める」は目的語関係が成り立たない。", "と": "相手・引用の「と」で、「メッセージと受け止める」は不自然。", "より": "比較の格で、「メッセージより受け止める」は意味が通らない。"}, "error_tags": {"で": "手段", "と": "相手・引用", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52771, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを受け取って、その意味を考えること。", "primary_collocate": null, "pronunciation": "うけとめる", "ipa": "ɯketomeɾɯ", "syllable_count": 5, "sentences": [{"text": "友人の言葉を、どういう意味か考えながら受け止めた。", "target_word": "受け止めた", "complexity_tier": "T3", "furigana": "友人[ゆうじん]の言葉[ことば]を、どういう意味[いみ]か考[かんが]えながら受[う]け止[と]めた。", "sentence_source": "generated"}, {"text": "彼女の告白を受け止めて、返事の言葉を探した。", "target_word": "受け止めて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の告白[こくはく]を受[う]け止[と]めて、返事[へんじ]の言葉[ことば]を探[さが]した。", "sentence_source": "generated"}, {"text": "先生の助言を、自分への励ましとして受け止めた。", "target_word": "受け止めた", "complexity_tier": "T3", "furigana": "先生[せんせい]の助言[じょげん]を、自分[じぶん]への励[はげ]ましとして受[う]け止[と]めた。", "sentence_source": "generated"}, {"text": "その冗談を、彼は本気の批判と受け止めてしまった。", "target_word": "受け止めて", "complexity_tier": "T3", "furigana": "その冗談[じょうだん]を、彼[かれ]は本気[ほんき]の批判[ひはん]と受[う]け止[と]めてしまった。", "sentence_source": "generated"}, {"text": "読者は物語を、それぞれ違うかたちで受け止める。", "target_word": "受け止める", "complexity_tier": "T3", "furigana": "読者[どくしゃ]は物語[ものがたり]を、それぞれ違[ちが]うかたちで受[う]け止[と]める。", "sentence_source": "generated"}, {"text": "母の短い一言を、私は深く受け止めた。", "target_word": "受け止めた", "complexity_tier": "T3", "furigana": "母[はは]の短[みじか]い一言[ひとこと]を、私[わたし]は深[ふか]く受[う]け止[と]めた。", "sentence_source": "generated"}, {"text": "彼の沈黙をどう受け止めればいいのか分からなかった。", "target_word": "受け止めれば", "complexity_tier": "T4", "furigana": "彼[かれ]の沈黙[ちんもく]をどう受[う]け止[と]めればいいのか分[わ]からなかった。", "sentence_source": "generated"}, {"text": "作品のメッセージを受け止めるには、時間が必要だ。", "target_word": "受け止める", "complexity_tier": "T4", "furigana": "作品[さくひん]のメッセージを受[う]け止[と]めるには、時間[じかん]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "贈り物にこめられた気持ちを受け止めて、心から礼を言った。", "target_word": "受け止めて", "complexity_tier": "T4", "furigana": "贈[おく]り物[もの]にこめられた気持[きも]ちを受[う]け止[と]めて、心[こころ]から礼[れい]を言[い]った。", "sentence_source": "generated"}, {"text": "相手の話を、いったん受け止めてから自分の意見を述べた。", "target_word": "受け止めて", "complexity_tier": "T4", "furigana": "相手[あいて]の話[はなし]を、いったん受[う]け止[と]めてから自分[じぶん]の意見[いけん]を述[の]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "受け止めない", "label": "否定形"}, {"form": "受け止めます", "label": "丁寧形"}, {"form": "受け止めて", "label": "て形"}, {"form": "受け止めた", "label": "た形"}, {"form": "受け止められる", "label": "可能形・受身形"}, {"form": "受け止めれば", "label": "仮定形"}, {"form": "受け止めよう", "label": "意志形"}], "register": "標準", "sense_fingerprint": "言葉・気持ち・作品を受け取りその意味を考える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04359626-3ca1-4f32-9bac-ab26ac416c0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52771, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受け止めた", "is_correct": true, "explanation": "た形。「考えながら受け止めた。」と文末に入り、文脈と一致する。"}, {"text": "受け止め", "is_correct": false, "explanation": "連用形。「考えながら受け止め。」と文末に立たない。"}, {"text": "受け止めれば", "is_correct": false, "explanation": "仮定形。「考えながら受け止めれば。」と文が完結しない。"}, {"text": "受け止められ", "is_correct": false, "explanation": "受身の連用形。「受け止められ。」と文が完結しない。"}], "explanations": {"受け止めた": "た形。「考えながら受け止めた。」と文末に入り、文脈と一致する。", "受け止め": "連用形。「考えながら受け止め。」と文末に立たない。", "受け止めれば": "仮定形。「考えながら受け止めれば。」と文が完結しない。", "受け止められ": "受身の連用形。「受け止められ。」と文が完結しない。"}, "sentence_index": 0, "correct_answer": "受け止めた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ボールを、グローブでしっかり受け止めた。", "explanation": "ここは〈物を受けて止める〉の意味。意味を理解する場面ではないので、〈捕る〉が正しい。"}, {"text": "申し込みを受け止めた。", "explanation": "ここは〈受理する〉の意味。申し込みは〈受け付ける〉を使う。"}, {"text": "先輩の服を、そのまま受け止めた。", "explanation": "ここは〈身につける〉の意味。服は〈着る〉を使い、受け止めるは意味を考える語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52771, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受け止めれば", "is_correct": true, "explanation": "仮定形。「どう受け止めればいい」と〈どうしたらよいか〉の意味で正しい。"}, {"text": "受け止める", "is_correct": false, "explanation": "終止・連体形。「どう受け止めるいい」となり不可。"}, {"text": "受け止めた", "is_correct": false, "explanation": "た形。「どう受け止めたいい」となり不可。"}, {"text": "受け止めよう", "is_correct": false, "explanation": "意志形。「どう受け止めようしい」となり不可。"}], "explanations": {"受け止めれば": "仮定形。「どう受け止めればいい」と〈どうしたらよいか〉の意味で正しい。", "受け止める": "終止・連体形。「どう受け止めるいい」となり不可。", "受け止めた": "た形。「どう受け止めたいい」となり不可。", "受け止めよう": "意志形。「どう受け止めようしい」となり不可。"}, "sentence_index": 6, "correct_answer": "受け止めれば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その料理を、あえて私が受け止めた。", "explanation": "ここは〈食べる〉の意味。料理は〈食べる〉を使い、〈受け止める〉は意味を理解する語なので合わない。"}, {"text": "客を笑顔で受け止めた。", "explanation": "ここは〈出迎える〉の意味。客を迎えるには〈迎える〉を使う。"}, {"text": "代金を受け止めた。", "explanation": "ここは〈受け取る〉の意味。代金は〈受け取る〉を使い、〈受け止める〉は意味を理解する語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52771, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の言葉に、その場で受け止めるのは難しい。", "corrected_sentence": "彼女の言葉を、その場で受け止めるのは難しい。", "error_description": "「受け止める」の対象は「言葉を」と目的語で示す。「言葉に」と格助詞を誤っている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "受け止めて", "is_correct": true, "explanation": "て形。「告白を受け止めて、返事の言葉を探した」の形で文中と一致する。"}, {"text": "受け止めれば", "is_correct": false, "explanation": "仮定形。「受け止めれば、返事」と続けると条件の文脈になり不自然。"}, {"text": "受け止めよう", "is_correct": false, "explanation": "意志形。「受け止めよう、返事」と続けると意味が変わる。"}, {"text": "受け止めない", "is_correct": false, "explanation": "否定形。「受け止めない、返事」は否定の意味になり文脈と合わない。"}], "correct_form": "受け止めて", "base_form": "受け止める", "form_label": "て形", "sentence_index": 1, "explanations": {"受け止めて": "て形。「告白を受け止めて、返事の言葉を探した」の形で文中と一致する。", "受け止めれば": "仮定形。「受け止めれば、返事」と続けると条件の文脈になり不自然。", "受け止めよう": "意志形。「受け止めよう、返事」と続けると意味が変わる。", "受け止めない": "否定形。「受け止めない、返事」は否定の意味になり文脈と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52771, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先輩の助言を素直に受け止めれ、すぐ実行した。", "corrected_sentence": "先輩の助言を素直に受け止め、すぐ実行した。", "error_description": "連用形「受け止め」に余分な「れ」が付いている。「受け止めれ」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "受け止める", "is_correct": true, "explanation": "終止・連体形。「受け止めるには」の形で文中と一致する。"}, {"text": "受け止めます", "is_correct": false, "explanation": "丁寧形。「受け止めますには」となり、「には」の前に辞書形が要る。"}, {"text": "受け止めた", "is_correct": false, "explanation": "た形。「受け止めたには」となり、目的を表す「〜するには」の形にならない。"}, {"text": "受け止め", "is_correct": false, "explanation": "連用形。「受け止めには」と「には」に続く形にならない。"}], "correct_form": "受け止める", "base_form": "受け止める", "form_label": "終止・連体形", "sentence_index": 7, "explanations": {"受け止める": "終止・連体形。「受け止めるには」の形で文中と一致する。", "受け止めます": "丁寧形。「受け止めますには」となり、「には」の前に辞書形が要る。", "受け止めた": "た形。「受け止めたには」となり、目的を表す「〜するには」の形にならない。", "受け止め": "連用形。「受け止めには」と「には」に続く形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52772, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "引用の「と」で、「だと受け止める」と目的語を導く。正しい。"}, {"text": "を", "is_correct": false, "explanation": "「だを受け止める」となり、目的語として成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「だに受け止める」となり、受け止める対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「だで受け止める」となり、手段の格として成立しない。"}], "correct_answer": "と", "explanations": {"と": "引用の「と」で、「だと受け止める」と目的語を導く。正しい。", "を": "「だを受け止める」となり、目的語として成立しない。", "に": "「だに受け止める」となり、受け止める対象を示せない。", "で": "「だで受け止める」となり、手段の格として成立しない。"}, "error_tags": {"を": "目的語", "に": "対象", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52772, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「結果を受け止める」の目的語を示す。正しい。"}, {"text": "が", "is_correct": false, "explanation": "「結果が受け止めた」は主語として成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の格で、「結果へ受け止めた」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の格で、「結果より受け止めた」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「結果を受け止める」の目的語を示す。正しい。", "が": "「結果が受け止めた」は主語として成立しない。", "へ": "方向の格で、「結果へ受け止めた」は不自然。", "より": "比較の格で、「結果より受け止めた」は意味が通らない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52772, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "（物事や状況を）自分のものとして理解し、それに対応すること。", "primary_collocate": null, "pronunciation": "うけとめる", "ipa": "ɯketomeɾɯ", "syllable_count": 5, "sentences": [{"text": "我々は、この不可逆的な変化の連鎖をどう受け止めるべきか、文明の存続をかけて抜本的な転換を迫られているのである。", "target_word": "受け止める", "complexity_tier": "T5", "furigana": "我々[われわれ]は、この不可逆的[ふかぎゃくてき]な変化[へんか]の連鎖[れんさ]をどう受[う]け止[と]めるべきか、文明[ぶんめい]の存続[そんぞく]をかけて抜本的[ばっぽんてき]な転換[てんかん]を迫[せま]られているのである。", "sentence_source": "mined"}, {"text": "厳しい意見も、成長のためだと受け止めるようにしている。", "target_word": "受け止める", "complexity_tier": "T3", "furigana": "厳[きび]しい意見[いけん]も、成長[せいちょう]のためだと受[う]け止[と]めるようにしている。", "sentence_source": "generated"}, {"text": "彼は失敗を真剣に受け止めて、原因を調べた。", "target_word": "受け止めて", "complexity_tier": "T3", "furigana": "彼[かれ]は失敗[しっぱい]を真剣[しんけん]に受[う]け止[と]めて、原因[げんいん]を調[しら]べた。", "sentence_source": "generated"}, {"text": "会社は、客の苦情を重く受け止め、対策を発表した。", "target_word": "受け止め", "complexity_tier": "T4", "furigana": "会社[かいしゃ]は、客[きゃく]の苦情[くじょう]を重[おも]く受[う]け止[と]め、対策[たいさく]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "突然の知らせを冷静に受け止めるのは難しい。", "target_word": "受け止める", "complexity_tier": "T3", "furigana": "突然[とつぜん]の知[し]らせを冷静[れいせい]に受[う]け止[と]めるのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "現実を受け止めなければ、前に進めない。", "target_word": "受け止め", "complexity_tier": "T3", "furigana": "現実[げんじつ]を受[う]け止[と]めなければ、前[まえ]に進[すす]めない。", "sentence_source": "generated"}, {"text": "先生は生徒の悩みをしっかり受け止めてくれた。", "target_word": "受け止めて", "complexity_tier": "T2", "furigana": "先生[せんせい]は生徒[せいと]の悩[なや]みをしっかり受[う]け止[と]めてくれた。", "sentence_source": "generated"}, {"text": "結果を受け止めた上で、次の計画を立てた。", "target_word": "受け止めた", "complexity_tier": "T3", "furigana": "結果[けっか]を受[う]け止[と]めた上[うえ]で、次[つぎ]の計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "批判を素直に受け止められる人は強い。", "target_word": "受け止め", "complexity_tier": "T4", "furigana": "批判[ひはん]を素直[すなお]に受[う]け止[と]められる人[ひと]は強[つよ]い。", "sentence_source": "generated"}, {"text": "市長は住民の不安を受け止め、説明会を開いた。", "target_word": "受け止め", "complexity_tier": "T4", "furigana": "市長[しちょう]は住民[じゅうみん]の不安[ふあん]を受[う]け止[と]め、説明会[せつめいかい]を開[ひら]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "受け止めない", "label": "否定形"}, {"form": "受け止めます", "label": "丁寧形"}, {"form": "受け止めて", "label": "て形"}, {"form": "受け止めた", "label": "た形"}, {"form": "受け止められる", "label": "可能形・受身形"}, {"form": "受け止めれば", "label": "仮定形"}, {"form": "受け止めよう", "label": "意志形"}], "register": "標準", "sense_fingerprint": "事態・意見・現実を自分の問題として理解し向き合う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04359626-3ca1-4f32-9bac-ab26ac416c0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52772, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受け止める", "is_correct": true, "explanation": "終止形。「どう受け止めるべきか」の空所に入り、文脈と一致する。"}, {"text": "受け止めた", "is_correct": false, "explanation": "た形。「どう受け止めたべきか」となり不可。"}, {"text": "受け止め", "is_correct": false, "explanation": "連用形。「どう受け止めべきか」となり不可。"}, {"text": "受け止めれば", "is_correct": false, "explanation": "仮定形。「どう受け止めればべきか」となり不可。"}], "explanations": {"受け止める": "終止形。「どう受け止めるべきか」の空所に入り、文脈と一致する。", "受け止めた": "た形。「どう受け止めたべきか」となり不可。", "受け止め": "連用形。「どう受け止めべきか」となり不可。", "受け止めれば": "仮定形。「どう受け止めればべきか」となり不可。"}, "sentence_index": 0, "correct_answer": "受け止める"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その商品の代金を、店が受け止めた。", "explanation": "ここは〈受け取る〉の意味。代金は〈受け取る〉を使い、〈受け止める〉は事態や意見を理解して対応する語なので合わない。"}, {"text": "電話を受け止めて、すぐ折り返した。", "explanation": "ここは〈受ける・応答する〉の意味。電話には〈受ける〉を使う。"}, {"text": "会社は、客の注文を受け止め、すぐ発送した。", "explanation": "ここは〈受け取る〉の意味。注文は〈受け取る〉を使い、〈受け止める〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52772, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受け止めて", "is_correct": true, "explanation": "て形。「しっかり受け止めてくれた」の空所に入り、補助動詞「くれる」と続く。"}, {"text": "受け止めない", "is_correct": false, "explanation": "否定形。「受け止めないくれた」となり、「くれた」に続く形にならない。"}, {"text": "受け止めよう", "is_correct": false, "explanation": "意志形。「受け止めようくれた」となり、「くれた」に続けられない。"}, {"text": "受け止められる", "is_correct": false, "explanation": "可能・受身の辞書形。て形がないと「受け止められるくれた」となり、「くれた」に続かない。"}], "explanations": {"受け止めて": "て形。「しっかり受け止めてくれた」の空所に入り、補助動詞「くれる」と続く。", "受け止めない": "否定形。「受け止めないくれた」となり、「くれた」に続く形にならない。", "受け止めよう": "意志形。「受け止めようくれた」となり、「くれた」に続けられない。", "受け止められる": "可能・受身の辞書形。て形がないと「受け止められるくれた」となり、「くれた」に続かない。"}, "sentence_index": 6, "correct_answer": "受け止めて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "給料の振り込みを受け止めた。", "explanation": "ここは〈受け取る〉の意味。振り込みは〈受け取る〉を使い、〈受け止める〉とは言わない。"}, {"text": "申し込みを受け止めた。", "explanation": "ここは〈受理する〉の意味。申し込みは〈受け付ける〉を使う。"}, {"text": "雪の結晶を、手袋の上で受け止めた。", "explanation": "ここは物理的に受けて止める意味。事態や意見を理解する意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52772, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "相手の言葉に素直に受け止めることが大切だ。", "corrected_sentence": "相手の言葉を素直に受け止めることが大切だ。", "error_description": "「受け止める」の対象は「言葉を」と目的語で示す。「言葉に」と格助詞を誤っている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "受け止める", "is_correct": true, "explanation": "終止・連体形。「受け止めるようにしている」の形で文中と一致する。"}, {"text": "受け止めれば", "is_correct": false, "explanation": "仮定形。「受け止めればようにしている」となり不可。"}, {"text": "受け止めよう", "is_correct": false, "explanation": "意志形。「受け止めようようにしている」となり不可。"}, {"text": "受け止めて", "is_correct": false, "explanation": "て形。「受け止めてようにしている」となり不可。"}], "correct_form": "受け止める", "base_form": "受け止める", "form_label": "終止・連体形", "sentence_index": 1, "explanations": {"受け止める": "終止・連体形。「受け止めるようにしている」の形で文中と一致する。", "受け止めれば": "仮定形。「受け止めればようにしている」となり不可。", "受け止めよう": "意志形。「受け止めようようにしている」となり不可。", "受け止めて": "て形。「受け止めてようにしている」となり不可。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52772, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は私の話をしっかり受け止めくれた。", "corrected_sentence": "彼女は私の話をしっかり受け止めてくれた。", "error_description": "「受け止めてくれた」のて形が抜けている。「受け止めくれた」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "受け止めた", "is_correct": true, "explanation": "た形。「結果を受け止めた上で」の形で文中と一致する。"}, {"text": "受け止め", "is_correct": false, "explanation": "連用形。「受け止め上で」と「上で」に続かず、文として成り立たない。"}, {"text": "受け止めます", "is_correct": false, "explanation": "丁寧形。「受け止めます上で」となり、「上で」に続けられない。"}, {"text": "受け止めない", "is_correct": false, "explanation": "否定形。「受け止めない上で」は「結果を受け止めた」の事実と合わず、文脈に合わない。"}], "correct_form": "受け止めた", "base_form": "受け止める", "form_label": "た形", "sentence_index": 7, "explanations": {"受け止めた": "た形。「結果を受け止めた上で」の形で文中と一致する。", "受け止め": "連用形。「受け止め上で」と「上で」に続かず、文として成り立たない。", "受け止めます": "丁寧形。「受け止めます上で」となり、「上で」に続けられない。", "受け止めない": "否定形。「受け止めない上で」は「結果を受け止めた」の事実と合わず、文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d96e95c-29a2-4588-8185-2393ad0c651c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
