INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52773, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "止まっていたものが動かないようにするためのもの。", "primary_collocate": null, "pronunciation": "はどめ", "ipa": "hadome", "syllable_count": 3, "sentences": [{"text": "歯止めを置く。", "target_word": "歯止め", "complexity_tier": "T1", "furigana": "歯止[はど]めを置[お]く。", "sentence_source": "generated"}, {"text": "歯止めが外れた。", "target_word": "歯止め", "complexity_tier": "T1", "furigana": "歯止[はど]めが外[はず]れた。", "sentence_source": "generated"}, {"text": "坂道では車に歯止めをします。", "target_word": "歯止め", "complexity_tier": "T2", "furigana": "坂道[さかみち]では車[くるま]に歯止[はど]めをします。", "sentence_source": "generated"}, {"text": "歯止めの石を後ろに置いた。", "target_word": "歯止め", "complexity_tier": "T2", "furigana": "歯止[はど]めの石[いし]を後[うし]ろに置[お]いた。", "sentence_source": "generated"}, {"text": "歯止めは車の下にあります。", "target_word": "歯止め", "complexity_tier": "T2", "furigana": "歯止[はど]めは車[くるま]の下[した]にあります。", "sentence_source": "generated"}, {"text": "駐車するとき、タイヤに歯止めを入れてください。", "target_word": "歯止め", "complexity_tier": "T3", "furigana": "駐車[ちゅうしゃ]するとき、タイヤに歯止[はど]めを入[い]れてください。", "sentence_source": "generated"}, {"text": "歯止めがないと、荷物が動いてしまう。", "target_word": "歯止め", "complexity_tier": "T3", "furigana": "歯止[はど]めがないと、荷物[にもつ]が動[うご]いてしまう。", "sentence_source": "generated"}, {"text": "工事の人が台車に歯止めをかけている。", "target_word": "歯止め", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]が台車[だいしゃ]に歯止[はど]めをかけている。", "sentence_source": "generated"}, {"text": "歯止めを外したとたん、車は坂をゆっくり下り始めた。", "target_word": "歯止め", "complexity_tier": "T4", "furigana": "歯止[はど]めを外[はず]したとたん、車[くるま]は坂[さか]をゆっくり下[くだ]り始[はじ]めた。", "sentence_source": "generated"}, {"text": "古い歯止めは壊れていたので、新しいものに替えた。", "target_word": "歯止め", "complexity_tier": "T4", "furigana": "古[ふる]い歯止[はど]めは壊[こわ]れていたので、新[あたら]しいものに替[か]えた。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 動かないよう止めるための物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b9edc6-97f7-4887-afa1-fce3d82da614') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52773, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "歯止め", "is_correct": true, "explanation": "「はどめ」で、聞いた語と同じ。"}, {"text": "初め", "is_correct": false, "explanation": "「はじめ」で、「ど」が「じ」に変わっている。"}, {"text": "傍目", "is_correct": false, "explanation": "「はため」で、「ど」が「た」に変わっている。"}, {"text": "波動", "is_correct": false, "explanation": "「はどう」で、「め」が「う」に変わっている。"}], "explanations": {"歯止め": "「はどめ」で、聞いた語と同じ。", "初め": "「はじめ」で、「ど」が「じ」に変わっている。", "傍目": "「はため」で、「ど」が「た」に変わっている。", "波動": "「はどう」で、「め」が「う」に変わっている。"}, "sentence_index": null, "correct_answer": "歯止め"}, "level_3": {"options": [{"text": "歯止め", "is_correct": true, "explanation": "動かないように置く物で、「置く」と意味が合う。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、「置く」対象にならず意味が合わない。"}, {"text": "勇気", "is_correct": false, "explanation": "形は合うが、物として置けず意味が合わない。"}, {"text": "返事", "is_correct": false, "explanation": "形は合うが、物として置くものではなく意味が合わない。"}], "explanations": {"歯止め": "動かないように置く物で、「置く」と意味が合う。", "季節": "形は合うが、「置く」対象にならず意味が合わない。", "勇気": "形は合うが、物として置けず意味が合わない。", "返事": "形は合うが、物として置くものではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "歯止め"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "歯止めを飲んで、風邪を治した。", "explanation": "歯止めは車などを止める物で、薬のように飲むものではない。"}, {"text": "彼は歯止めで空を飛んで学校へ行った。", "explanation": "歯止めは動かないように止める物で、飛ぶ道具ではない。"}, {"text": "歯止めに水を入れて、花にやった。", "explanation": "歯止めは止めるための物で、水を入れる容器ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
