INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52774, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「歯止めがかかる」の主語を示す「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「かかる」は自動詞なので「を」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「歯止めへかかった」は文として成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「歯止めとかかった」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「歯止めがかかる」の主語を示す「が」が正しい。", "を": "「かかる」は自動詞なので「を」は使えない。", "へ": "「歯止めへかかった」は文として成立しない。", "と": "「歯止めとかかった」は意味が通らない。"}, "error_tags": {"を": "transitive_confusion", "へ": "direction", "と": "with_or_quotation"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拍車", "is_correct": true, "explanation": "「拍車をかける」は進行を速めることで、「歯止め」と反対の働き。"}, {"text": "抑制", "is_correct": false, "explanation": "動きを抑えることで、「歯止め」に近い意味。"}, {"text": "防止", "is_correct": false, "explanation": "起こらないようにすることで、「歯止め」に近い意味。"}, {"text": "規制", "is_correct": false, "explanation": "決まりで制限することで、「歯止め」に近い意味。"}], "correct_answer": "拍車", "explanations": {"拍車": "「拍車をかける」は進行を速めることで、「歯止め」と反対の働き。", "抑制": "動きを抑えることで、「歯止め」に近い意味。", "防止": "起こらないようにすることで、「歯止め」に近い意味。", "規制": "決まりで制限することで、「歯止め」に近い意味。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
