INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52774, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の進行や動きを止めるための仕組みや手段。比喩的に、悪い傾向をくい止めることを指す。", "primary_collocate": "かける", "pronunciation": "はどめ", "ipa": "hadome", "syllable_count": 3, "sentences": [{"text": "近年、都市の無秩序な拡大に伴う緑の希薄化に歯止めをかけるべく、地域コミュニティガーデンプロジェクトが各地で顕在化している。", "target_word": "歯止め", "complexity_tier": "T6", "furigana": "近年[きんねん]、都市[とし]の無秩序[むちつじょ]な拡大[かくだい]に伴[ともな]う緑[みどり]の希薄化[きはくか]に歯止[はど]めをかけるべく、地域[ちいき]コミュニティガーデンプロジェクトが各地[かくち]で顕在化[けんざいか]している。", "sentence_source": "mined"}, {"text": "物価の上昇に歯止めがかかった。", "target_word": "歯止め", "complexity_tier": "T2", "furigana": "物価[ぶっか]の上昇[じょうしょう]に歯止[はど]めがかかった。", "sentence_source": "generated"}, {"text": "この法律が歯止めになります。", "target_word": "歯止め", "complexity_tier": "T2", "furigana": "この法律[ほうりつ]が歯止[はど]めになります。", "sentence_source": "generated"}, {"text": "人口の減少に歯止めをかけるのは難しい。", "target_word": "歯止め", "complexity_tier": "T3", "furigana": "人口[じんこう]の減少[げんしょう]に歯止[はど]めをかけるのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "値上げに歯止めがきかず、みんな困っている。", "target_word": "歯止め", "complexity_tier": "T3", "furigana": "値上[ねあ]げに歯止[はど]めがきかず、みんな困[こま]っている。", "sentence_source": "generated"}, {"text": "彼の怒りには歯止めがなかった。", "target_word": "歯止め", "complexity_tier": "T3", "furigana": "彼[かれ]の怒[いか]りには歯止[はど]めがなかった。", "sentence_source": "generated"}, {"text": "国は事故の増加に歯止めをかけるため、新しい規則を作った。", "target_word": "歯止め", "complexity_tier": "T4", "furigana": "国[くに]は事故[じこ]の増加[ぞうか]に歯止[はど]めをかけるため、新[あたら]しい規則[きそく]を作[つく]った。", "sentence_source": "generated"}, {"text": "歯止めのない開発が自然を壊してしまった。", "target_word": "歯止め", "complexity_tier": "T4", "furigana": "歯止[はど]めのない開発[かいはつ]が自然[しぜん]を壊[こわ]してしまった。", "sentence_source": "generated"}, {"text": "ルールがなければ、争いに歯止めがかからなくなる。", "target_word": "歯止め", "complexity_tier": "T4", "furigana": "ルールがなければ、争[あらそ]いに歯止[はど]めがかからなくなる。", "sentence_source": "generated"}, {"text": "若者の都市への流出に歯止めをかけない限り、地方の未来は明るくならないだろう。", "target_word": "歯止め", "complexity_tier": "T5", "furigana": "若者[わかもの]の都市[とし]への流出[りゅうしゅつ]に歯止[はど]めをかけない限[かぎ]り、地方[ちほう]の未来[みらい]は明[あか]るくならないだろう。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 悪い流れをくい止める手段", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b9edc6-97f7-4887-afa1-fce3d82da614') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52774, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "歯止め", "is_correct": true, "explanation": "「はどめ」で、聞いた語と同じ。"}, {"text": "初め", "is_correct": false, "explanation": "「はじめ」で、「ど」が「じ」に変わっている。"}, {"text": "傍目", "is_correct": false, "explanation": "「はため」で、「ど」が「た」に変わっている。"}, {"text": "波動", "is_correct": false, "explanation": "「はどう」で、「め」が「う」に変わっている。"}], "explanations": {"歯止め": "「はどめ」で、聞いた語と同じ。", "初め": "「はじめ」で、「ど」が「じ」に変わっている。", "傍目": "「はため」で、「ど」が「た」に変わっている。", "波動": "「はどう」で、「め」が「う」に変わっている。"}, "sentence_index": null, "correct_answer": "歯止め"}, "level_3": {"options": [{"text": "歯止め", "is_correct": true, "explanation": "「歯止めをかける」は悪い傾向をくい止める意味で合う。"}, {"text": "声", "is_correct": false, "explanation": "「声をかける」は成り立つが、希薄化をくい止める意味にならず合わない。"}, {"text": "迷惑", "is_correct": false, "explanation": "「迷惑をかける」は成り立つが、希薄化に対しては意味が合わない。"}, {"text": "眼鏡", "is_correct": false, "explanation": "「眼鏡をかける」は成り立つが、希薄化に対しては意味が合わない。"}], "explanations": {"歯止め": "「歯止めをかける」は悪い傾向をくい止める意味で合う。", "声": "「声をかける」は成り立つが、希薄化をくい止める意味にならず合わない。", "迷惑": "「迷惑をかける」は成り立つが、希薄化に対しては意味が合わない。", "眼鏡": "「眼鏡をかける」は成り立つが、希薄化に対しては意味が合わない。"}, "sentence_index": 0, "correct_answer": "歯止め"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎食後、歯止めで歯を丁寧にみがく。", "explanation": "歯止めは悪い流れをくい止める手段で、歯みがきの道具ではない。「歯」の字からの誤用。"}, {"text": "人口の減少に歯止めをもらうのは難しい。", "explanation": "歯止めは「かける」ものであり、「もらう」とは言わない。"}, {"text": "母は庭に歯止めを植えて水をやった。", "explanation": "歯止めは抽象的な手段で、植物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52774, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "歯止め", "is_correct": true, "explanation": "「はどめ」で、聞いた語と同じ。"}, {"text": "鳩目", "is_correct": false, "explanation": "「はとめ」で、「ど」が清音の「と」になっている。"}, {"text": "早め", "is_correct": false, "explanation": "「はやめ」で、「ど」が「や」に変わっている。"}, {"text": "とどめ", "is_correct": false, "explanation": "「とどめ」で、最初の「は」が「と」に変わっている。"}], "explanations": {"歯止め": "「はどめ」で、聞いた語と同じ。", "鳩目": "「はとめ」で、「ど」が清音の「と」になっている。", "早め": "「はやめ」で、「ど」が「や」に変わっている。", "とどめ": "「とどめ」で、最初の「は」が「と」に変わっている。"}, "sentence_index": null, "correct_answer": "歯止め"}, "level_3": {"options": [{"text": "歯止め", "is_correct": true, "explanation": "事故の増加をくい止める意味で、「歯止めをかける」が合う。"}, {"text": "鍵", "is_correct": false, "explanation": "「鍵をかける」は成り立つが、事故の増加には意味が合わない。"}, {"text": "電話", "is_correct": false, "explanation": "「電話をかける」は成り立つが、事故の増加には意味が合わない。"}, {"text": "保険", "is_correct": false, "explanation": "「保険をかける」は成り立つが、増加をくい止める意味にならない。"}], "explanations": {"歯止め": "事故の増加をくい止める意味で、「歯止めをかける」が合う。", "鍵": "「鍵をかける」は成り立つが、事故の増加には意味が合わない。", "電話": "「電話をかける」は成り立つが、事故の増加には意味が合わない。", "保険": "「保険をかける」は成り立つが、増加をくい止める意味にならない。"}, "sentence_index": 6, "correct_answer": "歯止め"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "歯止めを開けて、中のお菓子を食べた。", "explanation": "歯止めは抽象的な手段で、箱のように開けるものではない。"}, {"text": "若者の都市への流出に歯止めを読まない限り、地方の未来は暗い。", "explanation": "歯止めは「読む」ものではなく、「かける」と言う。"}, {"text": "私は歯止めの色が好きで、毎日着ている。", "explanation": "歯止めは抽象的な手段で、服のように着るものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
