INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52775, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ものの数が少なくて、うすいこと。", "primary_collocate": null, "pronunciation": "きはく", "ipa": "kihakɯ", "syllable_count": 3, "sentences": [{"text": "空気が希薄だ。", "target_word": "希薄", "complexity_tier": "T1", "furigana": "空気[くうき]が希薄[きはく]だ。", "sentence_source": "generated"}, {"text": "希薄な空気だ。", "target_word": "希薄", "complexity_tier": "T1", "furigana": "希薄[きはく]な空気[くうき]だ。", "sentence_source": "generated"}, {"text": "高い山は酸素が希薄です。", "target_word": "希薄", "complexity_tier": "T2", "furigana": "高[たか]い山[やま]は酸素[さんそ]が希薄[きはく]です。", "sentence_source": "generated"}, {"text": "この村は人口が希薄です。", "target_word": "希薄", "complexity_tier": "T2", "furigana": "この村[むら]は人口[じんこう]が希薄[きはく]です。", "sentence_source": "generated"}, {"text": "山を登るにつれて、空気が希薄になってきた。", "target_word": "希薄", "complexity_tier": "T3", "furigana": "山[やま]を登[のぼ]るにつれて、空気[くうき]が希薄[きはく]になってきた。", "sentence_source": "generated"}, {"text": "希薄な霧が山の上にかかっていた。", "target_word": "希薄", "complexity_tier": "T3", "furigana": "希薄[きはく]な霧[きり]が山[やま]の上[うえ]にかかっていた。", "sentence_source": "generated"}, {"text": "高い山の上ほど、空気は希薄だと言われる。", "target_word": "希薄", "complexity_tier": "T3", "furigana": "高[たか]い山[やま]の上[うえ]ほど、空気[くうき]は希薄[きはく]だと言[い]われる。", "sentence_source": "generated"}, {"text": "空気が希薄な場所では、長い時間運動することができない。", "target_word": "希薄", "complexity_tier": "T4", "furigana": "空気[くうき]が希薄[きはく]な場所[ばしょ]では、長[なが]い時間[じかん]運動[うんどう]することができない。", "sentence_source": "generated"}, {"text": "酸素が希薄だったので、頂上では何度も休んだ。", "target_word": "希薄", "complexity_tier": "T4", "furigana": "酸素[さんそ]が希薄[きはく]だったので、頂上[ちょうじょう]では何度[なんど]も休[やす]んだ。", "sentence_source": "generated"}, {"text": "人口が希薄な場所は、夜がとても静かだ。", "target_word": "希薄", "complexity_tier": "T3", "furigana": "人口[じんこう]が希薄[きはく]な場所[ばしょ]は、夜[よる]がとても静[しず]かだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "希薄だ", "label": "活用"}, {"form": "希薄な", "label": "活用"}, {"form": "希薄に", "label": "活用"}, {"form": "希薄化", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 数が少なく薄いこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b9edc6-97f7-4887-afa1-fce3d82da614') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52775, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "希薄", "is_correct": true, "explanation": "「きはく」で、見出し語そのもの。"}, {"text": "企画", "is_correct": false, "explanation": "「きかく」で、2拍目が違う。"}, {"text": "帰宅", "is_correct": false, "explanation": "「きたく」で、2拍目が違う。"}, {"text": "起爆", "is_correct": false, "explanation": "「きばく」で、2拍目が清濁だけ違う。"}, {"text": "気さく", "is_correct": false, "explanation": "「きさく」で、2拍目が違う。"}], "explanations": {"希薄": "「きはく」で、見出し語そのもの。", "企画": "「きかく」で、2拍目が違う。", "帰宅": "「きたく」で、2拍目が違う。", "起爆": "「きばく」で、2拍目が清濁だけ違う。", "気さく": "「きさく」で、2拍目が違う。"}, "sentence_index": null, "correct_answer": "希薄"}, "level_3": {"options": [{"text": "希薄", "is_correct": true, "explanation": "空気が薄いことを表し、文に合う。"}, {"text": "派手", "is_correct": false, "explanation": "形は合うが、空気の状態として意味が合わない。"}, {"text": "丁寧", "is_correct": false, "explanation": "形は合うが、空気について丁寧だとは言えず意味が合わない。"}, {"text": "正直", "is_correct": false, "explanation": "形は合うが、空気の性質として意味が合わない。"}], "explanations": {"希薄": "空気が薄いことを表し、文に合う。", "派手": "形は合うが、空気の状態として意味が合わない。", "丁寧": "形は合うが、空気について丁寧だとは言えず意味が合わない。", "正直": "形は合うが、空気の性質として意味が合わない。"}, "sentence_index": 0, "correct_answer": "希薄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "希薄な雪が降って、道が真っ白になった。", "explanation": "「希薄」は少なく薄いことなので、道が真っ白になるほどの雪とは矛盾する。"}, {"text": "彼は希薄な体で、重い荷物を軽々と運んだ。", "explanation": "「希薄」は人の体の強さを表さず、体が薄いという意味で力持ちとは合わない。"}, {"text": "このカレーは希薄な味で、とても辛い。", "explanation": "味が薄いという意味なので、とても辛いという内容と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52775, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "希薄", "is_correct": true, "explanation": "「きはく」で、見出し語そのもの。"}, {"text": "危篤", "is_correct": false, "explanation": "「きとく」で、2拍目が違う。"}, {"text": "気楽", "is_correct": false, "explanation": "「きらく」で、2拍目が違う。"}, {"text": "規範", "is_correct": false, "explanation": "「きはん」で、最後の拍が違う。"}], "explanations": {"希薄": "「きはく」で、見出し語そのもの。", "危篤": "「きとく」で、2拍目が違う。", "気楽": "「きらく」で、2拍目が違う。", "規範": "「きはん」で、最後の拍が違う。"}, "sentence_index": null, "correct_answer": "希薄"}, "level_3": {"options": [{"text": "希薄", "is_correct": true, "explanation": "高い所ほど空気が薄いという内容に合う。"}, {"text": "派手", "is_correct": false, "explanation": "形は合うが、空気の濃さとして意味が合わない。"}, {"text": "巧み", "is_correct": false, "explanation": "形は合うが、空気の性質として意味が合わない。"}, {"text": "素直", "is_correct": false, "explanation": "形は合うが、人の性格を表す語で空気には使えない。"}], "explanations": {"希薄": "高い所ほど空気が薄いという内容に合う。", "派手": "形は合うが、空気の濃さとして意味が合わない。", "巧み": "形は合うが、空気の性質として意味が合わない。", "素直": "形は合うが、人の性格を表す語で空気には使えない。"}, "sentence_index": 6, "correct_answer": "希薄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "高い山の上は空気が希薄なので、息がしやすい。", "explanation": "空気が薄いと息がしにくくなるので、「息がしやすい」と矛盾する。"}, {"text": "希薄な夕食を食べて、お腹いっぱいになった。", "explanation": "「希薄」は量が少ないことなので、お腹いっぱいという結果と矛盾する。"}, {"text": "都会の道は車が希薄で、渋滞がひどい。", "explanation": "車が少ないという意味なので、渋滞がひどいことと矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52775, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山を登るにつれて、酸素が希薄をなっていった。", "corrected_sentence": "山を登るにつれて、酸素が希薄になっていった。", "error_description": "変化を表すときは「希薄になる」で、「希薄をなる」は誤り。助詞は「に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "希薄", "is_correct": true, "explanation": "「な」の前は語幹の形になる。"}, {"text": "希薄な", "is_correct": false, "explanation": "「な」を重ねて「希薄なな」になってしまう。"}, {"text": "希薄に", "is_correct": false, "explanation": "「に」のあとに「な」は続かない。"}, {"text": "希薄だ", "is_correct": false, "explanation": "「だ」のあとに「な」は続かない。"}], "correct_form": "希薄", "base_form": "希薄", "form_label": "語幹（な接続）", "sentence_index": 1, "explanations": {"希薄": "「な」の前は語幹の形になる。", "希薄な": "「な」を重ねて「希薄なな」になってしまう。", "希薄に": "「に」のあとに「な」は続かない。", "希薄だ": "「だ」のあとに「な」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
