INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52776, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "人間関係・意識・意欲などの度合いが乏しく、薄いさま。", "primary_collocate": null, "pronunciation": "きはく", "ipa": "kihakɯ", "syllable_count": 3, "sentences": [{"text": "近年、都市の無秩序な拡大に伴う緑の希薄化に歯止めをかけるべく、地域コミュニティガーデンプロジェクトが各地で顕在化している。", "target_word": "希薄", "complexity_tier": "T6", "furigana": "近年[きんねん]、都市[とし]の無秩序[むちつじょ]な拡大[かくだい]に伴[ともな]う緑[みどり]の希薄化[きはくか]に歯止[はど]めをかけるべく、地域[ちいき]コミュニティガーデンプロジェクトが各地[かくち]で顕在化[けんざいか]している。", "sentence_source": "mined"}, {"text": "この町は近所づきあいが希薄です。", "target_word": "希薄", "complexity_tier": "T2", "furigana": "この町[まち]は近所[きんじょ]づきあいが希薄[きはく]です。", "sentence_source": "generated"}, {"text": "二人の関係は希薄だ。", "target_word": "希薄", "complexity_tier": "T2", "furigana": "二人[ふたり]の関係[かんけい]は希薄[きはく]だ。", "sentence_source": "generated"}, {"text": "都会では人と人のつながりが希薄になった。", "target_word": "希薄", "complexity_tier": "T3", "furigana": "都会[とかい]では人[ひと]と人[ひと]のつながりが希薄[きはく]になった。", "sentence_source": "generated"}, {"text": "希薄な人間関係の中で、彼は孤独を感じていた。", "target_word": "希薄", "complexity_tier": "T3", "furigana": "希薄[きはく]な人間関係[にんげんかんけい]の中[なか]で、彼[かれ]は孤独[こどく]を感[かん]じていた。", "sentence_source": "generated"}, {"text": "彼は責任感が希薄で、すぐ約束を忘れる。", "target_word": "希薄", "complexity_tier": "T3", "furigana": "彼[かれ]は責任感[せきにんかん]が希薄[きはく]で、すぐ約束[やくそく]を忘[わす]れる。", "sentence_source": "generated"}, {"text": "地域との関係が希薄だと、困ったときに助けてもらいにくい。", "target_word": "希薄", "complexity_tier": "T4", "furigana": "地域[ちいき]との関係[かんけい]が希薄[きはく]だと、困[こま]ったときに助[たす]けてもらいにくい。", "sentence_source": "generated"}, {"text": "危機感が希薄なせいで、対策がすっかり遅れてしまった。", "target_word": "希薄", "complexity_tier": "T4", "furigana": "危機感[ききかん]が希薄[きはく]なせいで、対策[たいさく]がすっかり遅[おく]れてしまった。", "sentence_source": "generated"}, {"text": "安全への意識が希薄な人は、事故を起こしやすい。", "target_word": "希薄", "complexity_tier": "T3", "furigana": "安全[あんぜん]への意識[いしき]が希薄[きはく]な人[ひと]は、事故[じこ]を起[お]こしやすい。", "sentence_source": "generated"}, {"text": "家族の会話が希薄になっている現代では、食事の時間を大切にすることが求められる。", "target_word": "希薄", "complexity_tier": "T5", "furigana": "家族[かぞく]の会話[かいわ]が希薄[きはく]になっている現代[げんだい]では、食事[しょくじ]の時間[じかん]を大切[たいせつ]にすることが求[もと]められる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "希薄だ", "label": "活用"}, {"form": "希薄な", "label": "活用"}, {"form": "希薄に", "label": "活用"}, {"form": "希薄化", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 関係・意識などが乏しく薄いさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b9edc6-97f7-4887-afa1-fce3d82da614') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52776, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "希薄", "is_correct": true, "explanation": "「きはく」で、見出し語そのもの。"}, {"text": "企画", "is_correct": false, "explanation": "「きかく」で、2拍目が違う。"}, {"text": "帰宅", "is_correct": false, "explanation": "「きたく」で、2拍目が違う。"}, {"text": "起爆", "is_correct": false, "explanation": "「きばく」で、2拍目が清濁だけ違う。"}, {"text": "気さく", "is_correct": false, "explanation": "「きさく」で、2拍目が違う。"}], "explanations": {"希薄": "「きはく」で、見出し語そのもの。", "企画": "「きかく」で、2拍目が違う。", "帰宅": "「きたく」で、2拍目が違う。", "起爆": "「きばく」で、2拍目が清濁だけ違う。", "気さく": "「きさく」で、2拍目が違う。"}, "sentence_index": null, "correct_answer": "希薄"}, "level_3": {"options": [{"text": "希薄", "is_correct": true, "explanation": "緑が減っていくことを表し、文脈に合う。"}, {"text": "活発", "is_correct": false, "explanation": "形は合うが、緑を守る文脈で歯止めをかける対象として意味が合わない。"}, {"text": "濃厚", "is_correct": false, "explanation": "形は合うが、緑の減少という文脈に意味が合わない。"}, {"text": "複雑", "is_correct": false, "explanation": "形は合うが、緑が減る話の流れに意味が合わない。"}], "explanations": {"希薄": "緑が減っていくことを表し、文脈に合う。", "活発": "形は合うが、緑を守る文脈で歯止めをかける対象として意味が合わない。", "濃厚": "形は合うが、緑の減少という文脈に意味が合わない。", "複雑": "形は合うが、緑が減る話の流れに意味が合わない。"}, "sentence_index": 0, "correct_answer": "希薄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は希薄な努力を重ねて、ついに優勝した。", "explanation": "「希薄」は数量や密度が低いさまで、努力を重ねて優勝するという意味と矛盾する。"}, {"text": "彼は責任感が希薄なので、どんな仕事も最後まで必ずやりとげる。", "explanation": "責任感が乏しいという意味なので、必ずやりとげるという内容と矛盾する。"}, {"text": "希薄な財布の中に、お金がたくさん入っている。", "explanation": "「希薄」は少ない・薄いさまなので、お金がたくさんあるという内容と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52776, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "希薄", "is_correct": true, "explanation": "「きはく」で、見出し語そのもの。"}, {"text": "危篤", "is_correct": false, "explanation": "「きとく」で、2拍目が違う。"}, {"text": "気楽", "is_correct": false, "explanation": "「きらく」で、2拍目が違う。"}, {"text": "規範", "is_correct": false, "explanation": "「きはん」で、最後の拍が違う。"}], "explanations": {"希薄": "「きはく」で、見出し語そのもの。", "危篤": "「きとく」で、2拍目が違う。", "気楽": "「きらく」で、2拍目が違う。", "規範": "「きはん」で、最後の拍が違う。"}, "sentence_index": null, "correct_answer": "希薄"}, "level_3": {"options": [{"text": "希薄", "is_correct": true, "explanation": "関係が薄いと助けてもらいにくいという流れに合う。"}, {"text": "派手", "is_correct": false, "explanation": "形は合うが、関係が派手だと助けにくいという意味にならない。"}, {"text": "巧み", "is_correct": false, "explanation": "形は合うが、関係が巧みだと助けにくいという意味が合わない。"}, {"text": "正直", "is_correct": false, "explanation": "形は合うが、関係が正直だと助けにくいという意味が合わない。"}], "explanations": {"希薄": "関係が薄いと助けてもらいにくいという流れに合う。", "派手": "形は合うが、関係が派手だと助けにくいという意味にならない。", "巧み": "形は合うが、関係が巧みだと助けにくいという意味が合わない。", "正直": "形は合うが、関係が正直だと助けにくいという意味が合わない。"}, "sentence_index": 6, "correct_answer": "希薄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "希薄な会議が長引いて、全員が疲れた。", "explanation": "「希薄」は数量や密度が低いさまで、会議の長さや様子を表すのには使えない。"}, {"text": "赤ちゃんは希薄な声で、元気よく泣いている。", "explanation": "「希薄」は声の大きさや調子を表さず、元気に泣くという内容とも合わない。"}, {"text": "二人は関係が希薄なので、毎日何時間も電話で話している。", "explanation": "関係が薄いという意味なので、毎日長く話すほど親しいことと矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52776, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人間関係が希薄の社会になってきた。", "corrected_sentence": "人間関係が希薄な社会になってきた。", "error_description": "形状詞「希薄」が名詞を修飾するときは「希薄の」ではなく「希薄な」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "希薄", "is_correct": true, "explanation": "「です」の前は語幹の形になる。"}, {"text": "希薄な", "is_correct": false, "explanation": "「な」は名詞を修飾する形で、「です」に続かない。"}, {"text": "希薄に", "is_correct": false, "explanation": "「に」は連用形で、「です」に続かない。"}, {"text": "希薄だ", "is_correct": false, "explanation": "「だ」と「です」を重ねることはできない。"}], "correct_form": "希薄", "base_form": "希薄", "form_label": "語幹（です接続）", "sentence_index": 1, "explanations": {"希薄": "「です」の前は語幹の形になる。", "希薄な": "「な」は名詞を修飾する形で、「です」に続かない。", "希薄に": "「に」は連用形で、「です」に続かない。", "希薄だ": "「だ」と「です」を重ねることはできない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52776, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家族のつながりが希薄くなっている。", "corrected_sentence": "家族のつながりが希薄になっている。", "error_description": "形状詞「希薄」は「〜くなる」ではなく「〜になる」と変化する。形容詞の活用との混同。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "希薄", "is_correct": true, "explanation": "「な」の前は語幹の形になる。"}, {"text": "希薄な", "is_correct": false, "explanation": "「な」を重ねて「希薄なな」になってしまう。"}, {"text": "希薄に", "is_correct": false, "explanation": "「に」のあとに「な」は続かない。"}, {"text": "希薄だ", "is_correct": false, "explanation": "「だ」のあとに「な」は続かない。"}], "correct_form": "希薄", "base_form": "希薄", "form_label": "語幹（な接続）", "sentence_index": 7, "explanations": {"希薄": "「な」の前は語幹の形になる。", "希薄な": "「な」を重ねて「希薄なな」になってしまう。", "希薄に": "「に」のあとに「な」は続かない。", "希薄だ": "「だ」のあとに「な」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52777, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在する場所を表し、「前にガーデンがあります」となる。"}, {"text": "を", "is_correct": false, "explanation": "「家の前をガーデンがあります」は文法的に成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "ものが存在する場所に「で」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「前へガーデンがあります」は文法的に成り立たない。"}], "correct_answer": "に", "explanations": {"に": "存在する場所を表し、「前にガーデンがあります」となる。", "を": "「家の前をガーデンがあります」は文法的に成り立たない。", "で": "ものが存在する場所に「で」は使えない。", "へ": "「前へガーデンがあります」は文法的に成り立たない。"}, "error_tags": {"を": "object marker", "で": "action location", "へ": "direction"}, "sentence_index": 2}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52777, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ガーデンの木」と所属を表す。"}, {"text": "を", "is_correct": false, "explanation": "「ガーデンを木の下で本を読んだ」は目的語が重なり文法的に成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「ガーデンに木の下で」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「ガーデンへ木の下で」は文法的に成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「ガーデンの木」と所属を表す。", "を": "「ガーデンを木の下で本を読んだ」は目的語が重なり文法的に成り立たない。", "に": "「ガーデンに木の下で」は文法的に成り立たない。", "へ": "「ガーデンへ木の下で」は文法的に成り立たない。"}, "error_tags": {"を": "object marker", "に": "location", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52777, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "花や木を育てる場所です。", "primary_collocate": null, "pronunciation": "がーでん", "ipa": "ɡaːdeɴ", "syllable_count": 4, "sentences": [{"text": "ガーデンに行く。", "target_word": "ガーデン", "complexity_tier": "T1", "furigana": "ガーデンに行[い]く。", "sentence_source": "generated"}, {"text": "ガーデンがある。", "target_word": "ガーデン", "complexity_tier": "T1", "furigana": "ガーデンがある。", "sentence_source": "generated"}, {"text": "家の前にガーデンがあります。", "target_word": "ガーデン", "complexity_tier": "T2", "furigana": "家[いえ]の前[まえ]にガーデンがあります。", "sentence_source": "generated"}, {"text": "ガーデンで花を見ました。", "target_word": "ガーデン", "complexity_tier": "T2", "furigana": "ガーデンで花[はな]を見[み]ました。", "sentence_source": "generated"}, {"text": "私のガーデンはとても小さいです。", "target_word": "ガーデン", "complexity_tier": "T2", "furigana": "私[わたし]のガーデンはとても小[ちい]さいです。", "sentence_source": "generated"}, {"text": "母は毎日ガーデンに水をやっている。", "target_word": "ガーデン", "complexity_tier": "T3", "furigana": "母[はは]は毎日[まいにち]ガーデンに水[みず]をやっている。", "sentence_source": "generated"}, {"text": "春になると、ガーデンにきれいな花が咲く。", "target_word": "ガーデン", "complexity_tier": "T3", "furigana": "春[はる]になると、ガーデンにきれいな花[はな]が咲[さ]く。", "sentence_source": "generated"}, {"text": "ガーデンの木の下で本を読んだ。", "target_word": "ガーデン", "complexity_tier": "T3", "furigana": "ガーデンの木[き]の下[した]で本[ほん]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "ガーデンを広くするために、大きな石を全部どかした。", "target_word": "ガーデン", "complexity_tier": "T4", "furigana": "ガーデンを広[ひろ]くするために、大[おお]きな石[いし]を全部[ぜんぶ]どかした。", "sentence_source": "generated"}, {"text": "このガーデンでは、季節ごとにちがう花を楽しむことができる。", "target_word": "ガーデン", "complexity_tier": "T4", "furigana": "このガーデンでは、季節[きせつ]ごとにちがう花[はな]を楽[たの]しむことができる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ガーデニング", "label": "派生"}, {"form": "ガーデナー", "label": "派生"}, {"form": "コミュニティガーデン", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 花や木を育てる場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b9edc6-97f7-4887-afa1-fce3d82da614') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52777, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ガーデン", "is_correct": true, "explanation": "行く場所として自然で、意味が合う。"}, {"text": "去年", "is_correct": false, "explanation": "形は合うが、「去年に行く」では場所にならず意味が合わない。"}, {"text": "空腹", "is_correct": false, "explanation": "形は合うが、空腹は行く先にならず意味が合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "形は合うが、鉛筆は行く場所ではなく意味が合わない。"}], "explanations": {"ガーデン": "行く場所として自然で、意味が合う。", "去年": "形は合うが、「去年に行く」では場所にならず意味が合わない。", "空腹": "形は合うが、空腹は行く先にならず意味が合わない。", "鉛筆": "形は合うが、鉛筆は行く場所ではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "ガーデン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ガーデンでお金をおろして、ご飯を食べた。", "explanation": "ガーデンは花や木を育てる場所で、お金をおろす銀行ではない。"}, {"text": "ガーデンを冷蔵庫に入れて冷やした。", "explanation": "ガーデンは花や木を育てる場所で、冷蔵庫に入れられる物ではない。"}, {"text": "ガーデンに乗って、駅まで行った。", "explanation": "ガーデンは場所であり、乗り物ではないので「乗る」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52777, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ガーデン", "is_correct": true, "explanation": "花が咲く場所として自然で、意味が合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "形は合うが、冷蔵庫にきれいな花が咲くという意味が合わない。"}, {"text": "電車", "is_correct": false, "explanation": "形は合うが、電車に花が咲くという意味が合わない。"}, {"text": "財布", "is_correct": false, "explanation": "形は合うが、財布に花が咲くという意味が合わない。"}], "explanations": {"ガーデン": "花が咲く場所として自然で、意味が合う。", "冷蔵庫": "形は合うが、冷蔵庫にきれいな花が咲くという意味が合わない。", "電車": "形は合うが、電車に花が咲くという意味が合わない。", "財布": "形は合うが、財布に花が咲くという意味が合わない。"}, "sentence_index": 6, "correct_answer": "ガーデン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母はガーデンを洗濯機に入れて洗っている。", "explanation": "ガーデンは庭や花壇で、洗濯機に入れられるものではない。"}, {"text": "ガーデンに切手をはって、手紙を出した。", "explanation": "ガーデンは花や木を育てる場所で、切手をはる封筒ではない。"}, {"text": "寒いので、ガーデンをかぶって出かけた。", "explanation": "ガーデンは場所であり、頭にかぶる帽子ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52777, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ガーデンに花を見ました。", "corrected_sentence": "ガーデンで花を見ました。", "error_description": "見るという動作が行われる場所なので、「に」ではなく「で」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
