INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52778, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "ガーデンを主題として示し、文が成り立つ。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、主題の位置には入らない。"}, {"text": "を", "is_correct": false, "explanation": "「与えている」はすでに「影響を」を取っているので、「ガーデンを」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、比べる対象がなく文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "ガーデンを主題として示し、文が成り立つ。", "へ": "方向を表す助詞で、主題の位置には入らない。", "を": "「与えている」はすでに「影響を」を取っているので、「ガーデンを」は成り立たない。", "より": "比較の助詞で、比べる対象がなく文が成り立たない。"}, "error_tags": {"へ": "direction", "を": "object marker", "より": "comparison"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
