INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52778, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物を育てるための庭や花壇。特に、西洋風の庭園や地域の共同緑地を指すことが多い。", "primary_collocate": null, "pronunciation": "がーでん", "ipa": "ɡaːdeɴ", "syllable_count": 4, "sentences": [{"text": "都市の緑を増やすため、住民が共同のガーデンを作るプロジェクトが各地で広がっている。", "target_word": "ガーデン", "complexity_tier": "T5", "furigana": "都市[とし]の緑[みどり]を増[ふ]やすため、住民[じゅうみん]が共同[きょうどう]のガーデンを作[つく]るプロジェクトが各地[かくち]で広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "住民が参加して作ったガーデンは、生き物を増やすだけでなく、近所の緑にもよい影響を与えている。", "target_word": "ガーデン", "complexity_tier": "T5", "furigana": "住民[じゅうみん]が参加[さんか]して作[つく]ったガーデンは、生[い]き物[もの]を増[ふ]やすだけでなく、近所[きんじょ]の緑[みどり]にもよい影響[えいきょう]を与[あた]えている。", "sentence_source": "generated"}, {"text": "ガーデンで花を見る。", "target_word": "ガーデン", "complexity_tier": "T1", "furigana": "ガーデンで花[はな]を見[み]る。", "sentence_source": "generated"}, {"text": "駅の近くに小さなガーデンがあります。", "target_word": "ガーデン", "complexity_tier": "T2", "furigana": "駅[えき]の近[ちか]くに小[ちい]さなガーデンがあります。", "sentence_source": "generated"}, {"text": "ガーデンは町の人が世話をしています。", "target_word": "ガーデン", "complexity_tier": "T2", "furigana": "ガーデンは町[まち]の人[ひと]が世話[せわ]をしています。", "sentence_source": "generated"}, {"text": "友だちと一緒にガーデンで野菜を育てている。", "target_word": "ガーデン", "complexity_tier": "T3", "furigana": "友[とも]だちと一緒[いっしょ]にガーデンで野菜[やさい]を育[そだ]てている。", "sentence_source": "generated"}, {"text": "この地域のガーデンは、だれでも使うことができる。", "target_word": "ガーデン", "complexity_tier": "T3", "furigana": "この地域[ちいき]のガーデンは、だれでも使[つか]うことができる。", "sentence_source": "generated"}, {"text": "住民が作ったガーデンのおかげで、町に花が増えた。", "target_word": "ガーデン", "complexity_tier": "T4", "furigana": "住民[じゅうみん]が作[つく]ったガーデンのおかげで、町[まち]に花[はな]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "イギリスのガーデンを見に行くために、旅行の計画を立てた。", "target_word": "ガーデン", "complexity_tier": "T4", "furigana": "イギリスのガーデンを見[み]に行[い]くために、旅行[りょこう]の計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "共同のガーデンは、近所の人が顔を合わせる場所としても役に立っている。", "target_word": "ガーデン", "complexity_tier": "T5", "furigana": "共同[きょうどう]のガーデンは、近所[きんじょ]の人[ひと]が顔[かお]を合[あ]わせる場所[ばしょ]としても役[やく]に立[た]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ガーデニング", "label": "派生"}, {"form": "ガーデナー", "label": "派生"}, {"form": "コミュニティガーデン", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 植物を育てる庭や共同緑地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b9edc6-97f7-4887-afa1-fce3d82da614') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52778, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ガーデン", "is_correct": true, "explanation": "緑を増やす地域の共同緑地という文脈に合う。"}, {"text": "ミサイル", "is_correct": false, "explanation": "形は合うが、緑を守る取り組みとして意味が合わない。"}, {"text": "エレベーター", "is_correct": false, "explanation": "形は合うが、緑を増やすために住民が作るものとして意味が合わない。"}, {"text": "ガソリン", "is_correct": false, "explanation": "形は合うが、緑を増やすプロジェクトとして意味が合わない。"}], "explanations": {"ガーデン": "緑を増やす地域の共同緑地という文脈に合う。", "ミサイル": "形は合うが、緑を守る取り組みとして意味が合わない。", "エレベーター": "形は合うが、緑を増やすために住民が作るものとして意味が合わない。", "ガソリン": "形は合うが、緑を増やすプロジェクトとして意味が合わない。"}, "sentence_index": 0, "correct_answer": "ガーデン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝ガーデンで電車に乗って会社へ行く。", "explanation": "ガーデンは植物を育てる庭で、電車に乗る場所ではない。"}, {"text": "ガーデンを冷蔵庫に入れて冷やした。", "explanation": "ガーデンは植物を育てる場所で、冷蔵庫に入れられる物ではない。"}, {"text": "寒い日はガーデンを着て学校へ行く。", "explanation": "ガーデンは庭や花壇で、着る服ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52778, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ガーデン", "is_correct": true, "explanation": "地域のだれでも使える共同の庭という意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気は使うものではなく意味が合わない。"}, {"text": "歴史", "is_correct": false, "explanation": "形は合うが、歴史は使うことができるものではなく意味が合わない。"}, {"text": "気温", "is_correct": false, "explanation": "形は合うが、気温を使うという意味にならない。"}], "explanations": {"ガーデン": "地域のだれでも使える共同の庭という意味に合う。", "天気": "形は合うが、天気は使うものではなく意味が合わない。", "歴史": "形は合うが、歴史は使うことができるものではなく意味が合わない。", "気温": "形は合うが、気温を使うという意味にならない。"}, "sentence_index": 6, "correct_answer": "ガーデン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ガーデンで薬を出してもらい、医者に診てもらった。", "explanation": "ガーデンは庭で、診察や薬をもらう場所の病院を指さない。"}, {"text": "ガーデンに乗って、パリへ飛んだ。", "explanation": "ガーデンは植物を育てる場所で、乗り物ではない。"}, {"text": "雨の日は、ガーデンで泳ぐ授業がある。", "explanation": "ガーデンは庭や花壇で、泳ぐ場所のプールではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52778, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちと一緒にガーデンを野菜を育てている。", "corrected_sentence": "友だちと一緒にガーデンで野菜を育てている。", "error_description": "「野菜を」がすでに目的語なので、動作の場所のガーデンには「を」ではなく「で」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52778, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "住民がガーデンが作ったおかげで、町に花が増えた。", "corrected_sentence": "住民がガーデンを作ったおかげで、町に花が増えた。", "error_description": "「作る」の対象であるガーデンには「を」を使う。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52779, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「時間をかける」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「時間がかけて」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞なので「時間へかけて」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「時間とかけて」は文法的に成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「時間をかける」の目的語を示す。", "が": "「時間がかけて」は文法的に成り立たない。", "へ": "方向の助詞なので「時間へかけて」は成り立たない。", "と": "「時間とかけて」は文法的に成り立たない。"}, "error_tags": {"が": "subject_marker", "へ": "direction", "と": "comitative"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "破壊", "is_correct": true, "explanation": "つくり上げることの反対で、こわすこと。"}, {"text": "形成", "is_correct": false, "explanation": "醸成と近い意味で、反対ではない。"}, {"text": "育成", "is_correct": false, "explanation": "少しずつ育てることで、近い意味。"}, {"text": "構築", "is_correct": false, "explanation": "つくり上げることで、反対ではない。"}], "correct_answer": "破壊", "explanations": {"破壊": "つくり上げることの反対で、こわすこと。", "形成": "醸成と近い意味で、反対ではない。", "育成": "少しずつ育てることで、近い意味。", "構築": "つくり上げることで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52779, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "空気は醸成するの目的語なので「を」。"}, {"text": "が", "is_correct": false, "explanation": "主語は先生なので「空気が醸成してくれた」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞で、ここでは成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「空気と醸成して」は文法的に成り立たない。"}], "correct_answer": "を", "explanations": {"を": "空気は醸成するの目的語なので「を」。", "が": "主語は先生なので「空気が醸成してくれた」は成り立たない。", "へ": "方向の助詞で、ここでは成り立たない。", "と": "「空気と醸成して」は文法的に成り立たない。"}, "error_tags": {"が": "subject_marker", "へ": "direction", "と": "comitative"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "崩壊", "is_correct": true, "explanation": "積み上げたものが崩れることで、つくり上げるの反対。"}, {"text": "創出", "is_correct": false, "explanation": "新しく生み出すことで、近い意味。"}, {"text": "構築", "is_correct": false, "explanation": "つくり上げることで、反対ではない。"}, {"text": "熟成", "is_correct": false, "explanation": "時間をかけて整うことで、反対ではない。"}], "correct_answer": "崩壊", "explanations": {"崩壊": "積み上げたものが崩れることで、つくり上げるの反対。", "創出": "新しく生み出すことで、近い意味。", "構築": "つくり上げることで、反対ではない。", "熟成": "時間をかけて整うことで、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52779, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを少しずつ作り上げていくこと。", "primary_collocate": null, "pronunciation": "じょうせい", "ipa": "dʑoːseː", "syllable_count": 4, "sentences": [{"text": "信頼を醸成する。", "target_word": "醸成する", "complexity_tier": "T1", "furigana": "信頼[しんらい]を醸成[じょうせい]する。", "sentence_source": "generated"}, {"text": "仲間意識の醸成が大切だ。", "target_word": "醸成", "complexity_tier": "T2", "furigana": "仲間[なかま]意識[いしき]の醸成[じょうせい]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "友情は時間をかけて醸成されます。", "target_word": "醸成されます", "complexity_tier": "T2", "furigana": "友情[ゆうじょう]は時間[じかん]をかけて醸成[じょうせい]されます。", "sentence_source": "generated"}, {"text": "良い習慣は少しずつ醸成される。", "target_word": "醸成される", "complexity_tier": "T2", "furigana": "良[よ]い習慣[しゅうかん]は少[すこ]しずつ醸成[じょうせい]される。", "sentence_source": "generated"}, {"text": "クラスの仲間意識を醸成したい。", "target_word": "醸成したい", "complexity_tier": "T3", "furigana": "クラスの仲間[なかま]意識[いしき]を醸成[じょうせい]したい。", "sentence_source": "generated"}, {"text": "長い年月の中で、独特の文化が醸成された。", "target_word": "醸成された", "complexity_tier": "T3", "furigana": "長[なが]い年月[ねんげつ]の中[なか]で、独特[どくとく]の文化[ぶんか]が醸成[じょうせい]された。", "sentence_source": "generated"}, {"text": "信頼の醸成には時間が必要だ。", "target_word": "醸成", "complexity_tier": "T3", "furigana": "信頼[しんらい]の醸成[じょうせい]には時間[じかん]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "先生は、みんなが安心して話せる空気を醸成してくれた。", "target_word": "醸成して", "complexity_tier": "T4", "furigana": "先生[せんせい]は、みんなが安心[あんしん]して話[はな]せる空気[くうき]を醸成[じょうせい]してくれた。", "sentence_source": "generated"}, {"text": "毎日の小さな会話が、家族の絆を醸成していく。", "target_word": "醸成して", "complexity_tier": "T4", "furigana": "毎日[まいにち]の小[ちい]さな会話[かいわ]が、家族[かぞく]の絆[きずな]を醸成[じょうせい]していく。", "sentence_source": "generated"}, {"text": "この町では協力の心が醸成された。", "target_word": "醸成された", "complexity_tier": "T3", "furigana": "この町[まち]では協力[きょうりょく]の心[こころ]が醸成[じょうせい]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "醸成する", "label": "活用"}, {"form": "醸成される", "label": "活用"}, {"form": "醸成させる", "label": "活用"}, {"form": "醸成し", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 少しずつ作り上げていくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b9edc6-97f7-4887-afa1-fce3d82da614') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52779, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "醸成", "is_correct": true, "explanation": "じょうせい。正解の見出し語。"}, {"text": "造成", "is_correct": false, "explanation": "ぞうせい。最初の一拍が違う。"}, {"text": "構成", "is_correct": false, "explanation": "こうせい。最初の一拍が違う。"}, {"text": "養成", "is_correct": false, "explanation": "ようせい。最初の一拍が違う。"}, {"text": "状態", "is_correct": false, "explanation": "じょうたい。三拍目だけが違う。"}], "explanations": {"醸成": "じょうせい。正解の見出し語。", "造成": "ぞうせい。最初の一拍が違う。", "構成": "こうせい。最初の一拍が違う。", "養成": "ようせい。最初の一拍が違う。", "状態": "じょうたい。三拍目だけが違う。"}, "sentence_index": null, "correct_answer": "醸成"}, "level_3": {"options": [{"text": "醸成する", "is_correct": true, "explanation": "信頼を少しずつつくるという意味で合う。"}, {"text": "返却する", "is_correct": false, "explanation": "形は合うが、信頼を返却するでは意味が合わない。"}, {"text": "洗濯する", "is_correct": false, "explanation": "形は合うが、信頼を洗濯するでは意味が合わない。"}, {"text": "運転する", "is_correct": false, "explanation": "形は合うが、信頼を運転するでは意味が合わない。"}], "explanations": {"醸成する": "信頼を少しずつつくるという意味で合う。", "返却する": "形は合うが、信頼を返却するでは意味が合わない。", "洗濯する": "形は合うが、信頼を洗濯するでは意味が合わない。", "運転する": "形は合うが、信頼を運転するでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "醸成する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お茶を飲むために、お湯をコップに醸成した。", "explanation": "醸成は物を注ぐ動作ではなく、少しずつつくり上げることなので合わない。"}, {"text": "財布が机の上に醸成されている。", "explanation": "醸成は物が置かれている状態を表さず、場所の表現と合わない。"}, {"text": "試合は五分で醸成してしまった。", "explanation": "醸成は「終わる」という意味ではないので誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, ge