INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52780, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "雰囲気と醸成をつなぐ連体の助詞。"}, {"text": "を", "is_correct": false, "explanation": "「雰囲気を醸成には」は文法的に成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「雰囲気から醸成には」は不自然で成り立たない。"}, {"text": "まで", "is_correct": false, "explanation": "「雰囲気まで醸成には」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "雰囲気と醸成をつなぐ連体の助詞。", "を": "「雰囲気を醸成には」は文法的に成り立たない。", "から": "「雰囲気から醸成には」は不自然で成り立たない。", "まで": "「雰囲気まで醸成には」は成り立たない。"}, "error_tags": {"を": "object_marker", "から": "starting_point", "まで": "limit"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "崩壊", "is_correct": true, "explanation": "つくり上げることの反対で、積み上げたものが崩れること。"}, {"text": "形成", "is_correct": false, "explanation": "醸成と近い意味で、反対ではない。"}, {"text": "育成", "is_correct": false, "explanation": "時間をかけて育てることで、反対ではない。"}, {"text": "構築", "is_correct": false, "explanation": "つくり上げることで、反対ではない。"}], "correct_answer": "崩壊", "explanations": {"崩壊": "つくり上げることの反対で、積み上げたものが崩れること。", "形成": "醸成と近い意味で、反対ではない。", "育成": "時間をかけて育てることで、反対ではない。", "構築": "つくり上げることで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
