INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52780, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある状態や雰囲気を、時間をかけてつくり出すこと。", "primary_collocate": null, "pronunciation": "じょうせい", "ipa": "dʑoːseː", "syllable_count": 4, "sentences": [{"text": "この取り組みは、単なる植物の栽培を超え、環境再生と社会的結束の醸成を同時に企図する点に特徴がある。", "target_word": "醸成", "complexity_tier": "T6", "furigana": "この取[と]り組[く]みは、単[たん]なる植物[しょくぶつ]の栽培[さいばい]を超[こ]え、環境[かんきょう]再生[さいせい]と社会的[しゃかいてき]結束[けっそく]の醸成[じょうせい]を同時[どうじ]に企図[きと]する点[てん]に特徴[とくちょう]がある。", "sentence_source": "mined"}, {"text": "雰囲気の醸成には時間がかかる。", "target_word": "醸成", "complexity_tier": "T2", "furigana": "雰囲気[ふんいき]の醸成[じょうせい]には時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "チームの信頼を醸成するのは簡単ではない。", "target_word": "醸成する", "complexity_tier": "T3", "furigana": "チームの信頼[しんらい]を醸成[じょうせい]するのは簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "新しい文化が少しずつ醸成されてきた。", "target_word": "醸成されて", "complexity_tier": "T3", "furigana": "新[あたら]しい文化[ぶんか]が少[すこ]しずつ醸成[じょうせい]されてきた。", "sentence_source": "generated"}, {"text": "安心できる空気を醸成したいと思っている。", "target_word": "醸成したい", "complexity_tier": "T3", "furigana": "安心[あんしん]できる空気[くうき]を醸成[じょうせい]したいと思[おも]っている。", "sentence_source": "generated"}, {"text": "社長は自由に話せる雰囲気を醸成しようとしている。", "target_word": "醸成しよう", "complexity_tier": "T4", "furigana": "社長[しゃちょう]は自由[じゆう]に話[はな]せる雰囲気[ふんいき]を醸成[じょうせい]しようとしている。", "sentence_source": "generated"}, {"text": "地域の一体感の醸成が、このイベントの大きな目的だ。", "target_word": "醸成", "complexity_tier": "T4", "furigana": "地域[ちいき]の一体感[いったいかん]の醸成[じょうせい]が、このイベントの大[おお]きな目的[もくてき]だ。", "sentence_source": "generated"}, {"text": "互いに話し合うことで、協力の意識が醸成された。", "target_word": "醸成された", "complexity_tier": "T4", "furigana": "互[たが]いに話[はな]し合[あ]うことで、協力[きょうりょく]の意識[いしき]が醸成[じょうせい]された。", "sentence_source": "generated"}, {"text": "長年の交流を通じて醸成された友情は、簡単には壊れないものである。", "target_word": "醸成された", "complexity_tier": "T5", "furigana": "長年[ながねん]の交流[こうりゅう]を通[つう]じて醸成[じょうせい]された友情[ゆうじょう]は、簡単[かんたん]には壊[こわ]れないものである。", "sentence_source": "generated"}, {"text": "学校では勉強だけでなく、思いやりの心を醸成する教育も求められている。", "target_word": "醸成する", "complexity_tier": "T5", "furigana": "学校[がっこう]では勉強[べんきょう]だけでなく、思[おも]いやりの心[こころ]を醸成[じょうせい]する教育[きょういく]も求[もと]められている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "醸成する", "label": "活用"}, {"form": "醸成される", "label": "活用"}, {"form": "醸成させる", "label": "活用"}, {"form": "醸成し", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 時間をかけ雰囲気をつくること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b9edc6-97f7-4887-afa1-fce3d82da614') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52780, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "醸成", "is_correct": true, "explanation": "じょうせい。正解の見出し語。"}, {"text": "造成", "is_correct": false, "explanation": "ぞうせい。最初の一拍が違う。"}, {"text": "構成", "is_correct": false, "explanation": "こうせい。最初の一拍が違う。"}, {"text": "養成", "is_correct": false, "explanation": "ようせい。最初の一拍が違う。"}, {"text": "状態", "is_correct": false, "explanation": "じょうたい。三拍目だけが違う。"}], "explanations": {"醸成": "じょうせい。正解の見出し語。", "造成": "ぞうせい。最初の一拍が違う。", "構成": "こうせい。最初の一拍が違う。", "養成": "ようせい。最初の一拍が違う。", "状態": "じょうたい。三拍目だけが違う。"}, "sentence_index": null, "correct_answer": "醸成"}, "level_3": {"options": [{"text": "醸成", "is_correct": true, "explanation": "結束を時間をかけてつくり出すという意味で文脈に合う。"}, {"text": "紛失", "is_correct": false, "explanation": "形は合うが、結束の紛失では意味が合わない。"}, {"text": "遅延", "is_correct": false, "explanation": "形は合うが、結束の遅延では意味が合わない。"}, {"text": "短縮", "is_correct": false, "explanation": "形は合うが、結束の短縮では意味が合わない。"}], "explanations": {"醸成": "結束を時間をかけてつくり出すという意味で文脈に合う。", "紛失": "形は合うが、結束の紛失では意味が合わない。", "遅延": "形は合うが、結束の遅延では意味が合わない。", "短縮": "形は合うが、結束の短縮では意味が合わない。"}, "sentence_index": 0, "correct_answer": "醸成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、冷たい水を醸成してから家を出ている。", "explanation": "醸成は雰囲気や意識を時間をかけてつくることで、水のような具体物には使えない。"}, {"text": "大きな地震で、古い橋が一瞬のうちに醸成された。", "explanation": "醸成は壊れることではなく、時間をかけてつくり出すことなので意味が合わない。"}, {"text": "郵便局で切手を醸成して、はがきを出した。", "explanation": "醸成は雰囲気や意識を時間をかけてつくることで、切手のような物を買う動作には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52780, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "醸成", "is_correct": true, "explanation": "じょうせい。正解の見出し語。"}, {"text": "条例", "is_correct": false, "explanation": "じょうれい。三拍目だけが違う。"}, {"text": "情景", "is_correct": false, "explanation": "じょうけい。三拍目だけが違う。"}, {"text": "常設", "is_correct": false, "explanation": "じょうせつ。四拍目だけが違う。"}, {"text": "同性", "is_correct": false, "explanation": "どうせい。最初の一拍が違う。"}], "explanations": {"醸成": "じょうせい。正解の見出し語。", "条例": "じょうれい。三拍目だけが違う。", "情景": "じょうけい。三拍目だけが違う。", "常設": "じょうせつ。四拍目だけが違う。", "同性": "どうせい。最初の一拍が違う。"}, "sentence_index": null, "correct_answer": "醸成"}, "level_3": {"options": [{"text": "醸成", "is_correct": true, "explanation": "一体感を時間をかけてつくることが目的として合う。"}, {"text": "返却", "is_correct": false, "explanation": "形は合うが、一体感の返却では意味が合わない。"}, {"text": "遅刻", "is_correct": false, "explanation": "形は合うが、一体感の遅刻では意味が合わない。"}, {"text": "節約", "is_correct": false, "explanation": "形は合うが、一体感の節約では意味が合わない。"}], "explanations": {"醸成": "一体感を時間をかけてつくることが目的として合う。", "返却": "形は合うが、一体感の返却では意味が合わない。", "遅刻": "形は合うが、一体感の遅刻では意味が合わない。", "節約": "形は合うが、一体感の節約では意味が合わない。"}, "sentence_index": 6, "correct_answer": "醸成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車の中で、駅で買った新聞を醸成した。", "explanation": "醸成は雰囲気や心をつくることで、新聞を読む動作には使えない。"}, {"text": "新しい靴を醸成して、毎日きれいに磨いた。", "explanation": "醸成は物の手入れを表さず、状態や雰囲気をつくる意味なので合わない。"}, {"text": "ケーキの作り方を醸成する本を図書館で借りた。", "explanation": "醸成は「説明する」という意味ではなく、使い方が違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings