INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52781, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在する場所を表す「に」が合う。"}, {"text": "を", "is_correct": false, "explanation": "「あります」の場所には「を」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "存在を表す「あります」は方向の「へ」と結びつかない。"}, {"text": "から", "is_correct": false, "explanation": "「近隣からスーパーがあります」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "存在する場所を表す「に」が合う。", "を": "「あります」の場所には「を」は使えない。", "へ": "存在を表す「あります」は方向の「へ」と結びつかない。", "から": "「近隣からスーパーがあります」は意味が通らない。"}, "error_tags": {"を": "object", "へ": "direction", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52781, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「近隣の様子」と名詞をつなぐ「の」が合う。"}, {"text": "を", "is_correct": false, "explanation": "「様子が気になる」の前に「を」は置けない。"}, {"text": "へ", "is_correct": false, "explanation": "「近隣へ様子が」は文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「近隣から様子が気になって」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「近隣の様子」と名詞をつなぐ「の」が合う。", "を": "「様子が気になる」の前に「を」は置けない。", "へ": "「近隣へ様子が」は文として成り立たない。", "から": "「近隣から様子が気になって」は意味が通らない。"}, "error_tags": {"を": "object", "へ": "direction", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52781, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "近くの場所や、となりどうしのことを言います。", "primary_collocate": null, "pronunciation": "きんりん", "ipa": "kiɴɾiɴ", "syllable_count": 4, "sentences": [{"text": "近隣とは仲がいい。", "target_word": "近隣", "complexity_tier": "T1", "furigana": "近隣[きんりん]とは仲[なか]がいい。", "sentence_source": "generated"}, {"text": "近隣にスーパーがあります。", "target_word": "近隣", "complexity_tier": "T2", "furigana": "近隣[きんりん]にスーパーがあります。", "sentence_source": "generated"}, {"text": "近隣の公園で子どもが遊んでいる。", "target_word": "近隣", "complexity_tier": "T3", "furigana": "近隣[きんりん]の公園[こうえん]で子[こ]どもが遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "近隣と助け合うことが大切だ。", "target_word": "近隣", "complexity_tier": "T3", "furigana": "近隣[きんりん]と助[たす]け合[あ]うことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "近隣からの苦情で、音楽を小さくした。", "target_word": "近隣", "complexity_tier": "T3", "furigana": "近隣[きんりん]からの苦情[くじょう]で、音楽[おんがく]を小[ちい]さくした。", "sentence_source": "generated"}, {"text": "引っ越しの時、近隣にあいさつに行った。", "target_word": "近隣", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの時[とき]、近隣[きんりん]にあいさつに行[い]った。", "sentence_source": "generated"}, {"text": "近隣には病院が三つもある。", "target_word": "近隣", "complexity_tier": "T2", "furigana": "近隣[きんりん]には病院[びょういん]が三[みっ]つもある。", "sentence_source": "generated"}, {"text": "近隣の様子が気になって、窓から外を見た。", "target_word": "近隣", "complexity_tier": "T3", "furigana": "近隣[きんりん]の様子[ようす]が気[き]になって、窓[まど]から外[そと]を見[み]た。", "sentence_source": "generated"}, {"text": "近隣の町まで自転車で行くことにした。", "target_word": "近隣", "complexity_tier": "T3", "furigana": "近隣[きんりん]の町[まち]まで自転車[じてんしゃ]で行[い]くことにした。", "sentence_source": "generated"}, {"text": "災害に備えて、近隣と連絡先を交換しておくべきだ。", "target_word": "近隣", "complexity_tier": "T4", "furigana": "災害[さいがい]に備[そな]えて、近隣[きんりん]と連絡先[れんらくさき]を交換[こうかん]しておくべきだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "近隣諸国", "label": "派生"}, {"form": "近隣住民", "label": "派生"}, {"form": "近隣地区", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 近くの場所やとなり同士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ac3fe2-6ce0-4a2e-b7a6-92b185db239c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52781, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "近隣", "is_correct": true, "explanation": "見出し語そのもの。きんりん。"}, {"text": "銀輪", "is_correct": false, "explanation": "ぎんりん。最初の「き」が「ぎ」に変わる別語。"}, {"text": "森林", "is_correct": false, "explanation": "しんりん。最初の「き」が「し」に変わる別語。"}, {"text": "近臣", "is_correct": false, "explanation": "きんしん。「り」が「し」に変わる別語。"}], "explanations": {"近隣": "見出し語そのもの。きんりん。", "銀輪": "ぎんりん。最初の「き」が「ぎ」に変わる別語。", "森林": "しんりん。最初の「き」が「し」に変わる別語。", "近臣": "きんしん。「り」が「し」に変わる別語。"}, "sentence_index": null, "correct_answer": "近隣"}, "level_3": {"options": [{"text": "近隣", "is_correct": true, "explanation": "「近くに住む人たち」と仲がいいという意味で合う。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、机と仲がいいという意味は合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気と仲がいいという意味は合わない。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、値段と仲がいいという意味は合わない。"}], "explanations": {"近隣": "「近くに住む人たち」と仲がいいという意味で合う。", "机": "形は合うが、机と仲がいいという意味は合わない。", "天気": "形は合うが、天気と仲がいいという意味は合わない。", "値段": "形は合うが、値段と仲がいいという意味は合わない。"}, "sentence_index": 0, "correct_answer": "近隣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "近隣へ行くため、飛行機で半日かかった。", "explanation": "近隣は近い場所を表すので、飛行機で半日かかる遠さには使えない。"}, {"text": "近隣を食べすぎて、お腹が痛くなった。", "explanation": "近隣は場所や地域を表す語で、食べ物ではない。"}, {"text": "近隣が三時に終わるので、その後で会おう。", "explanation": "近隣は時間や出来事を表す語ではなく、「終わる」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
