INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52782, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "出来事が起こった場所を表す「で」が合う。"}, {"text": "を", "is_correct": false, "explanation": "「火事があった」の場所には「を」は使えない。"}, {"text": "と", "is_correct": false, "explanation": "「近隣と火事があった」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「あった」は方向を表す「へ」と結びつかない。"}], "correct_answer": "で", "explanations": {"で": "出来事が起こった場所を表す「で」が合う。", "を": "「火事があった」の場所には「を」は使えない。", "と": "「近隣と火事があった」は文として成り立たない。", "へ": "「あった」は方向を表す「へ」と結びつかない。"}, "error_tags": {"を": "object", "と": "companion", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52782, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある場所や物事に、距離や関係が近いこと。また、そのような場所や地域。", "primary_collocate": null, "pronunciation": "きんりん", "ipa": "kiɴɾiɴ", "syllable_count": 4, "sentences": [{"text": "特に、住民の主体的な参加により創出されるガーデンは、生物多様性の回復のみならず、微気候の改善といった側面においても近隣緑地に好影響を及ぼしている。", "target_word": "近隣", "complexity_tier": "T6", "furigana": "特[とく]に、住民[じゅうみん]の主体的[しゅたいてき]な参加[さんか]により創出[そうしゅつ]されるガーデンは、生物[せいぶつ]多様性[たようせい]の回復[かいふく]のみならず、微気候[びきこう]の改善[かいぜん]といった側面[そくめん]においても近隣[きんりん]緑地[りょくち]に好影響[こうえいきょう]を及[およ]ぼしている。", "sentence_source": "mined"}, {"text": "近隣は静かだ。", "target_word": "近隣", "complexity_tier": "T1", "furigana": "近隣[きんりん]は静[しず]かだ。", "sentence_source": "generated"}, {"text": "近隣の店で買いました。", "target_word": "近隣", "complexity_tier": "T1", "furigana": "近隣[きんりん]の店[みせ]で買[か]いました。", "sentence_source": "generated"}, {"text": "近隣にも公園があります。", "target_word": "近隣", "complexity_tier": "T2", "furigana": "近隣[きんりん]にも公園[こうえん]があります。", "sentence_source": "generated"}, {"text": "近隣の住民に挨拶をして回った。", "target_word": "近隣", "complexity_tier": "T3", "furigana": "近隣[きんりん]の住民[じゅうみん]に挨拶[あいさつ]をして回[まわ]った。", "sentence_source": "generated"}, {"text": "この工事は近隣に迷惑をかけた。", "target_word": "近隣", "complexity_tier": "T3", "furigana": "この工事[こうじ]は近隣[きんりん]に迷惑[めいわく]をかけた。", "sentence_source": "generated"}, {"text": "駅の近隣には古い寺が多い。", "target_word": "近隣", "complexity_tier": "T2", "furigana": "駅[えき]の近隣[きんりん]には古[ふる]い寺[てら]が多[おお]い。", "sentence_source": "generated"}, {"text": "近隣で火事があったと聞いて、すぐ駆けつけた。", "target_word": "近隣", "complexity_tier": "T3", "furigana": "近隣[きんりん]で火事[かじ]があったと聞[き]いて、すぐ駆[か]けつけた。", "sentence_source": "generated"}, {"text": "近隣の国々との関係を大切にしたい。", "target_word": "近隣", "complexity_tier": "T3", "furigana": "近隣[きんりん]の国々[くにぐに]との関係[かんけい]を大切[たいせつ]にしたい。", "sentence_source": "generated"}, {"text": "近隣と協力して、防災訓練を行った。", "target_word": "近隣", "complexity_tier": "T3", "furigana": "近隣[きんりん]と協力[きょうりょく]して、防災[ぼうさい]訓練[くんれん]を行[おこな]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "近隣諸国", "label": "派生"}, {"form": "近隣住民", "label": "派生"}, {"form": "近隣地域", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 距離や関係が近い場所・地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ac3fe2-6ce0-4a2e-b7a6-92b185db239c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52782, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "近隣", "is_correct": true, "explanation": "見出し語そのもの。きんりん。"}, {"text": "銀輪", "is_correct": false, "explanation": "ぎんりん。最初の「き」が「ぎ」に変わる別語。"}, {"text": "森林", "is_correct": false, "explanation": "しんりん。最初の「き」が「し」に変わる別語。"}, {"text": "近臣", "is_correct": false, "explanation": "きんしん。「り」が「し」に変わる別語。"}, {"text": "近刊", "is_correct": false, "explanation": "きんかん。「り」が「か」に変わる別語。"}], "explanations": {"近隣": "見出し語そのもの。きんりん。", "銀輪": "ぎんりん。最初の「き」が「ぎ」に変わる別語。", "森林": "しんりん。最初の「き」が「し」に変わる別語。", "近臣": "きんしん。「り」が「し」に変わる別語。", "近刊": "きんかん。「り」が「か」に変わる別語。"}, "sentence_index": null, "correct_answer": "近隣"}, "level_3": {"options": [{"text": "近隣", "is_correct": true, "explanation": "「近くの地域の緑地」という意味で文脈に合う。"}, {"text": "海外", "is_correct": false, "explanation": "形は合うが、住民参加のガーデンが海外の緑地に影響するという意味は合わない。"}, {"text": "前年", "is_correct": false, "explanation": "形は合うが、「前年の緑地」では意味が合わない。"}, {"text": "地下", "is_correct": false, "explanation": "形は合うが、地下の緑地では意味が合わない。"}], "explanations": {"近隣": "「近くの地域の緑地」という意味で文脈に合う。", "海外": "形は合うが、住民参加のガーデンが海外の緑地に影響するという意味は合わない。", "前年": "形は合うが、「前年の緑地」では意味が合わない。", "地下": "形は合うが、地下の緑地では意味が合わない。"}, "sentence_index": 0, "correct_answer": "近隣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "飛行機で十時間もかかる近隣の国へ旅行した。", "explanation": "近隣は距離が近いことを表すので、十時間もかかる遠い国には使えない。"}, {"text": "近隣に会議が終わってから、すぐに帰った。", "explanation": "近隣は場所や地域を表す語で、時間を表す語として使うのは誤り。"}, {"text": "近隣は私の母で、毎朝お弁当を作ってくれる。", "explanation": "近隣は近くの場所や地域を指す語で、身内の人を指すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors =