INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52782, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "近隣", "is_correct": true, "explanation": "見出し語そのもの。きんりん。"}, {"text": "近眼", "is_correct": false, "explanation": "きんがん。「り」が「が」に変わる別語。"}, {"text": "近年", "is_correct": false, "explanation": "きんねん。「り」が「ね」に変わる別語。"}, {"text": "近親", "is_correct": false, "explanation": "きんしん。「り」が「し」に変わる別語。"}, {"text": "凛々", "is_correct": false, "explanation": "りんりん。最初の「き」が「り」に変わる別語。"}], "explanations": {"近隣": "見出し語そのもの。きんりん。", "近眼": "きんがん。「り」が「が」に変わる別語。", "近年": "きんねん。「り」が「ね」に変わる別語。", "近親": "きんしん。「り」が「し」に変わる別語。", "凛々": "りんりん。最初の「き」が「り」に変わる別語。"}, "sentence_index": null, "correct_answer": "近隣"}, "level_3": {"options": [{"text": "近隣", "is_correct": true, "explanation": "「駅の近くの地域」という意味で文に合う。"}, {"text": "上空", "is_correct": false, "explanation": "形は合うが、駅の上空に古い寺が多いという意味は合わない。"}, {"text": "内部", "is_correct": false, "explanation": "形は合うが、駅の内部に古い寺が多いという意味は合わない。"}, {"text": "前日", "is_correct": false, "explanation": "形は合うが、駅の前日では意味が合わない。"}], "explanations": {"近隣": "「駅の近くの地域」という意味で文に合う。", "上空": "形は合うが、駅の上空に古い寺が多いという意味は合わない。", "内部": "形は合うが、駅の内部に古い寺が多いという意味は合わない。", "前日": "形は合うが、駅の前日では意味が合わない。"}, "sentence_index": 6, "correct_answer": "近隣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "近隣へ行くために、新幹線で五時間も乗った。", "explanation": "近隣は近い場所を指すので、新幹線で五時間かかる遠さには使えない。"}, {"text": "近隣を毎朝コップ二杯飲んでいる。", "explanation": "近隣は場所や地域を表す語で、飲み物ではない。"}, {"text": "近隣を二つに切って、友達に分けた。", "explanation": "近隣は地域を表す語で、切って分けられる物としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52782, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "近隣を住民に挨拶をして回った。", "corrected_sentence": "近隣の住民に挨拶をして回った。", "error_description": "「近隣」が「住民」を修飾するときは「を」ではなく「の」でつなぐ。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52782, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この工事は近隣を迷惑をかけた。", "corrected_sentence": "この工事は近隣に迷惑をかけた。", "error_description": "迷惑をかける相手には「を」ではなく「に」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52783, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "波及した先を表す「に」が合う。"}, {"text": "が", "is_correct": false, "explanation": "「教室中が波及した」は主語が重なり文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「教室中と波及した」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「教室中の波及した」は名詞と動詞を「の」でつなげず、文にならない。"}], "correct_answer": "に", "explanations": {"に": "波及した先を表す「に」が合う。", "が": "「教室中が波及した」は主語が重なり文が成り立たない。", "と": "「教室中と波及した」は意味が通らない。", "の": "「教室中の波及した」は名詞と動詞を「の」でつなげず、文にならない。"}, "error_tags": {"が": "subject", "と": "companion", "の": "possessive"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "限定", "is_correct": true, "explanation": "範囲を限る意味で、広がる波及と反対の関係。"}, {"text": "伝播", "is_correct": false, "explanation": "伝わり広がる意味で、波及の類義語。"}, {"text": "拡散", "is_correct": false, "explanation": "散らばり広がる意味で、波及に近い。"}, {"text": "普及", "is_correct": false, "explanation": "広く行き渡る意味で、反対ではない。"}], "correct_answer": "限定", "explanations": {"限定": "範囲を限る意味で、広がる波及と反対の関係。", "伝播": "伝わり広がる意味で、波及の類義語。", "拡散": "散らばり広がる意味で、波及に近い。", "普及": "広く行き渡る意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52783, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「止める」の対象を表す「を」が合う。"}, {"text": "に", "is_correct": false, "explanation": "「波及に止めるには」は対象の示し方が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「止める」は方向の「へ」と結びつかない。"}, {"text": "と", "is_correct": false, "explanation": "「波及と止めるには」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「止める」の対象を表す「を」が合う。", "に": "「波及に止めるには」は対象の示し方が合わない。", "へ": "「止める」は方向の「へ」と結びつかない。", "と": "「波及と止めるには」は意味が通らない。"}, "error_tags": {"に": "target", "へ": "direction", "と": "companion"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "封じ込め", "is_correct": true, "explanation": "広がらないよう抑える意味で、波及と反対の関係。"}, {"text": "浸透", "is_correct": false, "explanation": "しみ通って広がる意味で、反対ではない。"}, {"text": "連鎖", "is_correct": false, "explanation": "つながって続く意味で、反対ではない。"}, {"text": "蔓延", "is_correct": false, "explanation": "はびこり広がる意味で、波及に近い。"}], "correct_answer": "封じ込め", "explanations": {"封じ込め": "広がらないよう抑える意味で、波及と反対の関係。", "浸透": "しみ通って広がる意味で、反対ではない。", "連鎖": "つながって続く意味で、反対ではない。", "蔓延": "はびこり広がる意味で、波及に近い。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52783, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることがきっかけで、そのえいきょうが次々とひろがっていくこと。", "primary_collocate": null, "pronunciation": "はきゅう", "ipa": "hakʲɯː", "syllable_count": 3, "sentences": [{"text": "混乱が波及した。", "target_word": "波及", "complexity_tier": "T1", "furigana": "混乱[こんらん]が波及[はきゅう]した。", "sentence_source": "generated"}, {"text": "笑いが教室中に波及した。", "target_word": "波及", "complexity_tier": "T2", "furigana": "笑[わら]いが教室中[きょうしつじゅう]に波及[はきゅう]した。", "sentence_source": "generated"}, {"text": "流行は町全体に波及しました。", "target_word": "波及", "complexity_tier": "T2", "furigana": "流行[りゅうこう]は町[まち]全体[ぜんたい]に波及[はきゅう]しました。", "sentence_source": "generated"}, {"text": "悪い影響が波及しないようにしたい。", "target_word": "波及", "complexity_tier": "T3", "furigana": "悪[わる]い影響[えいきょう]が波及[はきゅう]しないようにしたい。", "sentence_source": "generated"}, {"text": "波及のスピードに驚いた。", "target_word": "波及", "complexity_tier": "T2", "furigana": "波及[はきゅう]のスピードに驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "一人の親切が、次々と周りに波及していった。", "target_word": "波及", "complexity_tier": "T3", "furigana": "一人[ひとり]の親切[しんせつ]が、次々[つぎつぎ]と周[まわ]りに波及[はきゅう]していった。", "sentence_source": "generated"}, {"text": "不安が世界へ波及するまで一日もかからなかった。", "target_word": "波及", "complexity_tier": "T4", "furigana": "不安[ふあん]が世界[せかい]へ波及[はきゅう]するまで一日[いちにち]もかからなかった。", "sentence_source": "generated"}, {"text": "この波及を止めるには、早めの対応が欠かせない。", "target_word": "波及", "complexity_tier": "T3", "furigana": "この波及[はきゅう]を止[と]めるには、早[はや]めの対応[たいおう]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "値上がりの波及で、生活費が増えた。", "target_word": "波及", "complexity_tier": "T3", "furigana": "値上[ねあ]がりの波及[はきゅう]で、生活費[せいかつひ]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "小さな変化が波及することもある。", "target_word": "波及", "complexity_tier": "T3", "furigana": "小[ちい]さな変化[へんか]が波及[はきゅう]することもある。", "sentence_source": "generated"}], "mo