INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52783, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "波及", "is_correct": true, "explanation": "見出し語そのもの。はきゅう。"}, {"text": "下級", "is_correct": false, "explanation": "かきゅう。最初の「は」が「か」に変わる別語。"}, {"text": "気球", "is_correct": false, "explanation": "ききゅう。最初の「は」が「き」に変わる別語。"}, {"text": "砂丘", "is_correct": false, "explanation": "さきゅう。最初の「は」が「さ」に変わる別語。"}], "explanations": {"波及": "見出し語そのもの。はきゅう。", "下級": "かきゅう。最初の「は」が「か」に変わる別語。", "気球": "ききゅう。最初の「は」が「き」に変わる別語。", "砂丘": "さきゅう。最初の「は」が「さ」に変わる別語。"}, "sentence_index": null, "correct_answer": "波及"}, "level_3": {"options": [{"text": "波及", "is_correct": true, "explanation": "「混乱が周りに広がった」という意味で合う。"}, {"text": "完成", "is_correct": false, "explanation": "形は合うが、混乱が完成するという意味は合わない。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが、混乱が卒業するという意味は合わない。"}, {"text": "出発", "is_correct": false, "explanation": "形は合うが、混乱が出発するという意味は合わない。"}], "explanations": {"波及": "「混乱が周りに広がった」という意味で合う。", "完成": "形は合うが、混乱が完成するという意味は合わない。", "卒業": "形は合うが、混乱が卒業するという意味は合わない。", "出発": "形は合うが、混乱が出発するという意味は合わない。"}, "sentence_index": 0, "correct_answer": "波及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "波及の高い海で泳ぐのは危ない。", "explanation": "波及は影響が広がることで、海の波の高さを表す語ではない。"}, {"text": "ねこがお皿の上の魚を波及した。", "explanation": "波及は物事の影響が広がることで、食べる動作は表せない。"}, {"text": "弟は毎日学校まで波及して通っている。", "explanation": "波及は影響が広がることで、人が移動する手段や動作ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
