INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52784, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事がきっかけとなり、その影響が周囲に広がっていくこと。", "primary_collocate": null, "pronunciation": "はきゅう", "ipa": "hakʲɯː", "syllable_count": 3, "sentences": [{"text": "さらに、こうした緑の拠点が生み出す波及効果は計り知れない。", "target_word": "波及", "complexity_tier": "T6", "furigana": "さらに、こうした緑[みどり]の拠点[きょてん]が生[う]み出[だ]す波及[はきゅう]効果[こうか]は計[はか]り知[し]れない。", "sentence_source": "mined"}, {"text": "影響が波及した。", "target_word": "波及", "complexity_tier": "T1", "furigana": "影響[えいきょう]が波及[はきゅう]した。", "sentence_source": "generated"}, {"text": "値上げは全国に波及した。", "target_word": "波及", "complexity_tier": "T2", "furigana": "値上[ねあ]げは全国[ぜんこく]に波及[はきゅう]した。", "sentence_source": "generated"}, {"text": "その波及は予想より早かった。", "target_word": "波及", "complexity_tier": "T2", "furigana": "その波及[はきゅう]は予想[よそう]より早[はや]かった。", "sentence_source": "generated"}, {"text": "事故の波及を防ぐ必要がある。", "target_word": "波及", "complexity_tier": "T3", "furigana": "事故[じこ]の波及[はきゅう]を防[ふせ]ぐ必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "一つの店の成功が、周りの店にも波及していった。", "target_word": "波及", "complexity_tier": "T3", "furigana": "一[ひと]つの店[みせ]の成功[せいこう]が、周[まわ]りの店[みせ]にも波及[はきゅう]していった。", "sentence_source": "generated"}, {"text": "不況は他の産業へ波及するおそれがある。", "target_word": "波及", "complexity_tier": "T3", "furigana": "不況[ふきょう]は他[ほか]の産業[さんぎょう]へ波及[はきゅう]するおそれがある。", "sentence_source": "generated"}, {"text": "良い影響の波及を期待して、新しい駅が建てられた。", "target_word": "波及", "complexity_tier": "T4", "furigana": "良[よ]い影響[えいきょう]の波及[はきゅう]を期待[きたい]して、新[あたら]しい駅[えき]が建[た]てられた。", "sentence_source": "generated"}, {"text": "小さな問題でも、放っておくと大きな波及を招く。", "target_word": "波及", "complexity_tier": "T4", "furigana": "小[ちい]さな問題[もんだい]でも、放[ほう]っておくと大[おお]きな波及[はきゅう]を招[まね]く。", "sentence_source": "generated"}, {"text": "この政策の経済への波及を調べている。", "target_word": "波及", "complexity_tier": "T3", "furigana": "この政策[せいさく]の経済[けいざい]への波及[はきゅう]を調[しら]べている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "波及する", "label": "活用"}, {"form": "波及した", "label": "活用"}, {"form": "波及しない", "label": "活用"}, {"form": "波及効果", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事の影響が周囲に広がること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ac3fe2-6ce0-4a2e-b7a6-92b185db239c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52784, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "波及", "is_correct": true, "explanation": "見出し語そのもの。はきゅう。"}, {"text": "下級", "is_correct": false, "explanation": "かきゅう。最初の「は」が「か」に変わる別語。"}, {"text": "気球", "is_correct": false, "explanation": "ききゅう。最初の「は」が「き」に変わる別語。"}, {"text": "砂丘", "is_correct": false, "explanation": "さきゅう。最初の「は」が「さ」に変わる別語。"}], "explanations": {"波及": "見出し語そのもの。はきゅう。", "下級": "かきゅう。最初の「は」が「か」に変わる別語。", "気球": "ききゅう。最初の「は」が「き」に変わる別語。", "砂丘": "さきゅう。最初の「は」が「さ」に変わる別語。"}, "sentence_index": null, "correct_answer": "波及"}, "level_3": {"options": [{"text": "波及", "is_correct": true, "explanation": "「影響が広がる効果」という意味で文に合う。"}, {"text": "防寒", "is_correct": false, "explanation": "形は合うが、緑の拠点が生む効果が防寒というのは意味が合わない。"}, {"text": "美白", "is_correct": false, "explanation": "形は合うが、緑の拠点が生み出す効果が美白というのは意味が合わない。"}, {"text": "洗浄", "is_correct": false, "explanation": "形は合うが、緑の拠点が生む効果が洗浄というのは意味が合わない。"}], "explanations": {"波及": "「影響が広がる効果」という意味で文に合う。", "防寒": "形は合うが、緑の拠点が生む効果が防寒というのは意味が合わない。", "美白": "形は合うが、緑の拠点が生み出す効果が美白というのは意味が合わない。", "洗浄": "形は合うが、緑の拠点が生む効果が洗浄というのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "波及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大きな地震のあと、海岸の波及が高くなって危なかった。", "explanation": "波及は影響が広がることで、海の波の高さを表す語ではない。"}, {"text": "友達と一緒に隣町まで波及した。", "explanation": "波及は物事の影響が広がることで、人が移動する意味はない。"}, {"text": "彼女は波及が上手で、ピアノの曲をきれいに弾く。", "explanation": "波及は技能や特技を表す語ではなく、「上手」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52784, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "波及", "is_correct": true, "explanation": "見出し語そのもの。はきゅう。"}, {"text": "二級", "is_correct": false, "explanation": "にきゅう。最初の「は」が「に」に変わる別語。"}, {"text": "普及", "is_correct": false, "explanation": "ふきゅう。最初の「は」が「ふ」に変わる別語。"}, {"text": "離宮", "is_correct": false, "explanation": "りきゅう。最初の「は」が「り」に変わる別語。"}], "explanations": {"波及": "見出し語そのもの。はきゅう。", "二級": "にきゅう。最初の「は」が「に」に変わる別語。", "普及": "ふきゅう。最初の「は」が「ふ」に変わる別語。", "離宮": "りきゅう。最初の「は」が「り」に変わる別語。"}, "sentence_index": null, "correct_answer": "波及"}, "level_3": {"options": [{"text": "波及", "is_correct": true, "explanation": "「不況の影響が他の産業へ広がる」という意味で合う。"}, {"text": "到着", "is_correct": false, "explanation": "形は合うが、不況が産業へ到着するという意味は合わない。"}, {"text": "輸出", "is_correct": false, "explanation": "形は合うが、不況を産業へ輸出するという意味は合わない。"}, {"text": "返却", "is_correct": false, "explanation": "形は合うが、不況が産業へ返却するという意味は合わない。"}], "explanations": {"波及": "「不況の影響が他の産業へ広がる」という意味で合う。", "到着": "形は合うが、不況が産業へ到着するという意味は合わない。", "輸出": "形は合うが、不況を産業へ輸出するという意味は合わない。", "返却": "形は合うが、不況が産業へ返却するという意味は合わない。"}, "sentence_index": 6, "correct_answer": "波及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "波及の大きさは三メートルで、冷蔵庫に入らない。", "explanation": "波及は影響が広がることで、物の大きさを表す語ではない。"}, {"text": "私は昨日、駅まで走って波及しました。", "explanation": "波及は物事の影響が広がることで、人が移動する意味はない。"}, {"text": "彼の波及を借りて、旅行に行った。", "explanation": "波及は借りられる物や助けではなく、「借りる」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52784, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "影響が全国を波及した。", "corrected_sentence": "影響が全国に波及した。", "error_description": "波及の到達先を表すには「を」ではなく「に」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
