INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52785, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "働く場所・分野を「で」で示す。"}, {"text": "を", "is_correct": false, "explanation": "「セクターを働く」とは言えず、文法的に誤り。"}, {"text": "が", "is_correct": false, "explanation": "「父は」が主語なので、「セクターが働く」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「セクターへ働く」は文法的に成り立たない。"}], "correct_answer": "で", "explanations": {"で": "働く場所・分野を「で」で示す。", "を": "「セクターを働く」とは言えず、文法的に誤り。", "が": "「父は」が主語なので、「セクターが働く」は文として成り立たない。", "へ": "「セクターへ働く」は文法的に成り立たない。"}, "error_tags": {"を": "object_marker_misuse", "が": "double_subject", "へ": "direction_misuse"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
