INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52785, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "経済や産業のなかの、あるまとまり（例えば、会社の仕事の種類）。", "primary_collocate": null, "pronunciation": "せくたー", "ipa": "sekɯtaː", "syllable_count": 4, "sentences": [{"text": "セクターを選ぶ。", "target_word": "セクター", "complexity_tier": "T1", "furigana": "セクターを選[えら]ぶ。", "sentence_source": "generated"}, {"text": "父はこのセクターで働きます。", "target_word": "セクター", "complexity_tier": "T2", "furigana": "父[ちち]はこのセクターで働[はたら]きます。", "sentence_source": "generated"}, {"text": "このセクターは人気があります。", "target_word": "セクター", "complexity_tier": "T2", "furigana": "このセクターは人気[にんき]があります。", "sentence_source": "generated"}, {"text": "会社の仕事の種類を、セクターで分ける。", "target_word": "セクター", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の仕事[しごと]の種類[しゅるい]を、セクターで分[わ]ける。", "sentence_source": "generated"}, {"text": "製造業は、日本の大きなセクターだ。", "target_word": "セクター", "complexity_tier": "T3", "furigana": "製造業[せいぞうぎょう]は、日本[にほん]の大[おお]きなセクターだ。", "sentence_source": "generated"}, {"text": "将来、情報のセクターで働きたいと思っている。", "target_word": "セクター", "complexity_tier": "T3", "furigana": "将来[しょうらい]、情報[じょうほう]のセクターで働[はたら]きたいと思[おも]っている。", "sentence_source": "generated"}, {"text": "食品のセクターは、会社が増えている。", "target_word": "セクター", "complexity_tier": "T3", "furigana": "食品[しょくひん]のセクターは、会社[かいしゃ]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "セクターによって、給料の高さは大きく違うと言われる。", "target_word": "セクター", "complexity_tier": "T4", "furigana": "セクターによって、給料[きゅうりょう]の高[たか]さは大[おお]きく違[ちが]うと言[い]われる。", "sentence_source": "generated"}, {"text": "成長が見込めるセクターを選べば、投資で利益を得やすいだろう。", "target_word": "セクター", "complexity_tier": "T4", "furigana": "成長[せいちょう]が見込[みこ]めるセクターを選[えら]べば、投資[とうし]で利益[りえき]を得[え]やすいだろう。", "sentence_source": "generated"}, {"text": "小さな会社が多いセクターでは、競争が激しくなりがちだ。", "target_word": "セクター", "complexity_tier": "T4", "furigana": "小[ちい]さな会社[かいしゃ]が多[おお]いセクターでは、競争[きょうそう]が激[はげ]しくなりがちだ。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 経済・産業の中のまとまり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35403af3-e307-4569-9687-90b6f2030bed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52785, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "セクター", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "ベクター", "is_correct": false, "explanation": "最初の「せ」が「べ」に変わる一拍違いの語。"}, {"text": "ドクター", "is_correct": false, "explanation": "最初の「せ」が「ど」に変わる一拍違いの語。"}, {"text": "ファクター", "is_correct": false, "explanation": "最初の「せ」が「ふぁ」に変わる一拍違いの語。"}], "explanations": {"セクター": "見出し語そのもの。", "ベクター": "最初の「せ」が「べ」に変わる一拍違いの語。", "ドクター": "最初の「せ」が「ど」に変わる一拍違いの語。", "ファクター": "最初の「せ」が「ふぁ」に変わる一拍違いの語。"}, "sentence_index": null, "correct_answer": "セクター"}, "level_3": {"options": [{"text": "セクター", "is_correct": true, "explanation": "産業の区分を表し、「選ぶ」の対象になる。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが意味が合わない。地震は選べるものではない。"}, {"text": "空腹", "is_correct": false, "explanation": "形は合うが意味が合わない。空腹を選ぶとは言わない。"}, {"text": "夕立", "is_correct": false, "explanation": "形は合うが意味が合わない。夕立は選べるものではない。"}], "explanations": {"セクター": "産業の区分を表し、「選ぶ」の対象になる。", "地震": "形は合うが意味が合わない。地震は選べるものではない。", "空腹": "形は合うが意味が合わない。空腹を選ぶとは言わない。", "夕立": "形は合うが意味が合わない。夕立は選べるものではない。"}, "sentence_index": 0, "correct_answer": "セクター"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、学校へセクターに乗って行く。", "explanation": "セクターは乗り物ではなく、産業の区分を指す。"}, {"text": "私は毎日、公園で小さなセクターを散歩させている。", "explanation": "セクターは動物ではなく、散歩させることはできない。"}, {"text": "台所のセクターで、パンを焼いた。", "explanation": "セクターはパンを焼く道具ではなく、産業の区分を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52785, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "セクター", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "セーター", "is_correct": false, "explanation": "「く」が長音「ー」に変わる一拍違いの語。"}, {"text": "セッター", "is_correct": false, "explanation": "「く」が促音「っ」に変わる一拍違いの語。"}, {"text": "アクター", "is_correct": false, "explanation": "最初の「せ」が「あ」に変わる一拍違いの語。"}], "explanations": {"セクター": "見出し語そのもの。", "セーター": "「く」が長音「ー」に変わる一拍違いの語。", "セッター": "「く」が促音「っ」に変わる一拍違いの語。", "アクター": "最初の「せ」が「あ」に変わる一拍違いの語。"}, "sentence_index": null, "correct_answer": "セクター"}, "level_3": {"options": [{"text": "セクター", "is_correct": true, "explanation": "「食品のセクター」で産業の区分を表し、会社が増える主体になる。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気は「会社が増える」の主語にならない。"}, {"text": "眠気", "is_correct": false, "explanation": "形は合うが意味が合わない。食品と会社の増加に関係しない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが意味が合わない。会社が増える理由として不自然。"}], "explanations": {"セクター": "「食品のセクター」で産業の区分を表し、会社が増える主体になる。", "天気": "形は合うが意味が合わない。天気は「会社が増える」の主語にならない。", "眠気": "形は合うが意味が合わない。食品と会社の増加に関係しない。", "地震": "形は合うが意味が合わない。会社が増える理由として不自然。"}, "sentence_index": 6, "correct_answer": "セクター"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この川のセクターは、水がとてもきれいだ。", "explanation": "セクターは川の場所を指す語ではなく、産業の区分を指す。"}, {"text": "彼は大きな声でセクターを歌った。", "explanation": "セクターは歌ではなく、産業の区分を指す。"}, {"text": "私は新しいセクターを買って、ご飯を炊いた。", "explanation": "セクターは炊飯器のような調理道具ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
