INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52786, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "産業や経済活動を区分したときの、特定の分野や部門のこと。", "primary_collocate": null, "pronunciation": "せくたー", "ipa": "sekɯtaː", "syllable_count": 4, "sentences": [{"text": "気候変動という地球的危機の緩和に向け、産業セクターにおける排出量の抑制は、持続可能性を担保する上で不可避の責務である。", "target_word": "セクター", "complexity_tier": "T6", "furigana": "気候[きこう]変動[へんどう]という地球的[ちきゅうてき]危機[きき]の緩和[かんわ]に向[む]け、産業[さんぎょう]セクターにおける排出量[はいしゅつりょう]の抑制[よくせい]は、持続[じぞく]可能性[かのうせい]を担保[たんぽ]する上[うえ]で不可避[ふかひ]の責務[せきむ]である。", "sentence_source": "mined"}, {"text": "セクターが違う。", "target_word": "セクター", "complexity_tier": "T1", "furigana": "セクターが違[ちが]う。", "sentence_source": "generated"}, {"text": "彼はこのセクターで働く。", "target_word": "セクター", "complexity_tier": "T2", "furigana": "彼[かれ]はこのセクターで働[はたら]く。", "sentence_source": "generated"}, {"text": "医療のセクターは人が足りません。", "target_word": "セクター", "complexity_tier": "T2", "furigana": "医療[いりょう]のセクターは人[ひと]が足[た]りません。", "sentence_source": "generated"}, {"text": "成長しているセクターに、お金が集まっている。", "target_word": "セクター", "complexity_tier": "T3", "furigana": "成長[せいちょう]しているセクターに、お金[かね]が集[あつ]まっている。", "sentence_source": "generated"}, {"text": "農業のセクターでも、機械化が進んでいる。", "target_word": "セクター", "complexity_tier": "T3", "furigana": "農業[のうぎょう]のセクターでも、機械化[きかいか]が進[すす]んでいる。", "sentence_source": "generated"}, {"text": "政府は、エネルギーのセクターを支援する。", "target_word": "セクター", "complexity_tier": "T3", "furigana": "政府[せいふ]は、エネルギーのセクターを支援[しえん]する。", "sentence_source": "generated"}, {"text": "セクターごとに、必要な人材が違う。", "target_word": "セクター", "complexity_tier": "T3", "furigana": "セクターごとに、必要[ひつよう]な人材[じんざい]が違[ちが]う。", "sentence_source": "generated"}, {"text": "公的なセクターと民間のセクターでは、働き方が異なる。", "target_word": "セクター", "complexity_tier": "T4", "furigana": "公的[こうてき]なセクターと民間[みんかん]のセクターでは、働[はたら]き方[かた]が異[こと]なる。", "sentence_source": "generated"}, {"text": "景気が悪くなれば、観光のセクターは大きな影響を受けるだろう。", "target_word": "セクター", "complexity_tier": "T5", "furigana": "景気[けいき]が悪[わる]くなれば、観光[かんこう]のセクターは大[おお]きな影響[えいきょう]を受[う]けるだろう。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 産業・経済活動の部門や分野", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35403af3-e307-4569-9687-90b6f2030bed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52786, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "セクター", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "ベクター", "is_correct": false, "explanation": "最初の「せ」が「べ」に変わる一拍違いの語。"}, {"text": "ドクター", "is_correct": false, "explanation": "最初の「せ」が「ど」に変わる一拍違いの語。"}, {"text": "ファクター", "is_correct": false, "explanation": "最初の「せ」が「ふぁ」に変わる一拍違いの語。"}], "explanations": {"セクター": "見出し語そのもの。", "ベクター": "最初の「せ」が「べ」に変わる一拍違いの語。", "ドクター": "最初の「せ」が「ど」に変わる一拍違いの語。", "ファクター": "最初の「せ」が「ふぁ」に変わる一拍違いの語。"}, "sentence_index": null, "correct_answer": "セクター"}, "level_3": {"options": [{"text": "セクター", "is_correct": true, "explanation": "産業の部門を表し、「産業セクター」と自然に使える。"}, {"text": "楽器", "is_correct": false, "explanation": "形は合うが意味が合わない。排出量の抑制と関係がない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。「産業天気」という分野は成り立たない。"}, {"text": "毛布", "is_correct": false, "explanation": "形は合うが意味が合わない。産業の部門を表さない。"}], "explanations": {"セクター": "産業の部門を表し、「産業セクター」と自然に使える。", "楽器": "形は合うが意味が合わない。排出量の抑制と関係がない。", "天気": "形は合うが意味が合わない。「産業天気」という分野は成り立たない。", "毛布": "形は合うが意味が合わない。産業の部門を表さない。"}, "sentence_index": 0, "correct_answer": "セクター"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は朝ごはんにセクターを食べました。", "explanation": "セクターは産業の部門で、食べ物ではない。"}, {"text": "昨日、友達と大きなセクターで映画を見た。", "explanation": "セクターは映画を見る場所ではなく、産業の部門を指す。"}, {"text": "彼の誕生日に、きれいなセクターを贈った。", "explanation": "セクターは贈り物になる物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52786, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "セクター", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "セーター", "is_correct": false, "explanation": "「く」が長音「ー」に変わる一拍違いの語。"}, {"text": "セッター", "is_correct": false, "explanation": "「く」が促音「っ」に変わる一拍違いの語。"}, {"text": "アクター", "is_correct": false, "explanation": "最初の「せ」が「あ」に変わる一拍違いの語。"}], "explanations": {"セクター": "見出し語そのもの。", "セーター": "「く」が長音「ー」に変わる一拍違いの語。", "セッター": "「く」が促音「っ」に変わる一拍違いの語。", "アクター": "最初の「せ」が「あ」に変わる一拍違いの語。"}, "sentence_index": null, "correct_answer": "セクター"}, "level_3": {"options": [{"text": "セクター", "is_correct": true, "explanation": "「エネルギーのセクター」で産業の部門を表し、支援の対象になる。"}, {"text": "台所", "is_correct": false, "explanation": "形は合うが意味が合わない。政府が支援する産業の区分ではない。"}, {"text": "靴下", "is_correct": false, "explanation": "形は合うが意味が合わない。エネルギーの部門を表さない。"}, {"text": "挨拶", "is_correct": false, "explanation": "形は合うが意味が合わない。政府が支援する対象として不自然。"}], "explanations": {"セクター": "「エネルギーのセクター」で産業の部門を表し、支援の対象になる。", "台所": "形は合うが意味が合わない。政府が支援する産業の区分ではない。", "靴下": "形は合うが意味が合わない。エネルギーの部門を表さない。", "挨拶": "形は合うが意味が合わない。政府が支援する対象として不自然。"}, "sentence_index": 6, "correct_answer": "セクター"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の日に、セクターをさして歩いた。", "explanation": "セクターは傘のような持ち物ではなく、産業の部門を指す。"}, {"text": "田中さんは日本のセクターで、とても優しい人だ。", "explanation": "セクターは人を指す語ではなく、産業の部門を指す。"}, {"text": "セクターを飲んで、のどの渇きがなくなった。", "explanation": "セクターは飲み物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52786, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は医療のセクターを働いている。", "corrected_sentence": "彼女は医療のセクターで働いている。", "error_description": "働く場所・分野は「で」で示す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52786, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "成長しているセクターを、お金が集まっている。", "corrected_sentence": "成長しているセクターに、お金が集まっている。", "error_description": "「集まる」は集まる先を「に」で示す。「セクターを」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52787, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「既存」が名詞「もの」を修飾するので「の」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「既存をものを使います」は「を」が重なり、文法的に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「既存へものを使います」は方向の「へ」がつながらず、文法的に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「既存にものを使います」は「に」の後がつながらず、文法的に合わない。"}], "correct_answer": "の", "explanations": {"の": "「既存」が名詞「もの」を修飾するので「の」が入る。", "を": "「既存をものを使います」は「を」が重なり、文法的に合わない。", "へ": "「既存へものを使います」は方向の「へ」がつながらず、文法的に合わない。", "に": "「既存にものを使います」は「に」の後がつながらず、文法的に合わない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "に": "target_location"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新規", "is_correct": true, "explanation": "「既存」に対して、新しく作ることを表す反対語。"}, {"text": "現存", "is_correct": false, "explanation": "「現存」は「既存」と近い意味の類義語で、反対語ではない。"}, {"text": "従来", "is_correct": false, "explanation": "「従来」は以前からあることを表し、反対語ではない。"}, {"text": "既成", "is_correct": false, "explanation": "「既成」はすでにできあがっていることで、反対語ではない。"}], "correct_answer": "新規", "explanations": {"新規": "「既存」に対して、新しく作ることを表す反対語。", "現存": "「現存」は「既存」と近い意味の類義語で、反対語ではない。", "従来": "「従来」は以前からあることを表し、反対語ではない。", "既成": "「既成」はすでにできあがっていることで、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52787, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「調べる」の目的語「既存の物」を示す「を」が入る。"}, {"text": "の", "is_correct": false, "explanation": "「既存の物の調べてから」は名詞につながらず、文法的に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「既存の物へ調べてから」は方向の「へ」が「調べる」と合わず、文法的に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「既存の物に調べてから」は「調べる」の目的語を「に」で示せず、文法的に合わない。"}], "correct_answer": "を", "explanations": {"を": "「調べる」の目的語「既存の物」を示す「を」が入る。", "の": "「既存の物の調べてから」は名詞につながらず、文法的に合わない。", "へ": "「既存の物へ調べてから」は方向の「へ」が「調べる」と合わず、文法的に合わない。", "に": "「既存の物に調べてから」は「調べる」の目的語を「に」で示せず、文法的に合わない。"}, "error_tags": {"の": "possessive", "へ": "direction", "に": "target_location"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新規", "is_correct": true, "explanation": "「既存」に対して、新しい方法・新しいものを表す反対語。"}, {"text": "既設", "is_correct": false, "explanation": "「既設」はすでに設置されていることで、「既存」に近い類義語。"}, {"text": "現行", "is_correct": false, "explanation": "「現行」は今行われていることで、反対語ではない。"}, {"text": "在来", "is_correct": false, "explanation": "「在来」は以前からあることで、「既存」に近い意味。"}], "correct_answer": "新規", "explanations": {"新規": "「既存」に対して、新しい方法・新しいものを表す反対語。", "既設": "「既設」はすでに設置されていることで、「既存」に近い類義語。", "現行": "「現行」は今行われていることで、反対語ではない。", "在来": "「在来」は以前からあることで、「既存」に近い意味。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52787, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "もうあること。", "primary_collocate": null, "pronunciation": "きそん", "ipa": "kisoɴ", "syllable_count": 3, "sentences": [{"text": "既存の本棚に、新しい本を並べた。", "target_word": "既存", "complexity_tier": "T2", "furigana": "既存[きそん]の本棚[ほんだな]に、新[あたら]しい本[ほん]を並[なら]べた。", "sentence_source": "generated"}, {"text": "既存のものを使います。", "target_word": "既存", "complexity_tier": "T1", "furigana": "既存[きそん]のものを使[つか]います。", "sentence_source": "generated"}, {"text": "既存の道具だけで足りた。", "target_word": "既存", "complexity_tier": "T1", "furigana": "既存[きそん]の道具[どうぐ]だけで足[た]りた。", "sentence_source": "generated"}, {"text": "道は既存のものを使い、新しく作らなかった。", "target_word": "既存", "complexity_tier": "T2", "furigana": "道[みち]は既存[きそん]のものを使[つか]い、新[あたら]しく作[つく]らなかった。", "sentence_source": "generated"}, {"text": "既存の物と同じ形で作ってください。", "target_word": "既存", "complexity_tier": "T3", "furigana": "既存[きそん]の物[もの]と同[おな]じ形[かたち]で作[つく]ってください。", "sentence_source": "generated"}, {"text": "既存の部屋を、会議室に変えた。", "target_word": "既存", "complexity_tier": "T3", "furigana": "既存[きそん]の部屋[へや]を、会議室[かいぎしつ]に変[か]えた。", "sentence_source": "generated"}, {"text": "新しい案は既存の案より分かりやすい。", "target_word": "既存", "complexity_tier": "T2", "furigana": "新[あたら]しい案[あん]は既存[きそん]の案[あん]より分[わ]かりやすい。", "sentence_source": "generated"}, {"text": "既存の物を調べてから、足りない物を買った。", "target_word": "既存", "complexity_tier": "T3", "furigana": "既存[きそん]の物[もの]を調[しら]べてから、足[た]りない物[もの]を買[か]った。", "sentence_source": "generated"}, {"text": "既存の物を捨てずに、直して使おう。", "target_word": "既存", "complexity_tier": "T3", "furigana": "既存[きそん]の物[もの]を捨[す]てずに、直[なお]して使[つか]おう。", "sentence_source": "generated"}, {"text": "既存の方法では対応できないので、新しい方法を探している。", "target_word": "既存", "complexity_tier": "T4", "furigana": "既存[きそん]の方法[ほうほう]では対応[たいおう]できないので、新[あたら]しい方法[ほうほう]を探[さが]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "既存顧客", "label": "派生"}, {"form": "既存店", "label": "派生"}, {"form": "既存システム", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | もうあること・すでにある物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ac3fe2-6ce0-4a2e-b7a6-92b185db239c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52787, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "既存", "is_correct": true, "explanation": "「きそん」が見出し語で、これが正解。"}, {"text": "子孫", "is_correct": false, "explanation": "「しそん」で、最初の「き」が「し」に変わっている。"}, {"text": "基本", "is_correct": false, "explanation": "「きほん」で、二つ目の「そ」が「ほ」に変わっている。"}, {"text": "規則", "is_correct": false, "explanation": "「きそく」で、最後の「ん」が「く」に変わっている。"}, {"text": "起草", "is_correct": false, "explanation": "「きそう」で、最後の「ん」が「う」に変わっている。"}], "explanations": {"既存": "「きそん」が見出し語で、これが正解。", "子孫": "「しそん」で、最初の「き」が「し」に変わっている。", "基本": "「きほん」で、二つ目の「そ」が「ほ」に変わっている。", "規則": "「きそく」で、最後の「ん」が「く」に変わっている。", "起草": "「きそう」で、最後の「ん」が「う」に変わっている。"}, "sentence_index": null, "correct_answer": "既存"}, "level_3": {"options": [{"text": "既存", "is_correct": true, "explanation": "すでにある本棚に新しい本を並べるという意味で、文に合う。"}, {"text": "空腹", "is_correct": false, "explanation": "形は合うが意味が合わない。本棚がおなかをすかせることはない。"}, {"text": "寝坊", "is_correct": false, "explanation": "形は合うが意味が合わない。「寝坊の本棚」では意味が通らない。"}, {"text": "満腹", "is_correct": false, "explanation": "形は合うが意味が合わない。本棚が満腹になることはない。"}], "explanations": {"既存": "すでにある本棚に新しい本を並べるという意味で、文に合う。", "空腹": "形は合うが意味が合わない。本棚がおなかをすかせることはない。", "寝坊": "形は合うが意味が合わない。「寝坊の本棚」では意味が通らない。", "満腹": "形は合うが意味が合わない。本棚が満腹になることはない。"}, "sentence_index": 0, "correct_answer": "既存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は先週できたばかりなので、既存の建物だ。", "explanation": "「既存」はもうあることを表すので、先週できたばかりという内容と矛盾する。"}, {"text": "彼は既存に宿題を終えて、遊びに出かけた。", "explanation": "「既存」は名詞で、「すでに」の意味の副詞としては使えない。"}, {"text": "私は既存を飲んで、のどの渇きを癒やした。", "explanation": "「既存」は飲む対象ではなく、「飲む」との組み合わせが成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
