INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52788, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「生かす」の目的語「既存の設備」を示す「を」が入る。"}, {"text": "の", "is_correct": false, "explanation": "「既存の設備の生かして」は名詞につながらず、文法的に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「既存の設備へ生かして」は方向の「へ」が「生かす」と合わず、文法的に合わない。"}, {"text": "が", "is_correct": false, "explanation": "「生かす」は他動詞なので、生かす対象を「が」で示すことはできない。"}], "correct_answer": "を", "explanations": {"を": "「生かす」の目的語「既存の設備」を示す「を」が入る。", "の": "「既存の設備の生かして」は名詞につながらず、文法的に合わない。", "へ": "「既存の設備へ生かして」は方向の「へ」が「生かす」と合わず、文法的に合わない。", "が": "「生かす」は他動詞なので、生かす対象を「が」で示すことはできない。"}, "error_tags": {"の": "possessive", "へ": "direction", "が": "subject_marker"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新規", "is_correct": true, "explanation": "「既存」に対して、新しく作られたものを表す反対語。"}, {"text": "既設", "is_correct": false, "explanation": "「既設」はすでに設置されていることで、「既存」に近い類義語。"}, {"text": "現行", "is_correct": false, "explanation": "「現行」は今行われていることで、反対語ではない。"}, {"text": "既往", "is_correct": false, "explanation": "「既往」は過ぎ去った事柄を指し、反対語ではない。"}], "correct_answer": "新規", "explanations": {"新規": "「既存」に対して、新しく作られたものを表す反対語。", "既設": "「既設」はすでに設置されていることで、「既存」に近い類義語。", "現行": "「現行」は今行われていることで、反対語ではない。", "既往": "「既往」は過ぎ去った事柄を指し、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52788, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "すでに存在していること。現存しているもの。", "primary_collocate": null, "pronunciation": "きそん", "ipa": "kisoɴ", "syllable_count": 3, "sentences": [{"text": "既存の緑地と有機的にネットワークを形成することで生態系の回廊としての機能を補完し、ひいては地域全体の環境リテラシーを向上させる原動力となり得るのである。", "target_word": "既存", "complexity_tier": "T6", "furigana": "既存[きそん]の緑地[りょくち]と有機的[ゆうきてき]にネットワークを形成[けいせい]することで生態系[せいたいけい]の回廊[かいろう]としての機能[きのう]を補完[ほかん]し、ひいては地域[ちいき]全体[ぜんたい]の環境[かんきょう]リテラシーを向上[こうじょう]させる原動力[げんどうりょく]となり得[え]るのである。", "sentence_source": "mined"}, {"text": "既存の道を使う。", "target_word": "既存", "complexity_tier": "T1", "furigana": "既存[きそん]の道[みち]を使[つか]う。", "sentence_source": "generated"}, {"text": "この道は既存のもので、橋だけ新しい。", "target_word": "既存", "complexity_tier": "T2", "furigana": "この道[みち]は既存[きそん]のもので、橋[はし]だけ新[あたら]しい。", "sentence_source": "generated"}, {"text": "既存と新規を分けて数えます。", "target_word": "既存", "complexity_tier": "T2", "furigana": "既存[きそん]と新規[しんき]を分[わ]けて数[かぞ]えます。", "sentence_source": "generated"}, {"text": "新しい機能は既存のシステムと合わない。", "target_word": "既存", "complexity_tier": "T3", "furigana": "新[あたら]しい機能[きのう]は既存[きそん]のシステムと合[あ]わない。", "sentence_source": "generated"}, {"text": "既存の店舗を改装して、カフェにした。", "target_word": "既存", "complexity_tier": "T3", "furigana": "既存[きそん]の店舗[てんぽ]を改装[かいそう]して、カフェにした。", "sentence_source": "generated"}, {"text": "新しい客より、既存の客を優先して案内した。", "target_word": "既存", "complexity_tier": "T3", "furigana": "新[あたら]しい客[きゃく]より、既存[きそん]の客[きゃく]を優先[ゆうせん]して案内[あんない]した。", "sentence_source": "generated"}, {"text": "費用は、既存の設備を生かして抑えることにした。", "target_word": "既存", "complexity_tier": "T3", "furigana": "費用[ひよう]は、既存[きそん]の設備[せつび]を生[い]かして抑[おさ]えることにした。", "sentence_source": "generated"}, {"text": "既存の技術を超える方法が求められている。", "target_word": "既存", "complexity_tier": "T4", "furigana": "既存[きそん]の技術[ぎじゅつ]を超[こ]える方法[ほうほう]が求[もと]められている。", "sentence_source": "generated"}, {"text": "新製品は既存の製品より軽く、値段も安い。", "target_word": "既存", "complexity_tier": "T3", "furigana": "新製品[しんせいひん]は既存[きそん]の製品[せいひん]より軽[かる]く、値段[ねだん]も安[やす]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "既存顧客", "label": "派生"}, {"form": "既存店", "label": "派生"}, {"form": "既存システム", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | すでに存在していること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 5 words above tier T2 (max 3): 緑地 (Zipf 3.09), 回廊 (Zipf 3.11), ひいては (Zipf 3.24), リテラシー (Zipf 3.08), 原動力 (Zipf 3.4)']::text[], '57ac3fe2-6ce0-4a2e-b7a6-92b185db239c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52788, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "既存", "is_correct": true, "explanation": "「きそん」が見出し語で、これが正解。"}, {"text": "子孫", "is_correct": false, "explanation": "「しそん」で、最初の「き」が「し」に変わっている。"}, {"text": "基本", "is_correct": false, "explanation": "「きほん」で、二つ目の「そ」が「ほ」に変わっている。"}, {"text": "規則", "is_correct": false, "explanation": "「きそく」で、最後の「ん」が「く」に変わっている。"}, {"text": "起草", "is_correct": false, "explanation": "「きそう」で、最後の「ん」が「う」に変わっている。"}], "explanations": {"既存": "「きそん」が見出し語で、これが正解。", "子孫": "「しそん」で、最初の「き」が「し」に変わっている。", "基本": "「きほん」で、二つ目の「そ」が「ほ」に変わっている。", "規則": "「きそく」で、最後の「ん」が「く」に変わっている。", "起草": "「きそう」で、最後の「ん」が「う」に変わっている。"}, "sentence_index": null, "correct_answer": "既存"}, "level_3": {"options": [{"text": "既存", "is_correct": true, "explanation": "すでにある緑地という意味になり、文に合う。"}, {"text": "架空", "is_correct": false, "explanation": "形は合うが意味が合わない。実在しない緑地とは生態系のネットワークを形成できない。"}, {"text": "月面", "is_correct": false, "explanation": "形は合うが意味が合わない。月面の緑地は地域の環境の文脈に合わない。"}, {"text": "水中", "is_correct": false, "explanation": "形は合うが意味が合わない。水中の緑地では地域のネットワークの話にならない。"}], "explanations": {"既存": "すでにある緑地という意味になり、文に合う。", "架空": "形は合うが意味が合わない。実在しない緑地とは生態系のネットワークを形成できない。", "月面": "形は合うが意味が合わない。月面の緑地は地域の環境の文脈に合わない。", "水中": "形は合うが意味が合わない。水中の緑地では地域のネットワークの話にならない。"}, "sentence_index": 0, "correct_answer": "既存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来年作られる予定の既存の橋を、見に行った。", "explanation": "「既存」はすでにあるものを指すので、これから作る予定の橋には使えない。"}, {"text": "宿題はもう既存だから、遊びに行ける。", "explanation": "「既存」は「すでに済んでいる」の意味ではなく、完了を表す語としては誤用。"}, {"text": "このスープは既存の味がして、とても辛い。", "explanation": "「既存」は味の特徴を表す語ではなく、「独特な」といった意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52788, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "既存", "is_correct": true, "explanation": "「きそん」が見出し語で、これが正解。"}, {"text": "自尊", "is_correct": false, "explanation": "「じそん」で、最初の「き」が「じ」に変わっている。"}, {"text": "期間", "is_correct": false, "explanation": "「きかん」で、二つ目の「そ」が「か」に変わっている。"}, {"text": "起源", "is_correct": false, "explanation": "「きげん」で、二つ目の「そ」が「げ」に変わっている。"}, {"text": "汽船", "is_correct": false, "explanation": "「きせん」で、二つ目の「そ」が「せ」に変わっている。"}], "explanations": {"既存": "「きそん」が見出し語で、これが正解。", "自尊": "「じそん」で、最初の「き」が「じ」に変わっている。", "期間": "「きかん」で、二つ目の「そ」が「か」に変わっている。", "起源": "「きげん」で、二つ目の「そ」が「げ」に変わっている。", "汽船": "「きせん」で、二つ目の「そ」が「せ」に変わっている。"}, "sentence_index": null, "correct_answer": "既存"}, "level_3": {"options": [{"text": "既存", "is_correct": true, "explanation": "新しい客に対して、すでにいる客を指し、文に合う。"}, {"text": "月面", "is_correct": false, "explanation": "形は合うが意味が合わない。月面の客を店で優先して案内することはない。"}, {"text": "空想", "is_correct": false, "explanation": "形は合うが意味が合わない。空想の客は実在せず、案内できない。"}, {"text": "地底", "is_correct": false, "explanation": "形は合うが意味が合わない。地底の客を優先して案内する場面は考えにくい。"}], "explanations": {"既存": "新しい客に対して、すでにいる客を指し、文に合う。", "月面": "形は合うが意味が合わない。月面の客を店で優先して案内することはない。", "空想": "形は合うが意味が合わない。空想の客は実在せず、案内できない。", "地底": "形は合うが意味が合わない。地底の客を優先して案内する場面は考えにくい。"}, "sentence_index": 6, "correct_answer": "既存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "まだ作っていない既存の家具を、今から買いに行く。", "explanation": "「既存」はすでにあるものなので、まだ作っていない家具とは矛盾する。"}, {"text": "既存を食べて、お腹がいっぱいになった。", "explanation": "「既存」は食べる対象ではなく、「食べる」との組み合わせが成り立たない。"}, {"text": "みんなで既存を歌って、楽しい時間を過ごした。", "explanation": "「既存」は歌える作品の名前ではなく、「歌う」との組み合わせが成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52788, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先週できたばかりの既存の店で、食事をした。", "corrected_sentence": "先週できたばかりの新しい店で、食事をした。", "error_description": "「既存」はすでにあるものを指すので、先週できたばかりの店には合わない。「新しい」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
