INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52789, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "ささやか", "is_correct": true, "explanation": "非常に大きいことの反対で、小さく控えめなこと。"}, {"text": "莫大", "is_correct": false, "explanation": "非常に大きいという意味で、類義であって反対ではない。"}, {"text": "広大", "is_correct": false, "explanation": "非常に広く大きいという意味で、反対ではない。"}, {"text": "膨大", "is_correct": false, "explanation": "非常に大きな量を表し、反対ではない。"}], "correct_answer": "ささやか", "explanations": {"ささやか": "非常に大きいことの反対で、小さく控えめなこと。", "莫大": "非常に大きいという意味で、類義であって反対ではない。", "広大": "非常に広く大きいという意味で、反対ではない。", "膨大": "非常に大きな量を表し、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
