INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52789, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "何かがどれくらい大きいか、ぜんぶは知ることができないこと。", "primary_collocate": null, "pronunciation": "はかりしれる", "ipa": "hakaɾiɕiɾeɾɯ", "syllable_count": 6, "sentences": [{"text": "計り知れない力だ。", "target_word": "計り知れない", "complexity_tier": "T1", "furigana": "計[はか]り知[し]れない力[ちから]だ。", "sentence_source": "generated"}, {"text": "彼の優しさは計り知れないものだ。", "target_word": "計り知れない", "complexity_tier": "T2", "furigana": "彼[かれ]の優[やさ]しさは計[はか]り知[し]れないものだ。", "sentence_source": "generated"}, {"text": "海の深さは計り知れない。", "target_word": "計り知れない", "complexity_tier": "T2", "furigana": "海[うみ]の深[ふか]さは計[はか]り知[し]れない。", "sentence_source": "generated"}, {"text": "彼女の悲しみは計り知れません。", "target_word": "計り知れません", "complexity_tier": "T2", "furigana": "彼女[かのじょ]の悲[かな]しみは計[はか]り知[し]れません。", "sentence_source": "generated"}, {"text": "計り知れないほど大きな山だった。", "target_word": "計り知れない", "complexity_tier": "T3", "furigana": "計[はか]り知[し]れないほど大[おお]きな山[やま]だった。", "sentence_source": "generated"}, {"text": "この森の広さは、だれにも計り知れなかった。", "target_word": "計り知れなかった", "complexity_tier": "T3", "furigana": "この森[もり]の広[ひろ]さは、だれにも計[はか]り知[し]れなかった。", "sentence_source": "generated"}, {"text": "計り知れない数の星が空に見える。", "target_word": "計り知れない", "complexity_tier": "T3", "furigana": "計[はか]り知[し]れない数[かず]の星[ほし]が空[そら]に見[み]える。", "sentence_source": "generated"}, {"text": "先生への感謝は計り知れず、言葉にできない。", "target_word": "計り知れず", "complexity_tier": "T3", "furigana": "先生[せんせい]への感謝[かんしゃ]は計[はか]り知[し]れず、言葉[ことば]にできない。", "sentence_source": "generated"}, {"text": "その影響がどこまで広がるか、今は計り知れない。", "target_word": "計り知れない", "complexity_tier": "T4", "furigana": "その影響[えいきょう]がどこまで広[ひろ]がるか、今[いま]は計[はか]り知[し]れない。", "sentence_source": "generated"}, {"text": "計り知れない危険があると知らされた。", "target_word": "計り知れない", "complexity_tier": "T4", "furigana": "計[はか]り知[し]れない危険[きけん]があると知[し]らされた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "計り知れない", "label": "活用"}, {"form": "計り知れず", "label": "活用"}, {"form": "計り知れなかった", "label": "活用"}, {"form": "計り知れません", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 大きさを全部は知ることができない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ac3fe2-6ce0-4a2e-b7a6-92b185db239c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52789, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "計り知れない", "is_correct": true, "explanation": "「計り知れない力」で、大きさが全部は分からない力という意味になる。"}, {"text": "飲めない", "is_correct": false, "explanation": "形は合うが意味が合わない。「飲めない力」では力の説明にならない。"}, {"text": "行けない", "is_correct": false, "explanation": "形は合うが意味が合わない。「行けない力」では力の大きさを表せない。"}, {"text": "眠れない", "is_correct": false, "explanation": "形は合うが意味が合わない。「眠れない力」は意味が通らない。"}], "explanations": {"計り知れない": "「計り知れない力」で、大きさが全部は分からない力という意味になる。", "飲めない": "形は合うが意味が合わない。「飲めない力」では力の説明にならない。", "行けない": "形は合うが意味が合わない。「行けない力」では力の大きさを表せない。", "眠れない": "形は合うが意味が合わない。「眠れない力」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "計り知れない"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の長さを定規で計り知れない。", "explanation": "「計り知れない」は大きさが測りきれないという意味で、定規で測れる長さには使えない。"}, {"text": "小さくて軽い消しゴムの重さは計り知れない。", "explanation": "「計り知れない」は非常に大きいものに使う。小さな消しゴムの重さには合わない。"}, {"text": "彼の名前は計り知れないので、聞いてみた。", "explanation": "「計り知れない」は大きさを知りきれないことで、名前を知らない意味には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52789, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "計り知れない", "is_correct": true, "explanation": "「計り知れない数の星」で、数えきれないほど多いという意味になる。"}, {"text": "食べきれない", "is_correct": false, "explanation": "形は合うが意味が合わない。星の数を「食べきれない」とは言わない。"}, {"text": "読み切れない", "is_correct": false, "explanation": "形は合うが意味が合わない。星の数に「読み切れない」は合わない。"}, {"text": "持ち上げられない", "is_correct": false, "explanation": "形は合うが意味が合わない。星の数を持ち上げることはできない。"}], "explanations": {"計り知れない": "「計り知れない数の星」で、数えきれないほど多いという意味になる。", "食べきれない": "形は合うが意味が合わない。星の数を「食べきれない」とは言わない。", "読み切れない": "形は合うが意味が合わない。星の数に「読み切れない」は合わない。", "持ち上げられない": "形は合うが意味が合わない。星の数を持ち上げることはできない。"}, "sentence_index": 6, "correct_answer": "計り知れない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この鉛筆の長さは十五センチで、計り知れない。", "explanation": "「計り知れない」は大きすぎて測りきれないことを表すので、十五センチと分かっている長さには使えない。"}, {"text": "小さな虫の危険は計り知れないほど小さい。", "explanation": "「計り知れない」は大きいことを表すので、「小さい」とは合わない。"}, {"text": "計り知れない量の水を、コップ一杯だけ飲んだ。", "explanation": "「計り知れない」は非常に大きいことを表すので、「コップ一杯だけ」という少ない量と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
