INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52790, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "その影響や効果が非常に大きく、すべてを測り知ることができない様子。", "primary_collocate": null, "pronunciation": "はかりしれる", "ipa": "hakaɾiɕiɾeɾɯ", "syllable_count": 6, "sentences": [{"text": "さらに、こうした緑の拠点が生み出す波及効果は計り知れない。", "target_word": "計り知れない", "complexity_tier": "T6", "furigana": "さらに、こうした緑[みどり]の拠点[きょてん]が生[う]み出[だ]す波及[はきゅう]効果[こうか]は計[はか]り知[し]れない。", "sentence_source": "mined"}, {"text": "損害は計り知れない。", "target_word": "計り知れない", "complexity_tier": "T1", "furigana": "損害[そんがい]は計[はか]り知[し]れない。", "sentence_source": "generated"}, {"text": "彼は計り知れない力を持っていた。", "target_word": "計り知れない", "complexity_tier": "T2", "furigana": "彼[かれ]は計[はか]り知[し]れない力[ちから]を持[も]っていた。", "sentence_source": "generated"}, {"text": "彼の苦労は計り知れません。", "target_word": "計り知れません", "complexity_tier": "T2", "furigana": "彼[かれ]の苦労[くろう]は計[はか]り知[し]れません。", "sentence_source": "generated"}, {"text": "計り知れない影響を受けた。", "target_word": "計り知れない", "complexity_tier": "T2", "furigana": "計[はか]り知[し]れない影響[えいきょう]を受[う]けた。", "sentence_source": "generated"}, {"text": "この発見の価値は計り知れず、世界中が注目した。", "target_word": "計り知れず", "complexity_tier": "T4", "furigana": "この発見[はっけん]の価値[かち]は計[はか]り知[し]れず、世界中[せかいじゅう]が注目[ちゅうもく]した。", "sentence_source": "generated"}, {"text": "母の愛は、計り知れないほど大きい。", "target_word": "計り知れない", "complexity_tier": "T3", "furigana": "母[はは]の愛[あい]は、計[はか]り知[し]れないほど大[おお]きい。", "sentence_source": "generated"}, {"text": "事故による被害は計り知れない。", "target_word": "計り知れない", "complexity_tier": "T2", "furigana": "事故[じこ]による被害[ひがい]は計[はか]り知[し]れない。", "sentence_source": "generated"}, {"text": "計り知れない恩があるので、一生感謝したい。", "target_word": "計り知れない", "complexity_tier": "T3", "furigana": "計[はか]り知[し]れない恩[おん]があるので、一生[いっしょう]感謝[かんしゃ]したい。", "sentence_source": "generated"}, {"text": "地震が経済に与える打撃は計り知れないと言われている。", "target_word": "計り知れない", "complexity_tier": "T4", "furigana": "地震[じしん]が経済[けいざい]に与[あた]える打撃[だげき]は計[はか]り知[し]れないと言[い]われている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "計り知れない", "label": "活用"}, {"form": "計り知れず", "label": "活用"}, {"form": "計り知れなかった", "label": "活用"}, {"form": "計り知れません", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 影響や大きさが測り知れない様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ac3fe2-6ce0-4a2e-b7a6-92b185db239c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52790, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "計り知れない", "is_correct": true, "explanation": "波及効果が非常に大きく測りきれないという意味で、文に合う。"}, {"text": "飲めない", "is_correct": false, "explanation": "形は合うが意味が合わない。効果は飲むものではなく、文脈に合わない。"}, {"text": "眠れない", "is_correct": false, "explanation": "形は合うが意味が合わない。波及効果が眠れないという表現は成り立たない。"}, {"text": "泳げない", "is_correct": false, "explanation": "形は合うが意味が合わない。波及効果が泳げないという表現は成り立たない。"}], "explanations": {"計り知れない": "波及効果が非常に大きく測りきれないという意味で、文に合う。", "飲めない": "形は合うが意味が合わない。効果は飲むものではなく、文脈に合わない。", "眠れない": "形は合うが意味が合わない。波及効果が眠れないという表現は成り立たない。", "泳げない": "形は合うが意味が合わない。波及効果が泳げないという表現は成り立たない。"}, "sentence_index": 0, "correct_answer": "計り知れない"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱の重さは計り知れないので、すぐに分かった。", "explanation": "「計り知れない」は測りきれないことを表すので、すぐに分かったという内容と矛盾する。"}, {"text": "定規で長さを測ったら、計り知れない三センチだった。", "explanation": "「計り知れない」は非常に大きいものに使う語で、三センチのような小さい量には使えない。"}, {"text": "彼女は計り知れない料理を食べて、お腹がいっぱいになった。", "explanation": "「計り知れない」は影響や価値などの大きさを表し、料理を修飾する使い方はできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52790, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "計り知れない", "is_correct": true, "explanation": "母の愛が測りきれないほど大きいという意味で、文に合う。"}, {"text": "泳げない", "is_correct": false, "explanation": "形は合うが意味が合わない。愛の大きさを泳げないという言い方はできない。"}, {"text": "飛べない", "is_correct": false, "explanation": "形は合うが意味が合わない。愛の大きさを飛べないという言い方はできない。"}, {"text": "歩けない", "is_correct": false, "explanation": "形は合うが意味が合わない。愛の大きさを歩けないという言い方はできない。"}], "explanations": {"計り知れない": "母の愛が測りきれないほど大きいという意味で、文に合う。", "泳げない": "形は合うが意味が合わない。愛の大きさを泳げないという言い方はできない。", "飛べない": "形は合うが意味が合わない。愛の大きさを飛べないという言い方はできない。", "歩けない": "形は合うが意味が合わない。愛の大きさを歩けないという言い方はできない。"}, "sentence_index": 6, "correct_answer": "計り知れない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "テーブルの上のコップは小さくて、計り知れない。", "explanation": "「計り知れない」は非常に大きいものに使う語で、小さいコップには使えない。"}, {"text": "彼は計り知れない声で、小さく返事をした。", "explanation": "「計り知れない」は声の様子を表す語ではなく、小さな声という内容とも矛盾する。"}, {"text": "計り知れないので、駅までの時間はちょうど五分だ。", "explanation": "測りきれないという意味と、ちょうど五分と分かっていることが矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52790, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この政策がもたらす影響は計り知れる。", "corrected_sentence": "この政策がもたらす影響は計り知れない。", "error_description": "「計り知れる」は肯定形で意味が通らない。影響が大きく測りきれないことを表すには「計り知れない」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "計り知れない", "is_correct": true, "explanation": "損害の大きさを測りきれないという否定形で、文に合う。"}, {"text": "計り知れて", "is_correct": false, "explanation": "て形では文が終わらず、この位置には入らない。"}, {"text": "計り知れれば", "is_correct": false, "explanation": "仮定形では文が終わらず、この位置には入らない。"}, {"text": "計り知れ", "is_correct": false, "explanation": "連用形では文が終わらず、この位置には入らない。"}], "correct_form": "計り知れない", "base_form": "計り知れる", "form_label": "否定形（ない形）", "sentence_index": 1, "explanations": {"計り知れない": "損害の大きさを測りきれないという否定形で、文に合う。", "計り知れて": "て形では文が終わらず、この位置には入らない。", "計り知れれば": "仮定形では文が終わらず、この位置には入らない。", "計り知れ": "連用形では文が終わらず、この位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52790, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の功績は世界に対して計り知れないだ。", "corrected_sentence": "彼の功績は世界に対して計り知れない。", "error_description": "「計り知れない」の後に「だ」を付けるのは誤り。「ない」で言い切る形が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "計り知れない", "is_correct": true, "explanation": "事故の被害が非常に大きく測りきれないという否定形で、文に合う。"}, {"text": "計り知れ", "is_correct": false, "explanation": "連用形では文が終わらず、この位置には入らない。"}, {"text": "計り知れて", "is_correct": false, "explanation": "て形では文が終わらず、この位置には入らない。"}, {"text": "計り知れれば", "is_correct": false, "explanation": "仮定形では文が終わらず、この位置には入らない。"}], "correct_form": "計り知れない", "base_form": "計り知れる", "form_label": "否定形（ない形）", "sentence_index": 7, "explanations": {"計り知れない": "事故の被害が非常に大きく測りきれないという否定形で、文に合う。", "計り知れ": "連用形では文が終わらず、この位置には入らない。", "計り知れて": "て形では文が終わらず、この位置には入らない。", "計り知れれば": "仮定形では文が終わらず、この位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
