INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52791, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二酸化炭素を集めて、地面の深いところにしまうこと。", "primary_collocate": null, "pronunciation": "しーしーゆーえす", "ipa": "ɕiːɕiːjuːesu", "syllable_count": 8, "sentences": [{"text": "CCUS は、工場から出る二酸化炭素を集めて地下にためる技術だ。", "target_word": "CCUS", "complexity_tier": "T3", "furigana": "CCUS は、工場[こうじょう]から出[で]る二酸化炭素[にさんかたんそ]を集[あつ]めて地下[ちか]にためる技術[ぎじゅつ]だ。", "sentence_source": "generated"}, {"text": "政府は温暖化を防ぐため、CCUS の研究に力を入れている。", "target_word": "CCUS", "complexity_tier": "T3", "furigana": "政府[せいふ]は温暖化[おんだんか]を防[ふせ]ぐため、CCUS の研究[けんきゅう]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "CCUS が広まれば、石炭を使う発電所も二酸化炭素を減らせるかもしれない。", "target_word": "CCUS", "complexity_tier": "T3", "furigana": "CCUS が広[ひろ]まれば、石炭[せきたん]を使[つか]う発電所[はつでんしょ]も二酸化炭素[にさんかたんそ]を減[へ]らせるかもしれない。", "sentence_source": "generated"}, {"text": "CCUS には費用が高いという課題がある。", "target_word": "CCUS", "complexity_tier": "T3", "furigana": "CCUS には費用[ひよう]が高[たか]いという課題[かだい]がある。", "sentence_source": "generated"}, {"text": "海の下の古いガス田は、CCUS で二酸化炭素をしまう場所として注目されている。", "target_word": "CCUS", "complexity_tier": "T3", "furigana": "海[うみ]の下[した]の古[ふる]いガス田[でん]は、CCUS で二酸化炭素[にさんかたんそ]をしまう場所[ばしょ]として注目[ちゅうもく]されている。", "sentence_source": "generated"}, {"text": "この会社は CCUS の設備を作って、海外にも売っている。", "target_word": "CCUS", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は CCUS の設備[せつび]を作[つく]って、海外[かいがい]にも売[う]っている。", "sentence_source": "generated"}, {"text": "二酸化炭素をためた地層から漏れないか、CCUS では長い間調べ続ける。", "target_word": "CCUS", "complexity_tier": "T3", "furigana": "二酸化炭素[にさんかたんそ]をためた地層[ちそう]から漏[も]れないか、CCUS では長[なが]い間[あいだ]調[しら]べ続[つづ]ける。", "sentence_source": "generated"}, {"text": "専門家は、CCUS だけでは温暖化は止まらないと話している。", "target_word": "CCUS", "complexity_tier": "T3", "furigana": "専門家[せんもんか]は、CCUS だけでは温暖化[おんだんか]は止[と]まらないと話[はな]している。", "sentence_source": "generated"}, {"text": "製鉄所は、CCUS を導入して二酸化炭素の排出を大きく減らす計画だ。", "target_word": "CCUS", "complexity_tier": "T3", "furigana": "製鉄所[せいてつじょ]は、CCUS を導入[どうにゅう]して二酸化炭素[にさんかたんそ]の排出[はいしゅつ]を大[おお]きく減[へ]らす計画[けいかく]だ。", "sentence_source": "generated"}, {"text": "新しい発電所は、CCUS を使って環境への負担を減らしている。", "target_word": "CCUS", "complexity_tier": "T3", "furigana": "新[あたら]しい発電所[はつでんしょ]は、CCUS を使[つか]って環境[かんきょう]への負担[ふたん]を減[へ]らしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "CCUS", "label": "基本形"}], "register": "専門", "sense_fingerprint": "二酸化炭素を集めて地下に貯める技術", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6fe5c65-9a1d-44c6-9f19-15b31205c511') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52791, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "CCUS", "is_correct": true, "explanation": "排ガスの二酸化炭素を集めて地下に貯める技術の名称で、文の主語に合う。"}, {"text": "太陽光", "is_correct": false, "explanation": "太陽光は発電方式で、二酸化炭素を地下に貯める技術ではないので合わない。"}, {"text": "石炭", "is_correct": false, "explanation": "石炭は燃料の名前で、貯留技術の説明の主語にはならない。"}, {"text": "水素", "is_correct": false, "explanation": "水素はエネルギー源の名前で、二酸化炭素を集める技術の説明とは合わない。"}], "explanations": {"CCUS": "排ガスの二酸化炭素を集めて地下に貯める技術の名称で、文の主語に合う。", "太陽光": "太陽光は発電方式で、二酸化炭素を地下に貯める技術ではないので合わない。", "石炭": "石炭は燃料の名前で、貯留技術の説明の主語にはならない。", "水素": "水素はエネルギー源の名前で、二酸化炭素を集める技術の説明とは合わない。"}, "sentence_index": 0, "correct_answer": "CCUS"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この新しいアプリは、CCUS で写真を編集できる。", "explanation": "ここは〈ソフト〉の意味。CCUS は地下に二酸化炭素を貯める技術の名称で、ソフトウェアの名前ではないので合わない。"}, {"text": "彼は体が弱いので、CCUS の食事を控えている。", "explanation": "ここは〈ダイエット〉の意味。CCUS は地下貯留技術の名称で、体重を減らす方法の名前ではないので合わない。"}, {"text": "ボランティアは、CCUS で公園のごみを拾った。", "explanation": "ここは〈トング〉の意味。CCUS は技術の名称で、ごみを掴む道具の名前ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52791, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "CCUS", "is_correct": true, "explanation": "地層からの漏れを調べる対象として、二酸化炭素の貯留技術を指す文に合う。"}, {"text": "原子力", "is_correct": false, "explanation": "原子力は発電方式で、二酸化炭素の貯留を調べる文の主題にはならない。"}, {"text": "風力", "is_correct": false, "explanation": "風力は発電方式で、地層への二酸化炭素の貯留を説明する文とは合わない。"}, {"text": "地熱", "is_correct": false, "explanation": "地熱は地下の熱を使うエネルギーで、貯留の漏れを調べる文には合わない。"}], "explanations": {"CCUS": "地層からの漏れを調べる対象として、二酸化炭素の貯留技術を指す文に合う。", "原子力": "原子力は発電方式で、二酸化炭素の貯留を調べる文の主題にはならない。", "風力": "風力は発電方式で、地層への二酸化炭素の貯留を説明する文とは合わない。", "地熱": "地熱は地下の熱を使うエネルギーで、貯留の漏れを調べる文には合わない。"}, "sentence_index": 6, "correct_answer": "CCUS"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この新しい曲は、CCUS の気持ちを込めて作られた。", "explanation": "ここは〈思い〉の意味。CCUS は地下貯留技術の名称で、曲に込める心の働きを表す語ではないので合わない。"}, {"text": "寒い夜は、CCUS の布団で寝る。", "explanation": "ここは〈寝具〉の意味。CCUS は地下に二酸化炭素を貯める技術の名称で、寝具の種類を表す語ではない。"}, {"text": "彼は大切な人に、CCUS で手紙を書いた。", "explanation": "ここは〈ペン〉の意味。CCUS は技術の名称で、筆記用具の名前ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52791, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府は CCUS を実用化を目指している。", "corrected_sentence": "政府は CCUS の実用化を目指している。", "error_description": "「の」が正しい。「CCUS の実用化」と名詞をつなぐには「の」が必要で、「を」では文の構造が崩れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52791, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場は CCUS を使いて排出を減らす。", "corrected_sentence": "工場は CCUS を使って排出を減らす。", "error_description": "「使って」が正しい。「使いて」は動詞「使う」の て形の誤りで、音便の形が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea92751-1859-4dc6-ade0-2e3c2ba56cfc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52793, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「わたしの責務」で所有・帰属を表します。"}, {"text": "を", "is_correct": false, "explanation": "「わたしを責務だ」は文法的に成り立ちません。"}, {"text": "に", "is_correct": false, "explanation": "「わたしに責務だ」は成り立ちません。"}, {"text": "から", "is_correct": false, "explanation": "「わたしから責務だ」は成り立ちません。"}], "correct_answer": "の", "explanations": {"の": "「わたしの責務」で所有・帰属を表します。", "を": "「わたしを責務だ」は文法的に成り立ちません。", "に": "「わたしに責務だ」は成り立ちません。", "から": "「わたしから責務だ」は成り立ちません。"}, "error_tags": {"を": "object_marker", "に": "target", "から": "source"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "権利", "is_correct": true, "explanation": "しなければならない責務に対し、権利は反対の関係です。"}, {"text": "仕事", "is_correct": false, "explanation": "責務の類義で、対義語ではありません。"}, {"text": "役目", "is_correct": false, "explanation": "責務の類義で、対義語ではありません。"}, {"text": "任務", "is_correct": false, "explanation": "責務の類義で、対義語ではありません。"}], "correct_answer": "権利", "explanations": {"権利": "しなければならない責務に対し、権利は反対の関係です。", "仕事": "責務の類義で、対義語ではありません。", "役目": "責務の類義で、対義語ではありません。", "任務": "責務の類義で、対義語ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52793, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「責務を与える」で目的語を示します。"}, {"text": "が", "is_correct": false, "explanation": "「責務が与える」は成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「責務へ与える」は成り立ちません。"}, {"text": "から", "is_correct": false, "explanation": "「責務から与える」は成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「責務を与える」で目的語を示します。", "が": "「責務が与える」は成り立ちません。", "へ": "「責務へ与える」は成り立ちません。", "から": "「責務から与える」は成り立ちません。"}, "error_tags": {"が": "subject_marker", "へ": "direction", "から": "source"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "権利", "is_correct": true, "explanation": "負うべき責務に対し、権利は反対の関係です。"}, {"text": "使命", "is_correct": false, "explanation": "果たすべき務めで、類義の語です。"}, {"text": "役割", "is_correct": false, "explanation": "受け持ちを表し、対義語ではありません。"}, {"text": "義務", "is_correct": false, "explanation": "責務に近い語で、対義語ではありません。"}], "correct_answer": "権利", "explanations": {"権利": "負うべき責務に対し、権利は反対の関係です。", "使命": "果たすべき務めで、類義の語です。", "役割": "受け持ちを表し、対義語ではありません。", "義務": "責務に近い語で、対義語ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52793, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "しなければならない仕事や役目。", "primary_collocate": null, "pronunciation": "せきむ", "ipa": "sekimɯ", "syllable_count": 3, "sentences": [{"text": "これは私の責務です。", "target_word": "責務", "complexity_tier": "T2", "furigana": "これは私[わたし]の責務[せきむ]です。", "sentence_source": "generated"}, {"text": "毎日の掃除は、わたしの責務だ。", "target_word": "責務", "complexity_tier": "T3", "furigana": "毎日[まいにち]の掃除[そうじ]は、わたしの責務[せきむ]だ。", "sentence_source": "generated"}, {"text": "先生には、生徒を守る責務がある。", "target_word": "責務", "complexity_tier": "T3", "furigana": "先生[せんせい]には、生徒[せいと]を守[まも]る責務[せきむ]がある。", "sentence_source": "generated"}, {"text": "責務を果たすまで、帰れない。", "target_word": "責務", "complexity_tier": "T3", "furigana": "責務[せきむ]を果[は]たすまで、帰[かえ]れない。", "sentence_source": "generated"}, {"text": "彼は大きな責務を負っている。", "target_word": "責務", "complexity_tier": "T3", "furigana": "彼[かれ]は大[おお]きな責務[せきむ]を負[お]っている。", "sentence_source": "generated"}, {"text": "責務の重さを感じて、夜も眠れなかった。", "target_word": "責務", "complexity_tier": "T3", "furigana": "責務[せきむ]の重[おも]さを感[かん]じて、夜[よる]も眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "班長としての責務を全うした。", "target_word": "責務", "complexity_tier": "T3", "furigana": "班長[はんちょう]としての責務[せきむ]を全[まっと]うした。", "sentence_source": "generated"}, {"text": "子どもにも、家での責務を与える。", "target_word": "責務", "complexity_tier": "T3", "furigana": "子[こ]どもにも、家[いえ]での責務[せきむ]を与[あた]える。", "sentence_source": "generated"}, {"text": "責務が多すぎて、休む時間がない。", "target_word": "責務", "complexity_tier": "T3", "furigana": "責務[せきむ]が多[おお]すぎて、休[やす]む時間[じかん]がない。", "sentence_source": "generated"}, {"text": "新入社員にも責務があるはずだ。", "target_word": "責務", "complexity_tier": "T3", "furigana": "新入社員[しんにゅうしゃいん]にも責務[せきむ]があるはずだ。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | しなければならない仕事や役目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5c0cbd4-9068-402c-8710-9d8b63a52347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52793, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "責務", "is_correct": true, "explanation": "見出し語「せきむ」そのものです。"}, {"text": "政務", "is_correct": false, "explanation": "「せいむ」で、二音目が異なります。"}, {"text": "石油", "is_correct": false, "explanation": "「せきゆ」で、三音目が異なります。"}, {"text": "赤痢", "is_correct": false, "explanation": "「せきり」で、三音目が異なります。"}, {"text": "石碑", "is_correct": false, "explanation": "「せきひ」で、三音目が異なります。"}, {"text": "席次", "is_correct": false, "explanation": "「せきじ」で、三音目が異なります。"}], "explanations": {"責務": "見出し語「せきむ」そのものです。", "政務": "「せいむ」で、二音目が異なります。", "石油": "「せきゆ」で、三音目が異なります。", "赤痢": "「せきり」で、三音目が異なります。", "石碑": "「せきひ」で、三音目が異なります。", "席次": "「せきじ」で、三音目が異なります。"}, "sentence_index": null, "correct_answer": "責務"}, "level_3": {"options": [{"text": "責務", "is_correct": true, "explanation": "しなければならない仕事の意味で「私の責務です」と通ります。"}, {"text": "偶然", "is_correct": false, "explanation": "形は合うが、「私の偶然」では意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「私の天気」では意味が合わない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、「私の地震」では意味が合わない。"}], "explanations": {"責務": "しなければならない仕事の意味で「私の責務です」と通ります。", "偶然": "形は合うが、「私の偶然」では意味が合わない。", "天気": "形は合うが、「私の天気」では意味が合わない。", "地震": "形は合うが、「私の地震」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "責務"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ごはんに責務を食べた。", "explanation": "責務は仕事や役目で、食べ物ではありません。"}, {"text": "責務は小さくて、ポケットに入る。", "explanation": "責務は形のある物ではなく、ポケットに入りません。"}, {"text": "責務が降ってきたので、傘をさした。", "explanation": "責務は天気ではなく、「降る」の主語になりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52793, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "責務", "is_correct": true, "explanation": "「全うする」と結びつき、班長の務めの意味で通ります。"}, {"text": "趣味", "is_correct": false, "explanation": "形は合うが、「趣味を全うする」は班長としての意味が合わない。"}, {"text": "偶然", "is_correct": false, "explanation": "形は合うが、「偶然を全うする」では意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、「季節を全うする」では意味が合わない。"}], "explanations": {"責務": "「全うする」と結びつき、班長の務めの意味で通ります。", "趣味": "形は合うが、「趣味を全うする」は班長としての意味が合わない。", "偶然": "形は合うが、「偶然を全うする」では意味が合わない。", "季節": "形は合うが、「季節を全うする」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "責務"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "責務を聞きながら、散歩をした。", "explanation": "責務は音や話ではなく、聞いて楽しむ対象ではありません。"}, {"text": "公園の責務で、犬が遊んでいる。", "explanation": "責務は場所ではなく、「で」で場所として使えません。"}, {"text": "責務は甘くて、子どもに人気だ。", "explanation": "責務は味のある食べ物ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
