INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52794, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「責務がある」で存在の主語を示します。"}, {"text": "を", "is_correct": false, "explanation": "「責務をある」は文法的に成り立ちません。"}, {"text": "から", "is_correct": false, "explanation": "「責務からある」は成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「責務へある」は文法的に成り立ちません。"}], "correct_answer": "が", "explanations": {"が": "「責務がある」で存在の主語を示します。", "を": "「責務をある」は文法的に成り立ちません。", "から": "「責務からある」は成り立ちません。", "へ": "「責務へある」は文法的に成り立ちません。"}, "error_tags": {"を": "object_marker", "から": "source", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "権利", "is_correct": true, "explanation": "負うべき務めの責務に対し、権利は反対の関係にあります。"}, {"text": "義務", "is_correct": false, "explanation": "責務とほぼ同じ意味で、対義語ではありません。"}, {"text": "職務", "is_correct": false, "explanation": "役目を表し、責務の対義語ではありません。"}, {"text": "責任", "is_correct": false, "explanation": "近い意味で、対義語ではありません。"}], "correct_answer": "権利", "explanations": {"権利": "負うべき務めの責務に対し、権利は反対の関係にあります。", "義務": "責務とほぼ同じ意味で、対義語ではありません。", "職務": "役目を表し、責務の対義語ではありません。", "責任": "近い意味で、対義語ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52794, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「責務を受け止める」で目的語を示します。"}, {"text": "が", "is_correct": false, "explanation": "「責務が受け止めている」では意味が通りません。"}, {"text": "から", "is_correct": false, "explanation": "「責務から受け止める」は不自然で成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「責務へ受け止める」は成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「責務を受け止める」で目的語を示します。", "が": "「責務が受け止めている」では意味が通りません。", "から": "「責務から受け止める」は不自然で成り立ちません。", "へ": "「責務へ受け止める」は成り立ちません。"}, "error_tags": {"が": "subject_marker", "から": "source", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "権利", "is_correct": true, "explanation": "果たすべき責務に対し、権利は反対の関係にあります。"}, {"text": "任務", "is_correct": false, "explanation": "与えられた務めで、責務に近い語です。"}, {"text": "役割", "is_correct": false, "explanation": "受け持ちを表し、対義語ではありません。"}, {"text": "使命", "is_correct": false, "explanation": "果たすべき務めで、類義の語です。"}], "correct_answer": "権利", "explanations": {"権利": "果たすべき責務に対し、権利は反対の関係にあります。", "任務": "与えられた務めで、責務に近い語です。", "役割": "受け持ちを表し、対義語ではありません。", "使命": "果たすべき務めで、類義の語です。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52794, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "その立場や役割から当然負わなければならない務め。", "primary_collocate": null, "pronunciation": "せきむ", "ipa": "sekimɯ", "syllable_count": 3, "sentences": [{"text": "気候変動という地球的危機の緩和に向け、産業セクターにおける排出量の抑制は、持続可能性を担保する上で不可避の責務である。", "target_word": "責務", "complexity_tier": "T6", "furigana": "気候変動[きこうへんどう]という地球的[ちきゅうてき]危機[きき]の緩和[かんわ]に向[む]け、産業[さんぎょう]セクターにおける排出量[はいしゅつりょう]の抑制[よくせい]は、持続可能性[じぞくかのうせい]を担保[たんぽ]する上[うえ]で不可避[ふかひ]の責務[せきむ]である。", "sentence_source": "mined"}, {"text": "親には、子どもを守る責務がある。", "target_word": "責務", "complexity_tier": "T3", "furigana": "親[おや]には、子[こ]どもを守[まも]る責務[せきむ]がある。", "sentence_source": "generated"}, {"text": "医者の責務は、患者の命を救うことだ。", "target_word": "責務", "complexity_tier": "T3", "furigana": "医者[いしゃ]の責務[せきむ]は、患者[かんじゃ]の命[いのち]を救[すく]うことだ。", "sentence_source": "generated"}, {"text": "政府は国民の安全を守る責務を負う。", "target_word": "責務", "complexity_tier": "T3", "furigana": "政府[せいふ]は国民[こくみん]の安全[あんぜん]を守[まも]る責務[せきむ]を負[お]う。", "sentence_source": "generated"}, {"text": "彼は自分の責務を果たした。", "target_word": "責務", "complexity_tier": "T2", "furigana": "彼[かれ]は自分[じぶん]の責務[せきむ]を果[は]たした。", "sentence_source": "generated"}, {"text": "責務を放棄した社長は、厳しく批判された。", "target_word": "責務", "complexity_tier": "T4", "furigana": "責務[せきむ]を放棄[ほうき]した社長[しゃちょう]は、厳[きび]しく批判[ひはん]された。", "sentence_source": "generated"}, {"text": "企業には、環境を守るという責務があります。", "target_word": "責務", "complexity_tier": "T3", "furigana": "企業[きぎょう]には、環境[かんきょう]を守[まも]るという責務[せきむ]があります。", "sentence_source": "generated"}, {"text": "教師としての責務を、重く受け止めている。", "target_word": "責務", "complexity_tier": "T3", "furigana": "教師[きょうし]としての責務[せきむ]を、重[おも]く受[う]け止[と]めている。", "sentence_source": "generated"}, {"text": "責務の重さに、新しい部長は戸惑った。", "target_word": "責務", "complexity_tier": "T4", "furigana": "責務[せきむ]の重[おも]さに、新[あたら]しい部長[ぶちょう]は戸惑[とまど]った。", "sentence_source": "generated"}, {"text": "ここまで来て、責務から逃げることはできない。", "target_word": "責務", "complexity_tier": "T4", "furigana": "ここまで来[き]て、責務[せきむ]から逃[に]げることはできない。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 立場上当然負うべき務め", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5c0cbd4-9068-402c-8710-9d8b63a52347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52794, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "責務", "is_correct": true, "explanation": "見出し語「せきむ」そのものです。"}, {"text": "政務", "is_correct": false, "explanation": "「せいむ」で、二音目が異なります。"}, {"text": "石油", "is_correct": false, "explanation": "「せきゆ」で、三音目が異なります。"}, {"text": "赤痢", "is_correct": false, "explanation": "「せきり」で、三音目が異なります。"}, {"text": "石碑", "is_correct": false, "explanation": "「せきひ」で、三音目が異なります。"}, {"text": "席次", "is_correct": false, "explanation": "「せきじ」で、三音目が異なります。"}], "explanations": {"責務": "見出し語「せきむ」そのものです。", "政務": "「せいむ」で、二音目が異なります。", "石油": "「せきゆ」で、三音目が異なります。", "赤痢": "「せきり」で、三音目が異なります。", "石碑": "「せきひ」で、三音目が異なります。", "席次": "「せきじ」で、三音目が異なります。"}, "sentence_index": null, "correct_answer": "責務"}, "level_3": {"options": [{"text": "責務", "is_correct": true, "explanation": "立場上負うべき務めを表し、「不可避の責務である」と文意が通ります。"}, {"text": "趣味", "is_correct": false, "explanation": "形は合うが、排出量の抑制が「不可避の趣味」では意味が合わない。"}, {"text": "娯楽", "is_correct": false, "explanation": "形は合うが、「不可避の娯楽」では意味が合わない。"}, {"text": "偶然", "is_correct": false, "explanation": "形は合うが、「不可避」と「偶然」が矛盾し意味が合わない。"}], "explanations": {"責務": "立場上負うべき務めを表し、「不可避の責務である」と文意が通ります。", "趣味": "形は合うが、排出量の抑制が「不可避の趣味」では意味が合わない。", "娯楽": "形は合うが、「不可避の娯楽」では意味が合わない。", "偶然": "形は合うが、「不可避」と「偶然」が矛盾し意味が合わない。"}, "sentence_index": 0, "correct_answer": "責務"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上に責務を置いて、部屋を出た。", "explanation": "責務は抽象的な務めで、物のように机に置くことはできません。"}, {"text": "責務が高くて、山に登れなかった。", "explanation": "責務は高さのある物ではなく、「高い」と言って山に登れない理由にはなりません。"}, {"text": "責務を壊してしまったので、新しいものを買った。", "explanation": "責務は壊したり買い替えたりできる物ではなく、誤用です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52794, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "責務", "is_correct": true, "explanation": "企業が環境を守るという負うべき務めの意味で通ります。"}, {"text": "趣味", "is_correct": false, "explanation": "形は合うが、企業の環境保護を「趣味」とは言えず意味が合わない。"}, {"text": "偶然", "is_correct": false, "explanation": "形は合うが、「守るという偶然」では意味が合わない。"}, {"text": "才能", "is_correct": false, "explanation": "形は合うが、「守るという才能」では意味が合わない。"}], "explanations": {"責務": "企業が環境を守るという負うべき務めの意味で通ります。", "趣味": "形は合うが、企業の環境保護を「趣味」とは言えず意味が合わない。", "偶然": "形は合うが、「守るという偶然」では意味が合わない。", "才能": "形は合うが、「守るという才能」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "責務"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "責務を飲んで、のどの渇きがおさまった。", "explanation": "責務は飲み物ではなく、「飲む」とは結びつきません。"}, {"text": "今日は責務が降っていて、傘が必要だ。", "explanation": "責務は天気現象ではなく、「降る」の主語になりません。"}, {"text": "責務の色は、赤くてとてもきれいだ。", "explanation": "責務は抽象的な務めで、色を持つ物ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
