INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52794, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教師は生徒を守る責務に果たした。", "corrected_sentence": "教師は生徒を守る責務を果たした。", "error_description": "「果たす」の目的語を示すのは「に」ではなく「を」です。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52795, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「一人で」で状態・様態を表します。"}, {"text": "を", "is_correct": false, "explanation": "「一人を隔離された」は成り立ちません。"}, {"text": "の", "is_correct": false, "explanation": "「一人の隔離された」は文として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「一人へ隔離された」は成り立ちません。"}], "correct_answer": "で", "explanations": {"で": "「一人で」で状態・様態を表します。", "を": "「一人を隔離された」は成り立ちません。", "の": "「一人の隔離された」は文として成り立ちません。", "へ": "「一人へ隔離された」は成り立ちません。"}, "error_tags": {"を": "object_marker", "の": "possessive", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "交流", "is_correct": true, "explanation": "離して一人にする隔離に対し、交流は反対の関係です。"}, {"text": "看病", "is_correct": false, "explanation": "病人の世話で、対義語ではありません。"}, {"text": "診察", "is_correct": false, "explanation": "医者が診ることで、対義語ではありません。"}, {"text": "観察", "is_correct": false, "explanation": "様子を見ることで、対義語ではありません。"}], "correct_answer": "交流", "explanations": {"交流": "離して一人にする隔離に対し、交流は反対の関係です。", "看病": "病人の世話で、対義語ではありません。", "診察": "医者が診ることで、対義語ではありません。", "観察": "様子を見ることで、対義語ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52795, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「~、と患者は話した」で引用を示します。"}, {"text": "を", "is_correct": false, "explanation": "「さみしい、を患者は話した」は成り立ちません。"}, {"text": "に", "is_correct": false, "explanation": "「さみしい、に患者は話した」は成り立ちません。"}, {"text": "で", "is_correct": false, "explanation": "「さみしい、で患者は話した」は成り立ちません。"}], "correct_answer": "と", "explanations": {"と": "「~、と患者は話した」で引用を示します。", "を": "「さみしい、を患者は話した」は成り立ちません。", "に": "「さみしい、に患者は話した」は成り立ちません。", "で": "「さみしい、で患者は話した」は成り立ちません。"}, "error_tags": {"を": "object_marker", "に": "target", "で": "means"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "接触", "is_correct": true, "explanation": "離して一人にする隔離に対し、接触は反対の関係です。"}, {"text": "休養", "is_correct": false, "explanation": "体を休めることで、対義語ではありません。"}, {"text": "入院", "is_correct": false, "explanation": "病院に入ることで、対義語ではありません。"}, {"text": "退院", "is_correct": false, "explanation": "病院を出ることで、対義語ではありません。"}], "correct_answer": "接触", "explanations": {"接触": "離して一人にする隔離に対し、接触は反対の関係です。", "休養": "体を休めることで、対義語ではありません。", "入院": "病院に入ることで、対義語ではありません。", "退院": "病院を出ることで、対義語ではありません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52795, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ほかのものから、はなして、ひとりにすること。", "primary_collocate": null, "pronunciation": "かくり", "ipa": "kakɯɾi", "syllable_count": 3, "sentences": [{"text": "熱のある子を、別の部屋に隔離した。", "target_word": "隔離した", "complexity_tier": "T3", "furigana": "熱[ねつ]のある子[こ]を、別[べつ]の部屋[へや]に隔離[かくり]した。", "sentence_source": "generated"}, {"text": "彼は一人で隔離された。", "target_word": "隔離された", "complexity_tier": "T2", "furigana": "彼[かれ]は一人[ひとり]で隔離[かくり]された。", "sentence_source": "generated"}, {"text": "隔離された部屋は、とても静かだった。", "target_word": "隔離された", "complexity_tier": "T3", "furigana": "隔離[かくり]された部屋[へや]は、とても静[しず]かだった。", "sentence_source": "generated"}, {"text": "先生は、けんかした二人を隔離した。", "target_word": "隔離した", "complexity_tier": "T3", "furigana": "先生[せんせい]は、けんかした二人[ふたり]を隔離[かくり]した。", "sentence_source": "generated"}, {"text": "隔離の間、本を読んで過ごした。", "target_word": "隔離", "complexity_tier": "T3", "furigana": "隔離[かくり]の間[あいだ]、本[ほん]を読[よ]んで過[す]ごした。", "sentence_source": "generated"}, {"text": "病気がうつらないように、隔離する。", "target_word": "隔離する", "complexity_tier": "T3", "furigana": "病気[びょうき]がうつらないように、隔離[かくり]する。", "sentence_source": "generated"}, {"text": "隔離されている間は、家族にも会えない。", "target_word": "隔離されている", "complexity_tier": "T3", "furigana": "隔離[かくり]されている間[あいだ]は、家族[かぞく]にも会[あ]えない。", "sentence_source": "generated"}, {"text": "隔離はさみしい、と患者は話した。", "target_word": "隔離", "complexity_tier": "T3", "furigana": "隔離[かくり]はさみしい、と患者[かんじゃ]は話[はな]した。", "sentence_source": "generated"}, {"text": "隔離しないと、他の人にうつってしまう。", "target_word": "隔離しない", "complexity_tier": "T3", "furigana": "隔離[かくり]しないと、他[ほか]の人[ひと]にうつってしまう。", "sentence_source": "generated"}, {"text": "隔離のあと、彼は元気になった。", "target_word": "隔離", "complexity_tier": "T3", "furigana": "隔離[かくり]のあと、彼[かれ]は元気[げんき]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "隔離する", "label": "活用"}, {"form": "隔離した", "label": "活用"}, {"form": "隔離された", "label": "活用"}, {"form": "隔離しない", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 他から離して一人にすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: うつら (Zipf 1.84)']::text[], 'd5c0cbd4-9068-402c-8710-9d8b63a52347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52795, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "隔離", "is_correct": true, "explanation": "見出し語「かくり」そのものです。"}, {"text": "覚悟", "is_correct": false, "explanation": "「かくご」で、三音目が異なります。"}, {"text": "角度", "is_correct": false, "explanation": "「かくど」で、三音目が異なります。"}, {"text": "確保", "is_correct": false, "explanation": "「かくほ」で、三音目が異なります。"}, {"text": "各自", "is_correct": false, "explanation": "「かくじ」で、三音目が異なります。"}], "explanations": {"隔離": "見出し語「かくり」そのものです。", "覚悟": "「かくご」で、三音目が異なります。", "角度": "「かくど」で、三音目が異なります。", "確保": "「かくほ」で、三音目が異なります。", "各自": "「かくじ」で、三音目が異なります。"}, "sentence_index": null, "correct_answer": "隔離"}, "level_3": {"options": [{"text": "隔離した", "is_correct": true, "explanation": "熱のある子を別の部屋に離す意味で通ります。"}, {"text": "翻訳した", "is_correct": false, "explanation": "形は合うが、子を部屋に「翻訳する」では意味が合わない。"}, {"text": "録音した", "is_correct": false, "explanation": "形は合うが、子を部屋に「録音する」では意味が合わない。"}, {"text": "採点した", "is_correct": false, "explanation": "形は合うが、子を「採点する」では意味が合わない。"}], "explanations": {"隔離した": "熱のある子を別の部屋に離す意味で通ります。", "翻訳した": "形は合うが、子を部屋に「翻訳する」では意味が合わない。", "録音した": "形は合うが、子を部屋に「録音する」では意味が合わない。", "採点した": "形は合うが、子を「採点する」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "隔離した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友だちを家に隔離して、いっしょにゲームをした。", "explanation": "隔離は離して一人にすることで、招いて一緒に遊ぶ意味はありません。"}, {"text": "隔離を飲んで、のどをうるおした。", "explanation": "隔離は行為で、飲み物ではありません。"}, {"text": "母は、隔離の色で服を選んだ。", "explanation": "隔離は色を持つ物ではなく、色の名前として使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52795, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "隔離", "is_correct": true, "explanation": "見出し語「かくり」そのものです。"}, {"text": "隠す", "is_correct": false, "explanation": "「かくす」で、三音目が異なります。"}, {"text": "係", "is_correct": false, "explanation": "「かかり」で、二音目が異なります。"}, {"text": "捲り", "is_correct": false, "explanation": "「まくり」で、一音目が異なります。"}, {"text": "各位", "is_correct": false, "explanation": "「かくい」で、三音目が異なります。"}], "explanations": {"隔離": "見出し語「かくり」そのものです。", "隠す": "「かくす」で、三音目が異なります。", "係": "「かかり」で、二音目が異なります。", "捲り": "「まくり」で、一音目が異なります。", "各位": "「かくい」で、三音目が異なります。"}, "sentence_index": null, "correct_answer": "隔離"}, "level_3": {"options": [{"text": "隔離されている", "is_correct": true, "explanation": "離されて家族に会えない状態の意味で通ります。"}, {"text": "翻訳されている", "is_correct": false, "explanation": "形は合うが、「翻訳されている間は会えない」では意味が合わない。"}, {"text": "録音されている", "is_correct": false, "explanation": "形は合うが、「録音されている間は会えない」では意味が合わない。"}, {"text": "採点されている", "is_correct": false, "explanation": "形は合うが、「採点されている間は会えない」では意味が合わない。"}], "explanations": {"隔離されている": "離されて家族に会えない状態の意味で通ります。", "翻訳されている": "形は合うが、「翻訳されている間は会えない」では意味が合わない。", "録音されている": "形は合うが、「録音されている間は会えない」では意味が合わない。", "採点されている": "形は合うが、「採点されている間は会えない」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "隔離されている"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "隔離を聞くと、いつも楽しい気持ちになる。", "explanation": "隔離は音や話ではなく、「聞く」と結びつきません。"}, {"text": "新しい隔離を買って、部屋にかざった。", "explanation": "隔離は行為で、買って飾る物ではありません。"}, {"text": "隔離が高くて、山の上から町が見えた。", "explanation": "隔離は高さのある物ではなく、「高い」と結びつきません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, valid