INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52796, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "隔離される先の場所を示します。"}, {"text": "を", "is_correct": false, "explanation": "「病院を隔離された」は成り立ちません。"}, {"text": "の", "is_correct": false, "explanation": "「病院の隔離された」は文として成り立ちません。"}, {"text": "や", "is_correct": false, "explanation": "「病院や隔離された」は文として成り立ちません。"}], "correct_answer": "に", "explanations": {"に": "隔離される先の場所を示します。", "を": "「病院を隔離された」は成り立ちません。", "の": "「病院の隔離された」は文として成り立ちません。", "や": "「病院や隔離された」は文として成り立ちません。"}, "error_tags": {"を": "object_marker", "の": "possessive", "や": "listing"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解放", "is_correct": true, "explanation": "閉じ込める隔離に対し、解放は反対の関係です。"}, {"text": "検査", "is_correct": false, "explanation": "調べることで、隔離の対義語ではありません。"}, {"text": "治療", "is_correct": false, "explanation": "病気を治すことで、対義語ではありません。"}, {"text": "保管", "is_correct": false, "explanation": "しまっておくことで、対義語ではありません。"}], "correct_answer": "解放", "explanations": {"解放": "閉じ込める隔離に対し、解放は反対の関係です。", "検査": "調べることで、隔離の対義語ではありません。", "治療": "病気を治すことで、対義語ではありません。", "保管": "しまっておくことで、対義語ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52796, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「乗客が下船した」の主語を示します。"}, {"text": "を", "is_correct": false, "explanation": "「乗客を下船した」は成り立ちません。"}, {"text": "の", "is_correct": false, "explanation": "「乗客の下船した」は文として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「乗客へ下船した」は成り立ちません。"}], "correct_answer": "が", "explanations": {"が": "「乗客が下船した」の主語を示します。", "を": "「乗客を下船した」は成り立ちません。", "の": "「乗客の下船した」は文として成り立ちません。", "へ": "「乗客へ下船した」は成り立ちません。"}, "error_tags": {"を": "object_marker", "の": "possessive", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解放", "is_correct": true, "explanation": "切り離す隔離に対し、解放は反対の関係です。"}, {"text": "消毒", "is_correct": false, "explanation": "菌を除くことで、対義語ではありません。"}, {"text": "観察", "is_correct": false, "explanation": "様子を見ることで、対義語ではありません。"}, {"text": "封鎖", "is_correct": false, "explanation": "閉ざすことで、隔離に近い語です。"}], "correct_answer": "解放", "explanations": {"解放": "切り離す隔離に対し、解放は反対の関係です。", "消毒": "菌を除くことで、対義語ではありません。", "観察": "様子を見ることで、対義語ではありません。", "封鎖": "閉ざすことで、隔離に近い語です。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52796, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "他のものから切り離して、別の場所に置くこと。特に、感染症や危険なものなどを広げないように、閉じ込めること。", "primary_collocate": null, "pronunciation": "かくり", "ipa": "kakɯɾi", "syllable_count": 3, "sentences": [{"text": "単なる廃棄物としての隔離にとどまらず、炭素を資源へと転換し、あるいは地中へ封じ込めるこの技術は、経済活動と脱炭素化の両立という難題に対する、現時点での最適解たり得る。", "target_word": "隔離", "complexity_tier": "T6", "furigana": "単[たん]なる廃棄物[はいきぶつ]としての隔離[かくり]にとどまらず、炭素[たんそ]を資源[しげん]へと転換[てんかん]し、あるいは地中[ちちゅう]へ封[ふう]じ込[こ]めるこの技術[ぎじゅつ]は、経済活動[けいざいかつどう]と脱炭素化[だつたんそか]の両立[りょうりつ]という難題[なんだい]に対[たい]する、現時点[げんじてん]での最適解[さいてきかい]たり得[う]る。", "sentence_source": "mined"}, {"text": "患者は病院に隔離された。", "target_word": "隔離された", "complexity_tier": "T3", "furigana": "患者[かんじゃ]は病院[びょういん]に隔離[かくり]された。", "sentence_source": "generated"}, {"text": "感染した人を隔離する。", "target_word": "隔離する", "complexity_tier": "T2", "furigana": "感染[かんせん]した人[ひと]を隔離[かくり]する。", "sentence_source": "generated"}, {"text": "隔離の期間は、十日間です。", "target_word": "隔離", "complexity_tier": "T2", "furigana": "隔離[かくり]の期間[きかん]は、十日間[とおかかん]です。", "sentence_source": "generated"}, {"text": "危険な廃棄物は、他のごみから隔離して保管する。", "target_word": "隔離して", "complexity_tier": "T4", "furigana": "危険[きけん]な廃棄物[はいきぶつ]は、他[ほか]のごみから隔離[かくり]して保管[ほかん]する。", "sentence_source": "generated"}, {"text": "感染の広がりを防ぐため、早めの隔離が必要だ。", "target_word": "隔離", "complexity_tier": "T4", "furigana": "感染[かんせん]の広[ひろ]がりを防[ふせ]ぐため、早[はや]めの隔離[かくり]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "動物園では、病気の動物を別の部屋に隔離している。", "target_word": "隔離している", "complexity_tier": "T4", "furigana": "動物園[どうぶつえん]では、病気[びょうき]の動物[どうぶつ]を別[べつ]の部屋[へや]に隔離[かくり]している。", "sentence_source": "generated"}, {"text": "隔離されていた船の乗客が、ようやく下船した。", "target_word": "隔離されて", "complexity_tier": "T4", "furigana": "隔離[かくり]されていた船[ふね]の乗客[じょうきゃく]が、ようやく下船[げせん]した。", "sentence_source": "generated"}, {"text": "検査で陽性だったので、自宅で隔離することになった。", "target_word": "隔離する", "complexity_tier": "T4", "furigana": "検査[けんさ]で陽性[ようせい]だったので、自宅[じたく]で隔離[かくり]することになった。", "sentence_source": "generated"}, {"text": "放射性の物質は、人から隔離しなければならない。", "target_word": "隔離しなければ", "complexity_tier": "T4", "furigana": "放射性[ほうしゃせい]の物質[ぶっしつ]は、人[ひと]から隔離[かくり]しなければならない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "隔離する", "label": "活用"}, {"form": "隔離した", "label": "活用"}, {"form": "隔離される", "label": "活用"}, {"form": "隔離された", "label": "活用"}, {"form": "隔離室", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 危険なものを切り離して閉じ込める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5c0cbd4-9068-402c-8710-9d8b63a52347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52796, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "隔離", "is_correct": true, "explanation": "見出し語「かくり」そのものです。"}, {"text": "覚悟", "is_correct": false, "explanation": "「かくご」で、三音目が異なります。"}, {"text": "角度", "is_correct": false, "explanation": "「かくど」で、三音目が異なります。"}, {"text": "確保", "is_correct": false, "explanation": "「かくほ」で、三音目が異なります。"}, {"text": "各自", "is_correct": false, "explanation": "「かくじ」で、三音目が異なります。"}], "explanations": {"隔離": "見出し語「かくり」そのものです。", "覚悟": "「かくご」で、三音目が異なります。", "角度": "「かくど」で、三音目が異なります。", "確保": "「かくほ」で、三音目が異なります。", "各自": "「かくじ」で、三音目が異なります。"}, "sentence_index": null, "correct_answer": "隔離"}, "level_3": {"options": [{"text": "隔離", "is_correct": true, "explanation": "廃棄物を切り離す意味で「廃棄物としての隔離」と通ります。"}, {"text": "音楽", "is_correct": false, "explanation": "形は合うが、「廃棄物としての音楽」では意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「廃棄物としての天気」では意味が合わない。"}, {"text": "趣味", "is_correct": false, "explanation": "形は合うが、「廃棄物としての趣味」では意味が合わない。"}], "explanations": {"隔離": "廃棄物を切り離す意味で「廃棄物としての隔離」と通ります。", "音楽": "形は合うが、「廃棄物としての音楽」では意味が合わない。", "天気": "形は合うが、「廃棄物としての天気」では意味が合わない。", "趣味": "形は合うが、「廃棄物としての趣味」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "隔離"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "隔離を食べたら、おなかがいっぱいになった。", "explanation": "隔離は切り離す行為で、食べ物ではありません。"}, {"text": "友だちを家に隔離して、いっしょにお茶を飲んだ。", "explanation": "隔離は閉じ込めて切り離すことで、招いて一緒に過ごす意味はありません。"}, {"text": "隔離がきれいで、毎日写真を撮った。", "explanation": "隔離は行為であり、景色のようにきれいと形容できません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52796, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "隔離", "is_correct": true, "explanation": "見出し語「かくり」そのものです。"}, {"text": "隠す", "is_correct": false, "explanation": "「かくす」で、三音目が異なります。"}, {"text": "係", "is_correct": false, "explanation": "「かかり」で、二音目が異なります。"}, {"text": "捲り", "is_correct": false, "explanation": "「まくり」で、一音目が異なります。"}, {"text": "各位", "is_correct": false, "explanation": "「かくい」で、三音目が異なります。"}], "explanations": {"隔離": "見出し語「かくり」そのものです。", "隠す": "「かくす」で、三音目が異なります。", "係": "「かかり」で、二音目が異なります。", "捲り": "「まくり」で、一音目が異なります。", "各位": "「かくい」で、三音目が異なります。"}, "sentence_index": null, "correct_answer": "隔離"}, "level_3": {"options": [{"text": "隔離している", "is_correct": true, "explanation": "病気の動物を別の部屋に切り離す意味で通ります。"}, {"text": "翻訳している", "is_correct": false, "explanation": "形は合うが、病気の動物を「翻訳する」では意味が合わない。"}, {"text": "録音している", "is_correct": false, "explanation": "形は合うが、動物を部屋に「録音する」では意味が合わない。"}, {"text": "採点している", "is_correct": false, "explanation": "形は合うが、動物を「採点する」では意味が合わない。"}], "explanations": {"隔離している": "病気の動物を別の部屋に切り離す意味で通ります。", "翻訳している": "形は合うが、病気の動物を「翻訳する」では意味が合わない。", "録音している": "形は合うが、動物を部屋に「録音する」では意味が合わない。", "採点している": "形は合うが、動物を「採点する」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "隔離している"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "隔離を飲んだら、体が温まった。", "explanation": "隔離は切り離す行為で、飲み物ではありません。"}, {"text": "彼は隔離を歌いながら、台所で料理した。", "explanation": "隔離は歌えるものではなく、「歌う」と結びつきません。"}, {"text": "隔離の天気は、明日は雨だ。", "explanation": "隔離は天気を表す語ではなく、誤用です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
