INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52797, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ゼロは、なにもないことをあらわすかずです。", "primary_collocate": null, "pronunciation": "ぜろ", "ipa": "dzeɾo", "syllable_count": 2, "sentences": [{"text": "ゼロは何もない数です。", "target_word": "ゼロ", "complexity_tier": "T2", "furigana": "ゼロは何[なに]もない数[かず]です。", "sentence_source": "generated"}, {"text": "十から十をひくと、ゼロです。", "target_word": "ゼロ", "complexity_tier": "T2", "furigana": "十[じゅう]から十[じゅう]をひくと、ゼロです。", "sentence_source": "generated"}, {"text": "テストの点がゼロだった。", "target_word": "ゼロ", "complexity_tier": "T2", "furigana": "テストの点[てん]がゼロだった。", "sentence_source": "generated"}, {"text": "電話番号の最初はゼロです。", "target_word": "ゼロ", "complexity_tier": "T2", "furigana": "電話番号[でんわばんごう]の最初[さいしょ]はゼロです。", "sentence_source": "generated"}, {"text": "おかしはもうゼロになった。", "target_word": "ゼロ", "complexity_tier": "T2", "furigana": "おかしはもうゼロになった。", "sentence_source": "generated"}, {"text": "ゼロにゼロをかけても、ゼロだ。", "target_word": "ゼロ", "complexity_tier": "T2", "furigana": "ゼロにゼロをかけても、ゼロだ。", "sentence_source": "generated"}, {"text": "財布の中身はゼロに近い。", "target_word": "ゼロ", "complexity_tier": "T3", "furigana": "財布[さいふ]の中身[なかみ]はゼロに近[ちか]い。", "sentence_source": "generated"}, {"text": "気温がゼロまで下がった。", "target_word": "ゼロ", "complexity_tier": "T2", "furigana": "気温[きおん]がゼロまで下[さ]がった。", "sentence_source": "generated"}, {"text": "ゼロから数え始めてください。", "target_word": "ゼロ", "complexity_tier": "T3", "furigana": "ゼロから数[かぞ]え始[はじ]めてください。", "sentence_source": "generated"}, {"text": "友だちがゼロでも、さびしくない。", "target_word": "ゼロ", "complexity_tier": "T3", "furigana": "友[とも]だちがゼロでも、さびしくない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ゼロ化", "label": "派生"}, {"form": "ゼロ歳", "label": "助数詞"}, {"form": "ゼロ度", "label": "助数詞"}], "register": "plain", "sense_fingerprint": "名詞 | 何もないことを表す数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: さびしく (Zipf 2.32)']::text[], 'd5c0cbd4-9068-402c-8710-9d8b63a52347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52797, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "ゼロ", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "セロ", "is_correct": false, "explanation": "「セロ」は楽器で、ゼ→セの1拍違い。"}, {"text": "テロ", "is_correct": false, "explanation": "「テロ」は暴力行為で、ゼ→テの1拍違い。"}, {"text": "ベロ", "is_correct": false, "explanation": "「ベロ」は舌のことで、ゼ→ベの1拍違い。"}, {"text": "ゼミ", "is_correct": false, "explanation": "「ゼミ」は演習授業で、ロ→ミの1拍違い。"}], "explanations": {"ゼロ": "見出し語そのもの。", "セロ": "「セロ」は楽器で、ゼ→セの1拍違い。", "テロ": "「テロ」は暴力行為で、ゼ→テの1拍違い。", "ベロ": "「ベロ」は舌のことで、ゼ→ベの1拍違い。", "ゼミ": "「ゼミ」は演習授業で、ロ→ミの1拍違い。"}, "sentence_index": null, "correct_answer": "ゼロ"}, "level_3": {"options": [{"text": "ゼロ", "is_correct": true, "explanation": "「何もない数」はゼロのことで意味が合う。"}, {"text": "百", "is_correct": false, "explanation": "形は合うが、百は何もない数ではなく意味が合わない。"}, {"text": "一", "is_correct": false, "explanation": "形は合うが、一は何もない数ではなく意味が合わない。"}, {"text": "千", "is_correct": false, "explanation": "形は合うが、千は何もない数ではなく意味が合わない。"}], "explanations": {"ゼロ": "「何もない数」はゼロのことで意味が合う。", "百": "形は合うが、百は何もない数ではなく意味が合わない。", "一": "形は合うが、一は何もない数ではなく意味が合わない。", "千": "形は合うが、千は何もない数ではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "ゼロ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ゼロは九より大きい数です。", "explanation": "ゼロは何もない数で、九より小さい。大小の使い方が誤り。"}, {"text": "三に二をたすと、ゼロになる。", "explanation": "たし算でゼロにはならない。ゼロの使い方が誤り。"}, {"text": "箱にボールが十個あるので、ボールの数はゼロです。", "explanation": "十個あるのにゼロと言っており、「何もない」に反する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation