INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52798, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "数字の0。何もない状態や数量を表す。起点や基準となる値。", "primary_collocate": null, "pronunciation": "ぜろ", "ipa": "dzeɾo", "syllable_count": 2, "sentences": [{"text": "再生可能エネルギーの導入加速にもかかわらず、製造プロセスの性質上、炭素発生をゼロ化し得ない領域において、CCUSは極めて重要な役割を担う。", "target_word": "ゼロ", "complexity_tier": "T6", "furigana": "再生可能[さいせいかのう]エネルギーの導入[どうにゅう]加速[かそく]にもかかわらず、製造[せいぞう]プロセスの性質上[せいしつじょう]、炭素発生[たんそはっせい]をゼロ化[か]し得[え]ない領域[りょういき]において、CCUSは極[きわ]めて重要[じゅうよう]な役割[やくわり]を担[にな]う。", "sentence_source": "mined"}, {"text": "答えはゼロです。", "target_word": "ゼロ", "complexity_tier": "T2", "furigana": "答[こた]えはゼロです。", "sentence_source": "generated"}, {"text": "残りのお金がゼロになった。", "target_word": "ゼロ", "complexity_tier": "T3", "furigana": "残[のこ]りのお金[かね]がゼロになった。", "sentence_source": "generated"}, {"text": "ゼロから始めるのは大変だ。", "target_word": "ゼロ", "complexity_tier": "T3", "furigana": "ゼロから始[はじ]めるのは大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "事故をゼロにする目標を立てた。", "target_word": "ゼロ", "complexity_tier": "T3", "furigana": "事故[じこ]をゼロにする目標[もくひょう]を立[た]てた。", "sentence_source": "generated"}, {"text": "テストの点数はゼロだった。", "target_word": "ゼロ", "complexity_tier": "T3", "furigana": "テストの点数[てんすう]はゼロだった。", "sentence_source": "generated"}, {"text": "この町の人口はゼロに近い。", "target_word": "ゼロ", "complexity_tier": "T3", "furigana": "この町[まち]の人口[じんこう]はゼロに近[ちか]い。", "sentence_source": "generated"}, {"text": "失敗する可能性はゼロではない。", "target_word": "ゼロ", "complexity_tier": "T3", "furigana": "失敗[しっぱい]する可能性[かのうせい]はゼロではない。", "sentence_source": "generated"}, {"text": "電気の使用量をゼロにすることはできない。", "target_word": "ゼロ", "complexity_tier": "T4", "furigana": "電気[でんき]の使用量[しようりょう]をゼロにすることはできない。", "sentence_source": "generated"}, {"text": "メーターの針がゼロを指している。", "target_word": "ゼロ", "complexity_tier": "T3", "furigana": "メーターの針[はり]がゼロを指[さ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ゼロ化", "label": "派生"}, {"form": "ゼロ歳", "label": "助数詞"}, {"form": "ゼロ度", "label": "助数詞"}], "register": "plain", "sense_fingerprint": "名詞 | 数字の0や何もない状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5c0cbd4-9068-402c-8710-9d8b63a52347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52798, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "ゼロ", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "セロ", "is_correct": false, "explanation": "「セロ」は楽器で、ゼ→セの清濁1拍違い。"}, {"text": "テロ", "is_correct": false, "explanation": "「テロ」は暴力行為で、ゼ→テの1拍違い。"}, {"text": "ベロ", "is_correct": false, "explanation": "「ベロ」は舌のことで、ゼ→ベの1拍違い。"}, {"text": "ゼミ", "is_correct": false, "explanation": "「ゼミ」は演習授業で、ロ→ミの1拍違い。"}], "explanations": {"ゼロ": "見出し語そのもの。", "セロ": "「セロ」は楽器で、ゼ→セの清濁1拍違い。", "テロ": "「テロ」は暴力行為で、ゼ→テの1拍違い。", "ベロ": "「ベロ」は舌のことで、ゼ→ベの1拍違い。", "ゼミ": "「ゼミ」は演習授業で、ロ→ミの1拍違い。"}, "sentence_index": null, "correct_answer": "ゼロ"}, "level_3": {"options": [{"text": "ゼロ", "is_correct": true, "explanation": "「炭素発生をゼロ化する」で文意に合う。"}, {"text": "標準", "is_correct": false, "explanation": "形は合うが、炭素発生を標準化するという意味が合わない。"}, {"text": "民営", "is_correct": false, "explanation": "形は合うが、炭素発生に民営化は意味が合わない。"}, {"text": "一般", "is_correct": false, "explanation": "形は合うが、炭素発生を一般化できないという意味が文脈に合わない。"}], "explanations": {"ゼロ": "「炭素発生をゼロ化する」で文意に合う。", "標準": "形は合うが、炭素発生を標準化するという意味が合わない。", "民営": "形は合うが、炭素発生に民営化は意味が合わない。", "一般": "形は合うが、炭素発生を一般化できないという意味が文脈に合わない。"}, "sentence_index": 0, "correct_answer": "ゼロ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "かごにりんごが十個入っているので、りんごの数はゼロだ。", "explanation": "十個あるのにゼロと言っており、「何もない」という意味に反する。"}, {"text": "ゼロを十個集めると、百になる。", "explanation": "ゼロをいくつ集めて足してもゼロのままなので、百にはならない。"}, {"text": "満点を取ったので、テストの点数はゼロだった。", "explanation": "満点なら点数は最大で、ゼロの意味に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors,