INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52798, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "ゼロ", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "テロ", "is_correct": false, "explanation": "「テロ」は暴力行為のことで、ゼ→テの1拍違い。"}, {"text": "ゼニ", "is_correct": false, "explanation": "「ゼニ」はお金のことで、ロ→ニの1拍違い。"}, {"text": "ゼン", "is_correct": false, "explanation": "「ゼン」(禅)は、ロ→ンの1拍違い。"}], "explanations": {"ゼロ": "見出し語そのもの。", "テロ": "「テロ」は暴力行為のことで、ゼ→テの1拍違い。", "ゼニ": "「ゼニ」はお金のことで、ロ→ニの1拍違い。", "ゼン": "「ゼン」(禅)は、ロ→ンの1拍違い。"}, "sentence_index": null, "correct_answer": "ゼロ"}, "level_3": {"options": [{"text": "ゼロ", "is_correct": true, "explanation": "人口が「ゼロに近い」で意味が通る。"}, {"text": "駅", "is_correct": false, "explanation": "形は合うが、人口が駅に近いという意味が合わない。"}, {"text": "海", "is_correct": false, "explanation": "形は合うが、人口が海に近いという意味が合わない。"}, {"text": "屋根", "is_correct": false, "explanation": "形は合うが、人口が屋根に近いという意味が合わない。"}], "explanations": {"ゼロ": "人口が「ゼロに近い」で意味が通る。", "駅": "形は合うが、人口が駅に近いという意味が合わない。", "海": "形は合うが、人口が海に近いという意味が合わない。", "屋根": "形は合うが、人口が屋根に近いという意味が合わない。"}, "sentence_index": 6, "correct_answer": "ゼロ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水がいっぱい入っているので、タンクの水の量はゼロだ。", "explanation": "いっぱいなのにゼロと言っており、「何もない」に反する。"}, {"text": "ゼロは九より大きい数字だ。", "explanation": "ゼロは九より小さい数で、大小の使い方が誤り。"}, {"text": "駐車場に車が二十台とまっていて、車の数はゼロだ。", "explanation": "二十台あるのにゼロと言っており、「何もない」に反する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2933db7-1d61-47a0-b652-d7662d66cfd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
