INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52799, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "回廊は、建物と建物などをつなぐ、長い廊下のことです。", "primary_collocate": null, "pronunciation": "かいろう", "ipa": "kaiɾoː", "syllable_count": 4, "sentences": [{"text": "回廊を進む。", "target_word": "回廊", "complexity_tier": "T1", "furigana": "回廊[かいろう]を進[すす]む。", "sentence_source": "generated"}, {"text": "この回廊は長いです。", "target_word": "回廊", "complexity_tier": "T2", "furigana": "この回廊[かいろう]は長[なが]いです。", "sentence_source": "generated"}, {"text": "家と庭は回廊でつながっています。", "target_word": "回廊", "complexity_tier": "T2", "furigana": "家[いえ]と庭[にわ]は回廊[かいろう]でつながっています。", "sentence_source": "generated"}, {"text": "暗い回廊を一人で歩きました。", "target_word": "回廊", "complexity_tier": "T2", "furigana": "暗[くら]い回廊[かいろう]を一人[ひとり]で歩[ある]きました。", "sentence_source": "generated"}, {"text": "狭い回廊を抜けると、広い庭に出た。", "target_word": "回廊", "complexity_tier": "T3", "furigana": "狭[せま]い回廊[かいろう]を抜[ぬ]けると、広[ひろ]い庭[にわ]に出[で]た。", "sentence_source": "generated"}, {"text": "雨の日も、回廊を使えば濡れずに行ける。", "target_word": "回廊", "complexity_tier": "T4", "furigana": "雨[あめ]の日[ひ]も、回廊[かいろう]を使[つか]えば濡[ぬ]れずに行[い]ける。", "sentence_source": "generated"}, {"text": "回廊の両側には、古い絵が飾られていた。", "target_word": "回廊", "complexity_tier": "T4", "furigana": "回廊[かいろう]の両側[りょうがわ]には、古[ふる]い絵[え]が飾[かざ]られていた。", "sentence_source": "generated"}, {"text": "回廊は本館と別館をつなぐ長い廊下だ。", "target_word": "回廊", "complexity_tier": "T3", "furigana": "回廊[かいろう]は本館[ほんかん]と別館[べっかん]をつなぐ長[なが]い廊下[ろうか]だ。", "sentence_source": "generated"}, {"text": "長い回廊を渡って、ようやく奥の部屋に着いた。", "target_word": "回廊", "complexity_tier": "T4", "furigana": "長[なが]い回廊[かいろう]を渡[わた]って、ようやく奥[おく]の部屋[へや]に着[つ]いた。", "sentence_source": "generated"}, {"text": "回廊の先に何があるのか分からないまま、私は静かに歩き続けた。", "target_word": "回廊", "complexity_tier": "T5", "furigana": "回廊[かいろう]の先[さき]に何[なに]があるのか分[わ]からないまま、私[わたし]は静[しず]かに歩[ある]き続[つづ]けた。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 建物や場所をつなぐ長い廊下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3446334-3278-4fc4-9bdd-c73ba1cb63db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52799, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回廊", "is_correct": true, "explanation": "見出し語「かいろう」そのものです。"}, {"text": "開講", "is_correct": false, "explanation": "「かいこう」で、ろ→この一拍だけが違います。"}, {"text": "街道", "is_correct": false, "explanation": "「かいどう」で、ろ→どの一拍だけが違います。"}, {"text": "海洋", "is_correct": false, "explanation": "「かいよう」で、ろ→よの一拍だけが違います。"}, {"text": "解放", "is_correct": false, "explanation": "「かいほう」で、ろ→ほの一拍だけが違います。"}], "explanations": {"回廊": "見出し語「かいろう」そのものです。", "開講": "「かいこう」で、ろ→この一拍だけが違います。", "街道": "「かいどう」で、ろ→どの一拍だけが違います。", "海洋": "「かいよう」で、ろ→よの一拍だけが違います。", "解放": "「かいほう」で、ろ→ほの一拍だけが違います。"}, "sentence_index": null, "correct_answer": "回廊"}, "level_3": {"options": [{"text": "回廊", "is_correct": true, "explanation": "建物や場所をつなぐ長い廊下という意味に合います。"}, {"text": "牛乳", "is_correct": false, "explanation": "形は合うが、牛乳を進むでは意味が合わない。"}, {"text": "財布", "is_correct": false, "explanation": "形は合うが、財布を進むでは意味が合わない。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、野菜を進むでは意味が合わない。"}], "explanations": {"回廊": "建物や場所をつなぐ長い廊下という意味に合います。", "牛乳": "形は合うが、牛乳を進むでは意味が合わない。", "財布": "形は合うが、財布を進むでは意味が合わない。", "野菜": "形は合うが、野菜を進むでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "回廊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "回廊を飲んで、のどが潤った。", "explanation": "回廊は通路で、飲み物ではありません。"}, {"text": "回廊を着て、外に出ました。", "explanation": "回廊は通路で、着る物ではありません。"}, {"text": "回廊に電話して、予約を取った。", "explanation": "回廊は通路で、電話をかける相手ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52799, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "回廊", "is_correct": true, "explanation": "見出し語「かいろう」そのものです。"}, {"text": "回答", "is_correct": false, "explanation": "「かいとう」で、ろ→との一拍だけが違います。"}, {"text": "改造", "is_correct": false, "explanation": "「かいぞう」で、ろ→ぞの一拍だけが違います。"}, {"text": "海藻", "is_correct": false, "explanation": "「かいそう」で、ろ→その一拍だけが違います。"}, {"text": "大老", "is_correct": false, "explanation": "「たいろう」で、か→たの一拍だけが違います。"}], "explanations": {"回廊": "見出し語「かいろう」そのものです。", "回答": "「かいとう」で、ろ→との一拍だけが違います。", "改造": "「かいぞう」で、ろ→ぞの一拍だけが違います。", "海藻": "「かいそう」で、ろ→その一拍だけが違います。", "大老": "「たいろう」で、か→たの一拍だけが違います。"}, "sentence_index": null, "correct_answer": "回廊"}, "level_3": {"options": [{"text": "回廊", "is_correct": true, "explanation": "両側に絵が飾られた細長い通路という意味に合います。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、野菜の両側に絵が飾られるでは意味が合わない。"}, {"text": "空気", "is_correct": false, "explanation": "形は合うが、空気の両側に絵が飾られるでは意味が合わない。"}, {"text": "気持ち", "is_correct": false, "explanation": "形は合うが、気持ちの両側に絵が飾られるでは意味が合わない。"}], "explanations": {"回廊": "両側に絵が飾られた細長い通路という意味に合います。", "野菜": "形は合うが、野菜の両側に絵が飾られるでは意味が合わない。", "空気": "形は合うが、空気の両側に絵が飾られるでは意味が合わない。", "気持ち": "形は合うが、気持ちの両側に絵が飾られるでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "回廊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "回廊を焼いて、パンを作った。", "explanation": "回廊は通路で、焼く材料ではありません。"}, {"text": "回廊が泣いて、赤ちゃんが起きた。", "explanation": "回廊は通路で、泣くものではありません。"}, {"text": "回廊を貼って、手紙を送った。", "explanation": "回廊は通路で、貼るものではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_e