INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52802, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地表よりも下の部分。土や岩でできた地面の内部。", "primary_collocate": null, "pronunciation": "ちちゅう", "ipa": "tɕitɕɯː", "syllable_count": 3, "sentences": [{"text": "単なる廃棄物としての隔離にとどまらず、炭素を資源へと転換し、あるいは地中へ封じ込めるこの技術は、経済活動と脱炭素化の両立という難題に対する、現時点での最適解たり得る。", "target_word": "地中", "complexity_tier": "T6", "furigana": "単[たん]なる廃棄物[はいきぶつ]としての隔離[かくり]にとどまらず、炭素[たんそ]を資源[しげん]へと転換[てんかん]し、あるいは地中[ちちゅう]へ封[ふう]じ込[こ]めるこの技術[ぎじゅつ]は、経済活動[けいざいかつどう]と脱炭素化[だつたんそか]の両立[りょうりつ]という難題[なんだい]に対[たい]する、現時点[げんじてん]での最適解[さいてきかい]たり得[う]る。", "sentence_source": "mined"}, {"text": "地中には、たくさんの虫が住んでいる。", "target_word": "地中", "complexity_tier": "T3", "furigana": "地中[ちちゅう]には、たくさんの虫[むし]が住[す]んでいる。", "sentence_source": "generated"}, {"text": "古い水道管は、地中に埋められている。", "target_word": "地中", "complexity_tier": "T3", "furigana": "古[ふる]い水道管[すいどうかん]は、地中[ちちゅう]に埋[う]められている。", "sentence_source": "generated"}, {"text": "地中の温度は、一年を通して変わりにくい。", "target_word": "地中", "complexity_tier": "T4", "furigana": "地中[ちちゅう]の温度[おんど]は、一年[いちねん]を通[とお]して変[か]わりにくい。", "sentence_source": "generated"}, {"text": "木の根は、地中の水を求めて伸びていく。", "target_word": "地中", "complexity_tier": "T3", "furigana": "木[き]の根[ね]は、地中[ちちゅう]の水[みず]を求[もと]めて伸[の]びていく。", "sentence_source": "generated"}, {"text": "地中から出てきたセミが木に登った。", "target_word": "地中", "complexity_tier": "T3", "furigana": "地中[ちちゅう]から出[で]てきたセミが木[き]に登[のぼ]った。", "sentence_source": "generated"}, {"text": "地中で何かが動いているようだった。", "target_word": "地中", "complexity_tier": "T3", "furigana": "地中[ちちゅう]で何[なに]かが動[うご]いているようだった。", "sentence_source": "generated"}, {"text": "工事で、地中のガス管が見つかった。", "target_word": "地中", "complexity_tier": "T3", "furigana": "工事[こうじ]で、地中[ちちゅう]のガス管[かん]が見[み]つかった。", "sentence_source": "generated"}, {"text": "二酸化炭素を地中に閉じ込める研究が進んでいる。", "target_word": "地中", "complexity_tier": "T4", "furigana": "二酸化炭素[にさんかたんそ]を地中[ちちゅう]に閉[と]じ込[こ]める研究[けんきゅう]が進[すす]んでいる。", "sentence_source": "generated"}, {"text": "地中を掘ると、古い土器が出てきた。", "target_word": "地中", "complexity_tier": "T3", "furigana": "地中[ちちゅう]を掘[ほ]ると、古[ふる]い土器[どき]が出[で]てきた。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 地表より下の土や岩の内部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5c0cbd4-9068-402c-8710-9d8b63a52347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
